  ('pescados_068', 'Dorada a la sal con salsa romesco', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, 'horno', 45, 'normal', 'all', 445, 44, 11, 26, 2, true, false, '{"pescado","frutos_secos","gluten","sulfitos"}', '[{"name":"Dorada entera limpia sin escamar","amount":900,"unit":"g"},{"name":"Sal gruesa","amount":1500,"unit":"g"},{"name":"Tomate maduro","amount":100,"unit":"g"},{"name":"Ñora hidratada","amount":15,"unit":"g"},{"name":"Almendras tostadas","amount":25,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pan frito","amount":20,"unit":"g"},{"name":"Vinagre de vino","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 220 °C.","Extender la mitad de sal gruesa en una bandeja formando una capa uniforme.","Colocar dorada entera limpia sin escamar encima de la cama de sal gruesa.","Cubrir la dorada con el resto de la sal gruesa, apretando bien para formar una costra compacta.","Hornear la bandeja en el centro del horno hasta que la costra esté dura y ligeramente dorada.","Picar ajo.","Cortar tomate maduro en trozos.","Añadir el tomate, el ajo, ñora hidratada, almendras tostadas y pan frito al vaso de la batidora.","Añadir vinagre de vino y aceite de oliva al vaso de la batidora.","Triturar todo hasta obtener una salsa romesco fina y homogénea.","Retirar la bandeja del horno y dejar reposar la costra de sal intacta.","Romper la costra de sal golpeándola con el dorso de una cuchara.","Retirar la costra junto con la piel de la dorada con cuidado, sin romper la carne.","Separar los lomos de la dorada limpiándolos de espinas.","Servir los lomos de dorada en el plato con la salsa romesco aparte."}', 'Dorada entera horneada en costra de sal, con la carne jugosa y una salsa romesco de contraste.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Para la dorada, cubre el pescado con la sal gruesa y hornea a 190-200°C durante 45 minutos. Mientras, asa los tomates y ajos para la salsa romesco en el mismo horno, luego tritúralos con las ñoras, almendras, pan frito, vinagre y aceite hasta obtener una salsa homogénea."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 220 °C.","minutes":10,"kind":"pasivo","part":"principal"},{"text":"Extender la mitad de {{Sal gruesa}} en una bandeja formando una capa uniforme.","minutes":2,"kind":"prep","part":"principal"},{"text":"Colocar {{Dorada entera limpia sin escamar}} encima de la cama de sal gruesa.","minutes":1,"kind":"prep","part":"principal"},{"text":"Cubrir la dorada con el resto de la sal gruesa, apretando bien para formar una costra compacta.","minutes":2,"kind":"prep","part":"principal"},{"text":"Hornear la bandeja en el centro del horno hasta que la costra esté dura y ligeramente dorada.","minutes":28,"kind":"pasivo","part":"principal"},{"text":"Picar {{Ajo}}.","minutes":1,"kind":"paralelo","part":"salsa","during":4},{"text":"Cortar {{Tomate maduro}} en trozos.","minutes":1,"kind":"paralelo","part":"salsa","during":4},{"text":"Añadir el tomate, el ajo, {{Ñora hidratada}}, {{Almendras tostadas}} y {{Pan frito}} al vaso de la batidora.","minutes":1,"kind":"paralelo","part":"salsa","during":4},{"text":"Añadir {{Vinagre de vino}} y {{Aceite de oliva}} al vaso de la batidora.","minutes":1,"kind":"paralelo","part":"salsa","during":4},{"text":"Triturar todo hasta obtener una salsa romesco fina y homogénea.","minutes":2,"kind":"paralelo","part":"salsa","during":4},{"text":"Retirar la bandeja del horno y dejar reposar la costra de sal intacta.","minutes":5,"kind":"espera","part":"principal"},{"text":"Romper la costra de sal golpeándola con el dorso de una cuchara.","minutes":1,"kind":"activo","part":"principal"},{"text":"Retirar la costra junto con la piel de la dorada con cuidado, sin romper la carne.","minutes":2,"kind":"activo","part":"principal"},{"text":"Separar los lomos de la dorada limpiándolos de espinas.","minutes":2,"kind":"activo","part":"principal"},{"text":"Servir los lomos de dorada en el plato con la salsa romesco aparte.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, true),
  ('pescados_069', 'Emperador a la plancha con salsa tártara', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 414, 32, 2, 31, 2, false, false, '{"pescado","huevo","mostaza","sulfitos"}', '[{"name":"Rodajas de emperador","amount":320,"unit":"g"},{"name":"Mayonesa","amount":45,"unit":"g"},{"name":"Pepinillos en vinagre","amount":20,"unit":"g"},{"name":"Alcaparras","amount":15,"unit":"g"},{"name":"Mostaza de Dijon","amount":8,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Picar muy fino pepinillos en vinagre.","Picar muy finas alcaparras.","Picar muy fino perejil.","Mezclar mayonesa con los pepinillos, las alcaparras y el perejil picados.","Añadir mostaza de dijon a la mezcla y remover hasta que esté homogénea.","Reservar la salsa tártara en la nevera hasta el momento de servir.","Salpimentar rodajas de emperador por ambas caras.","Calentar plancha con aceite de oliva a fuego fuerte hasta que humee ligeramente.","Colocar las rodajas de emperador en la plancha y cocinar 3 min por el primer lado sin moverlas.","Dar la vuelta a las rodajas de emperador y cocinar 3 min más hasta que estén doradas y jugosas.","Retirar las rodajas de emperador de la plancha y dejar reposar 1 min.","Cortar limón en gajos.","Servir las rodajas de emperador con la salsa tártara aparte y los gajos de limón."}', 'Emperador a la plancha con una salsa tártara casera de pepinillos y alcaparras.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Rocía las rodajas de emperador con un poco de aceite de oliva y cocínalas durante 10-12 minutos, volteándolas a mitad, hasta que estén doradas por fuera y jugosas por dentro. Prepara la salsa tártara mientras el pescado se cocina."}]'::jsonb, '{}', NULL, NULL, NULL, '{"encurtido"}', NULL, '{}'::main_protein[], false, '[{"text":"Picar muy fino {{Pepinillos en vinagre}}.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Picar muy finas {{Alcaparras}}.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Picar muy fino {{Perejil}}.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Mezclar {{Mayonesa}} con los pepinillos, las alcaparras y el perejil picados.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Añadir {{Mostaza de Dijon}} a la mezcla y remover hasta que esté homogénea.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Reservar la salsa tártara en la nevera hasta el momento de servir.","minutes":5,"kind":"espera","part":"salsa"},{"text":"Salpimentar {{Rodajas de emperador}} por ambas caras.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} con {{Aceite de oliva}} a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo","part":"principal"},{"text":"Colocar las rodajas de emperador en la plancha y cocinar 3 min por el primer lado sin moverlas.","minutes":3,"kind":"pasivo","part":"principal"},{"text":"Dar la vuelta a las rodajas de emperador y cocinar 3 min más hasta que estén doradas y jugosas.","minutes":3,"kind":"pasivo","part":"principal"},{"text":"Retirar las rodajas de emperador de la plancha y dejar reposar 1 min.","minutes":1,"kind":"espera","part":"principal"},{"text":"Cortar {{Limón}} en gajos.","minutes":1,"kind":"prep","part":"principal"},{"text":"Servir las rodajas de emperador con la salsa tártara aparte y los gajos de limón.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, true),
  ('pescados_070', 'Chipirones encebollados', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 35, 'normal', 'all', 359, 31, 16, 15, 2, true, true, '{"moluscos","sulfitos"}', '[{"name":"Chipirones limpios","amount":400,"unit":"g"},{"name":"Cebolla","amount":220,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar cebolla en juliana fina.","Picar ajo fino.","Picar perejil fino y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Añadir la cebolla, el ajo y laurel a la sartén.","Sofreír a fuego suave hasta que la cebolla esté muy tierna y dulce.","Subir el fuego a fuego fuerte y añadir chipirones limpios a la sartén.","Saltear hasta que los chipirones suelten su agua.","Verter vino blanco y remover.","Reducir a fuego medio-fuerte hasta que el vino se evapore casi por completo.","Bajar el fuego a fuego suave y cocer hasta que los chipirones estén tiernos y la salsa melosa.","Retirar el laurel y añadir el perejil picado.","Servir los chipirones bien calientes."}', 'Chipirones tiernos cocinados a fuego lento con cebolla muy pochada.', '[{"appliance":"horno","time":40,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en una cazuela apta para horno. Añade los chipirones, el vino blanco y el laurel, tapa y hornea a 180°C durante 25-30 minutos hasta que los chipirones estén tiernos."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríelos con aceite. Incorpora los chipirones, el vino y el laurel, y cocina a temperatura Varoma, giro inverso, velocidad cuchara durante 20-25 minutos hasta que estén tiernos y la salsa reducida."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo en la olla abierta. Agrega los chipirones, el vino y el laurel, cierra la olla y cocina a presión alta durante 4-5 minutos. Deja despresurizar naturalmente para una textura perfecta."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Cebolla}} en juliana fina.","minutes":3,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Añadir la cebolla, el ajo y {{Laurel}} a la sartén.","minutes":1,"kind":"activo"},{"text":"Sofreír a fuego suave hasta que la cebolla esté muy tierna y dulce.","minutes":18,"kind":"pasivo"},{"text":"Subir el fuego a fuego fuerte y añadir {{Chipirones limpios}} a la sartén.","minutes":1,"kind":"activo"},{"text":"Saltear hasta que los chipirones suelten su agua.","minutes":3,"kind":"activo"},{"text":"Verter {{Vino blanco}} y remover.","minutes":1,"kind":"activo"},{"text":"Reducir a fuego medio-fuerte hasta que el vino se evapore casi por completo.","minutes":4,"kind":"activo"},{"text":"Bajar el fuego a fuego suave y cocer hasta que los chipirones estén tiernos y la salsa melosa.","minutes":5,"kind":"pasivo"},{"text":"Retirar el laurel y añadir el perejil picado.","minutes":1,"kind":"activo"},{"text":"Servir los chipirones bien calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, true),
  ('pescados_071', 'Sepia a la plancha con ajo y perejil', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 306, 30, 8, 15, 2, true, true, '{"moluscos"}', '[{"name":"Sepia limpia","amount":400,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar sepia limpia en trozos regulares y secar bien con papel de cocina para evitar que suelte agua en la plancha.","Picar ajo muy fino.","Picar perejil muy fino.","Calentar plancha a fuego fuerte con aceite de oliva hasta que humee ligeramente.","Marcar la sepia 2 min sin moverla, hasta que se dore por debajo.","Dar la vuelta a la sepia y marcar 2 min más por el otro lado hasta que esté dorada y tierna.","Añadir el ajo picado sobre la sepia durante el último minuto de cocción, sin dejar de vigilar para que no se queme.","Retirar la sepia del fuego y espolvorear con el perejil picado.","Exprimir limón por encima y servir inmediatamente."}', 'Sepia a la plancha con ajo y perejil, marcada por fuera y tierna por dentro.', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina la sepia marinada con ajo, perejil y aceite durante 12-15 minutos, volteándola a mitad, para lograr un exterior dorado y un interior tierno."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 220°C con la función grill. Coloca la sepia marinada en una bandeja y cocina 15-20 minutos, dándole la vuelta, hasta que esté bien dorada y jugosa, imitando el efecto plancha."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Sepia limpia}} en trozos regulares y secar bien con papel de cocina para evitar que suelte agua en la plancha.","minutes":3,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} muy fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte con {{Aceite de oliva|chorrito}} hasta que humee ligeramente.","minutes":1,"kind":"activo"},{"text":"Marcar la sepia 2 min sin moverla, hasta que se dore por debajo.","minutes":2,"kind":"activo"},{"text":"Dar la vuelta a la sepia y marcar 2 min más por el otro lado hasta que esté dorada y tierna.","minutes":2,"kind":"activo"},{"text":"Añadir el ajo picado sobre la sepia durante el último minuto de cocción, sin dejar de vigilar para que no se queme.","minutes":1,"kind":"activo"},{"text":"Retirar la sepia del fuego y espolvorear con el perejil picado.","minutes":1,"kind":"emplatado"},{"text":"Exprimir {{Limón}} por encima y servir inmediatamente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL, NULL),
  ('pescados_072', 'Mejillones a la marinera', 'pescados', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 313, 20, 14, 16, 2, true, true, '{"moluscos","sulfitos"}', '[{"name":"Mejillones frescos","amount":800,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Vino blanco","amount":80,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Limpiar mejillones frescos: retirar las barbas tirando hacia la punta y raspar las conchas con un cuchillo.","Descartar los mejillones que estén abiertos y no se cierren al golpearlos suavemente.","Picar cebolla muy fina.","Picar ajo muy fino.","Calentar aceite de oliva en una cazuela amplia a fuego medio.","Sofreír la cebolla picada y el ajo picado a fuego suave hasta que estén tiernos.","Añadir pimentón dulce y remover durante unos segundos hasta que se integre.","Añadir tomate triturado y cocer a fuego medio hasta que la salsa reduzca y espese.","Añadir vino blanco y laurel; llevar a ebullición.","Picar perejil fino y reservar.","Incorporar los mejillones limpios, tapar la cazuela y cocinar a fuego fuerte hasta que se abran todos.","Descartar los mejillones que no se hayan abierto.","Espolvorear el perejil picado sobre los mejillones y servir en la misma cazuela con el caldo."}', 'Mejillones abiertos en una salsa marinera de tomate, vino blanco y pimentón.', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríe con aceite. Añade el tomate, vino y especias. Coloca los mejillones en el Varoma y cocina al vapor mientras la salsa se integra en el vaso, o cocínalos directamente en el vaso."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla abierta. Añade el resto de ingredientes y los mejillones. Cierra la olla y cocina a presión alta 2-3 minutos desde que sube la válvula. Despresuriza y sirve."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Limpiar {{Mejillones frescos}}: retirar las barbas tirando hacia la punta y raspar las conchas con un cuchillo.","minutes":5,"kind":"prep"},{"text":"Descartar los mejillones que estén abiertos y no se cierren al golpearlos suavemente.","minutes":1,"kind":"prep"},{"text":"Picar {{Cebolla}} muy fina.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela amplia a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada y el ajo picado a fuego suave hasta que estén tiernos.","minutes":9,"kind":"pasivo"},{"text":"Añadir {{Pimentón dulce|pizca}} y remover durante unos segundos hasta que se integre.","minutes":1,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y cocer a fuego medio hasta que la salsa reduzca y espese.","minutes":5,"kind":"pasivo"},{"text":"Añadir {{Vino blanco}} y {{Laurel}}; llevar a ebullición.","minutes":2,"kind":"activo"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"paralelo","during":8},{"text":"Incorporar los mejillones limpios, tapar la cazuela y cocinar a fuego fuerte hasta que se abran todos.","minutes":5,"kind":"activo"},{"text":"Descartar los mejillones que no se hayan abierto.","minutes":1,"kind":"activo"},{"text":"Espolvorear el perejil picado sobre los mejillones y servir en la misma cazuela con el caldo.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, true),
  ('pescados_073', 'Almejas a la marinera', 'pescados', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 241, 14, 6, 14, 2, true, true, '{"moluscos","gluten","sulfitos","pescado"}', '[{"name":"Almejas frescas","amount":600,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Harina","amount":8,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Caldo de pescado","amount":50,"unit":"ml"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Sumergir almejas frescas en agua fría con sal durante 60 min para que suelten la arena.","Escurrir las almejas y aclarar bajo el grifo.","Picar ajo fino.","Picar perejil fino.","Calentar aceite de oliva en una cazuela baja a fuego medio.","Sofreír el ajo picado hasta que esté dorado sin llegar a quemarse.","Añadir harina y remover sin parar hasta que se integre con el ajo.","Verter vino blanco removiendo para disolver los grumos.","Añadir caldo de pescado y remover hasta que la salsa sea homogénea.","Llevar a ebullición y cocer a fuego medio hasta que la salsa espese ligeramente, unos 2 min.","Incorporar las almejas escurridas, subir a fuego fuerte y tapar la cazuela.","Cocer tapado, agitando la cazuela a mitad, hasta que todas las almejas estén abiertas.","Retirar las almejas que no se hayan abierto.","Espolvorear el perejil picado y servir en la misma cazuela bien caliente."}', 'Almejas abiertas en una salsa dorada de ajo, perejil y vino blanco.', '[{"appliance":"thermomix","time":20,"difficulty":"normal","prepSummary":"Sofríe el ajo picado, añade la harina, el vino blanco y el caldo de pescado. Incorpora las almejas y cocina a 100°C con giro inverso y velocidad cuchara durante 6-8 minutos, o hasta que se abran, finalizando con perejil picado."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Sumergir {{Almejas frescas}} en agua fría con sal durante 60 min para que suelten la arena.","minutes":60,"kind":"espera"},{"text":"Escurrir las almejas y aclarar bajo el grifo.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":2,"kind":"prep"},{"text":"Picar {{Perejil}} fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela baja a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado hasta que esté dorado sin llegar a quemarse.","minutes":3,"kind":"activo"},{"text":"Añadir {{Harina}} y remover sin parar hasta que se integre con el ajo.","minutes":1,"kind":"activo"},{"text":"Verter {{Vino blanco}} removiendo para disolver los grumos.","minutes":1,"kind":"activo"},{"text":"Añadir {{Caldo de pescado}} y remover hasta que la salsa sea homogénea.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición y cocer a fuego medio hasta que la salsa espese ligeramente, unos 2 min.","minutes":2,"kind":"pasivo"},{"text":"Incorporar las almejas escurridas, subir a fuego fuerte y tapar la cazuela.","minutes":1,"kind":"activo"},{"text":"Cocer tapado, agitando la cazuela a mitad, hasta que todas las almejas estén abiertas.","minutes":4,"kind":"activo"},{"text":"Retirar las almejas que no se hayan abierto.","minutes":1,"kind":"prep"},{"text":"Espolvorear el perejil picado y servir en la misma cazuela bien caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, true),
  ('pescados_074', 'Berberechos al natural', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 145, 22, 3, 3, 2, true, false, '{"moluscos","sulfitos"}', '[{"name":"Berberechos frescos","amount":500,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":40,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Sal gorda","amount":20,"unit":"g"},{"name":"Agua","amount":1000,"unit":"ml"}]'::jsonb, '{"Disolver sal gorda en agua fría en un bol amplio hasta que se integre.","Sumergir berberechos frescos en el agua con sal y dejar reposar para que suelten la arena.","Escurrir los berberechos y enjuagarlos bien bajo el grifo con agua fría.","Machacar ajo con la piel con el lateral de un cuchillo.","Colocar el ajo machacado y laurel en una cazuela amplia.","Verter vino blanco en la cazuela y llevar a ebullición a fuego fuerte.","Incorporar los berberechos escurridos de golpe y tapar la cazuela.","Cocer a fuego fuerte, agitando la cazuela una vez a mitad, hasta que todas las conchas se abran.","Retirar del fuego en cuanto estén abiertas para que no queden gomosos.","Descartar los berberechos que no se hayan abierto.","Servir inmediatamente en la misma cazuela con su propio jugo."}', 'Berberechos abiertos al vapor con ajo, laurel y un chorrito de vino blanco, con todo su jugo de mar.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Sofríe el ajo, añade el vino, agua, laurel y sal. Coloca los berberechos en el recipiente Varoma y cocina al vapor hasta que se abran, aprovechando el caldo aromático en el vaso."},{"appliance":"vaporera","time":15,"difficulty":"facil","prepSummary":"Hierve el agua con el vino, ajo, laurel y sal en la base de la vaporera. Cocina los berberechos en la cesta de vapor hasta que se abran, permitiendo que absorban los aromas del caldo."},{"appliance":"olla_express","time":10,"difficulty":"facil","prepSummary":"Introduce todos los ingredientes en la olla a presión. Cocina a fuego medio-bajo por 1-2 minutos desde que sube la válvula, liberando la presión inmediatamente para evitar sobrecocer los berberechos."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Disolver {{Sal gorda}} en {{Agua}} fría en un bol amplio hasta que se integre.","minutes":2,"kind":"prep"},{"text":"Sumergir {{Berberechos frescos}} en el agua con sal y dejar reposar para que suelten la arena.","minutes":60,"kind":"espera"},{"text":"Escurrir los berberechos y enjuagarlos bien bajo el grifo con agua fría.","minutes":2,"kind":"prep"},{"text":"Machacar {{Ajo}} con la piel con el lateral de un cuchillo.","minutes":1,"kind":"prep"},{"text":"Colocar el ajo machacado y {{Laurel}} en una cazuela amplia.","minutes":1,"kind":"prep"},{"text":"Verter {{Vino blanco}} en la cazuela y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Incorporar los berberechos escurridos de golpe y tapar la cazuela.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego fuerte, agitando la cazuela una vez a mitad, hasta que todas las conchas se abran.","minutes":3,"kind":"activo"},{"text":"Retirar del fuego en cuanto estén abiertas para que no queden gomosos.","minutes":1,"kind":"activo"},{"text":"Descartar los berberechos que no se hayan abierto.","minutes":1,"kind":"activo"},{"text":"Servir inmediatamente en la misma cazuela con su propio jugo.","minutes":1,"kind":"emplatado"}]'::jsonb, true, 'especial', NULL, 'sarten', NULL, NULL),
  ('pescados_075', 'Fritura de pescado variado', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'verano', 420, 30, 22, 24, 2, true, false, '{"pescado","moluscos","gluten"}', '[{"name":"Boquerones limpios","amount":200,"unit":"g"},{"name":"Calamar en anillas","amount":150,"unit":"g"},{"name":"Salmonetes pequeños","amount":150,"unit":"g"},{"name":"Harina fina de trigo","amount":100,"unit":"g"},{"name":"Aceite de oliva suave","amount":400,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Sal","amount":5,"unit":"g"}]'::jsonb, '{"Secar boquerones limpios con papel de cocina hasta eliminar toda la humedad.","Secar calamar en anillas con papel de cocina hasta eliminar toda la humedad.","Secar salmonetes pequeños con papel de cocina hasta eliminar toda la humedad.","Salar sal todo el pescado y el calamar por ambas caras.","Extender harina fina de trigo en una bandeja amplia.","Pasar cada pieza de pescado y calamar por la harina, sacudiendo bien el exceso.","Calentar aceite de oliva suave en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír el calamar en anillas en tandas pequeñas, sin amontonar, hasta que estén doradas.","Retirar el calamar con una espumadera a un plato con papel absorbente.","Freír los boquerones en tandas pequeñas, sin amontonar, hasta que estén dorados y crujientes.","Retirar los boquerones a papel absorbente y salar al instante de sacarlos del aceite.","Freír los salmonetes en tandas pequeñas, sin amontonar, hasta que estén dorados y crujientes.","Retirar los salmonetes a papel absorbente y salar al instante de sacarlos del aceite.","Cortar limón en gajos.","Servir todo el pescado junto, muy caliente, acompañado de los gajos de limón."}', 'Fritura variada de boquerones, calamar y salmonetes, crujiente por fuera y jugosa por dentro, con limón.', '[{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Enharina ligeramente el pescado, rocía con un poco de aceite y cocina en tandas durante 12-15 minutos cada una, volteando a mitad, hasta que esté dorado y crujiente."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C (con ventilador si es posible). Enharina el pescado, rocía con aceite y distribúyelo en una bandeja con papel de horno. Hornea durante 20-25 minutos, volteando a mitad, hasta que esté dorado y crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Secar {{Boquerones limpios}} con papel de cocina hasta eliminar toda la humedad.","minutes":2,"kind":"prep"},{"text":"Secar {{Calamar en anillas}} con papel de cocina hasta eliminar toda la humedad.","minutes":1,"kind":"prep"},{"text":"Secar {{Salmonetes pequeños}} con papel de cocina hasta eliminar toda la humedad.","minutes":1,"kind":"prep"},{"text":"Salar {{Sal|gusto}} todo el pescado y el calamar por ambas caras.","minutes":1,"kind":"prep"},{"text":"Extender {{Harina fina de trigo}} en una bandeja amplia.","minutes":1,"kind":"prep"},{"text":"Pasar cada pieza de pescado y calamar por la harina, sacudiendo bien el exceso.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva suave}} en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","minutes":3,"kind":"activo"},{"text":"Freír el calamar en anillas en tandas pequeñas, sin amontonar, hasta que estén doradas.","minutes":2,"kind":"activo"},{"text":"Retirar el calamar con una espumadera a un plato con papel absorbente.","minutes":1,"kind":"activo"},{"text":"Freír los boquerones en tandas pequeñas, sin amontonar, hasta que estén dorados y crujientes.","minutes":2,"kind":"activo"},{"text":"Retirar los boquerones a papel absorbente y salar al instante de sacarlos del aceite.","minutes":1,"kind":"activo"},{"text":"Freír los salmonetes en tandas pequeñas, sin amontonar, hasta que estén dorados y crujientes.","minutes":3,"kind":"activo"},{"text":"Retirar los salmonetes a papel absorbente y salar al instante de sacarlos del aceite.","minutes":1,"kind":"activo"},{"text":"Cortar {{Limón}} en gajos.","minutes":1,"kind":"prep"},{"text":"Servir todo el pescado junto, muy caliente, acompañado de los gajos de limón.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, NULL),
  ('pescados_076', 'Croquetas de bacalao con alioli', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 70, 'normal', 'all', 460, 22, 34, 26, 4, true, false, '{"pescado","gluten","lactosa","huevo"}', '[{"name":"Bacalao desalado desmigado","amount":250,"unit":"g"},{"name":"Leche entera","amount":500,"unit":"ml"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Harina de trigo","amount":60,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Pan rallado","amount":100,"unit":"g"},{"name":"Aceite de oliva suave","amount":400,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de girasol","amount":150,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Picar cebolla muy fina.","Fundir mantequilla en una sartén a fuego suave.","Sofreír la cebolla picada en la mantequilla fundida hasta que esté transparente.","Añadir bacalao desalado desmigado y sofreír removiendo durante 2 min.","Incorporar harina de trigo y remover sin parar durante 2 min hasta que no coja color.","Calentar leche entera en un cazo a fuego suave hasta que esté caliente sin llegar a hervir.","Verter la leche caliente sobre la mezcla poco a poco sin dejar de remover hasta obtener una bechamel espesa y sin grumos.","Añadir nuez moscada y remover para integrar.","Cocer la bechamel a fuego muy suave removiendo con frecuencia hasta que esté muy espesa y se despegue de los bordes.","Extender la masa en una bandeja y cubrir con film a piel para que no forme costra.","Enfriar la masa en la nevera hasta que esté completamente fría y firme.","Batir huevo en un bol hondo.","Poner pan rallado en otro bol o bandeja plana.","Formar las croquetas con las manos tomando porciones de masa fría y dándoles forma alargada.","Pasar cada croqueta por el huevo batido y escurrir el exceso.","Rebozar cada croqueta en el pan rallado presionando bien para que quede bien cubierta.","Pelar ajo y retirar el germen interior.","Majar el ajo en un mortero con una pizca de sal hasta obtener una pasta fina.","Añadir aceite de girasol en hilo muy fino sobre el ajo majado sin dejar de remover en círculos hasta emulsionar el alioli.","Reservar el alioli en un bol tapado en la nevera.","Calentar aceite de oliva suave en una sartén honda a fuego fuerte hasta alcanzar unos 180 °C.","Freír las croquetas en tandas sin amontonarlas hasta que estén doradas por todos los lados.","Escurrir las croquetas sobre papel absorbente.","Servir las croquetas calientes con el alioli aparte."}', 'Croquetas cremosas de bacalao desmigado con corteza dorada y crujiente, acompañadas de alioli casero.', '[{"appliance":"thermomix","time":60,"difficulty":"normal","prepSummary":"La Thermomix es excelente para preparar la masa de las croquetas y el alioli. Sofríe la cebolla, elabora una bechamel perfecta con el bacalao y luego el alioli de forma rápida y sin esfuerzo, controlando temperatura y velocidad para evitar grumos."},{"appliance":"airfryer","time":70,"difficulty":"normal","prepSummary":"Para una versión más ligera, cocina las croquetas en la airfryer a 190-200°C durante 15-20 minutos, dándoles la vuelta a mitad. Rocíalas ligeramente con aceite para un exterior más crujiente, aunque la textura será menos jugosa que la fritura tradicional."},{"appliance":"horno","time":75,"difficulty":"normal","prepSummary":"Para una alternativa horneada, precalienta el horno a 200°C. Hornea las croquetas durante 20-25 minutos, o hasta que estén doradas, dándoles la vuelta a mitad. Pulverízalas con un poco de aceite para mejorar la capa exterior."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Cebolla}} muy fina.","minutes":3,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en una sartén a fuego suave.","minutes":2,"kind":"activo"},{"text":"Sofreír la cebolla picada en la mantequilla fundida hasta que esté transparente.","minutes":8,"kind":"activo"},{"text":"Añadir {{Bacalao desalado desmigado}} y sofreír removiendo durante 2 min.","minutes":2,"kind":"activo"},{"text":"Incorporar {{Harina de trigo}} y remover sin parar durante 2 min hasta que no coja color.","minutes":2,"kind":"activo"},{"text":"Calentar {{Leche entera}} en un cazo a fuego suave hasta que esté caliente sin llegar a hervir.","minutes":4,"kind":"activo"},{"text":"Verter la leche caliente sobre la mezcla poco a poco sin dejar de remover hasta obtener una bechamel espesa y sin grumos.","minutes":5,"kind":"activo"},{"text":"Añadir {{Nuez moscada|pizca}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Cocer la bechamel a fuego muy suave removiendo con frecuencia hasta que esté muy espesa y se despegue de los bordes.","minutes":10,"kind":"activo"},{"text":"Extender la masa en una bandeja y cubrir con film a piel para que no forme costra.","minutes":2,"kind":"prep"},{"text":"Enfriar la masa en la nevera hasta que esté completamente fría y firme.","minutes":180,"kind":"espera"},{"text":"Batir {{Huevo}} en un bol hondo.","minutes":1,"kind":"prep"},{"text":"Poner {{Pan rallado}} en otro bol o bandeja plana.","minutes":1,"kind":"prep"},{"text":"Formar las croquetas con las manos tomando porciones de masa fría y dándoles forma alargada.","minutes":8,"kind":"prep"},{"text":"Pasar cada croqueta por el huevo batido y escurrir el exceso.","minutes":3,"kind":"prep"},{"text":"Rebozar cada croqueta en el pan rallado presionando bien para que quede bien cubierta.","minutes":3,"kind":"prep"},{"text":"Pelar {{Ajo}} y retirar el germen interior.","minutes":2,"kind":"prep"},{"text":"Majar el ajo en un mortero con una pizca de sal hasta obtener una pasta fina.","minutes":3,"kind":"activo"},{"text":"Añadir {{Aceite de girasol}} en hilo muy fino sobre el ajo majado sin dejar de remover en círculos hasta emulsionar el alioli.","minutes":5,"kind":"activo"},{"text":"Reservar el alioli en un bol tapado en la nevera.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva suave|abundante}} en una sartén honda a fuego fuerte hasta alcanzar unos 180 °C.","minutes":3,"kind":"activo"},{"text":"Freír las croquetas en tandas sin amontonarlas hasta que estén doradas por todos los lados.","minutes":3,"kind":"activo"},{"text":"Escurrir las croquetas sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Servir las croquetas calientes con el alioli aparte.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, true),
  ('pescados_077', 'Merluza a la sidra', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 35, 'normal', 'all', 320, 30, 12, 14, 2, true, true, '{"pescado","moluscos","sulfitos","gluten"}', '[{"name":"Merluza en lomos","amount":350,"unit":"g"},{"name":"Almejas","amount":150,"unit":"g"},{"name":"Sidra natural","amount":150,"unit":"ml"},{"name":"Manzana ácida","amount":100,"unit":"g"},{"name":"Cebolla","amount":70,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Harina de trigo","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Sumergir almejas en agua fría con sal durante 30 min para que suelten la arena.","Picar cebolla muy fina.","Picar ajo muy fino.","Pelar manzana ácida y laminar en láminas finas.","Picar perejil fino y reservar.","Calentar aceite de oliva en una cazuela a fuego suave.","Sofreír la cebolla y el ajo picados a fuego suave hasta que estén blandos y transparentes.","Añadir harina de trigo y remover sin parar hasta que se integre con el sofrito.","Verter sidra natural poco a poco removiendo sin parar hasta que la salsa ligue sin grumos.","Incorporar la manzana laminada y cocer a fuego medio hasta que esté tierna.","Escurrir las almejas del agua de remojo.","Salpimentar merluza en lomos y colocar sobre la salsa en la cazuela.","Añadir las almejas escurridas alrededor de los lomos de merluza.","Tapar la cazuela y cocer a fuego suave, moviendo en círculos, hasta que las almejas se abran.","Espolvorear el perejil picado sobre el pescado y servir en la misma cazuela."}', 'Merluza cocinada en una salsa dorada de sidra y manzana, con almejas abiertas en su punto.', '[{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Prepara un sofrito con cebolla, ajo y manzana en una sartén apta para horno. Añade la sidra, coloca la merluza y las almejas, y hornea a 190°C durante 15-20 minutos hasta que el pescado esté hecho y las almejas abiertas."},{"appliance":"thermomix","time":30,"difficulty":"normal","prepSummary":"Prepara un sofrito con cebolla, ajo y manzana en el vaso. Añade la sidra, coloca la merluza y las almejas en el Varoma y cocina todo simultáneamente a temperatura Varoma, velocidad cuchara, durante 15-20 minutos."},{"appliance":"olla_express","time":20,"difficulty":"normal","prepSummary":"Sofríe la cebolla, ajo y manzana en la olla. Añade la sidra, la merluza y las almejas. Cierra la olla y cocina a presión durante 3-4 minutos desde que sube la válvula. Despresuriza y sirve."}]'::jsonb, '{}', NULL, NULL, NULL, '{"fruta"}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Sumergir {{Almejas}} en agua fría con sal durante 30 min para que suelten la arena.","minutes":30,"kind":"espera"},{"text":"Picar {{Cebolla}} muy fina.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Pelar {{Manzana ácida}} y laminar en láminas finas.","minutes":2,"kind":"prep"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una cazuela a fuego suave.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el ajo picados a fuego suave hasta que estén blandos y transparentes.","minutes":8,"kind":"pasivo"},{"text":"Añadir {{Harina de trigo}} y remover sin parar hasta que se integre con el sofrito.","minutes":1,"kind":"activo"},{"text":"Verter {{Sidra natural}} poco a poco removiendo sin parar hasta que la salsa ligue sin grumos.","minutes":2,"kind":"activo"},{"text":"Incorporar la manzana laminada y cocer a fuego medio hasta que esté tierna.","minutes":5,"kind":"pasivo"},{"text":"Escurrir las almejas del agua de remojo.","minutes":1,"kind":"prep"},{"text":"Salpimentar {{Merluza en lomos}} y colocar sobre la salsa en la cazuela.","minutes":1,"kind":"activo"},{"text":"Añadir las almejas escurridas alrededor de los lomos de merluza.","minutes":1,"kind":"activo"},{"text":"Tapar la cazuela y cocer a fuego suave, moviendo en círculos, hasta que las almejas se abran.","minutes":9,"kind":"pasivo"},{"text":"Espolvorear el perejil picado sobre el pescado y servir en la misma cazuela.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, NULL)
