  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('pescados_078', 'Bacalao con pisto y huevo', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'verano', 390, 32, 16, 20, 2, true, true, '{"pescado","huevo"}', '[{"name":"Bacalao desalado en lomos","amount":300,"unit":"g"},{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Berenjena","amount":150,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"}]'::jsonb, '{"Cortar cebolla en dados pequeños.","Picar ajo fino.","Cortar pimiento rojo y pimiento verde en dados pequeños.","Cortar calabacín y berenjena en dados pequeños.","Calentar aceite de oliva en una sartén amplia a fuego medio.","Sofreír la cebolla y el ajo picado hasta que estén transparentes.","Añadir el pimiento rojo y el pimiento verde y sofreír hasta que se ablanden.","Añadir el calabacín y la berenjena y sofreír removiendo de vez en cuando.","Añadir tomate triturado, remover y tapar la sartén.","Cocer a fuego suave hasta que las verduras estén tiernas y el pisto espese.","Calentar plancha a fuego fuerte con aceite de oliva.","Dorar bacalao desalado en lomos por el lado de la piel hasta que esté dorado.","Dar la vuelta a los lomos y dorar por el otro lado hasta que la carne esté opaca.","Retirar los lomos y reservar.","Calentar aceite de oliva en sartén a fuego medio-fuerte.","Freír huevo uno a uno hasta que la clara esté cuajada y la yema líquida.","Repartir el pisto en 2 platos hondos o cazuelitas individuales.","Colocar un lomo de bacalao sobre el pisto en cada plato.","Colocar un huevo frito encima del bacalao y servir enseguida."}', 'Lomo de bacalao sobre un pisto de verduras coloridas, coronado con un huevo frito de yema rota.', '[{"appliance":"airfryer","time":35,"difficulty":"normal","prepSummary":"Prepara el pisto cocinando las verduras troceadas con un poco de aceite a 180°C durante 20-25 minutos, removiendo a mitad. Luego, cocina el bacalao a 190°C durante 10-12 minutos y, si lo deseas, hornea un huevo en un ramekin junto a ellos."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Asa el pisto mezclando todas las verduras troceadas con aceite y tomate a 180-190°C durante 30-40 minutos. Añade el bacalao en los últimos 15-20 minutos y, si lo deseas, hornea un huevo en un ramekin junto a ellos."},{"appliance":"thermomix","time":40,"difficulty":"facil","prepSummary":"Prepara el pisto en el vaso, troceando y sofriendo las verduras. Cocina el bacalao y los huevos al vapor en el recipiente Varoma mientras el pisto se termina de hacer en el vaso, a temperatura Varoma."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sofríe las verduras del pisto en la olla express, añade el tomate y cocina a presión durante 8-10 minutos. Abre, introduce el bacalao y cocina 2-3 minutos más. El huevo se puede freír aparte o escalfar rápidamente."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['huevo']::main_protein[], false, '[{"text":"Cortar {{Cebolla}} en dados pequeños.","minutes":2,"kind":"prep","part":"principal"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep","part":"principal"},{"text":"Cortar {{Pimiento rojo}} y {{Pimiento verde}} en dados pequeños.","minutes":2,"kind":"prep","part":"principal"},{"text":"Cortar {{Calabacín}} y {{Berenjena}} en dados pequeños.","minutes":3,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una sartén amplia a fuego medio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Sofreír la cebolla y el ajo picado hasta que estén transparentes.","minutes":5,"kind":"activo","part":"principal"},{"text":"Añadir el pimiento rojo y el pimiento verde y sofreír hasta que se ablanden.","minutes":5,"kind":"activo","part":"principal"},{"text":"Añadir el calabacín y la berenjena y sofreír removiendo de vez en cuando.","minutes":10,"kind":"activo","part":"principal"},{"text":"Añadir {{Tomate triturado}}, remover y tapar la sartén.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cocer a fuego suave hasta que las verduras estén tiernas y el pisto espese.","minutes":15,"kind":"pasivo","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Dorar {{Bacalao desalado en lomos}} por el lado de la piel hasta que esté dorado.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Dar la vuelta a los lomos y dorar por el otro lado hasta que la carne esté opaca.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Retirar los lomos y reservar.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva|abundante}} en {{@Sartén}} a fuego medio-fuerte.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Freír {{Huevo}} uno a uno hasta que la clara esté cuajada y la yema líquida.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Repartir el pisto en 2 platos hondos o cazuelitas individuales.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Colocar un lomo de bacalao sobre el pisto en cada plato.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Colocar un huevo frito encima del bacalao y servir enseguida.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('pescados_079', 'Tartar de salmón con soja y aguacate', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 25, 'normal', 'all', 380, 24, 8, 28, 2, false, false, '{"pescado","soja","sesamo","gluten"}', '[{"name":"Lomo de salmón fresco de calidad sashimi","amount":280,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Salsa de soja","amount":25,"unit":"ml"},{"name":"Aceite de sésamo","amount":8,"unit":"ml"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Semillas de sésamo","amount":5,"unit":"g"},{"name":"Cilantro fresco","amount":5,"unit":"g"}]'::jsonb, '{"Cortar lomo de salmón fresco de calidad sashimi en dados de medio centímetro, regulares y limpios.","Pelar aguacate y cortar en dados del mismo tamaño que el salmón.","Exprimir lima y reservar el zumo.","Rociar los dados de aguacate con la mitad del zumo de lima para evitar que se oxide.","Picar cebolleta muy fina.","Mezclar en un bol salsa de soja, aceite de sésamo y el zumo de lima restante hasta integrar.","Añadir el salmón, el aguacate y la cebolleta picada al bol con el aliño.","Mezclar con cuidado para no aplastar los dados, asegurando que el aliño los cubra por igual.","Tapar el bol y dejar reposar en la nevera hasta que los sabores se integren.","Emplatar con la ayuda de un aro de cocina, disponiendo el tartar en capas compactas.","Picar cilantro fresco y espolvorear sobre el tartar junto con semillas de sésamo justo antes de servir."}', 'Tartar fresco de salmón y aguacate en capas, aliñado con soja y sésamo, con un toque de lima.', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"La Thermomix es ideal para picar finamente la cebolleta y el cilantro, así como para emulsionar la vinagreta de soja y sésamo. El salmón se puede picar con golpes de turbo muy cortos para mantener su textura, mientras que el aguacate se corta a cuchillo para preservar su forma."}]'::jsonb, '{}', true, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Lomo de salmón fresco de calidad sashimi}} en dados de medio centímetro, regulares y limpios.","minutes":5,"kind":"prep"},{"text":"Pelar {{Aguacate}} y cortar en dados del mismo tamaño que el salmón.","minutes":3,"kind":"prep"},{"text":"Exprimir {{Lima}} y reservar el zumo.","minutes":1,"kind":"prep"},{"text":"Rociar los dados de aguacate con la mitad del zumo de lima para evitar que se oxide.","minutes":1,"kind":"prep"},{"text":"Picar {{Cebolleta}} muy fina.","minutes":2,"kind":"prep"},{"text":"Mezclar en un bol {{Salsa de soja}}, {{Aceite de sésamo}} y el zumo de lima restante hasta integrar.","minutes":1,"kind":"activo"},{"text":"Añadir el salmón, el aguacate y la cebolleta picada al bol con el aliño.","minutes":1,"kind":"activo"},{"text":"Mezclar con cuidado para no aplastar los dados, asegurando que el aliño los cubra por igual.","minutes":1,"kind":"activo"},{"text":"Tapar el bol y dejar reposar en la nevera hasta que los sabores se integren.","minutes":5,"kind":"espera"},{"text":"Emplatar con la ayuda de un aro de cocina, disponiendo el tartar en capas compactas.","minutes":2,"kind":"emplatado"},{"text":"Picar {{Cilantro fresco}} y espolvorear sobre el tartar junto con {{Semillas de sésamo|pizca}} justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, NULL),
  ('pescados_080', 'Ceviche de lubina con leche de tigre', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'normal', 'verano', 220, 26, 10, 6, 2, false, false, '{"pescado","apio"}', '[{"name":"Lomo de lubina fresca","amount":300,"unit":"g"},{"name":"Lima","amount":4,"unit":"ud"},{"name":"Cebolla morada","amount":60,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Chile fresco","amount":5,"unit":"g"},{"name":"Jengibre fresco","amount":5,"unit":"g"},{"name":"Apio","amount":15,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Cortar lomo de lubina fresca en dados de 1,5 cm, retirando cualquier espina.","Separar un tercio de los dados de lubina y reservar el resto en un bol frío.","Cortar cebolla morada en juliana muy fina y sumergirla en agua con hielo.","Dejar la cebolla morada en el agua con hielo hasta que pierda el amargor.","Exprimir lima y colar el zumo para eliminar pepitas.","Pelar y cortar jengibre fresco en trozos pequeños.","Cortar apio en trozos pequeños.","Picar chile fresco en trozos finos, retirando las semillas si se quiere menos picante.","Picar cilantro fresco fino y reservar.","Triturar el tercio de lubina reservado con el zumo de lima, el jengibre, el apio y sal hasta obtener una mezcla fina.","Colar la mezcla con un colador fino, presionando con una cuchara, hasta obtener la leche de tigre limpia.","Salpimentar los dados de lubina del bol frío con sal al gusto y remover con suavidad.","Verter la leche de tigre sobre los dados de lubina y remover con cuidado para que el zumo los cubra bien.","Dejar marinar hasta que el pescado quede opaco por fuera pero jugoso por dentro.","Escurrir la cebolla morada y añadirla al bol junto con el chile picado y el cilantro.","Servir de inmediato en cuencos fríos, repartiendo el jugo de la leche de tigre entre los dos."}', 'Ceviche de lubina fresca marinada en leche de tigre, con cebolla morada, cilantro y un toque picante.', '[{"appliance":"thermomix","time":30,"difficulty":"normal","prepSummary":"La Thermomix es excelente para picar finamente la cebolla morada, el cilantro, el chile, el jengibre y el apio. Además, permite emulsionar rápidamente la leche de tigre, mezclando los jugos de lima con los aromáticos para una base homogénea y llena de sabor."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Lomo de lubina fresca}} en dados de 1,5 cm, retirando cualquier espina.","minutes":5,"kind":"prep"},{"text":"Separar un tercio de los dados de lubina y reservar el resto en un bol frío.","minutes":1,"kind":"prep"},{"text":"Cortar {{Cebolla morada}} en juliana muy fina y sumergirla en agua con hielo.","minutes":2,"kind":"prep"},{"text":"Dejar la cebolla morada en el agua con hielo hasta que pierda el amargor.","minutes":10,"kind":"espera"},{"text":"Exprimir {{Lima}} y colar el zumo para eliminar pepitas.","minutes":2,"kind":"paralelo","during":3},{"text":"Pelar y cortar {{Jengibre fresco}} en trozos pequeños.","minutes":1,"kind":"paralelo","during":3},{"text":"Cortar {{Apio}} en trozos pequeños.","minutes":1,"kind":"paralelo","during":3},{"text":"Picar {{Chile fresco}} en trozos finos, retirando las semillas si se quiere menos picante.","minutes":1,"kind":"paralelo","during":3},{"text":"Picar {{Cilantro fresco}} fino y reservar.","minutes":1,"kind":"paralelo","during":3},{"text":"Triturar el tercio de lubina reservado con el zumo de lima, el jengibre, el apio y {{Sal|gusto}} hasta obtener una mezcla fina.","minutes":2,"kind":"activo"},{"text":"Colar la mezcla con un colador fino, presionando con una cuchara, hasta obtener la leche de tigre limpia.","minutes":2,"kind":"activo"},{"text":"Salpimentar los dados de lubina del bol frío con sal al gusto y remover con suavidad.","minutes":1,"kind":"activo"},{"text":"Verter la leche de tigre sobre los dados de lubina y remover con cuidado para que el zumo los cubra bien.","minutes":1,"kind":"activo"},{"text":"Dejar marinar hasta que el pescado quede opaco por fuera pero jugoso por dentro.","minutes":4,"kind":"espera"},{"text":"Escurrir la cebolla morada y añadirla al bol junto con el chile picado y el cilantro.","minutes":1,"kind":"activo"},{"text":"Servir de inmediato en cuencos fríos, repartiendo el jugo de la leche de tigre entre los dos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', 'peruana', NULL),
  ('pescados_081', 'Trucha con jamón y almendras', 'pescados', 'pescado_azul', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 380, 34, 6, 24, 2, true, true, '{"pescado","frutos_secos","gluten"}', '[{"name":"Trucha limpia sin espinas","amount":2,"unit":"ud"},{"name":"Jamón serrano en lonchas finas","amount":60,"unit":"g"},{"name":"Almendras laminadas","amount":30,"unit":"g"},{"name":"Harina de trigo","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Secar trucha limpia sin espinas con papel de cocina por dentro y por fuera hasta que estén bien secas.","Rellenar el interior de cada trucha con jamón serrano en lonchas finas, repartiendo las lonchas entre las 2 piezas.","Enharinar las truchas por fuera con harina de trigo, sacudiendo el exceso para dejar una capa fina y uniforme.","Calentar aceite de oliva en sartén amplia a fuego medio-alto hasta que el aceite brille.","Colocar las truchas en la sartén y freír 5 min por el primer lado sin moverlas.","Dar la vuelta a las truchas con cuidado y freír 5 min por el segundo lado hasta que estén doradas y hechas por dentro.","Retirar las truchas de la sartén y reservar en un plato caliente.","Tostar almendras laminadas en la misma sartén a fuego medio 2 min, removiendo, hasta que se doren sin quemarse.","Exprimir limón y reservar el zumo.","Picar perejil fino y reservar.","Colocar las truchas en los platos y repartir las almendras tostadas por encima.","Rociar con el zumo de limón y espolvorear el perejil picado antes de servir."}', 'Trucha rellena de jamón serrano y frita, con almendras tostadas por encima, el clásico de río.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Enharina ligeramente la trucha, rocíala con un poco de aceite y cocina 12-15 minutos, añadiendo el jamón y las almendras laminadas los últimos 3-5 minutos para que se doren y queden crujientes."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 180°C. Coloca la trucha en una bandeja con papel de horno y un chorrito de aceite. Hornea durante 15-20 minutos y añade el jamón y las almendras laminadas los últimos 5-7 minutos para que se tuesten y el jamón quede crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{"frutos_secos"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Secar {{Trucha limpia sin espinas}} con papel de cocina por dentro y por fuera hasta que estén bien secas.","minutes":2,"kind":"prep"},{"text":"Rellenar el interior de cada trucha con {{Jamón serrano en lonchas finas}}, repartiendo las lonchas entre las 2 piezas.","minutes":2,"kind":"prep"},{"text":"Enharinar las truchas por fuera con {{Harina de trigo}}, sacudiendo el exceso para dejar una capa fina y uniforme.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} amplia a fuego medio-alto hasta que el aceite brille.","minutes":2,"kind":"activo"},{"text":"Colocar las truchas en la sartén y freír 5 min por el primer lado sin moverlas.","minutes":5,"kind":"pasivo"},{"text":"Dar la vuelta a las truchas con cuidado y freír 5 min por el segundo lado hasta que estén doradas y hechas por dentro.","minutes":5,"kind":"pasivo"},{"text":"Retirar las truchas de la sartén y reservar en un plato caliente.","minutes":1,"kind":"activo"},{"text":"Tostar {{Almendras laminadas}} en la misma sartén a fuego medio 2 min, removiendo, hasta que se doren sin quemarse.","minutes":2,"kind":"activo"},{"text":"Exprimir {{Limón}} y reservar el zumo.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Colocar las truchas en los platos y repartir las almendras tostadas por encima.","minutes":1,"kind":"emplatado"},{"text":"Rociar con el zumo de limón y espolvorear el perejil picado antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, NULL),
  ('pescados_082', 'Sardinas al horno con limón y ajo', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, 'horno', 25, 'facil', 'verano', 260, 26, 2, 16, 2, true, true, '{"pescado"}', '[{"name":"Sardinas frescas limpias","amount":400,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Picar ajo fino.","Picar perejil fino.","Cortar limón en rodajas finas.","Mezclar el ajo picado y el perejil picado con aceite de oliva en un bol pequeño.","Colocar sardinas frescas limpias en una fuente de horno formando una sola capa.","Repartir la mezcla de ajo y perejil por encima de las sardinas.","Salpimentar con sal y colocar las rodajas de limón sobre las sardinas.","Hornear 13 min hasta que la piel esté dorada y la carne se separe fácilmente de la espina.","Servir directamente en la fuente."}', 'Sardinas frescas horneadas con ajo, perejil y limón, con la piel plateada y brillante recién salidas del horno.', '[{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Coloca las sardinas en una bandeja, rocía con la mezcla de limón, ajo, perejil y aceite, y hornea durante 18-22 minutos hasta que estén doradas y cocidas."},{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 185°C. Dispón las sardinas en una sola capa, rocía con la mezcla de aderezo y cocina por 12-15 minutos, volteándolas a mitad de cocción para un dorado uniforme y piel crujiente."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Picar {{Ajo}} fino.","minutes":2,"kind":"prep"},{"text":"Picar {{Perejil}} fino.","minutes":1,"kind":"paralelo","during":0},{"text":"Cortar {{Limón}} en rodajas finas.","minutes":1,"kind":"paralelo","during":0},{"text":"Mezclar el ajo picado y el perejil picado con {{Aceite de oliva|chorrito}} en un bol pequeño.","minutes":1,"kind":"paralelo","during":0},{"text":"Colocar {{Sardinas frescas limpias}} en una fuente de horno formando una sola capa.","minutes":1,"kind":"prep"},{"text":"Repartir la mezcla de ajo y perejil por encima de las sardinas.","minutes":1,"kind":"activo"},{"text":"Salpimentar con {{Sal|gusto}} y colocar las rodajas de limón sobre las sardinas.","minutes":1,"kind":"activo"},{"text":"Hornear 13 min hasta que la piel esté dorada y la carne se separe fácilmente de la espina.","minutes":13,"kind":"pasivo"},{"text":"Servir directamente en la fuente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('pescados_083', 'Rodaballo al horno con patatas panadera', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'all', 470, 34, 32, 22, 2, true, true, '{"pescado"}', '[{"name":"Rodaballo entero limpio","amount":800,"unit":"g"},{"name":"Patata","amount":350,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":45,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Vino blanco","amount":40,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar patata y laminar en rodajas de 3 mm.","Laminar cebolla en juliana fina.","Cortar pimiento verde en tiras finas.","Picar ajo fino.","Calentar aceite de oliva en sartén a fuego medio-bajo.","Sofreír la patata laminada y la cebolla en juliana hasta que estén tiernas, sin que se doren.","Escurrir el exceso de aceite de la patata y la cebolla.","Extender la patata y la cebolla escurridas en una fuente de horno grande formando una cama uniforme.","Salpimentar rodaballo entero limpio por ambos lados.","Colocar el rodaballo encima de la cama de patata y cebolla.","Repartir el ajo picado y las tiras de pimiento verde alrededor del rodaballo.","Rociar el rodaballo y las patatas con el aceite de oliva restante y vino blanco.","Hornear en el centro del horno hasta que el pescado esté opaco y se separe fácilmente de la espina.","Picar perejil fino.","Retirar la fuente del horno y dejar reposar el rodaballo.","Espolvorear el perejil picado sobre el rodaballo y servir directamente en la fuente."}', 'Rodaballo entero al horno sobre una cama de patatas panadera, cocinados juntos con ajo y vino blanco.', '[{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Precalienta el horno a 180-200°C. Dispón las patatas y verduras laminadas en una bandeja, coloca el rodaballo encima, riega con aceite y vino, y hornea hasta que el pescado esté en su punto y las patatas tiernas y doradas."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Patata}} y laminar en rodajas de 3 mm.","minutes":4,"kind":"prep"},{"text":"Laminar {{Cebolla}} en juliana fina.","minutes":2,"kind":"paralelo","during":0},{"text":"Cortar {{Pimiento verde}} en tiras finas.","minutes":2,"kind":"paralelo","during":0},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"paralelo","during":0},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio-bajo.","minutes":1,"kind":"activo"},{"text":"Sofreír la patata laminada y la cebolla en juliana hasta que estén tiernas, sin que se doren.","minutes":10,"kind":"activo"},{"text":"Escurrir el exceso de aceite de la patata y la cebolla.","minutes":1,"kind":"prep"},{"text":"Extender la patata y la cebolla escurridas en una fuente de horno grande formando una cama uniforme.","minutes":1,"kind":"prep"},{"text":"Salpimentar {{Rodaballo entero limpio}} por ambos lados.","minutes":1,"kind":"prep"},{"text":"Colocar el rodaballo encima de la cama de patata y cebolla.","minutes":1,"kind":"prep"},{"text":"Repartir el ajo picado y las tiras de pimiento verde alrededor del rodaballo.","minutes":1,"kind":"prep"},{"text":"Rociar el rodaballo y las patatas con el aceite de oliva restante y {{Vino blanco}}.","minutes":1,"kind":"prep"},{"text":"Hornear en el centro del horno hasta que el pescado esté opaco y se separe fácilmente de la espina.","minutes":28,"kind":"pasivo"},{"text":"Picar {{Perejil}} fino.","minutes":1,"kind":"paralelo","during":13},{"text":"Retirar la fuente del horno y dejar reposar el rodaballo.","minutes":3,"kind":"espera"},{"text":"Espolvorear el perejil picado sobre el rodaballo y servir directamente en la fuente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, 'especial', NULL, 'horno', NULL, NULL),
  ('pescados_084', 'Pez espada a la plancha con salsa de mango', 'pescados', 'pescado_azul', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'verano', 310, 30, 14, 14, 2, true, false, '{"pescado"}', '[{"name":"Filetes de pez espada","amount":350,"unit":"g"},{"name":"Mango maduro","amount":150,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Pelar mango maduro y cortar en dados pequeños.","Picar cebolla morada en trozos muy finos.","Picar cilantro fresco en trozos muy finos.","Exprimir lima y reservar el zumo.","Mezclar en un bol el mango, la cebolla morada y el cilantro con el zumo de lima y sal.","Separar la mitad de la mezcla en un bol aparte y triturar esa mitad hasta obtener una salsa homogénea.","Mezclar la parte triturada con la parte en dados hasta integrar. Reservar.","Salar filetes de pez espada por ambos lados.","Calentar plancha con aceite de oliva a fuego fuerte hasta que empiece a humear.","Colocar los filetes de pez espada en la plancha y cocinar 3 min por el primer lado hasta que se doren.","Dar la vuelta a los filetes de pez espada y cocinar 2 min por el segundo lado hasta que estén dorados.","Retirar los filetes de pez espada de la plancha y reposar 1 min.","Servir los filetes de pez espada con la salsa de mango al lado o por encima."}', 'Pez espada marcado a la plancha con una salsa fresca y tropical de mango, lima y cilantro.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190-200°C. Cocina el pez espada salpimentado con un poco de aceite durante 10-14 minutos, dándole la vuelta a mitad para un dorado uniforme. Prepara la salsa de mango mientras se cocina el pescado."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Coloca el pez espada en una bandeja con un chorrito de aceite y hornea durante 15-20 minutos, o hasta que esté cocido y ligeramente dorado. Prepara la salsa fresca de mango mientras el pescado está en el horno."}]'::jsonb, '{}', NULL, NULL, NULL, '{"fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Mango maduro}} y cortar en dados pequeños.","minutes":3,"kind":"prep","part":"salsa"},{"text":"Picar {{Cebolla morada}} en trozos muy finos.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Picar {{Cilantro fresco}} en trozos muy finos.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Exprimir {{Lima}} y reservar el zumo.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Mezclar en un bol el mango, la cebolla morada y el cilantro con el zumo de lima y {{Sal|gusto}}.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Separar la mitad de la mezcla en un bol aparte y triturar esa mitad hasta obtener una salsa homogénea.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Mezclar la parte triturada con la parte en dados hasta integrar. Reservar.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Salar {{Filetes de pez espada}} por ambos lados.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} con {{Aceite de oliva|chorrito}} a fuego fuerte hasta que empiece a humear.","minutes":2,"kind":"activo","part":"principal"},{"text":"Colocar los filetes de pez espada en la plancha y cocinar 3 min por el primer lado hasta que se doren.","minutes":3,"kind":"activo","part":"principal"},{"text":"Dar la vuelta a los filetes de pez espada y cocinar 2 min por el segundo lado hasta que estén dorados.","minutes":2,"kind":"activo","part":"principal"},{"text":"Retirar los filetes de pez espada de la plancha y reposar 1 min.","minutes":1,"kind":"espera","part":"principal"},{"text":"Servir los filetes de pez espada con la salsa de mango al lado o por encima.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL, true),
  ('pescados_085', 'Bacalao con tomate y pimientos', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 40, 'facil', 'all', 300, 30, 12, 14, 2, true, true, '{"pescado"}', '[{"name":"Bacalao desalado en lomos","amount":320,"unit":"g"},{"name":"Tomate triturado","amount":300,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Azúcar","amount":3,"unit":"g"}]'::jsonb, '{"Cortar pimiento rojo y pimiento verde en tiras finas.","Cortar cebolla en tiras finas.","Picar ajo fino.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla, el ajo y los pimientos a fuego suave hasta que estén tiernos.","Añadir tomate triturado y azúcar y remover para integrar.","Cocer la salsa a fuego suave hasta que espese, removiendo de vez en cuando.","Colocar bacalao desalado en lomos sobre la salsa con la piel hacia abajo.","Tapar la cazuela y cocer a fuego suave hasta que el bacalao esté hecho y jugoso.","Servir el bacalao napado con la salsa de tomate y pimientos."}', 'Lomos de bacalao cocinados sobre una salsa brillante de tomate y pimientos asomando entre el rojo.', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Prepara el sofrito de cebolla y pimientos en una sartén. Añade el tomate triturado y cocina 10 minutos. Vierte la salsa en una fuente de horno, coloca los lomos de bacalao y hornea a 180°C durante 20-25 minutos hasta que el pescado esté tierno y la salsa reducida."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Pica la cebolla, pimientos y ajo, y sofríe en el vaso. Añade el tomate triturado y cocina la salsa. Incorpora el bacalao en el Varoma y cocina al vapor sobre la salsa durante 15-20 minutos, hasta que esté en su punto."},{"appliance":"olla_express","time":25,"difficulty":"normal","prepSummary":"Sofríe la cebolla, pimientos y ajo en la olla abierta. Añade el tomate triturado y cocina a presión durante 5-7 minutos. Despresuriza, incorpora los lomos de bacalao y cocina sin presión unos 3-5 minutos más hasta que el pescado esté hecho, evitando que se deshaga."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Pimiento rojo}} y {{Pimiento verde}} en tiras finas.","minutes":3,"kind":"prep"},{"text":"Cortar {{Cebolla}} en tiras finas.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, el ajo y los pimientos a fuego suave hasta que estén tiernos.","minutes":12,"kind":"pasivo"},{"text":"Añadir {{Tomate triturado}} y {{Azúcar}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Cocer la salsa a fuego suave hasta que espese, removiendo de vez en cuando.","minutes":15,"kind":"pasivo"},{"text":"Colocar {{Bacalao desalado en lomos}} sobre la salsa con la piel hacia abajo.","minutes":1,"kind":"activo"},{"text":"Tapar la cazuela y cocer a fuego suave hasta que el bacalao esté hecho y jugoso.","minutes":9,"kind":"pasivo"},{"text":"Servir el bacalao napado con la salsa de tomate y pimientos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, NULL),
  ('pescados_086', 'Lenguado meunière con mantequilla y limón', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 20, 'normal', 'all', 340, 28, 8, 22, 2, true, false, '{"pescado","gluten","lactosa"}', '[{"name":"Lenguado limpio","amount":2,"unit":"ud"},{"name":"Harina de trigo","amount":30,"unit":"g"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Sal","amount":4,"unit":"g"}]'::jsonb, '{"Secar lenguado limpio por ambas caras con papel de cocina hasta eliminar toda la humedad.","Salpimentar los lenguados por ambos lados con sal.","Enharinar los lenguados pasándolos por harina de trigo y sacudir el exceso.","Picar perejil finamente y reservar.","Exprimir limón y reservar el zumo.","Calentar sartén a fuego medio-alto y fundir un tercio de mantequilla hasta que empiece a espumar.","Colocar los lenguados en la sartén y cocinar 3 min por el primer lado hasta que estén dorados.","Dar la vuelta a los lenguados y cocinar 3 min por el segundo lado hasta que estén dorados y hechos por dentro.","Retirar los lenguados de la sartén y reservar en los platos de servicio.","Limpiar la sartén con papel de cocina para eliminar los restos de harina quemada.","Fundir el resto de la mantequilla en la sartén a fuego medio, removiendo, hasta que tome color avellana y huela a tostado.","Retirar la sartén del fuego y añadir el zumo de limón reservado, removiendo para emulsionar.","Verter la mantequilla avellana sobre los lenguados reservados en los platos.","Espolvorear el perejil picado sobre los lenguados y servir de inmediato."}', 'Lenguado dorado a la mantequilla con un toque de limón, bañado en mantequilla avellana recién hecha.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Enharina el lenguado, rocíalo con mantequilla derretida o aceite en spray y cocina en la airfryer precalentada a 190°C durante 12-15 minutos, dándole la vuelta a mitad para un dorado uniforme. Sirve con la salsa de mantequilla, limón y perejil."},{"appliance":"horno","time":25,"difficulty":"normal","prepSummary":"Enharina el lenguado y colócalo en una bandeja de horno con papel de hornear, rociando con mantequilla derretida. Hornea a 200°C durante 15-20 minutos, hasta que esté dorado y cocido, luego añade el limón y perejil."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Secar {{Lenguado limpio}} por ambas caras con papel de cocina hasta eliminar toda la humedad.","minutes":2,"kind":"prep"},{"text":"Salpimentar los lenguados por ambos lados con {{Sal|gusto}}.","minutes":1,"kind":"prep"},{"text":"Enharinar los lenguados pasándolos por {{Harina de trigo}} y sacudir el exceso.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} finamente y reservar.","minutes":1,"kind":"prep"},{"text":"Exprimir {{Limón}} y reservar el zumo.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio-alto y fundir un tercio de {{Mantequilla}} hasta que empiece a espumar.","minutes":1,"kind":"activo"},{"text":"Colocar los lenguados en la sartén y cocinar 3 min por el primer lado hasta que estén dorados.","minutes":3,"kind":"pasivo"},{"text":"Dar la vuelta a los lenguados y cocinar 3 min por el segundo lado hasta que estén dorados y hechos por dentro.","minutes":3,"kind":"pasivo"},{"text":"Retirar los lenguados de la sartén y reservar en los platos de servicio.","minutes":1,"kind":"activo"},{"text":"Limpiar la sartén con papel de cocina para eliminar los restos de harina quemada.","minutes":1,"kind":"activo"},{"text":"Fundir el resto de la mantequilla en la sartén a fuego medio, removiendo, hasta que tome color avellana y huela a tostado.","minutes":2,"kind":"activo"},{"text":"Retirar la sartén del fuego y añadir el zumo de limón reservado, removiendo para emulsionar.","minutes":1,"kind":"activo"},{"text":"Verter la mantequilla avellana sobre los lenguados reservados en los platos.","minutes":1,"kind":"emplatado"},{"text":"Espolvorear el perejil picado sobre los lenguados y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', 'francesa', true),
  ('pescados_087', 'Calamares en su tinta con arroz', 'pescados', 'marisco', 'arroz', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 75, 'elaborada', 'all', 480, 28, 55, 16, 4, false, true, '{"moluscos","sulfitos","pescado"}', '[{"name":"Calamares limpios con sus tintas","amount":800,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Vino blanco","amount":100,"unit":"ml"},{"name":"Bolsitas de tinta de calamar","amount":4,"unit":"ud"},{"name":"Caldo de pescado","amount":200,"unit":"ml"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Arroz blanco","amount":320,"unit":"g"}]'::jsonb, '{"Cortar calamares limpios con sus tintas en anillas los cuerpos y en trozos los tentáculos.","Picar cebolla, pimiento verde y ajo muy finos.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla, el pimiento y el ajo a fuego suave hasta que estén tiernos.","Añadir los calamares y saltear a fuego medio hasta que suelten su agua.","Verter vino blanco y remover hasta que se evapore el alcohol.","Añadir tomate triturado y sofreír a fuego medio hasta que la salsa espese.","Disolver bolsitas de tinta de calamar en caldo de pescado removiendo hasta integrar.","Verter el caldo con la tinta en la cazuela y remover para mezclar con la salsa.","Tapar la cazuela y cocer a fuego suave hasta que los calamares estén tiernos.","Hervir agua con sal en un cazo a fuego fuerte hasta que rompa a hervir.","Añadir arroz blanco y cocer a fuego medio hasta que esté en su punto.","Escurrir el arroz y reservar caliente.","Servir los calamares en su tinta acompañados del arroz blanco."}', 'Calamares guisados lentamente en su propia tinta, de negro intenso, con arroz blanco como contraste.', '[{"appliance":"horno","time":110,"difficulty":"elaborada","prepSummary":"Prepara el sofrito en una cazuela apta para horno, incorpora los calamares, tintas, vino y caldo. Cocina tapado en el horno precalentado a 160°C durante 90-100 minutos hasta que los calamares estén muy tiernos. El arroz se cocina aparte."},{"appliance":"thermomix","time":90,"difficulty":"normal","prepSummary":"Pica y sofríe las verduras en la Thermomix. Añade los calamares, tintas, vino y caldo, y cocina a 90°C, velocidad cuchara, giro inverso, durante 45-60 minutos. El arroz se puede cocinar en el cestillo o aparte."},{"appliance":"olla_express","time":55,"difficulty":"normal","prepSummary":"Sofríe las verduras en la olla express. Incorpora los calamares, tintas, vino y caldo. Cierra la olla y cocina a presión durante 15-20 minutos. Despresuriza y sirve con arroz blanco cocido aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Calamares limpios con sus tintas}} en anillas los cuerpos y en trozos los tentáculos.","minutes":5,"kind":"prep"},{"text":"Picar {{Cebolla}}, {{Pimiento verde}} y {{Ajo}} muy finos.","minutes":5,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, el pimiento y el ajo a fuego suave hasta que estén tiernos.","minutes":15,"kind":"pasivo"},{"text":"Añadir los calamares y saltear a fuego medio hasta que suelten su agua.","minutes":5,"kind":"activo"},{"text":"Verter {{Vino blanco}} y remover hasta que se evapore el alcohol.","minutes":3,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y sofreír a fuego medio hasta que la salsa espese.","minutes":5,"kind":"activo"},{"text":"Disolver {{Bolsitas de tinta de calamar}} en {{Caldo de pescado}} removiendo hasta integrar.","minutes":2,"kind":"prep"},{"text":"Verter el caldo con la tinta en la cazuela y remover para mezclar con la salsa.","minutes":1,"kind":"activo"},{"text":"Tapar la cazuela y cocer a fuego suave hasta que los calamares estén tiernos.","minutes":35,"kind":"pasivo"},{"text":"Hervir agua con sal en un cazo a fuego fuerte hasta que rompa a hervir.","minutes":5,"kind":"activo","part":"guarnicion"},{"text":"Añadir {{Arroz blanco}} y cocer a fuego medio hasta que esté en su punto.","minutes":17,"kind":"pasivo","part":"guarnicion"},{"text":"Escurrir el arroz y reservar caliente.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Servir los calamares en su tinta acompañados del arroz blanco.","minutes":2,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, true)
