  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('pescados_088', 'Langostinos a la plancha con alioli', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'verano', 260, 26, 2, 16, 2, true, false, '{"marisco","huevo"}', '[{"name":"Langostinos frescos con cáscara","amount":400,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de girasol","amount":150,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Sal gorda","amount":5,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar y picar ajo muy fino.","Secar langostinos frescos con cáscara con papel de cocina para que no suelten agua en la plancha.","Introducir el ajo picado y huevo en un vaso de batidora alto.","Añadir aceite de girasol en hilo muy fino sobre el huevo y el ajo, batiendo sin mover el brazo de la batidora hasta que emulsione.","Añadir sal gorda al alioli y reservar en frío.","Calentar plancha a fuego fuerte sin aceite hasta que humee ligeramente.","Colocar los langostinos en la plancha muy caliente en una sola capa.","Salar los langostinos con sal gorda.","Cocinar 2 min por el primer lado hasta que la cáscara empiece a ponerse roja.","Dar la vuelta a los langostinos y cocinar 2 min más hasta que estén completamente rojos y la carne opaca.","Cortar limón en gajos.","Retirar los langostinos de la plancha y colocarlos en una fuente.","Servir de inmediato con los gajos de limón y el alioli aparte."}', 'Langostinos a la plancha, rojos y jugosos, servidos con un alioli blanco recién hecho y limón.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 200°C. Rocía los langostinos con un poco de aceite y sal gorda y cocínalos durante 8-10 minutos, dándoles la vuelta a mitad, hasta que estén dorados y crujientes."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 220°C con la función grill. Coloca los langostinos en una bandeja, rocíalos con un hilo de aceite y sal gorda, y gratina durante 5-7 minutos, vigilando que no se sequen, hasta que estén rosados y ligeramente tostados."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar y picar {{Ajo}} muy fino.","minutes":2,"kind":"prep"},{"text":"Secar {{Langostinos frescos con cáscara}} con papel de cocina para que no suelten agua en la plancha.","minutes":2,"kind":"prep"},{"text":"Introducir el ajo picado y {{Huevo}} en un vaso de batidora alto.","minutes":1,"kind":"prep"},{"text":"Añadir {{Aceite de girasol}} en hilo muy fino sobre el huevo y el ajo, batiendo sin mover el brazo de la batidora hasta que emulsione.","minutes":3,"kind":"activo"},{"text":"Añadir {{Sal gorda|gusto}} al alioli y reservar en frío.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte sin aceite hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Colocar los langostinos en la plancha muy caliente en una sola capa.","minutes":1,"kind":"activo"},{"text":"Salar los langostinos con {{Sal gorda}}.","minutes":1,"kind":"activo"},{"text":"Cocinar 2 min por el primer lado hasta que la cáscara empiece a ponerse roja.","minutes":2,"kind":"activo"},{"text":"Dar la vuelta a los langostinos y cocinar 2 min más hasta que estén completamente rojos y la carne opaca.","minutes":2,"kind":"activo"},{"text":"Cortar {{Limón}} en gajos.","minutes":1,"kind":"paralelo","during":9},{"text":"Retirar los langostinos de la plancha y colocarlos en una fuente.","minutes":1,"kind":"emplatado"},{"text":"Servir de inmediato con los gajos de limón y el alioli aparte.","minutes":1,"kind":"emplatado"}]'::jsonb, true, 'especial', NULL, 'plancha', NULL, true),
  ('pescados_089', 'Buñuelos de bacalao', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 60, 'normal', 'all', 400, 20, 30, 22, 4, true, false, '{"pescado","gluten","huevo","lactosa"}', '[{"name":"Bacalao desalado desmigado","amount":250,"unit":"g"},{"name":"Harina de trigo","amount":150,"unit":"g"},{"name":"Levadura química","amount":6,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Leche entera","amount":100,"unit":"ml"},{"name":"Perejil","amount":8,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva suave","amount":500,"unit":"ml"}]'::jsonb, '{"Escurrir bacalao desalado desmigado con las manos, retirar cualquier espina y reservar.","Picar fino ajo y perejil. Reservar juntos.","Batir huevo en un bol grande hasta integrar.","Añadir leche entera al bol y mezclar con el huevo batido.","Tamizar harina de trigo con levadura química e incorporar poco a poco al bol, removiendo hasta obtener una masa sin grumos.","Añadir el bacalao escurrido, el ajo y el perejil picados al bol y mezclar hasta integrar.","Tapar el bol y dejar reposar la masa 15 min a temperatura ambiente.","Calentar aceite de oliva suave en sartén honda a fuego medio hasta que alcance unos 175 °C.","Formar los buñuelos con 2 cucharas y dejarlos caer con cuidado en el aceite caliente, en tandas pequeñas.","Freír cada tanda hasta que estén dorados por todos los lados, dándoles la vuelta a mitad.","Escurrir los buñuelos sobre papel absorbente. Repetir con el resto de la masa.","Servir los buñuelos calientes en una fuente."}', 'Buñuelos esponjosos de bacalao, dorados y crujientes por fuera y cremosos por dentro.', '[{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Precalienta la airfryer a 190°C. Rocía ligeramente los buñuelos formados con aceite de oliva y cocínalos en tandas durante 15-20 minutos, dándoles la vuelta a mitad, hasta que estén dorados y crujientes."},{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Forma los buñuelos y colócalos sobre papel de horno en una bandeja, pincelándolos con un poco de aceite. Hornea a 200°C durante 20-25 minutos, o hasta que estén bien dorados y cocidos por dentro."},{"appliance":"thermomix","time":45,"difficulty":"normal","prepSummary":"La Thermomix es ideal para preparar la masa de los buñuelos. Pica el ajo y perejil, añade el resto de ingredientes y mezcla a velocidad media hasta obtener una masa homogénea en pocos minutos. Luego, fríe los buñuelos en sartén como de costumbre."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Escurrir {{Bacalao desalado desmigado}} con las manos, retirar cualquier espina y reservar.","minutes":3,"kind":"prep"},{"text":"Picar fino {{Ajo}} y {{Perejil}}. Reservar juntos.","minutes":3,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol grande hasta integrar.","minutes":2,"kind":"prep"},{"text":"Añadir {{Leche entera}} al bol y mezclar con el huevo batido.","minutes":1,"kind":"prep"},{"text":"Tamizar {{Harina de trigo}} con {{Levadura química}} e incorporar poco a poco al bol, removiendo hasta obtener una masa sin grumos.","minutes":3,"kind":"activo"},{"text":"Añadir el bacalao escurrido, el ajo y el perejil picados al bol y mezclar hasta integrar.","minutes":2,"kind":"activo"},{"text":"Tapar el bol y dejar reposar la masa 15 min a temperatura ambiente.","minutes":15,"kind":"espera"},{"text":"Calentar {{Aceite de oliva suave}} en {{@Sartén}} honda a fuego medio hasta que alcance unos 175 °C.","minutes":4,"kind":"activo"},{"text":"Formar los buñuelos con 2 cucharas y dejarlos caer con cuidado en el aceite caliente, en tandas pequeñas.","minutes":2,"kind":"activo"},{"text":"Freír cada tanda hasta que estén dorados por todos los lados, dándoles la vuelta a mitad.","minutes":4,"kind":"activo"},{"text":"Escurrir los buñuelos sobre papel absorbente. Repetir con el resto de la masa.","minutes":5,"kind":"activo"},{"text":"Servir los buñuelos calientes en una fuente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, NULL),
  ('pescados_090', 'Marmitako de bonito', 'pescados', 'pescado_azul', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 380, 30, 32, 14, 4, true, true, '{"pescado"}', '[{"name":"Bonito fresco en tacos","amount":500,"unit":"g"},{"name":"Patata","amount":600,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Tomate triturado","amount":200,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Pimentón dulce","amount":6,"unit":"g"},{"name":"Caldo de pescado","amount":600,"unit":"ml"},{"name":"Aceite de oliva","amount":35,"unit":"ml"}]'::jsonb, '{"Picar cebolla, pimiento verde, pimiento rojo y ajo muy fino.","Pelar patata y cascarlas: cortar un poco y romper con la punta del cuchillo para que suelten almidón.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír la cebolla, los pimientos y el ajo picados a fuego suave hasta que estén pochados.","Añadir tomate triturado y sofreír a fuego medio hasta que pierda el agua.","Añadir pimentón dulce y remover sin parar durante 20 segundos para que no se queme.","Añadir las patatas cascadas y mezclar con el sofrito para que se impregnen.","Verter caldo de pescado, tapar la cazuela y llevar a ebullición a fuego medio.","Cocer tapado a fuego suave hasta que las patatas estén tiernas.","Añadir bonito fresco en tacos a la cazuela repartiendo los trozos por toda la superficie.","Cocer a fuego suave hasta que el bonito esté justo hecho, sin remover para que no se deshaga.","Reposar la cazuela apartada del fuego antes de servir.","Servir bien caliente en cazuela o platos hondos."}', 'Guiso marinero de patata y bonito en salsa roja, el clásico plato de barco vasco.', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Sofríe las verduras en una cazuela apta para horno. Añade el tomate, pimentón, patatas y caldo. Lleva a ebullición y hornea a 180°C durante 30-40 minutos hasta que las patatas estén tiernas. Incorpora el bonito los últimos 5 minutos."},{"appliance":"thermomix","time":50,"difficulty":"normal","prepSummary":"Trocea y sofríe las verduras. Añade las patatas, tomate, pimentón y caldo, y cocina 25-30 minutos a 100°C, giro inverso, velocidad cuchara. Incorpora el bonito al final y deja reposar unos minutos."},{"appliance":"olla_express","time":35,"difficulty":"normal","prepSummary":"Sofríe las verduras en la olla. Añade las patatas, tomate, pimentón y caldo. Cierra y cocina 10-12 minutos desde que sube la presión. Despresuriza, añade el bonito y deja reposar 5 minutos con el calor residual."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Cebolla}}, {{Pimiento verde}}, {{Pimiento rojo}} y {{Ajo}} muy fino.","minutes":5,"kind":"prep"},{"text":"Pelar {{Patata}} y cascarlas: cortar un poco y romper con la punta del cuchillo para que suelten almidón.","minutes":5,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, los pimientos y el ajo picados a fuego suave hasta que estén pochados.","minutes":12,"kind":"pasivo"},{"text":"Añadir {{Tomate triturado}} y sofreír a fuego medio hasta que pierda el agua.","minutes":5,"kind":"activo"},{"text":"Añadir {{Pimentón dulce|pizca}} y remover sin parar durante 20 segundos para que no se queme.","minutes":1,"kind":"activo"},{"text":"Añadir las patatas cascadas y mezclar con el sofrito para que se impregnen.","minutes":2,"kind":"activo"},{"text":"Verter {{Caldo de pescado}}, tapar la cazuela y llevar a ebullición a fuego medio.","minutes":3,"kind":"activo"},{"text":"Cocer tapado a fuego suave hasta que las patatas estén tiernas.","minutes":22,"kind":"pasivo"},{"text":"Añadir {{Bonito fresco en tacos}} a la cazuela repartiendo los trozos por toda la superficie.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave hasta que el bonito esté justo hecho, sin remover para que no se deshaga.","minutes":3,"kind":"pasivo"},{"text":"Reposar la cazuela apartada del fuego antes de servir.","minutes":2,"kind":"espera"},{"text":"Servir bien caliente en cazuela o platos hondos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('pescados_091', 'Pulpo a feira', 'pescados', 'marisco', 'patatas', ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 90, 'normal', 'all', 260, 28, 14, 10, 4, true, true, '{"moluscos"}', '[{"name":"Pulpo congelado limpio","amount":1200,"unit":"g"},{"name":"Patata","amount":500,"unit":"g"},{"name":"Pimentón dulce","amount":10,"unit":"g"},{"name":"Pimentón picante","amount":3,"unit":"g"},{"name":"Sal gorda","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":40,"unit":"ml"}]'::jsonb, '{"Descongelar pulpo congelado limpio en la nevera hasta que esté completamente blando.","Llevar una olla grande con agua abundante a ebullición fuerte.","Asustar el pulpo sumergiéndolo y sacándolo del agua hirviendo 3 veces sujetándolo por la cabeza.","Cocer el pulpo a fuego medio 45 min, hasta que al pinchar en la parte más gruesa con un palillo entre con facilidad.","Pelar patata y cortar en rodajas gruesas de unos 2 cm.","Retirar el pulpo del agua y reservar en un plato; dejar el agua de cocción en la olla a fuego medio.","Reposar el pulpo 5 min fuera del agua antes de cortarlo.","Cocer las patatas en el agua de cocción del pulpo a fuego medio, hasta que estén tiernas.","Cortar el pulpo en rodajas con unas tijeras empezando por los tentáculos.","Escurrir las patatas y colocarlas como base en una tabla de madera o plato de servir.","Repartir las rodajas de pulpo por encima de las patatas.","Espolvorear sal gorda de manera uniforme sobre el pulpo y las patatas.","Espolvorear pimentón dulce y pimentón picante por encima.","Regar con aceite de oliva virgen extra en crudo y servir de inmediato."}', 'Pulpo cocido y tierno sobre patatas, servido sobre madera con pimentón y aceite en crudo, al estilo gallego.', '[{"appliance":"olla_express","time":40,"difficulty":"facil","prepSummary":"Cuece el pulpo en la olla express con un vaso de agua durante 20-25 minutos desde que sube la válvula. Las patatas se pueden cocer en el mismo líquido o aparte para un resultado tierno y rápido."},{"appliance":"thermomix","time":70,"difficulty":"normal","prepSummary":"Cocina el pulpo troceado en el vaso con agua (o al vapor en el Varoma) a 95-100°C durante 40-60 minutos, y las patatas en el Varoma simultáneamente para un cocinado preciso y uniforme."},{"appliance":"vaporera","time":90,"difficulty":"normal","prepSummary":"Cuece el pulpo y las patatas en la vaporera durante 60-90 minutos hasta que estén muy tiernos. Este método mantiene mejor los sabores y la textura."},{"appliance":"horno","time":180,"difficulty":"normal","prepSummary":"Cocina el pulpo a baja temperatura (120-140°C) en un recipiente tapado con un poco de agua o sus propios jugos durante 2-3 horas hasta que esté muy tierno. Las patatas se cuecen aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Descongelar {{Pulpo congelado limpio}} en la nevera hasta que esté completamente blando.","minutes":720,"kind":"espera"},{"text":"Llevar una olla grande con agua abundante a ebullición fuerte.","minutes":10,"kind":"activo"},{"text":"Asustar el pulpo sumergiéndolo y sacándolo del agua hirviendo 3 veces sujetándolo por la cabeza.","minutes":2,"kind":"activo"},{"text":"Cocer el pulpo a fuego medio 45 min, hasta que al pinchar en la parte más gruesa con un palillo entre con facilidad.","minutes":45,"kind":"pasivo"},{"text":"Pelar {{Patata}} y cortar en rodajas gruesas de unos 2 cm.","minutes":5,"kind":"paralelo","during":3},{"text":"Retirar el pulpo del agua y reservar en un plato; dejar el agua de cocción en la olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Reposar el pulpo 5 min fuera del agua antes de cortarlo.","minutes":5,"kind":"espera"},{"text":"Cocer las patatas en el agua de cocción del pulpo a fuego medio, hasta que estén tiernas.","minutes":18,"kind":"pasivo"},{"text":"Cortar el pulpo en rodajas con unas tijeras empezando por los tentáculos.","minutes":3,"kind":"paralelo","during":7},{"text":"Escurrir las patatas y colocarlas como base en una tabla de madera o plato de servir.","minutes":1,"kind":"emplatado"},{"text":"Repartir las rodajas de pulpo por encima de las patatas.","minutes":1,"kind":"emplatado"},{"text":"Espolvorear {{Sal gorda|gusto}} de manera uniforme sobre el pulpo y las patatas.","minutes":1,"kind":"emplatado"},{"text":"Espolvorear {{Pimentón dulce|gusto}} y {{Pimentón picante|pizca}} por encima.","minutes":1,"kind":"emplatado"},{"text":"Regar con {{Aceite de oliva virgen extra|chorrito}} en crudo y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, 'especial', NULL, 'olla', NULL, NULL),
  ('pescados_092', 'Cazuela de fideos con rape y gambas', 'pescados', 'marisco', 'pasta', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 420, 28, 42, 14, 4, true, true, '{"pescado","marisco","gluten"}', '[{"name":"Fideos gruesos","amount":320,"unit":"g"},{"name":"Colas de rape en trozos","amount":250,"unit":"g"},{"name":"Gambas peladas","amount":200,"unit":"g"},{"name":"Cabezas y cáscaras de gamba","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Caldo de pescado","amount":700,"unit":"ml"},{"name":"Aceite de oliva","amount":35,"unit":"ml"},{"name":"Azafrán","amount":1,"unit":"g"}]'::jsonb, '{"Calentar aceite de oliva en una cazuela a fuego fuerte.","Saltear cabezas y cáscaras de gamba 5 min, aplastándolas con una cuchara hasta que suelten todo el jugo.","Añadir caldo de pescado y llevar a ebullición.","Hervir 10 min a fuego medio para extraer todo el sabor de las cáscaras.","Picar cebolla, ajo y pimiento rojo finos.","Colar el caldo con un colador fino, presionando las cáscaras para extraer todo el jugo, y reservar.","Calentar el resto del aceite de oliva en la cazuela limpia a fuego medio.","Sofreír la cebolla picada, el ajo picado y el pimiento rojo picado 10 min hasta que estén tiernos.","Añadir tomate triturado y sofreír 5 min hasta que espese y pierda el agua.","Incorporar fideos gruesos y saltear 2 min hasta que se doren ligeramente en el sofrito.","Verter el caldo reservado sobre los fideos y mezclar.","Añadir azafrán y remover para distribuirlo bien.","Cocer a fuego medio 8 min sin remover hasta que los fideos absorban casi todo el caldo.","Añadir colas de rape en trozos y cocer 4 min hasta que estén opacos y firmes.","Incorporar gambas peladas y cocer 2 min hasta que estén rosadas.","Retirar del fuego y reposar 2 min tapado antes de servir.","Servir en la misma cazuela en la mesa."}', 'Fideos dorados en cazuela con rape y gambas, en un caldo de pescado con azafrán, marisco asomando entre ellos.', '[{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Prepara el sofrito en una cazuela apta para horno en la encimera. Añade el caldo y los fideos, lleva a ebullición y hornea a 180°C durante 20-25 minutos. Incorpora el rape y las gambas en los últimos 5-7 minutos para que se cocinen a la perfección."},{"appliance":"thermomix","time":40,"difficulty":"normal","prepSummary":"Realiza el sofrito programando velocidad y temperatura. Luego, añade el caldo y los fideos, cocinando a temperatura Varoma o 100°C con giro inverso. Incorpora el rape y las gambas en los últimos minutos para una cocción precisa."},{"appliance":"olla_express","time":30,"difficulty":"normal","prepSummary":"Sofríe las verduras en la olla abierta. Añade el caldo y los fideos, cierra la olla y cocina a presión durante 3-5 minutos. Despresuriza, añade el rape y las gambas, y cocina unos minutos más sin presión hasta que estén hechos."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, ARRAY['pescado_blanco']::main_protein[], false, '[{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Saltear {{Cabezas y cáscaras de gamba}} 5 min, aplastándolas con una cuchara hasta que suelten todo el jugo.","minutes":5,"kind":"activo"},{"text":"Añadir {{Caldo de pescado}} y llevar a ebullición.","minutes":2,"kind":"activo"},{"text":"Hervir 10 min a fuego medio para extraer todo el sabor de las cáscaras.","minutes":10,"kind":"pasivo"},{"text":"Picar {{Cebolla}}, {{Ajo}} y {{Pimiento rojo}} finos.","minutes":5,"kind":"paralelo","during":3},{"text":"Colar el caldo con un colador fino, presionando las cáscaras para extraer todo el jugo, y reservar.","minutes":2,"kind":"prep"},{"text":"Calentar el resto del aceite de oliva en la cazuela limpia a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada, el ajo picado y el pimiento rojo picado 10 min hasta que estén tiernos.","minutes":10,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y sofreír 5 min hasta que espese y pierda el agua.","minutes":5,"kind":"activo"},{"text":"Incorporar {{Fideos gruesos}} y saltear 2 min hasta que se doren ligeramente en el sofrito.","minutes":2,"kind":"activo"},{"text":"Verter el caldo reservado sobre los fideos y mezclar.","minutes":1,"kind":"activo"},{"text":"Añadir {{Azafrán|pizca}} y remover para distribuirlo bien.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio 8 min sin remover hasta que los fideos absorban casi todo el caldo.","minutes":8,"kind":"pasivo"},{"text":"Añadir {{Colas de rape en trozos}} y cocer 4 min hasta que estén opacos y firmes.","minutes":4,"kind":"activo"},{"text":"Incorporar {{Gambas peladas}} y cocer 2 min hasta que estén rosadas.","minutes":2,"kind":"activo"},{"text":"Retirar del fuego y reposar 2 min tapado antes de servir.","minutes":2,"kind":"espera"},{"text":"Servir en la misma cazuela en la mesa.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('pescados_093', 'Salpicón de marisco', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'verano', 220, 24, 8, 10, 2, true, false, '{"marisco","moluscos","sulfitos","huevo","pescado"}', '[{"name":"Langostinos cocidos pelados","amount":150,"unit":"g"},{"name":"Mejillones cocidos","amount":100,"unit":"g"},{"name":"Palitos de cangrejo o surimi","amount":80,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":50,"unit":"g"},{"name":"Cebolla morada","amount":40,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Vinagre de vino","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar langostinos cocidos pelados en trozos de bocado si son grandes.","Cortar palitos de cangrejo o surimi en rodajas finas.","Picar pimiento rojo en dados muy pequeños y regulares.","Picar pimiento verde en dados muy pequeños y regulares.","Picar cebolla morada en dados muy pequeños y regulares.","Picar tomate en dados pequeños, retirando el exceso de agua y semillas.","Mezclar en un bol grande los langostinos, mejillones cocidos y los palitos con todas las verduras picadas.","Añadir aceite de oliva virgen extra y vinagre de vino sobre la mezcla.","Remover bien hasta que todos los ingredientes queden impregnados del aliño.","Tapar el bol y reservar en la nevera al menos 60 min para que se integren los sabores.","Servir bien frío en cuencos o copas individuales."}', 'Salpicón fresco y colorido de langostinos, mejillones y verdura picada, perfecto para el aperitivo de verano.', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"Pica las verduras (pimientos, cebolla, tomate) en el vaso en varios golpes de turbo o velocidad 4-5. Añade el marisco cocido y el aliño, y mezcla suavemente a velocidad cuchara para integrar todos los ingredientes sin triturar."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Langostinos cocidos pelados}} en trozos de bocado si son grandes.","minutes":2,"kind":"prep"},{"text":"Cortar {{Palitos de cangrejo o surimi}} en rodajas finas.","minutes":2,"kind":"prep"},{"text":"Picar {{Pimiento rojo}} en dados muy pequeños y regulares.","minutes":2,"kind":"prep"},{"text":"Picar {{Pimiento verde}} en dados muy pequeños y regulares.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla morada}} en dados muy pequeños y regulares.","minutes":2,"kind":"prep"},{"text":"Picar {{Tomate}} en dados pequeños, retirando el exceso de agua y semillas.","minutes":2,"kind":"prep"},{"text":"Mezclar en un bol grande los langostinos, {{Mejillones cocidos}} y los palitos con todas las verduras picadas.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva virgen extra}} y {{Vinagre de vino}} sobre la mezcla.","minutes":1,"kind":"activo"},{"text":"Remover bien hasta que todos los ingredientes queden impregnados del aliño.","minutes":1,"kind":"activo"},{"text":"Tapar el bol y reservar en la nevera al menos 60 min para que se integren los sabores.","minutes":60,"kind":"espera"},{"text":"Servir bien frío en cuencos o copas individuales.","minutes":1,"kind":"emplatado"}]'::jsonb, true, 'especial', NULL, 'olla', NULL, NULL),
  ('pescados_094', 'Vieiras gratinadas con jamón', 'pescados', 'marisco', NULL, ARRAY['segundo','cena']::meal_role[], 'principal', NULL, 'horno', 30, 'normal', 'all', 260, 20, 10, 15, 2, true, false, '{"moluscos","lactosa","gluten"}', '[{"name":"Vieiras limpias en su concha","amount":8,"unit":"ud"},{"name":"Jamón serrano picado","amount":40,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Pan rallado","amount":30,"unit":"g"},{"name":"Mantequilla","amount":25,"unit":"g"},{"name":"Vino blanco","amount":30,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno en modo grill a 220 °C.","Picar cebolla muy fina.","Picar perejil fino y reservar.","Separar el coral de la nuez de cada vieiras limpias en su concha y limpiar bien las conchas.","Cortar las nueces de vieira en 2 o 3 trozos y reservar.","Fundir la mitad de mantequilla en sartén a fuego suave.","Sofreír la cebolla picada en la mantequilla fundida a fuego suave hasta que esté blanda.","Añadir jamón serrano picado y sofreír a fuego medio 2 min.","Verter vino blanco y remover hasta que se evapore el alcohol.","Añadir los trozos de vieira y los corales a la sartén y saltear 1 min a fuego fuerte.","Retirar la sartén del fuego y repartir la mezcla entre las conchas limpias.","Fundir el resto de la mantequilla en la sartén limpia a fuego suave.","Mezclar pan rallado con la mantequilla fundida en un bol hasta obtener una mezcla arenosa.","Espolvorear la mezcla de pan rallado sobre cada concha rellena de forma uniforme.","Gratinar las conchas en el horno a 220 °C en modo grill hasta que la superficie esté dorada.","Espolvorear el perejil picado sobre las conchas y servir de inmediato."}', 'Vieiras gratinadas con jamón y pan rallado dorado, servidas en su propia concha individual.', '[{"appliance":"horno","time":30,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el jamón, mezcla con el vino y un poco de pan rallado. Coloca las vieiras en sus conchas, cubre con la mezcla, más pan rallado y un trocito de mantequilla. Gratina en el horno precalentado a 200°C durante 15-20 minutos hasta que estén doradas y burbujeantes."},{"appliance":"airfryer","time":20,"difficulty":"normal","prepSummary":"Prepara el sofrito de cebolla y jamón en una sartén. Monta las vieiras en sus conchas o en recipientes aptos para airfryer con la mezcla, pan rallado y mantequilla. Cocina en la airfryer precalentada a 190°C durante 8-12 minutos, vigilando que el gratinado quede dorado y las viei"}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Precalentar el horno en modo grill a 220 °C.","minutes":5,"kind":"pasivo"},{"text":"Picar {{Cebolla}} muy fina.","minutes":2,"kind":"prep"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Separar el coral de la nuez de cada {{Vieiras limpias en su concha}} y limpiar bien las conchas.","minutes":3,"kind":"prep"},{"text":"Cortar las nueces de vieira en 2 o 3 trozos y reservar.","minutes":2,"kind":"prep"},{"text":"Fundir la mitad de {{Mantequilla}} en {{@Sartén}} a fuego suave.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada en la mantequilla fundida a fuego suave hasta que esté blanda.","minutes":6,"kind":"pasivo"},{"text":"Añadir {{Jamón serrano picado}} y sofreír a fuego medio 2 min.","minutes":2,"kind":"activo"},{"text":"Verter {{Vino blanco}} y remover hasta que se evapore el alcohol.","minutes":2,"kind":"activo"},{"text":"Añadir los trozos de vieira y los corales a la sartén y saltear 1 min a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Retirar la sartén del fuego y repartir la mezcla entre las conchas limpias.","minutes":2,"kind":"activo"},{"text":"Fundir el resto de la mantequilla en la sartén limpia a fuego suave.","minutes":1,"kind":"activo"},{"text":"Mezclar {{Pan rallado}} con la mantequilla fundida en un bol hasta obtener una mezcla arenosa.","minutes":1,"kind":"prep"},{"text":"Espolvorear la mezcla de pan rallado sobre cada concha rellena de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Gratinar las conchas en el horno a 220 °C en modo grill hasta que la superficie esté dorada.","minutes":6,"kind":"pasivo"},{"text":"Espolvorear el perejil picado sobre las conchas y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, 'especial', NULL, 'horno', NULL, NULL),
  ('pescados_095', 'Congrio en salsa verde con almejas', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 40, 'elaborada', 'all', 300, 30, 8, 14, 2, true, true, '{"pescado","moluscos","gluten","sulfitos"}', '[{"name":"Congrio en rodajas","amount":400,"unit":"g"},{"name":"Almejas","amount":150,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Perejil","amount":15,"unit":"g"},{"name":"Harina de trigo","amount":12,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Caldo de pescado","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":35,"unit":"ml"}]'::jsonb, '{"Sumergir almejas en agua fría con sal para que suelten la arena.","Laminar ajo fino.","Picar perejil fino y reservar.","Calentar aceite de oliva en una cazuela ancha a fuego suave.","Sofreír el ajo laminado a fuego suave hasta que empiece a dorar.","Añadir harina de trigo y remover sin parar hasta que esté integrada sin coger color.","Verter vino blanco poco a poco sin dejar de remover hasta que la salsa ligue.","Añadir caldo de pescado poco a poco sin dejar de remover hasta obtener una salsa sin grumos.","Añadir la mitad del perejil picado y remover para integrarlo en la salsa.","Colocar congrio en rodajas en la cazuela en una sola capa.","Escurrir las almejas y repartirlas entre las rodajas de congrio.","Tapar la cazuela y cocer a fuego suave hasta que las almejas se abran y el congrio esté hecho.","Espolvorear con el resto del perejil picado y servir en la misma cazuela."}', 'Congrio en una salsa verde ligada y brillante, con almejas abiertas alrededor recién cocinadas.', '[{"appliance":"horno","time":45,"difficulty":"elaborada","prepSummary":"Prepara la salsa verde en una cazuela apta para horno, sofriendo el ajo y añadiendo la harina, vino y caldo hasta espesar. Incorpora el congrio y las almejas, y hornea a 180°C durante unos 20-25 minutos hasta que el pescado esté tierno y las almejas abiertas, vigilando que no se "},{"appliance":"thermomix","time":35,"difficulty":"normal","prepSummary":"Pica el ajo y perejil. Prepara la salsa verde en el vaso, sofriendo el ajo y luego añadiendo la harina, vino y caldo para cocinarla. Incorpora el congrio y las almejas y cocina a 90-100°C, velocidad cuchara inversa, durante 15-20 minutos, hasta que el pescado esté hecho y las alm"}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Sumergir {{Almejas}} en agua fría con {{Sal|gusto}} para que suelten la arena.","minutes":30,"kind":"espera"},{"text":"Laminar {{Ajo}} fino.","minutes":2,"kind":"prep"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela ancha a fuego suave.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo laminado a fuego suave hasta que empiece a dorar.","minutes":3,"kind":"activo"},{"text":"Añadir {{Harina de trigo}} y remover sin parar hasta que esté integrada sin coger color.","minutes":1,"kind":"activo"},{"text":"Verter {{Vino blanco}} poco a poco sin dejar de remover hasta que la salsa ligue.","minutes":2,"kind":"activo"},{"text":"Añadir {{Caldo de pescado}} poco a poco sin dejar de remover hasta obtener una salsa sin grumos.","minutes":2,"kind":"activo"},{"text":"Añadir la mitad del perejil picado y remover para integrarlo en la salsa.","minutes":1,"kind":"activo"},{"text":"Colocar {{Congrio en rodajas}} en la cazuela en una sola capa.","minutes":1,"kind":"activo"},{"text":"Escurrir las almejas y repartirlas entre las rodajas de congrio.","minutes":1,"kind":"activo"},{"text":"Tapar la cazuela y cocer a fuego suave hasta que las almejas se abran y el congrio esté hecho.","minutes":12,"kind":"pasivo"},{"text":"Espolvorear con el resto del perejil picado y servir en la misma cazuela.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, true),
  ('pescados_096', 'Salmonetes a la plancha con romesco', 'pescados', 'pescado_azul', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 40, 'facil', 'all', 340, 28, 10, 20, 2, true, false, '{"pescado","frutos_secos","gluten"}', '[{"name":"Salmonetes limpios","amount":400,"unit":"g"},{"name":"Tomate maduro","amount":150,"unit":"g"},{"name":"Pimiento choricero o ñora hidratado","amount":20,"unit":"g"},{"name":"Almendras tostadas","amount":25,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Pan frito","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Calentar el horno a 200 °C.","Lavar tomate maduro y ajo y disponerlos en una bandeja con piel, sin pelar.","Hornear el tomate y el ajo a 200 °C durante 20 min hasta que estén blandos y la piel esté chamuscada.","Secar salmonetes limpios con papel de cocina mientras hornea el tomate.","Raspar la pulpa de pimiento choricero o ñora hidratado con una cuchara, desechando la piel.","Retirar el tomate y el ajo del horno cuando estén blandos y dejar templar 5 min.","Pelar el tomate y el ajo una vez templados.","Triturar el tomate y el ajo pelados junto con la pulpa del pimiento, almendras tostadas, pan frito, vinagre de vino y aceite de oliva hasta obtener una salsa fina.","Reservar el romesco a temperatura ambiente.","Calentar plancha a fuego fuerte hasta que humee.","Añadir aceite de oliva sobre la plancha caliente.","Cocinar los salmonetes 3 min por el primer lado sin moverlos hasta que la piel esté crujiente.","Dar la vuelta a los salmonetes y cocinar 2 min más hasta que la carne esté opaca.","Servir los salmonetes recién hechos con el romesco al lado."}', 'Salmonetes de piel rosada y crujiente a la plancha, con una salsa romesco de contraste.', '[{"appliance":"airfryer","time":45,"difficulty":"facil","prepSummary":"Para los salmonetes, cocínalos directamente en la airfryer a 190°C durante 10-12 minutos, dándoles la vuelta a mitad para un dorado uniforme. Para el romesco, asa los tomates, pimiento y ajo en la airfryer a 180°C por 15-20 minutos, luego tritura con el resto de ingredientes."},{"appliance":"horno","time":50,"difficulty":"facil","prepSummary":"Para el romesco, asa los tomates, pimiento y ajo en el horno a 200°C durante 20-25 minutos. Luego, hornea los salmonetes a 210°C por 15-18 minutos hasta que estén dorados, pudiendo usar el grill al final. Tritura los ingredientes asados con el resto para la salsa."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Calentar el horno a 200 °C.","minutes":10,"kind":"pasivo","part":"salsa"},{"text":"Lavar {{Tomate maduro}} y {{Ajo}} y disponerlos en una bandeja con piel, sin pelar.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Hornear el tomate y el ajo a 200 °C durante 20 min hasta que estén blandos y la piel esté chamuscada.","minutes":20,"kind":"pasivo","part":"salsa"},{"text":"Secar {{Salmonetes limpios}} con papel de cocina mientras hornea el tomate.","minutes":2,"kind":"paralelo","part":"principal","during":2},{"text":"Raspar la pulpa de {{Pimiento choricero o ñora hidratado}} con una cuchara, desechando la piel.","minutes":2,"kind":"paralelo","part":"salsa","during":2},{"text":"Retirar el tomate y el ajo del horno cuando estén blandos y dejar templar 5 min.","minutes":5,"kind":"espera","part":"salsa"},{"text":"Pelar el tomate y el ajo una vez templados.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Triturar el tomate y el ajo pelados junto con la pulpa del pimiento, {{Almendras tostadas}}, {{Pan frito}}, {{Vinagre de vino}} y {{Aceite de oliva}} hasta obtener una salsa fina.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Reservar el romesco a temperatura ambiente.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que humee.","minutes":2,"kind":"activo","part":"principal"},{"text":"Añadir {{Aceite de oliva|chorrito}} sobre la plancha caliente.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cocinar los salmonetes 3 min por el primer lado sin moverlos hasta que la piel esté crujiente.","minutes":3,"kind":"activo","part":"principal"},{"text":"Dar la vuelta a los salmonetes y cocinar 2 min más hasta que la carne esté opaca.","minutes":2,"kind":"activo","part":"principal"},{"text":"Servir los salmonetes recién hechos con el romesco al lado.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL, true),
  ('pescados_097', 'Tacos de pescado estilo Baja California', 'pescados', 'pescado_blanco', 'pan', ARRAY['segundo','cena']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 420, 26, 40, 18, 2, true, false, '{"pescado","gluten","huevo","lactosa"}', '[{"name":"Filetes de merluza o abadejo","amount":300,"unit":"g"},{"name":"Harina de trigo","amount":60,"unit":"g"},{"name":"Cerveza fría","amount":100,"unit":"ml"},{"name":"Tortillas de trigo pequeñas","amount":6,"unit":"ud"},{"name":"Repollo morado","amount":100,"unit":"g"},{"name":"Yogur natural","amount":60,"unit":"g"},{"name":"Mayonesa","amount":30,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Cilantro fresco","amount":5,"unit":"g"},{"name":"Aceite de girasol","amount":300,"unit":"ml"}]'::jsonb, '{"Cortar filetes de merluza o abadejo en tiras de unos 2 cm de ancho.","Laminar repollo morado en juliana muy fina.","Exprimir lima y reservar el zumo.","Picar cilantro fresco fino.","Mezclar yogur natural, mayonesa, la mitad del zumo de lima y el cilantro picado hasta obtener una salsa homogénea.","Mezclar harina de trigo con cerveza fría hasta obtener una masa de rebozado ligera y sin grumos.","Calentar aceite de girasol en una sartén honda a fuego fuerte hasta que alcance unos 180 °C.","Pasar las tiras de merluza por la masa de rebozado, cubriendo bien cada pieza.","Freír las tiras rebozadas en tandas, sin amontonarlas, hasta que estén doradas y crujientes.","Escurrir las tiras fritas sobre papel absorbente.","Calentar tortillas de trigo pequeñas en sartén seca a fuego medio, 30 segundos por cada lado, hasta que estén flexibles.","Repartir el repollo en juliana sobre cada tortilla caliente.","Colocar 2 o 3 tiras de merluza rebozada sobre el repollo en cada tortilla.","Añadir un poco de salsa cremosa encima y unas gotas del zumo de lima restante.","Servir de inmediato."}', 'Tacos de pescado rebozado y crujiente, con repollo morado y una salsa cremosa de lima, estilo Baja California.', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Para los filetes de pescado, sumérgelos en la mezcla de harina y cerveza, rocía con un poco de aceite y cocina en la airfryer a 190°C durante 15-20 minutos, volteando a mitad, hasta que estén dorados y crujientes. Las tortillas se pueden calentar brevemente en la airfryer también"},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Reboza los filetes de merluza y colócalos en una bandeja de horno con papel de hornear, rociando con un poco de aceite. Hornea a 200°C (con calor arriba y abajo) durante 20-25 minutos, o hasta que estén dorados y cocidos, volteando una vez. Las tortillas se pueden calentar en el "}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Filetes de merluza o abadejo}} en tiras de unos 2 cm de ancho.","minutes":3,"kind":"prep"},{"text":"Laminar {{Repollo morado}} en juliana muy fina.","minutes":3,"kind":"prep"},{"text":"Exprimir {{Lima}} y reservar el zumo.","minutes":1,"kind":"prep"},{"text":"Picar {{Cilantro fresco}} fino.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Yogur natural}}, {{Mayonesa}}, la mitad del zumo de lima y el cilantro picado hasta obtener una salsa homogénea.","minutes":2,"kind":"activo"},{"text":"Mezclar {{Harina de trigo}} con {{Cerveza fría}} hasta obtener una masa de rebozado ligera y sin grumos.","minutes":2,"kind":"activo"},{"text":"Calentar {{Aceite de girasol}} en una sartén honda a fuego fuerte hasta que alcance unos 180 °C.","minutes":3,"kind":"activo"},{"text":"Pasar las tiras de merluza por la masa de rebozado, cubriendo bien cada pieza.","minutes":2,"kind":"activo"},{"text":"Freír las tiras rebozadas en tandas, sin amontonarlas, hasta que estén doradas y crujientes.","minutes":3,"kind":"activo"},{"text":"Escurrir las tiras fritas sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Calentar {{Tortillas de trigo pequeñas}} en {{@Sartén}} seca a fuego medio, 30 segundos por cada lado, hasta que estén flexibles.","minutes":3,"kind":"activo"},{"text":"Repartir el repollo en juliana sobre cada tortilla caliente.","minutes":1,"kind":"emplatado"},{"text":"Colocar 2 o 3 tiras de merluza rebozada sobre el repollo en cada tortilla.","minutes":1,"kind":"emplatado"},{"text":"Añadir un poco de salsa cremosa encima y unas gotas del zumo de lima restante.","minutes":1,"kind":"emplatado"},{"text":"Servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', 'mexicana', NULL)
