insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('pescados_098', 'Bowl de salmón, arroz y sriracha', 'pescados', 'pescado_azul', 'arroz', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 780, 36, 60, 40, 2, false, true, '{"pescado","huevo","soja","sesamo","gluten"}', '[{"name":"Salmón (lomos)","amount":280,"unit":"g"},{"name":"Arroz blanco","amount":140,"unit":"g"},{"name":"Aguacate","amount":100,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Edamame","amount":60,"unit":"g"},{"name":"Mayonesa","amount":40,"unit":"g"},{"name":"Sriracha","amount":15,"unit":"g"},{"name":"Salsa de soja","amount":10,"unit":"ml"},{"name":"Sésamo tostado","amount":5,"unit":"g"},{"name":"Cebollino","amount":5,"unit":"g"}]'::jsonb, '{"Cocer arroz blanco en agua con sal según el tiempo del paquete.","Mezclar mayonesa con sriracha y salsa de soja hasta obtener una crema homogénea.","Cortar pepino en bastones finos.","Laminar aguacate.","Picar cebollino fino.","Escurrir el arroz cocido y reservar templado.","Salpimentar salmón (lomos) por ambas caras.","Calentar sartén a fuego fuerte y dorar los lomos de salmón 2 min por cada lado, hasta que estén dorados por fuera y jugosos por dentro.","Retirar el salmón del fuego y desmenuzarlo en lascas grandes con un tenedor.","Repartir el arroz templado en 2 boles.","Colocar encima las lascas de salmón, el aguacate laminado, el pepino en bastones y edamame por zonas.","Rociar la crema de mayonesa y sriracha sobre el bowl.","Espolvorear sésamo tostado y el cebollino picado, y servir."}', 'Bowl templado de salmón desmenuzado y arroz con aguacate, edamame y una cremosa mayonesa picante de sriracha.', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Cocina el salmón en la airfryer a 190°C durante 12-15 minutos para un exterior ligeramente crujiente y un interior jugoso. Mientras, prepara el arroz por separado y el resto de ingredientes para montar el bowl."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Hornea el salmón a 200°C durante 15-20 minutos hasta que esté cocido y ligeramente dorado. Prepara el arroz y el resto de ingredientes frescos mientras el salmón se cocina."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina el arroz en el cestillo y el salmón (junto con el edamame) en el Varoma simultáneamente durante unos 20 minutos. Esto optimiza el tiempo y asegura una cocción perfecta y jugosa de todos los componentes principales."},{"appliance":"vaporera","time":30,"difficulty":"facil","prepSummary":"Cocina el arroz en un recipiente apto para vaporera y el salmón (y edamame) en las bandejas superiores durante unos 20-25 minutos. El salmón quedará muy jugoso y saludable, manteniendo todos sus nutrientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cocer {{Arroz blanco}} en agua con sal según el tiempo del paquete.","minutes":15,"kind":"pasivo"},{"text":"Mezclar {{Mayonesa}} con {{Sriracha}} y {{Salsa de soja}} hasta obtener una crema homogénea.","minutes":2,"kind":"paralelo","during":0},{"text":"Cortar {{Pepino}} en bastones finos.","minutes":2,"kind":"paralelo","during":0},{"text":"Laminar {{Aguacate}}.","minutes":1,"kind":"paralelo","during":0},{"text":"Picar {{Cebollino}} fino.","minutes":1,"kind":"paralelo","during":0},{"text":"Escurrir el arroz cocido y reservar templado.","minutes":1,"kind":"prep"},{"text":"Salpimentar {{Salmón (lomos)}} por ambas caras.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego fuerte y dorar los lomos de salmón 2 min por cada lado, hasta que estén dorados por fuera y jugosos por dentro.","minutes":4,"kind":"activo"},{"text":"Retirar el salmón del fuego y desmenuzarlo en lascas grandes con un tenedor.","minutes":1,"kind":"prep"},{"text":"Repartir el arroz templado en 2 boles.","minutes":1,"kind":"emplatado"},{"text":"Colocar encima las lascas de salmón, el aguacate laminado, el pepino en bastones y {{Edamame}} por zonas.","minutes":2,"kind":"emplatado"},{"text":"Rociar la crema de mayonesa y sriracha sobre el bowl.","minutes":1,"kind":"emplatado"},{"text":"Espolvorear {{Sésamo tostado}} y el cebollino picado, y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, true),
  ('pescados_099', 'Rodaballo a la plancha con patatas panadera y velouté de marisco', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 590, 30, 34, 37, 2, true, true, '{"pescado","marisco","lactosa","gluten","sulfitos"}', '[{"name":"Rodaballo (filetes)","amount":320,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Fumet de marisco","amount":200,"unit":"ml"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Vino blanco","amount":40,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en rodajas de 3 mm de grosor.","Laminar cebolla en juliana fina.","Calentar aceite de oliva en sartén a fuego medio-bajo.","Añadir las patatas y la cebolla y confitar a fuego suave hasta que estén tiernas y ligeramente doradas.","Fundir mantequilla en un cazo a fuego medio.","Añadir harina y remover sin parar hasta formar un roux liso.","Verter vino blanco y remover hasta que reduzca a la mitad.","Incorporar fumet de marisco poco a poco sin dejar de remover hasta obtener una salsa lisa y sin grumos.","Añadir nata para cocinar y cocer a fuego suave hasta que la velouté espese ligeramente.","Salpimentar la velouté y reservar caliente fuera del fuego.","Salpimentar rodaballo (filetes) por ambas caras.","Calentar plancha a fuego fuerte hasta que humee.","Marcar los filetes de rodaballo por el lado de la piel durante 2-3 min hasta que estén dorados.","Dar la vuelta a los filetes y marcar 1-2 min por el otro lado hasta que estén jugosos.","Repartir las patatas confitadas en la base de cada plato.","Colocar encima el rodaballo a la plancha y napar con la velouté caliente."}', 'Rodaballo a la plancha sobre patatas panadera doradas, napado con una velouté cremosa de marisco.', '[]'::jsonb, '{}', true, NULL, NULL, '{"lacteo"}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Pelar {{Patata}} y laminar en rodajas de 3 mm de grosor.","minutes":3,"kind":"prep","part":"guarnicion"},{"text":"Laminar {{Cebolla}} en juliana fina.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio-bajo.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Añadir las patatas y la cebolla y confitar a fuego suave hasta que estén tiernas y ligeramente doradas.","minutes":17,"kind":"pasivo","part":"guarnicion"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego medio.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Añadir {{Harina}} y remover sin parar hasta formar un roux liso.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Verter {{Vino blanco}} y remover hasta que reduzca a la mitad.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Incorporar {{Fumet de marisco}} poco a poco sin dejar de remover hasta obtener una salsa lisa y sin grumos.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Añadir {{Nata para cocinar}} y cocer a fuego suave hasta que la velouté espese ligeramente.","minutes":5,"kind":"pasivo","part":"salsa"},{"text":"Salpimentar la velouté y reservar caliente fuera del fuego.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Salpimentar {{Rodaballo (filetes)}} por ambas caras.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que humee.","minutes":2,"kind":"activo","part":"principal"},{"text":"Marcar los filetes de rodaballo por el lado de la piel durante 2-3 min hasta que estén dorados.","minutes":3,"kind":"activo","part":"principal"},{"text":"Dar la vuelta a los filetes y marcar 1-2 min por el otro lado hasta que estén jugosos.","minutes":2,"kind":"activo","part":"principal"},{"text":"Repartir las patatas confitadas en la base de cada plato.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Colocar encima el rodaballo a la plancha y napar con la velouté caliente.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, 'especial', NULL, 'plancha', NULL, true),
  ('pescados_100', 'Bacalao confitado sobre puré de coliflor con pil-pil', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 55, 'elaborada', 'all', 590, 32, 11, 46, 2, true, false, '{"pescado","lactosa"}', '[{"name":"Bacalao desalado (lomos)","amount":320,"unit":"g"},{"name":"Coliflor","amount":400,"unit":"g"},{"name":"Aceite de oliva suave","amount":70,"unit":"ml"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Nata para cocinar","amount":50,"unit":"ml"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Cortar coliflor en arbolitos pequeños.","Llevar a ebullición una olla con agua y sal. Añadir los arbolitos de coliflor y cocer 15 min hasta que estén muy tiernos.","Laminar ajo en láminas finas.","Calentar aceite de oliva suave en sartén a fuego suave. Sofreír el ajo laminado hasta que empiece a dorarse.","Retirar el ajo dorado de la sartén y reservar. Mantener el aceite en la sartén fuera del fuego.","Escurrir la coliflor cocida y dejar reposar 1 min para que pierda el exceso de vapor.","Triturar la coliflor escurrida con nata para cocinar, mantequilla y sal hasta obtener un puré fino y sedoso.","Reservar el puré caliente tapado.","Calentar el aceite reservado en la sartén a fuego muy suave, sin que llegue a humear.","Introducir bacalao desalado (lomos) con la piel hacia arriba. Confitar 9 min sin que el aceite llegue a hervir, hasta que la carne se separe en lascas.","Retirar los lomos con cuidado y reservar calientes tapados.","Colar el aceite de confitar en un cazo, dejando en el colador la gelatina que ha soltado el bacalao.","Añadir la gelatina del colador al cazo. Mover el cazo en círculos a fuego muy suave, incorporando el aceite poco a poco.","Continuar moviendo el cazo hasta que la salsa emulsione y adquiera un color blanquecino y textura untuosa.","Picar perejil fino.","Repartir el puré de coliflor en la base de los platos. Colocar encima los lomos de bacalao confitado.","Napar con el pil-pil. Terminar con el ajo laminado reservado y el perejil picado."}', 'Bacalao confitado a baja temperatura sobre un puré sedoso de coliflor, napado con un pil-pil brillante.', '[{"appliance":"horno","time":65,"difficulty":"elaborada","prepSummary":"El bacalao se confita en una fuente con aceite a baja temperatura (90-100°C) en el horno durante 30-40 minutos. La coliflor se puede asar en el horno para el puré, o cocer al vapor aparte, y el pil-pil se emulsiona en un cazo en la encimera."},{"appliance":"thermomix","time":45,"difficulty":"normal","prepSummary":"La Thermomix permite confitar el bacalao a baja temperatura (90°C, velocidad cuchara) en el vaso. La coliflor se cuece al vapor en el Varoma y se tritura en el vaso para el puré, y el pil-pil se emulsiona fácilmente con el aceite del confitado y los ajos, controlando temperatura "}]'::jsonb, '{}', true, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Coliflor}} en arbolitos pequeños.","minutes":3,"kind":"prep","part":"guarnicion"},{"text":"Llevar a ebullición una olla con agua y sal. Añadir los arbolitos de coliflor y cocer 15 min hasta que estén muy tiernos.","minutes":18,"kind":"pasivo","part":"guarnicion"},{"text":"Laminar {{Ajo}} en láminas finas.","minutes":2,"kind":"paralelo","part":"principal","during":1},{"text":"Calentar {{Aceite de oliva suave}} en {{@Sartén}} a fuego suave. Sofreír el ajo laminado hasta que empiece a dorarse.","minutes":5,"kind":"activo","part":"principal"},{"text":"Retirar el ajo dorado de la sartén y reservar. Mantener el aceite en la sartén fuera del fuego.","minutes":1,"kind":"prep","part":"principal"},{"text":"Escurrir la coliflor cocida y dejar reposar 1 min para que pierda el exceso de vapor.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Triturar la coliflor escurrida con {{Nata para cocinar}}, {{Mantequilla}} y sal hasta obtener un puré fino y sedoso.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Reservar el puré caliente tapado.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Calentar el aceite reservado en la sartén a fuego muy suave, sin que llegue a humear.","minutes":2,"kind":"activo","part":"principal"},{"text":"Introducir {{Bacalao desalado (lomos)}} con la piel hacia arriba. Confitar 9 min sin que el aceite llegue a hervir, hasta que la carne se separe en lascas.","minutes":9,"kind":"pasivo","part":"principal"},{"text":"Retirar los lomos con cuidado y reservar calientes tapados.","minutes":1,"kind":"prep","part":"principal"},{"text":"Colar el aceite de confitar en un cazo, dejando en el colador la gelatina que ha soltado el bacalao.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Añadir la gelatina del colador al cazo. Mover el cazo en círculos a fuego muy suave, incorporando el aceite poco a poco.","minutes":4,"kind":"activo","part":"salsa"},{"text":"Continuar moviendo el cazo hasta que la salsa emulsione y adquiera un color blanquecino y textura untuosa.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Picar {{Perejil}} fino.","minutes":1,"kind":"prep","part":"combinado"},{"text":"Repartir el puré de coliflor en la base de los platos. Colocar encima los lomos de bacalao confitado.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Napar con el pil-pil. Terminar con el ajo laminado reservado y el perejil picado.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('pescados_101', 'Filete de lubina con patatas panadera y beurre blanc de alcaparras', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'normal', 'all', 630, 35, 28, 44, 2, false, false, '{"pescado","lactosa","sulfitos"}', '[{"name":"Lubina (filetes)","amount":320,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Chalota","amount":30,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Vinagre de vino blanco","amount":10,"unit":"ml"},{"name":"Alcaparras","amount":20,"unit":"g"}]'::jsonb, '{"Pelar patata y laminarlas en rodajas finas de unos 3 mm.","Laminar cebolla en juliana fina.","Calentar aceite de oliva en una sartén amplia a fuego medio-bajo.","Añadir las patatas laminadas y la cebolla en juliana a la sartén.","Confitar las patatas y la cebolla a fuego suave durante 16 min, hasta que estén tiernas y ligeramente doradas.","Picar chalota muy fina mientras las patatas confitan.","Picar alcaparras finamente y reservar.","Retirar las patatas del fuego, salpimentar y reservar en un lugar templado.","Verter vino blanco y vinagre de vino blanco junto con la chalota picada en un cazo pequeño.","Reducir a fuego medio hasta que quede apenas 2 cucharadas de líquido, unos 5 min.","Cortar mantequilla en dados fríos mientras la reducción se concentra.","Bajar el fuego al mínimo e incorporar los dados de mantequilla fría de uno en uno, batiendo sin parar.","Remover hasta que la salsa emulsione y quede cremosa y brillante.","Añadir las alcaparras picadas, mezclar y retirar del fuego. Reservar caliente sin que vuelva a hervir.","Salpimentar lubina (filetes) por ambos lados.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Añadir aceite de oliva sobre la plancha y colocar los filetes con la piel hacia abajo.","Cocinar los filetes por el lado de la piel 3 min, hasta que la piel esté crujiente y dorada.","Dar la vuelta a los filetes y cocinar 1 min más por el lado de la carne, hasta que estén justos de punto.","Repartir las patatas panadera en la base de los platos y colocar los filetes encima con la piel hacia arriba.","Salsear generosamente con el beurre blanc de alcaparras y servir de inmediato."}', 'Filete de lubina a la plancha con patatas panadera y una mantecosa salsa beurre blanc de alcaparras.', '[{"appliance":"horno","time":45,"difficulty":"normal","prepSummary":"Para las patatas panadera, corta las patatas y cebolla en rodajas finas, mézclalas con aceite de oliva y sal, y hornea en una fuente a 180°C durante 30-35 minutos. Añade los filetes de lubina sobre las patatas o en una bandeja aparte y hornea 10-12 minutos más hasta que estén coc"}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo","encurtido"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y laminarlas en rodajas finas de unos 3 mm.","minutes":4,"kind":"prep","part":"guarnicion"},{"text":"Laminar {{Cebolla}} en juliana fina.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una sartén amplia a fuego medio-bajo.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Añadir las patatas laminadas y la cebolla en juliana a la sartén.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Confitar las patatas y la cebolla a fuego suave durante 16 min, hasta que estén tiernas y ligeramente doradas.","minutes":16,"kind":"pasivo","part":"guarnicion"},{"text":"Picar {{Chalota}} muy fina mientras las patatas confitan.","minutes":2,"kind":"paralelo","part":"salsa","during":4},{"text":"Picar {{Alcaparras}} finamente y reservar.","minutes":1,"kind":"paralelo","part":"salsa","during":4},{"text":"Retirar las patatas del fuego, salpimentar y reservar en un lugar templado.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Verter {{Vino blanco}} y {{Vinagre de vino blanco}} junto con la chalota picada en un cazo pequeño.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Reducir a fuego medio hasta que quede apenas 2 cucharadas de líquido, unos 5 min.","minutes":5,"kind":"pasivo","part":"salsa"},{"text":"Cortar {{Mantequilla}} en dados fríos mientras la reducción se concentra.","minutes":2,"kind":"paralelo","part":"salsa","during":9},{"text":"Bajar el fuego al mínimo e incorporar los dados de mantequilla fría de uno en uno, batiendo sin parar.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Remover hasta que la salsa emulsione y quede cremosa y brillante.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Añadir las alcaparras picadas, mezclar y retirar del fuego. Reservar caliente sin que vuelva a hervir.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Salpimentar {{Lubina (filetes)}} por ambos lados.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo","part":"principal"},{"text":"Añadir {{Aceite de oliva|chorrito}} sobre la plancha y colocar los filetes con la piel hacia abajo.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cocinar los filetes por el lado de la piel 3 min, hasta que la piel esté crujiente y dorada.","minutes":3,"kind":"activo","part":"principal"},{"text":"Dar la vuelta a los filetes y cocinar 1 min más por el lado de la carne, hasta que estén justos de punto.","minutes":1,"kind":"activo","part":"principal"},{"text":"Repartir las patatas panadera en la base de los platos y colocar los filetes encima con la piel hacia arriba.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Salsear generosamente con el beurre blanc de alcaparras y servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL, NULL),
  ('pescados_102', 'Pescadilla frita con patatas paja y alioli de limón', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 780, 33, 50, 46, 2, true, false, '{"pescado","gluten","huevo"}', '[{"name":"Pescadilla (filetes)","amount":320,"unit":"g"},{"name":"Patata","amount":350,"unit":"g"},{"name":"Harina","amount":50,"unit":"g"},{"name":"Aceite de oliva suave","amount":300,"unit":"ml"},{"name":"Mayonesa","amount":60,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar patata y laminar en juliana muy fina con mandolina.","Sumergir la patata en agua fría durante 10 min para eliminar el exceso de almidón.","Escurrir la patata y secarla bien con un paño limpio.","Rallar la piel de limón y exprimir la mitad.","Picar ajo muy fino.","Mezclar mayonesa con el ajo picado, la ralladura y el zumo de limón hasta integrar.","Reservar el alioli de limón en frío.","Calentar aceite de oliva suave en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír la patata en tandas hasta que esté dorada y crujiente.","Escurrir la patata sobre papel absorbente y salar al gusto.","Salpimentar pescadilla (filetes).","Pasar los filetes por harina, sacudiendo el exceso.","Freír los filetes en el mismo aceite caliente 2 min por el primer lado, hasta que estén dorados.","Dar la vuelta a los filetes y freír 2 min más por el otro lado, hasta que estén dorados y crujientes.","Escurrir los filetes sobre papel absorbente.","Servir la pescadilla con la patata paja y el alioli de limón al lado."}', 'Pescadilla rebozada y frita bien crujiente, con una nube de patatas paja y un alioli suave de limón.', '[{"appliance":"airfryer","time":35,"difficulty":"facil","prepSummary":"Para la pescadilla y las patatas, precalienta la airfryer a 190°C. Cocina el pescado enharinado y ligeramente rociado con aceite durante 12-15 minutos. Las patatas cortadas finas, también con un poco de aceite, cocínalas en tandas si es necesario, unos 15-20 minutos, agitando a m"},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Hornea la pescadilla enharinada y rociada con un hilo de aceite durante 15-20 minutos. Las patatas cortadas finas, con un poco de aceite y sal, hornéalas en una sola capa por 25-35 minutos, volteándolas a mitad, hasta que estén doradas y crujientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y laminar en juliana muy fina con mandolina.","minutes":5,"kind":"prep","part":"guarnicion"},{"text":"Sumergir la patata en agua fría durante 10 min para eliminar el exceso de almidón.","minutes":10,"kind":"espera","part":"guarnicion"},{"text":"Escurrir la patata y secarla bien con un paño limpio.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Rallar la piel de {{Limón}} y exprimir la mitad.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Mezclar {{Mayonesa}} con el ajo picado, la ralladura y el zumo de limón hasta integrar.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Reservar el alioli de limón en frío.","minutes":1,"kind":"espera","part":"salsa"},{"text":"Calentar {{Aceite de oliva suave|abundante}} en una sartén honda a fuego fuerte hasta alcanzar 180 °C.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Freír la patata en tandas hasta que esté dorada y crujiente.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Escurrir la patata sobre papel absorbente y salar al gusto.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Salpimentar {{Pescadilla (filetes)}}.","minutes":1,"kind":"prep","part":"principal"},{"text":"Pasar los filetes por {{Harina}}, sacudiendo el exceso.","minutes":1,"kind":"prep","part":"principal"},{"text":"Freír los filetes en el mismo aceite caliente 2 min por el primer lado, hasta que estén dorados.","minutes":2,"kind":"activo","part":"principal"},{"text":"Dar la vuelta a los filetes y freír 2 min más por el otro lado, hasta que estén dorados y crujientes.","minutes":2,"kind":"activo","part":"principal"},{"text":"Escurrir los filetes sobre papel absorbente.","minutes":1,"kind":"activo","part":"principal"},{"text":"Servir la pescadilla con la patata paja y el alioli de limón al lado.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, true),
  ('pescados_103', 'Salmón a la plancha con puré de boniato y salsa teriyaki', 'pescados', 'pescado_azul', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 660, 36, 50, 33, 2, true, true, '{"pescado","lactosa","soja","sesamo","gluten"}', '[{"name":"Salmón (lomos)","amount":320,"unit":"g"},{"name":"Boniato","amount":400,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Leche","amount":40,"unit":"ml"},{"name":"Salsa de soja","amount":30,"unit":"ml"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Maicena","amount":5,"unit":"g"},{"name":"Aceite de sésamo","amount":5,"unit":"ml"},{"name":"Sésamo tostado","amount":5,"unit":"g"}]'::jsonb, '{"Pelar boniato y cortar en trozos de tamaño similar.","Cocer el boniato en una olla con agua abundante y sal hasta que esté muy tierno.","Rallar jengibre fresco y picar ajo muy fino.","Mezclar salsa de soja, miel, el jengibre rallado y el ajo picado en un cazo pequeño.","Disolver maicena en una cucharadita de agua fría.","Llevar el cazo a fuego medio y añadir la maicena disuelta, removiendo hasta que la salsa espese y quede brillante.","Retirar el cazo del fuego y añadir aceite de sésamo. Reservar la salsa teriyaki.","Escurrir el boniato cocido.","Calentar leche en el mismo cazo a fuego suave.","Triturar el boniato escurrido con mantequilla y la leche caliente hasta obtener un puré fino.","Salpimentar el puré y reservar caliente tapado.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Salpimentar salmón (lomos) por ambos lados.","Colocar los lomos de salmón con la piel hacia abajo y cocinar hasta que la piel esté dorada y crujiente.","Dar la vuelta a los lomos y cocinar por el otro lado hasta que el salmón esté jugoso por dentro.","Pincelar los lomos con parte de la salsa teriyaki y retirar del fuego en cuanto se glaseen.","Repartir el puré de boniato en la base de los platos y colocar encima cada lomo de salmón.","Salsear con el resto de la salsa teriyaki y espolvorear sésamo tostado por encima."}', 'Salmón a la plancha glaseado en teriyaki casero, servido sobre un cremoso puré de boniato.', '[{"appliance":"airfryer","time":40,"difficulty":"facil","prepSummary":"Cocina el salmón a 180°C durante 12-15 minutos para un exterior crujiente y jugoso. El boniato, cortado en cubos, se cocina a 180°C por 15-20 minutos hasta ablandar y luego se tritura para el puré. La salsa teriyaki se prepara aparte en un cazo."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Asa el salmón a 190°C durante 15-20 minutos hasta que esté tierno y jugoso. El boniato se asa entero o en trozos a la misma temperatura por 30-40 minutos, luego se tritura para el puré. La salsa se elabora en un cazo aparte."},{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Prepara el puré de boniato cociéndolo al vapor en el Varoma y luego triturándolo con el resto de ingredientes. El salmón se cocina al vapor en el Varoma simultáneamente. La salsa teriyaki se elabora y espesa en el vaso de la Thermomix, picando previamente el jengibre y ajo."},{"appliance":"vaporera","time":30,"difficulty":"facil","prepSummary":"Cocina el boniato al vapor hasta que esté muy tierno para el puré. El salmón se cuece al vapor en la misma vaporera, resultando jugoso y saludable. La salsa teriyaki se prepara en un cazo aparte."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Cuece el boniato en la olla express con un poco de agua hasta que esté muy tierno (aprox. 5-7 min desde que sube la válvula) para el puré. El salmón se cocina al vapor en la misma olla en una cesta, muy rápidamente (3-5 min). La salsa se prepara en un cazo aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Boniato}} y cortar en trozos de tamaño similar.","minutes":3,"kind":"prep","part":"guarnicion"},{"text":"Cocer el boniato en una olla con agua abundante y sal hasta que esté muy tierno.","minutes":17,"kind":"pasivo","part":"guarnicion"},{"text":"Rallar {{Jengibre fresco}} y picar {{Ajo}} muy fino.","minutes":2,"kind":"paralelo","part":"salsa","during":1},{"text":"Mezclar {{Salsa de soja}}, {{Miel}}, el jengibre rallado y el ajo picado en un cazo pequeño.","minutes":1,"kind":"paralelo","part":"salsa","during":1},{"text":"Disolver {{Maicena}} en una cucharadita de agua fría.","minutes":1,"kind":"paralelo","part":"salsa","during":1},{"text":"Llevar el cazo a fuego medio y añadir la maicena disuelta, removiendo hasta que la salsa espese y quede brillante.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Retirar el cazo del fuego y añadir {{Aceite de sésamo}}. Reservar la salsa teriyaki.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Escurrir el boniato cocido.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Leche}} en el mismo cazo a fuego suave.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Triturar el boniato escurrido con {{Mantequilla}} y la leche caliente hasta obtener un puré fino.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Salpimentar el puré y reservar caliente tapado.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté muy caliente.","minutes":2,"kind":"activo","part":"principal"},{"text":"Salpimentar {{Salmón (lomos)}} por ambos lados.","minutes":1,"kind":"prep","part":"principal"},{"text":"Colocar los lomos de salmón con la piel hacia abajo y cocinar hasta que la piel esté dorada y crujiente.","minutes":4,"kind":"activo","part":"principal"},{"text":"Dar la vuelta a los lomos y cocinar por el otro lado hasta que el salmón esté jugoso por dentro.","minutes":2,"kind":"activo","part":"principal"},{"text":"Pincelar los lomos con parte de la salsa teriyaki y retirar del fuego en cuanto se glaseen.","minutes":1,"kind":"activo","part":"principal"},{"text":"Repartir el puré de boniato en la base de los platos y colocar encima cada lomo de salmón.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Salsear con el resto de la salsa teriyaki y espolvorear {{Sésamo tostado}} por encima.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'plancha', 'asiatica', true),
  ('pescados_104', 'Rape a la plancha con patatas panadera y salsa verde de almejas', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 550, 40, 36, 24, 2, true, true, '{"pescado","moluscos","gluten","sulfitos"}', '[{"name":"Rape (cola, en medallones)","amount":350,"unit":"g"},{"name":"Almejas","amount":200,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Harina","amount":10,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Poner almejas en un bol con agua fría y sal durante 30 min para que suelten la arena.","Escurrir las almejas y reservar.","Pelar patata y laminar en rodajas finas de unos 3 mm.","Laminar cebolla en juliana fina.","Calentar aceite de oliva en sartén a fuego medio.","Añadir las patatas laminadas y la cebolla en juliana. Confitar a fuego suave 18 min, hasta que estén tiernas y ligeramente doradas.","Laminar ajo en láminas finas.","Picar perejil fino.","Salpimentar las patatas confitadas y reservar en la sartén fuera del fuego.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír el ajo laminado hasta que empiece a dorarse, sin que se queme.","Añadir harina y remover sin parar durante 1 min para tostar la harina sin que coja color.","Verter vino blanco y remover hasta que evapore el alcohol, unos 2 min.","Añadir 60 ml de agua y remover hasta obtener una salsa ligera y homogénea.","Incorporar las almejas escurridas, tapar la cazuela y cocer a fuego medio hasta que se abran, unos 4 min.","Retirar las almejas que no se hayan abierto. Añadir el perejil picado y remover para ligar la salsa.","Salpimentar rape (cola, en medallones) por ambas caras.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Marcar los medallones de rape 3 min por el primer lado, sin moverlos, hasta que estén opacos por la mitad.","Dar la vuelta a los medallones y marcar 3 min más por el otro lado, hasta que estén opacos y firmes al tacto.","Repartir las patatas panadera en la base de los platos.","Colocar los medallones de rape encima de las patatas y napar con la salsa verde de almejas.","Servir de inmediato."}', 'Medallones de rape a la plancha con patatas panadera y una salsa verde ligada con almejas abiertas.', NULL, '{}', true, NULL, NULL, '{}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Poner {{Almejas}} en un bol con agua fría y {{Sal|gusto}} durante 30 min para que suelten la arena.","minutes":30,"kind":"espera","part":"salsa"},{"text":"Escurrir las almejas y reservar.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Pelar {{Patata}} y laminar en rodajas finas de unos 3 mm.","minutes":4,"kind":"prep","part":"guarnicion"},{"text":"Laminar {{Cebolla}} en juliana fina.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Añadir las patatas laminadas y la cebolla en juliana. Confitar a fuego suave 18 min, hasta que estén tiernas y ligeramente doradas.","minutes":18,"kind":"pasivo","part":"guarnicion"},{"text":"Laminar {{Ajo}} en láminas finas.","minutes":2,"kind":"paralelo","part":"salsa","during":5},{"text":"Picar {{Perejil}} fino.","minutes":1,"kind":"paralelo","part":"salsa","during":5},{"text":"Salpimentar las patatas confitadas y reservar en la sartén fuera del fuego.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela a fuego medio.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Sofreír el ajo laminado hasta que empiece a dorarse, sin que se queme.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Añadir {{Harina}} y remover sin parar durante 1 min para tostar la harina sin que coja color.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Verter {{Vino blanco}} y remover hasta que evapore el alcohol, unos 2 min.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Añadir 60 ml de agua y remover hasta obtener una salsa ligera y homogénea.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Incorporar las almejas escurridas, tapar la cazuela y cocer a fuego medio hasta que se abran, unos 4 min.","minutes":4,"kind":"pasivo","part":"salsa"},{"text":"Retirar las almejas que no se hayan abierto. Añadir el perejil picado y remover para ligar la salsa.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Salpimentar {{Rape (cola, en medallones)}} por ambas caras.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté muy caliente.","minutes":2,"kind":"activo","part":"principal"},{"text":"Marcar los medallones de rape 3 min por el primer lado, sin moverlos, hasta que estén opacos por la mitad.","minutes":3,"kind":"activo","part":"principal"},{"text":"Dar la vuelta a los medallones y marcar 3 min más por el otro lado, hasta que estén opacos y firmes al tacto.","minutes":3,"kind":"activo","part":"principal"},{"text":"Repartir las patatas panadera en la base de los platos.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Colocar los medallones de rape encima de las patatas y napar con la salsa verde de almejas.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Servir de inmediato.","kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL, NULL),
  ('pescados_105', 'Dorada al horno con patatas panadera y romesco', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'all', 720, 48, 36, 40, 2, true, true, '{"pescado","frutos_secos","gluten","sulfitos"}', '[{"name":"Dorada (limpia, entera)","amount":700,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Tomate","amount":100,"unit":"g"},{"name":"Pimiento choricero (pulpa de ñora)","amount":15,"unit":"g"},{"name":"Almendra tostada","amount":30,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pan","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Vinagre de vino","amount":10,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar patata y laminar en rodajas finas de unos 3 mm.","Pelar cebolla y cortar en aros finos.","Disponer las patatas y la cebolla en una bandeja de horno en capas uniformes.","Regar las patatas y la cebolla con aceite de oliva y salpimentar.","Hornear la bandeja a 200 °C durante 20 min, hasta que las patatas empiecen a estar tiernas.","Tostar pan en sartén sin aceite a fuego medio hasta que esté dorado.","Tostar almendra tostada en la misma sartén a fuego medio hasta que tome color.","Asar tomate y ajo con piel en la sartén a fuego medio hasta que estén blandos.","Pelar el tomate y el ajo asados cuando estén templados.","Triturar el pan, las almendras, el tomate, el ajo, pimiento choricero (pulpa de ñora) y vinagre de vino.","Añadir el resto del aceite de oliva al vaso mientras se tritura, hasta obtener una salsa espesa y homogénea.","Salpimentar el romesco al gusto y reservar.","Retirar la bandeja del horno y salpimentar dorada (limpia, entera) por dentro y por fuera.","Colocar la dorada sobre la cama de patatas y cebolla en la bandeja.","Hornear a 200 °C durante 20 min, hasta que la piel esté dorada y la carne se separe fácilmente de la espina.","Servir la dorada sobre las patatas y la cebolla, acompañada del romesco aparte."}', 'Dorada entera al horno sobre patatas panadera, con un romesco tostado de almendra y ñora.', NULL, '{}', NULL, NULL, NULL, '{"verdura","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo","part":"principal"},{"text":"Pelar {{Patata}} y laminar en rodajas finas de unos 3 mm.","minutes":4,"kind":"paralelo","part":"principal","during":0},{"text":"Pelar {{Cebolla}} y cortar en aros finos.","minutes":2,"kind":"paralelo","part":"principal","during":0},{"text":"Disponer las patatas y la cebolla en una bandeja de horno en capas uniformes.","minutes":2,"kind":"prep","part":"principal"},{"text":"Regar las patatas y la cebolla con {{Aceite de oliva|chorrito}} y salpimentar.","minutes":1,"kind":"prep","part":"principal"},{"text":"Hornear la bandeja a 200 °C durante 20 min, hasta que las patatas empiecen a estar tiernas.","minutes":20,"kind":"pasivo","part":"principal"},{"text":"Tostar {{Pan}} en {{@Sartén}} sin aceite a fuego medio hasta que esté dorado.","minutes":3,"kind":"paralelo","part":"salsa","during":5},{"text":"Tostar {{Almendra tostada}} en la misma sartén a fuego medio hasta que tome color.","minutes":2,"kind":"paralelo","part":"salsa","during":5},{"text":"Asar {{Tomate}} y {{Ajo}} con piel en la sartén a fuego medio hasta que estén blandos.","minutes":8,"kind":"paralelo","part":"salsa","during":5},{"text":"Pelar el tomate y el ajo asados cuando estén templados.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Triturar el pan, las almendras, el tomate, el ajo, {{Pimiento choricero (pulpa de ñora)}} y {{Vinagre de vino}}.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Añadir el resto del aceite de oliva al vaso mientras se tritura, hasta obtener una salsa espesa y homogénea.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Salpimentar el romesco al gusto y reservar.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Retirar la bandeja del horno y salpimentar {{Dorada (limpia, entera)}} por dentro y por fuera.","minutes":1,"kind":"prep","part":"principal"},{"text":"Colocar la dorada sobre la cama de patatas y cebolla en la bandeja.","minutes":1,"kind":"prep","part":"principal"},{"text":"Hornear a 200 °C durante 20 min, hasta que la piel esté dorada y la carne se separe fácilmente de la espina.","minutes":20,"kind":"pasivo","part":"principal"},{"text":"Servir la dorada sobre las patatas y la cebolla, acompañada del romesco aparte.","minutes":2,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, true),
  ('pescados_106', 'Atún a la plancha con puré de patata y salsa teriyaki', 'pescados', 'pescado_azul', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 500, 42, 40, 17, 2, true, true, '{"pescado","lactosa","soja","sesamo","gluten"}', '[{"name":"Atún (lomo fresco)","amount":320,"unit":"g"},{"name":"Patata","amount":350,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Leche","amount":40,"unit":"ml"},{"name":"Salsa de soja","amount":30,"unit":"ml"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Jengibre fresco","amount":8,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Maicena","amount":5,"unit":"g"},{"name":"Aceite de sésamo","amount":5,"unit":"ml"},{"name":"Sésamo tostado","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y cortarla en trozos de tamaño similar.","Cocer la patata en un cazo con agua y salsa de soja hasta que esté tierna.","Rallar jengibre fresco.","Picar ajo muy fino.","Mezclar salsa de soja, miel, el jengibre rallado y el ajo picado en un cazo pequeño.","Disolver maicena en una cucharada de agua fría y añadir la mezcla al cazo.","Llevar el cazo a fuego medio, removiendo, hasta que la salsa espese y brille.","Retirar del fuego y añadir aceite de sésamo. Reservar.","Escurrir la patata cocida cuando esté tierna.","Calentar leche en el mismo cazo a fuego suave hasta que esté caliente.","Triturar la patata escurrida con mantequilla y la leche caliente hasta obtener un puré fino.","Salpimentar el puré y reservar caliente.","Calentar plancha a fuego fuerte hasta que esté muy caliente.","Salpimentar atún (lomo fresco).","Marcar el atún en la plancha 1-2 min por cada lado hasta que esté dorado por fuera y rosado por dentro.","Cortar el atún en filetes gruesos y pincelar con parte de la salsa teriyaki.","Repartir el puré en la base de los platos y colocar el atún encima.","Salsear con el resto de la teriyaki y espolvorear sésamo tostado. Servir de inmediato."}', 'Atún marcado a la plancha, rosado por dentro, sobre puré de patata con un glaseado teriyaki.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortarla en trozos de tamaño similar.","minutes":3,"kind":"prep","part":"guarnicion"},{"text":"Cocer la patata en un cazo con agua y {{Salsa de soja|gusto}} hasta que esté tierna.","minutes":18,"kind":"pasivo","part":"guarnicion"},{"text":"Rallar {{Jengibre fresco}}.","minutes":1,"kind":"paralelo","part":"salsa","during":1},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"paralelo","part":"salsa","during":1},{"text":"Mezclar {{Salsa de soja}}, {{Miel}}, el jengibre rallado y el ajo picado en un cazo pequeño.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Disolver {{Maicena}} en una cucharada de agua fría y añadir la mezcla al cazo.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Llevar el cazo a fuego medio, removiendo, hasta que la salsa espese y brille.","minutes":3,"kind":"activo","part":"salsa"},{"text":"Retirar del fuego y añadir {{Aceite de sésamo}}. Reservar.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Escurrir la patata cocida cuando esté tierna.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Calentar {{Leche}} en el mismo cazo a fuego suave hasta que esté caliente.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Triturar la patata escurrida con {{Mantequilla}} y la leche caliente hasta obtener un puré fino.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Salpimentar el puré y reservar caliente.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté muy caliente.","minutes":2,"kind":"activo","part":"principal"},{"text":"Salpimentar {{Atún (lomo fresco)}}.","minutes":1,"kind":"prep","part":"principal"},{"text":"Marcar el atún en la plancha 1-2 min por cada lado hasta que esté dorado por fuera y rosado por dentro.","minutes":3,"kind":"activo","part":"principal"},{"text":"Cortar el atún en filetes gruesos y pincelar con parte de la salsa teriyaki.","minutes":1,"kind":"activo","part":"principal"},{"text":"Repartir el puré en la base de los platos y colocar el atún encima.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Salsear con el resto de la teriyaki y espolvorear {{Sésamo tostado}}. Servir de inmediato.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'plancha', 'asiatica', true),
  ('pescados_107', 'Coca de recapte con sardinas ahumadas', 'pescados', 'pescado_azul', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 110, 'normal', 'all', 570, 20, 70, 22, 4, false, true, '{"pescado","gluten"}', '[{"name":"Harina de fuerza","amount":300,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Levadura de panadería seca","amount":5,"unit":"g"},{"name":"Pimiento rojo","amount":200,"unit":"g"},{"name":"Pimiento verde","amount":150,"unit":"g"},{"name":"Berenjena","amount":200,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Tomate","amount":150,"unit":"g"},{"name":"Sardinas ahumadas","amount":200,"unit":"g"}]'::jsonb, '{"Disolver levadura de panadería seca en 150 ml de agua templada y dejar reposar hasta que haga espuma.","Mezclar harina de fuerza con sal en un bol grande.","Añadir el agua con levadura y aceite de oliva a la harina.","Amasar la mezcla durante 10 min hasta obtener una masa lisa y elástica.","Formar una bola con la masa, tapar con un paño y dejar fermentar en un lugar cálido hasta que doble su volumen.","Precalentar el horno a 200 °C.","Cortar pimiento rojo, pimiento verde, berenjena y cebolla en tiras.","Cortar tomate en tiras.","Repartir las verduras cortadas en una bandeja y regar con aceite de oliva.","Salpimentar las verduras y asar a 200 °C durante 35 min, removiendo a media cocción, hasta que estén tiernas y doradas.","Estirar la masa fermentada con un rodillo hasta formar un rectángulo fino sobre una bandeja forrada con papel vegetal.","Repartir las verduras asadas sobre la masa dejando un borde libre de 1 cm.","Hornear a 200 °C durante 15 min hasta que la base empiece a dorarse.","Distribuir sardinas ahumadas por encima de la coca.","Hornear 5 min más a 200 °C hasta que las sardinas estén calientes.","Retirar del horno y dejar templar antes de cortar.","Cortar la coca en porciones y servir."}', 'Coca catalana de base fina con verduras asadas de temporada y sardinas ahumadas por encima.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Disolver {{Levadura de panadería seca}} en 150 ml de agua templada y dejar reposar hasta que haga espuma.","minutes":5,"kind":"espera"},{"text":"Mezclar {{Harina de fuerza}} con {{Sal|gusto}} en un bol grande.","minutes":2,"kind":"prep"},{"text":"Añadir el agua con levadura y {{Aceite de oliva|chorrito}} a la harina.","minutes":1,"kind":"prep"},{"text":"Amasar la mezcla durante 10 min hasta obtener una masa lisa y elástica.","minutes":10,"kind":"activo"},{"text":"Formar una bola con la masa, tapar con un paño y dejar fermentar en un lugar cálido hasta que doble su volumen.","minutes":60,"kind":"espera"},{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo","part":"principal"},{"text":"Cortar {{Pimiento rojo}}, {{Pimiento verde}}, {{Berenjena}} y {{Cebolla}} en tiras.","minutes":8,"kind":"paralelo","part":"guarnicion","during":5},{"text":"Cortar {{Tomate}} en tiras.","minutes":2,"kind":"paralelo","part":"guarnicion","during":5},{"text":"Repartir las verduras cortadas en una bandeja y regar con {{Aceite de oliva|chorrito}}.","minutes":2,"kind":"prep","part":"guarnicion"},{"text":"Salpimentar las verduras y asar a 200 °C durante 35 min, removiendo a media cocción, hasta que estén tiernas y doradas.","minutes":35,"kind":"pasivo","part":"guarnicion"},{"text":"Estirar la masa fermentada con un rodillo hasta formar un rectángulo fino sobre una bandeja forrada con papel vegetal.","minutes":5,"kind":"prep","part":"principal"},{"text":"Repartir las verduras asadas sobre la masa dejando un borde libre de 1 cm.","minutes":2,"kind":"activo","part":"combinado"},{"text":"Hornear a 200 °C durante 15 min hasta que la base empiece a dorarse.","minutes":15,"kind":"pasivo","part":"combinado"},{"text":"Distribuir {{Sardinas ahumadas}} por encima de la coca.","minutes":2,"kind":"activo","part":"combinado"},{"text":"Hornear 5 min más a 200 °C hasta que las sardinas estén calientes.","minutes":5,"kind":"pasivo","part":"combinado"},{"text":"Retirar del horno y dejar templar antes de cortar.","minutes":5,"kind":"espera","part":"combinado"},{"text":"Cortar la coca en porciones y servir.","minutes":2,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL)
