insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('pescados_108', 'Tarta fina de cebolla caramelizada y anchoas', 'pescados', 'pescado_azul', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 520, 9, 40, 33, 4, false, true, '{"gluten","lactosa","pescado","sulfitos"}', '[{"name":"Masa de hojaldre","amount":230,"unit":"g"},{"name":"Cebolla","amount":500,"unit":"g"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Azúcar","amount":10,"unit":"g"},{"name":"Anchoas en aceite","amount":60,"unit":"g"},{"name":"Aceitunas negras","amount":40,"unit":"g"},{"name":"Tomillo","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar cebolla y cortar en juliana fina.","Calentar mantequilla y aceite de oliva en una sartén amplia a fuego medio hasta que la mantequilla se funda.","Añadir la cebolla en juliana y sofreír a fuego suave, removiendo de vez en cuando.","Añadir azúcar y remover para integrar.","Sofreír a fuego suave hasta que la cebolla caramelice ligeramente.","Retirar la sartén del fuego y dejar templar la cebolla caramelizada.","Extender masa de hojaldre sobre una bandeja de horno forrada con papel vegetal.","Pinchar toda la base del hojaldre con un tenedor para evitar que suba en exceso.","Repartir la cebolla caramelizada sobre el hojaldre dejando un borde libre de 1 cm.","Disponer anchoas en aceite en tiras formando un enrejado sobre la cebolla.","Repartir aceitunas negras entre los huecos del enrejado de anchoas.","Espolvorear tomillo de manera uniforme sobre la tarta.","Hornear en el centro del horno a 200 °C hasta que el hojaldre esté dorado y crujiente.","Retirar del horno y dejar templar antes de cortar.","Cortar en porciones y servir."}', 'Tarta fina de hojaldre crujiente con cebolla caramelizada, anchoas y aceitunas negras.', NULL, '{}', true, NULL, NULL, '{"encurtido"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Cebolla}} y cortar en juliana fina.","minutes":5,"kind":"prep"},{"text":"Calentar {{Mantequilla}} y {{Aceite de oliva|chorrito}} en una sartén amplia a fuego medio hasta que la mantequilla se funda.","minutes":2,"kind":"activo"},{"text":"Añadir la cebolla en juliana y sofreír a fuego suave, removiendo de vez en cuando.","minutes":25,"kind":"pasivo"},{"text":"Añadir {{Azúcar}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Sofreír a fuego suave hasta que la cebolla caramelice ligeramente.","minutes":5,"kind":"pasivo"},{"text":"Retirar la sartén del fuego y dejar templar la cebolla caramelizada.","minutes":10,"kind":"espera"},{"text":"Extender {{Masa de hojaldre}} sobre una bandeja de horno forrada con papel vegetal.","minutes":1,"kind":"prep"},{"text":"Pinchar toda la base del hojaldre con un tenedor para evitar que suba en exceso.","minutes":1,"kind":"prep"},{"text":"Repartir la cebolla caramelizada sobre el hojaldre dejando un borde libre de 1 cm.","minutes":2,"kind":"activo"},{"text":"Disponer {{Anchoas en aceite}} en tiras formando un enrejado sobre la cebolla.","minutes":2,"kind":"activo"},{"text":"Repartir {{Aceitunas negras}} entre los huecos del enrejado de anchoas.","minutes":1,"kind":"activo"},{"text":"Espolvorear {{Tomillo|pizca}} de manera uniforme sobre la tarta.","minutes":1,"kind":"activo"},{"text":"Hornear en el centro del horno a 200 °C hasta que el hojaldre esté dorado y crujiente.","minutes":22,"kind":"pasivo"},{"text":"Retirar del horno y dejar templar antes de cortar.","minutes":5,"kind":"espera"},{"text":"Cortar en porciones y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('pescados_109', 'Empanada de vieiras y gambas', 'pescados', 'marisco', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 110, 'normal', 'all', 560, 30, 72, 15, 4, true, true, '{"gluten","marisco","moluscos","huevo"}', '[{"name":"Harina de fuerza","amount":350,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Levadura de panadería seca","amount":6,"unit":"g"},{"name":"Vieiras (sin concha)","amount":200,"unit":"g"},{"name":"Gambas peladas","amount":200,"unit":"g"},{"name":"Cebolla","amount":200,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"}]'::jsonb, '{"Disolver levadura de panadería seca en 170 ml de agua templada y remover hasta integrar.","Esperar 5 min hasta que la levadura espume y esté activa.","Mezclar harina de fuerza con sal en un bol amplio y hacer un hueco en el centro.","Añadir el agua con levadura y aceite de oliva al hueco de la harina.","Amasar durante 10 min hasta obtener una masa lisa y elástica que no se pegue.","Tapar el bol con un paño y dejar fermentar la masa 60 min hasta que doble su volumen.","Picar cebolla fina.","Picar pimiento verde fino.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír la cebolla y el pimiento verde picados a fuego medio 14 min hasta que estén tiernos.","Añadir tomate triturado al sofrito y cocer a fuego medio 9 min hasta que espese.","Salpimentar el sofrito y retirar la sartén del fuego.","Dejar templar el sofrito 10 min antes de añadir el marisco.","Cortar vieiras (sin concha) en trozos de bocado.","Añadir las vieiras troceadas y gambas peladas al sofrito templado y remover para integrar.","Reservar el relleno mientras la masa termina de fermentar.","Precalentar el horno a 190 °C.","Dividir la masa fermentada en 2 porciones iguales.","Estirar la primera porción con un rodillo hasta obtener una lámina del tamaño de la bandeja.","Estirar la segunda porción del mismo modo y reservar ambas láminas.","Colocar la primera lámina sobre la bandeja de horno y repartir el relleno dejando 1 cm de borde.","Cubrir con la segunda lámina y sellar los bordes pellizcando la masa con los dedos.","Batir huevo en un bol pequeño hasta homogeneizar.","Pintar toda la superficie de la empanada con el huevo batido usando un pincel.","Hornear a 190 °C durante 32 min hasta que la empanada esté dorada y crujiente.","Dejar templar la empanada 10 min antes de cortar en porciones y servir.","Cortar en porciones y servir."}', 'Empanada casera de masa fermentada rellena de vieiras y gambas con sofrito de pimiento.', NULL, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Disolver {{Levadura de panadería seca}} en 170 ml de agua templada y remover hasta integrar.","minutes":2,"kind":"prep"},{"text":"Esperar 5 min hasta que la levadura espume y esté activa.","minutes":5,"kind":"espera"},{"text":"Mezclar {{Harina de fuerza}} con {{Sal|gusto}} en un bol amplio y hacer un hueco en el centro.","minutes":2,"kind":"prep"},{"text":"Añadir el agua con levadura y {{Aceite de oliva|chorrito}} al hueco de la harina.","minutes":1,"kind":"prep"},{"text":"Amasar durante 10 min hasta obtener una masa lisa y elástica que no se pegue.","minutes":10,"kind":"activo"},{"text":"Tapar el bol con un paño y dejar fermentar la masa 60 min hasta que doble su volumen.","minutes":60,"kind":"espera"},{"text":"Picar {{Cebolla}} fina.","minutes":3,"kind":"paralelo","during":5},{"text":"Picar {{Pimiento verde}} fino.","minutes":2,"kind":"paralelo","during":5},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio hasta que esté caliente.","minutes":1,"kind":"paralelo","during":5},{"text":"Sofreír la cebolla y el pimiento verde picados a fuego medio 14 min hasta que estén tiernos.","minutes":14,"kind":"pasivo"},{"text":"Añadir {{Tomate triturado}} al sofrito y cocer a fuego medio 9 min hasta que espese.","minutes":9,"kind":"activo"},{"text":"Salpimentar el sofrito y retirar la sartén del fuego.","minutes":1,"kind":"activo"},{"text":"Dejar templar el sofrito 10 min antes de añadir el marisco.","minutes":10,"kind":"espera"},{"text":"Cortar {{Vieiras (sin concha)}} en trozos de bocado.","minutes":3,"kind":"paralelo","during":12},{"text":"Añadir las vieiras troceadas y {{Gambas peladas}} al sofrito templado y remover para integrar.","minutes":2,"kind":"activo"},{"text":"Reservar el relleno mientras la masa termina de fermentar.","minutes":1,"kind":"prep"},{"text":"Precalentar el horno a 190 °C.","minutes":10,"kind":"pasivo"},{"text":"Dividir la masa fermentada en 2 porciones iguales.","minutes":1,"kind":"paralelo","during":16},{"text":"Estirar la primera porción con un rodillo hasta obtener una lámina del tamaño de la bandeja.","minutes":3,"kind":"paralelo","during":16},{"text":"Estirar la segunda porción del mismo modo y reservar ambas láminas.","minutes":3,"kind":"paralelo","during":16},{"text":"Colocar la primera lámina sobre la bandeja de horno y repartir el relleno dejando 1 cm de borde.","minutes":3,"kind":"activo"},{"text":"Cubrir con la segunda lámina y sellar los bordes pellizcando la masa con los dedos.","minutes":3,"kind":"activo"},{"text":"Batir {{Huevo}} en un bol pequeño hasta homogeneizar.","minutes":1,"kind":"prep"},{"text":"Pintar toda la superficie de la empanada con el huevo batido usando un pincel.","minutes":2,"kind":"activo"},{"text":"Hornear a 190 °C durante 32 min hasta que la empanada esté dorada y crujiente.","minutes":32,"kind":"pasivo"},{"text":"Dejar templar la empanada 10 min antes de cortar en porciones y servir.","minutes":10,"kind":"espera"},{"text":"Cortar en porciones y servir.","minutes":2,"kind":"emplatado"}]'::jsonb, true, 'especial', NULL, 'horno', NULL, NULL),
  ('pescados_110', 'Tosta de tartar de atún y aguacate', 'pescados', 'pescado_azul', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 600, 34, 38, 33, 2, false, false, '{"pescado","soja","sesamo","gluten"}', '[{"name":"Atún rojo (calidad sashimi)","amount":240,"unit":"g"},{"name":"Aguacate","amount":200,"unit":"g"},{"name":"Pan de payés","amount":120,"unit":"g"},{"name":"Salsa de soja","amount":20,"unit":"ml"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Cebolleta","amount":20,"unit":"g"},{"name":"Sésamo tostado","amount":5,"unit":"g"},{"name":"Lima","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar atún rojo (calidad sashimi) en dados muy pequeños y regulares con un cuchillo bien afilado.","Picar cebolleta muy fina.","Exprimir lima y reservar el zumo separado en dos partes iguales.","Mezclar el atún con salsa de soja, aceite de sésamo y la mitad del zumo de lima.","Añadir la cebolleta picada al atún aliñado y remover con cuidado.","Tapar el bol y dejar marinar el tartar en frío.","Cortar aguacate por la mitad y retirar el hueso.","Machacar la pulpa de aguacate con un tenedor junto con el resto del zumo de lima y aceite de oliva.","Calentar plancha a fuego medio y tostar pan de payés con aceite de oliva hasta que esté dorado y crujiente.","Untar cada tosta con la crema de aguacate en capa generosa.","Repartir el tartar de atún marinado encima de la crema de aguacate.","Espolvorear sésamo tostado sobre cada tosta y servir de inmediato."}', 'Tostas crujientes con crema de aguacate y un tartar de atún fresco marinado en soja y lima.', NULL, '{}', true, true, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Atún rojo (calidad sashimi)}} en dados muy pequeños y regulares con un cuchillo bien afilado.","minutes":5,"kind":"prep"},{"text":"Picar {{Cebolleta}} muy fina.","minutes":2,"kind":"prep"},{"text":"Exprimir {{Lima}} y reservar el zumo separado en dos partes iguales.","minutes":1,"kind":"prep"},{"text":"Mezclar el atún con {{Salsa de soja}}, {{Aceite de sésamo}} y la mitad del zumo de lima.","minutes":1,"kind":"activo"},{"text":"Añadir la cebolleta picada al atún aliñado y remover con cuidado.","minutes":1,"kind":"activo"},{"text":"Tapar el bol y dejar marinar el tartar en frío.","minutes":10,"kind":"espera"},{"text":"Cortar {{Aguacate}} por la mitad y retirar el hueso.","minutes":1,"kind":"paralelo","during":5},{"text":"Machacar la pulpa de aguacate con un tenedor junto con el resto del zumo de lima y {{Aceite de oliva|chorrito}}.","minutes":2,"kind":"paralelo","during":5},{"text":"Calentar {{@Plancha}} a fuego medio y tostar {{Pan de payés}} con {{Aceite de oliva|chorrito}} hasta que esté dorado y crujiente.","minutes":3,"kind":"activo"},{"text":"Untar cada tosta con la crema de aguacate en capa generosa.","minutes":1,"kind":"emplatado"},{"text":"Repartir el tartar de atún marinado encima de la crema de aguacate.","minutes":1,"kind":"emplatado"},{"text":"Espolvorear {{Sésamo tostado}} sobre cada tosta y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, NULL),
  ('pescados_111', 'Buñuelos de bacalao con alioli', 'pescados', 'pescado_blanco', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 760, 30, 46, 45, 2, true, false, '{"pescado","gluten","huevo","lactosa"}', '[{"name":"Bacalao desalado (desmigado)","amount":200,"unit":"g"},{"name":"Harina","amount":120,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Levadura química","amount":5,"unit":"g"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Perejil","amount":10,"unit":"g"},{"name":"Ajo","amount":16,"unit":"g"},{"name":"Aceite de oliva suave","amount":300,"unit":"ml"},{"name":"Mayonesa","amount":60,"unit":"g"}]'::jsonb, '{"Desmigar bacalao desalado (desmigado) en trozos pequeños, comprobando que no queden espinas.","Picar perejil muy fino.","Picar la mitad de ajo muy fino.","Batir huevo en un bol grande hasta que estén homogéneos.","Añadir harina, levadura química y leche al bol y mezclar hasta obtener una masa sin grumos.","Incorporar el bacalao desmigado, el perejil picado y el ajo picado a la masa y mezclar bien.","Tapar el bol y dejar reposar la masa 15 min en la nevera.","Machacar la otra mitad del ajo y mezclar con mayonesa hasta obtener un alioli suave.","Reservar el alioli en la nevera hasta el momento de servir.","Calentar aceite de oliva suave en sartén honda a fuego medio-fuerte hasta alcanzar 180 °C.","Formar los buñuelos con 2 cucharas cogiendo porciones de masa y depositarlas con cuidado en el aceite caliente.","Freír los buñuelos en tandas 3 min, hasta que estén dorados por todos los lados, dándoles la vuelta a mitad.","Escurrir los buñuelos sobre papel absorbente para retirar el exceso de aceite.","Servir los buñuelos calientes acompañados del alioli."}', 'Buñuelos esponjosos de bacalao desmigado, fritos hasta quedar dorados, con un alioli suave al lado.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, ARRAY['huevo']::main_protein[], false, '[{"text":"Desmigar {{Bacalao desalado (desmigado)}} en trozos pequeños, comprobando que no queden espinas.","minutes":3,"kind":"prep"},{"text":"Picar {{Perejil}} muy fino.","minutes":2,"kind":"prep"},{"text":"Picar la mitad de {{Ajo}} muy fino.","minutes":2,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol grande hasta que estén homogéneos.","minutes":1,"kind":"prep"},{"text":"Añadir {{Harina}}, {{Levadura química}} y {{Leche}} al bol y mezclar hasta obtener una masa sin grumos.","minutes":2,"kind":"activo"},{"text":"Incorporar el bacalao desmigado, el perejil picado y el ajo picado a la masa y mezclar bien.","minutes":2,"kind":"activo"},{"text":"Tapar el bol y dejar reposar la masa 15 min en la nevera.","minutes":15,"kind":"espera"},{"text":"Machacar la otra mitad del ajo y mezclar con {{Mayonesa}} hasta obtener un alioli suave.","minutes":3,"kind":"paralelo","during":6},{"text":"Reservar el alioli en la nevera hasta el momento de servir.","minutes":1,"kind":"paralelo","during":6},{"text":"Calentar {{Aceite de oliva suave|abundante}} en {{@Sartén}} honda a fuego medio-fuerte hasta alcanzar 180 °C.","minutes":3,"kind":"activo"},{"text":"Formar los buñuelos con 2 cucharas cogiendo porciones de masa y depositarlas con cuidado en el aceite caliente.","minutes":1,"kind":"activo"},{"text":"Freír los buñuelos en tandas 3 min, hasta que estén dorados por todos los lados, dándoles la vuelta a mitad.","minutes":3,"kind":"activo"},{"text":"Escurrir los buñuelos sobre papel absorbente para retirar el exceso de aceite.","minutes":1,"kind":"activo"},{"text":"Servir los buñuelos calientes acompañados del alioli.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, true),
  ('pescados_112', 'Pastel de cabracho', 'pescados', 'pescado_blanco', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 90, 'elaborada', 'all', 490, 32, 6, 35, 4, true, true, '{"pescado","marisco","huevo","lactosa"}', '[{"name":"Cabracho (o rape/merluza)","amount":400,"unit":"g"},{"name":"Gambas peladas","amount":150,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Tomate frito","amount":100,"unit":"g"},{"name":"Nata para cocinar","amount":150,"unit":"ml"},{"name":"Mayonesa","amount":80,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Calentar agua con sal en una olla a fuego fuerte hasta que rompa a hervir.","Cocer cabracho (o rape/merluza) a fuego medio hasta que esté hecho.","Retirar el cabracho del agua y dejar templar.","Picar cebolla muy fina.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada a fuego suave hasta que esté tierna y transparente.","Retirar piel y espinas del cabracho templado y desmenuzar la carne.","Llevar agua a ebullición en un cazo a fuego fuerte.","Cocer gambas peladas en el agua hirviendo durante 2 min.","Escurrir las gambas y picarlas en trozos pequeños.","Precalentar el horno a 180 °C.","Forrar un molde rectangular con papel vegetal mientras el horno calienta.","Triturar el cabracho desmenuzado, la cebolla pochada, tomate frito, huevo y nata para cocinar hasta obtener una mezcla fina.","Añadir las gambas picadas a la mezcla y remover con una espátula sin triturar.","Verter la mezcla en el molde preparado.","Hornear al baño maría a 180 °C hasta que al pinchar con un palillo salga limpio.","Retirar del horno y dejar enfriar completamente a temperatura ambiente.","Refrigerar el pastel en el molde hasta que esté bien frío y firme.","Desmoldar el pastel sobre una fuente.","Servir en lonchas cubierto con mayonesa."}', 'Pastel de pescado tipo terrina, con cabracho y gambas, cuajado al horno y cubierto de mayonesa.', NULL, '{}', true, NULL, NULL, '{"lacteo"}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Calentar agua con sal en una olla a fuego fuerte hasta que rompa a hervir.","minutes":5,"kind":"activo"},{"text":"Cocer {{Cabracho (o rape/merluza)}} a fuego medio hasta que esté hecho.","minutes":15,"kind":"pasivo"},{"text":"Retirar el cabracho del agua y dejar templar.","minutes":10,"kind":"espera"},{"text":"Picar {{Cebolla}} muy fina.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada a fuego suave hasta que esté tierna y transparente.","minutes":10,"kind":"pasivo"},{"text":"Retirar piel y espinas del cabracho templado y desmenuzar la carne.","minutes":5,"kind":"prep"},{"text":"Llevar agua a ebullición en un cazo a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer {{Gambas peladas}} en el agua hirviendo durante 2 min.","minutes":2,"kind":"pasivo"},{"text":"Escurrir las gambas y picarlas en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Forrar un molde rectangular con papel vegetal mientras el horno calienta.","minutes":2,"kind":"paralelo","during":10},{"text":"Triturar el cabracho desmenuzado, la cebolla pochada, {{Tomate frito}}, {{Huevo}} y {{Nata para cocinar}} hasta obtener una mezcla fina.","minutes":3,"kind":"activo"},{"text":"Añadir las gambas picadas a la mezcla y remover con una espátula sin triturar.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla en el molde preparado.","minutes":1,"kind":"activo"},{"text":"Hornear al baño maría a 180 °C hasta que al pinchar con un palillo salga limpio.","minutes":50,"kind":"pasivo"},{"text":"Retirar del horno y dejar enfriar completamente a temperatura ambiente.","minutes":60,"kind":"espera"},{"text":"Refrigerar el pastel en el molde hasta que esté bien frío y firme.","minutes":180,"kind":"espera"},{"text":"Desmoldar el pastel sobre una fuente.","minutes":1,"kind":"emplatado"},{"text":"Servir en lonchas cubierto con {{Mayonesa}}.","minutes":1,"kind":"emplatado"}]'::jsonb, true, 'especial', NULL, 'horno', NULL, true),
  ('pescados_113', 'Empanada gallega de bonito', 'pescados', 'pescado_azul', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 110, 'normal', 'all', 665, 32, 87, 21, 4, true, true, '{"gluten","pescado","huevo"}', '[{"name":"Harina de fuerza","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Levadura de panadería seca","amount":7,"unit":"g"},{"name":"Bonito en conserva","amount":300,"unit":"g"},{"name":"Cebolla","amount":250,"unit":"g"},{"name":"Pimiento rojo","amount":150,"unit":"g"},{"name":"Pimiento verde","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"}]'::jsonb, '{"Disolver levadura de panadería seca en 190 ml de agua templada.","Reposar la mezcla de levadura 5 min hasta que espume.","Mezclar harina de fuerza con sal en un bol grande.","Añadir el agua con levadura y aceite de oliva a la harina.","Amasar la mezcla 10 min hasta obtener una masa lisa y elástica.","Tapar la masa con un paño y dejar fermentar 60 min hasta que doble su volumen.","Picar cebolla en dados pequeños.","Cortar pimiento rojo y pimiento verde en dados pequeños.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla y los pimientos 15 min hasta que estén tiernos.","Añadir pimentón dulce y tomate triturado al sofrito.","Cocer el sofrito a fuego medio 10 min hasta que espese.","Salpimentar el sofrito y retirar del fuego.","Dejar templar el sofrito 10 min.","Escurrir bonito en conserva y desmenuzarlo en trozos sobre el sofrito templado.","Mezclar el bonito con el sofrito con cuidado hasta integrar.","Precalentar el horno a 190 °C.","Dividir la masa en 2 porciones iguales.","Estirar cada porción de masa hasta obtener 2 láminas del tamaño de la bandeja.","Colocar la primera lámina de masa sobre la bandeja de horno.","Repartir el relleno sobre la primera lámina dejando 1 cm de borde libre.","Cubrir con la segunda lámina y sellar bien los bordes presionando con los dedos.","Batir huevo en un bol pequeño.","Pintar la superficie de la empanada con el huevo batido.","Hacer un pequeño agujero en el centro de la empanada para que salga el vapor.","Hornear la empanada 35 min hasta que la superficie esté dorada.","Retirar la empanada del horno y dejar reposar 5 min antes de cortar.","Cortar la empanada en porciones y servir."}', 'Empanada gallega tradicional de masa fermentada, rellena de bonito y un sofrito de pimientos.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Disolver {{Levadura de panadería seca}} en 190 ml de agua templada.","minutes":2,"kind":"prep"},{"text":"Reposar la mezcla de levadura 5 min hasta que espume.","minutes":5,"kind":"espera"},{"text":"Mezclar {{Harina de fuerza}} con {{Sal|gusto}} en un bol grande.","minutes":2,"kind":"prep"},{"text":"Añadir el agua con levadura y {{Aceite de oliva|chorrito}} a la harina.","minutes":1,"kind":"prep"},{"text":"Amasar la mezcla 10 min hasta obtener una masa lisa y elástica.","minutes":10,"kind":"activo"},{"text":"Tapar la masa con un paño y dejar fermentar 60 min hasta que doble su volumen.","minutes":60,"kind":"espera"},{"text":"Picar {{Cebolla}} en dados pequeños.","minutes":3,"kind":"paralelo","during":5},{"text":"Cortar {{Pimiento rojo}} y {{Pimiento verde}} en dados pequeños.","minutes":3,"kind":"paralelo","during":5},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"paralelo","during":5},{"text":"Sofreír la cebolla y los pimientos 15 min hasta que estén tiernos.","minutes":15,"kind":"paralelo","during":5},{"text":"Añadir {{Pimentón dulce}} y {{Tomate triturado}} al sofrito.","minutes":1,"kind":"activo"},{"text":"Cocer el sofrito a fuego medio 10 min hasta que espese.","minutes":10,"kind":"pasivo"},{"text":"Salpimentar el sofrito y retirar del fuego.","minutes":1,"kind":"activo"},{"text":"Dejar templar el sofrito 10 min.","minutes":10,"kind":"espera"},{"text":"Escurrir {{Bonito en conserva}} y desmenuzarlo en trozos sobre el sofrito templado.","minutes":2,"kind":"prep"},{"text":"Mezclar el bonito con el sofrito con cuidado hasta integrar.","minutes":1,"kind":"prep"},{"text":"Precalentar el horno a 190 °C.","minutes":10,"kind":"pasivo"},{"text":"Dividir la masa en 2 porciones iguales.","minutes":1,"kind":"paralelo","during":16},{"text":"Estirar cada porción de masa hasta obtener 2 láminas del tamaño de la bandeja.","minutes":4,"kind":"paralelo","during":16},{"text":"Colocar la primera lámina de masa sobre la bandeja de horno.","minutes":1,"kind":"prep"},{"text":"Repartir el relleno sobre la primera lámina dejando 1 cm de borde libre.","minutes":2,"kind":"prep"},{"text":"Cubrir con la segunda lámina y sellar bien los bordes presionando con los dedos.","minutes":2,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol pequeño.","minutes":1,"kind":"prep"},{"text":"Pintar la superficie de la empanada con el huevo batido.","minutes":1,"kind":"prep"},{"text":"Hacer un pequeño agujero en el centro de la empanada para que salga el vapor.","minutes":1,"kind":"prep"},{"text":"Hornear la empanada 35 min hasta que la superficie esté dorada.","minutes":35,"kind":"pasivo"},{"text":"Retirar la empanada del horno y dejar reposar 5 min antes de cortar.","minutes":5,"kind":"espera"},{"text":"Cortar la empanada en porciones y servir.","minutes":2,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('pescados_114', 'Empanada de atún y pimientos', 'pescados', 'pescado_azul', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 110, 'normal', 'all', 648, 31, 87, 19, 4, true, true, '{"gluten","pescado","huevo"}', '[{"name":"Harina de fuerza","amount":400,"unit":"g"},{"name":"Aceite de oliva","amount":55,"unit":"ml"},{"name":"Levadura de panadería seca","amount":7,"unit":"g"},{"name":"Atún en conserva","amount":280,"unit":"g"},{"name":"Pimiento rojo","amount":200,"unit":"g"},{"name":"Pimiento verde","amount":150,"unit":"g"},{"name":"Cebolla","amount":150,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"}]'::jsonb, '{"Disolver levadura de panadería seca en 190 ml de agua templada y remover hasta que no queden grumos.","Esperar 5 min hasta que la levadura empiece a burbujear.","Mezclar harina de fuerza con sal en un bol amplio y hacer un hueco en el centro.","Añadir el agua con levadura y aceite de oliva al hueco de la harina.","Amasar la mezcla durante 10 min hasta obtener una masa lisa, elástica y que no se pegue.","Tapar el bol con un paño húmedo y dejar fermentar la masa 60 min hasta que doble su volumen.","Cortar pimiento rojo en dados pequeños.","Cortar pimiento verde en dados pequeños.","Cortar cebolla en dados pequeños.","Calentar sartén a fuego medio con aceite de oliva.","Sofreír el pimiento rojo, el pimiento verde y la cebolla picados a fuego medio 18 min hasta que estén muy tiernos.","Añadir tomate triturado al sofrito y cocer a fuego medio 10 min hasta que espese.","Salpimentar el sofrito y retirar la sartén del fuego.","Dejar templar el sofrito 10 min antes de incorporar el atún.","Escurrir atún en conserva y desmenuzarlo sobre el sofrito templado.","Mezclar el atún con el sofrito con cuidado hasta integrar bien todo el relleno.","Precalentar el horno a 190 °C.","Dividir la masa fermentada en 2 porciones iguales.","Estirar cada porción de masa con un rodillo hasta obtener 2 láminas del tamaño de la bandeja.","Colocar la primera lámina de masa sobre la bandeja de horno.","Repartir el relleno sobre la primera lámina dejando 1 cm de borde libre.","Cubrir el relleno con la segunda lámina de masa y sellar los bordes presionando con los dedos.","Batir huevo en un bol pequeño hasta homogeneizar.","Pintar toda la superficie de la empanada con el huevo batido usando un pincel.","Hornear la empanada a 190 °C durante 33 min hasta que esté dorada y crujiente.","Retirar la empanada del horno y dejar reposar 5 min antes de cortar.","Cortar la empanada en porciones y servir."}', 'Empanada casera bien rellena de atún y un colorido sofrito de pimiento rojo y verde.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Disolver {{Levadura de panadería seca}} en 190 ml de agua templada y remover hasta que no queden grumos.","minutes":2,"kind":"prep"},{"text":"Esperar 5 min hasta que la levadura empiece a burbujear.","minutes":5,"kind":"espera"},{"text":"Mezclar {{Harina de fuerza}} con {{Sal|gusto}} en un bol amplio y hacer un hueco en el centro.","minutes":2,"kind":"prep"},{"text":"Añadir el agua con levadura y {{Aceite de oliva|chorrito}} al hueco de la harina.","minutes":1,"kind":"prep"},{"text":"Amasar la mezcla durante 10 min hasta obtener una masa lisa, elástica y que no se pegue.","minutes":10,"kind":"activo"},{"text":"Tapar el bol con un paño húmedo y dejar fermentar la masa 60 min hasta que doble su volumen.","minutes":60,"kind":"espera"},{"text":"Cortar {{Pimiento rojo}} en dados pequeños.","minutes":3,"kind":"paralelo","during":5},{"text":"Cortar {{Pimiento verde}} en dados pequeños.","minutes":2,"kind":"paralelo","during":5},{"text":"Cortar {{Cebolla}} en dados pequeños.","minutes":3,"kind":"paralelo","during":5},{"text":"Calentar {{@Sartén}} a fuego medio con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"activo"},{"text":"Sofreír el pimiento rojo, el pimiento verde y la cebolla picados a fuego medio 18 min hasta que estén muy tiernos.","minutes":18,"kind":"pasivo"},{"text":"Añadir {{Tomate triturado}} al sofrito y cocer a fuego medio 10 min hasta que espese.","minutes":10,"kind":"pasivo"},{"text":"Salpimentar el sofrito y retirar la sartén del fuego.","minutes":1,"kind":"activo"},{"text":"Dejar templar el sofrito 10 min antes de incorporar el atún.","minutes":10,"kind":"espera"},{"text":"Escurrir {{Atún en conserva}} y desmenuzarlo sobre el sofrito templado.","minutes":2,"kind":"prep"},{"text":"Mezclar el atún con el sofrito con cuidado hasta integrar bien todo el relleno.","minutes":1,"kind":"prep"},{"text":"Precalentar el horno a 190 °C.","minutes":10,"kind":"pasivo"},{"text":"Dividir la masa fermentada en 2 porciones iguales.","minutes":1,"kind":"paralelo","during":16},{"text":"Estirar cada porción de masa con un rodillo hasta obtener 2 láminas del tamaño de la bandeja.","minutes":5,"kind":"paralelo","during":16},{"text":"Colocar la primera lámina de masa sobre la bandeja de horno.","minutes":1,"kind":"activo"},{"text":"Repartir el relleno sobre la primera lámina dejando 1 cm de borde libre.","minutes":2,"kind":"activo"},{"text":"Cubrir el relleno con la segunda lámina de masa y sellar los bordes presionando con los dedos.","minutes":2,"kind":"activo"},{"text":"Batir {{Huevo}} en un bol pequeño hasta homogeneizar.","minutes":1,"kind":"prep"},{"text":"Pintar toda la superficie de la empanada con el huevo batido usando un pincel.","minutes":1,"kind":"activo"},{"text":"Hornear la empanada a 190 °C durante 33 min hasta que esté dorada y crujiente.","minutes":33,"kind":"pasivo"},{"text":"Retirar la empanada del horno y dejar reposar 5 min antes de cortar.","minutes":5,"kind":"espera"},{"text":"Cortar la empanada en porciones y servir.","minutes":2,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('pescados_115', 'Vol-au-vent de marisco', 'pescados', 'marisco', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, 'horno', 60, 'elaborada', 'all', 670, 27, 40, 39, 2, true, false, '{"gluten","marisco","moluscos","lactosa"}', '[{"name":"Vol-au-vent de hojaldre (cestas precocidas)","amount":6,"unit":"ud"},{"name":"Gambas peladas","amount":150,"unit":"g"},{"name":"Mejillones (sin concha)","amount":100,"unit":"g"},{"name":"Champiñones","amount":100,"unit":"g"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Leche","amount":300,"unit":"ml"},{"name":"Vino blanco","amount":30,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Laminar champiñones en láminas finas.","Fundir la mitad de mantequilla en sartén a fuego medio.","Sofreír los champiñones laminados a fuego medio hasta que suelten el agua y se doren ligeramente.","Retirar los champiñones de la sartén y reservar.","Saltear gambas peladas y mejillones (sin concha) en la misma sartén a fuego fuerte.","Añadir vino blanco y cocinar hasta que las gambas cambien de color y el vino se evapore.","Retirar las gambas y los mejillones de la sartén y reservar junto con los champiñones.","Fundir el resto de la mantequilla en un cazo a fuego medio.","Añadir harina al cazo y remover sin parar durante 1 min hasta formar un roux homogéneo.","Verter leche poco a poco sin dejar de remover para evitar grumos.","Cocer a fuego medio removiendo hasta obtener una bechamel espesa y lisa.","Añadir nuez moscada y remover para integrar.","Incorporar las gambas, los mejillones y los champiñones reservados a la bechamel y remover.","Colocar vol-au-vent de hojaldre (cestas precocidas) en una bandeja y calentar en el horno 5 min hasta que estén crujientes.","Retirar las cestas del horno y rellenar cada una con el relleno de marisco y bechamel.","Servir de inmediato."}', 'Cestas de hojaldre rellenas de una bechamel cremosa con gambas, mejillones y champiñones.', NULL, '{}', true, NULL, NULL, '{"lacteo","seta"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Laminar {{Champiñones}} en láminas finas.","minutes":3,"kind":"prep"},{"text":"Fundir la mitad de {{Mantequilla}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír los champiñones laminados a fuego medio hasta que suelten el agua y se doren ligeramente.","minutes":5,"kind":"activo"},{"text":"Retirar los champiñones de la sartén y reservar.","minutes":1,"kind":"prep"},{"text":"Saltear {{Gambas peladas}} y {{Mejillones (sin concha)}} en la misma sartén a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Añadir {{Vino blanco}} y cocinar hasta que las gambas cambien de color y el vino se evapore.","minutes":1,"kind":"activo"},{"text":"Retirar las gambas y los mejillones de la sartén y reservar junto con los champiñones.","minutes":1,"kind":"prep"},{"text":"Fundir el resto de la mantequilla en un cazo a fuego medio.","minutes":1,"kind":"activo"},{"text":"Añadir {{Harina}} al cazo y remover sin parar durante 1 min hasta formar un roux homogéneo.","minutes":1,"kind":"activo"},{"text":"Verter {{Leche}} poco a poco sin dejar de remover para evitar grumos.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio removiendo hasta obtener una bechamel espesa y lisa.","minutes":8,"kind":"activo"},{"text":"Añadir {{Nuez moscada|pizca}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Incorporar las gambas, los mejillones y los champiñones reservados a la bechamel y remover.","minutes":1,"kind":"activo"},{"text":"Colocar {{Vol-au-vent de hojaldre (cestas precocidas)}} en una bandeja y calentar en el horno 5 min hasta que estén crujientes.","minutes":5,"kind":"pasivo"},{"text":"Retirar las cestas del horno y rellenar cada una con el relleno de marisco y bechamel.","minutes":2,"kind":"emplatado"},{"text":"Servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, 'especial', NULL, 'horno', NULL, NULL),
  ('pescados_116', 'Timbal de patata y bacalao', 'pescados', 'pescado_blanco', 'patatas', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'all', 550, 33, 37, 26, 2, true, true, '{"pescado","lactosa","huevo"}', '[{"name":"Bacalao desalado (desmigado)","amount":250,"unit":"g"},{"name":"Patata","amount":400,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Pelar patata y colocarlas enteras en una olla cubiertas de agua fría con sal.","Llevar a ebullición y cocer a fuego medio hasta que estén tiernas.","Picar cebolla en fino.","Picar perejil fino y reservar.","Calentar aceite de oliva en sartén a fuego medio y sofreír la cebolla picada hasta que esté tierna.","Añadir bacalao desalado (desmigado) a la sartén y sofreír hasta que pierda el aspecto crudo.","Retirar la sartén del fuego y reservar el sofrito de bacalao y cebolla.","Escurrir las patatas cocidas y dejar templar.","Cortar las patatas templadas en rodajas de grosor uniforme.","Batir huevo con nata para cocinar en un bol hasta integrar.","Mezclar la mezcla de huevo y nata con el sofrito de bacalao y cebolla hasta obtener un relleno homogéneo.","Precalentar el horno a 190 °C y engrasar dos moldes individuales con aceite de oliva.","Disponer una primera capa de rodajas de patata en la base de cada molde.","Cubrir con una capa del relleno de bacalao y repetir hasta agotar ingredientes, terminando con rodajas de patata.","Espolvorear queso rallado sobre la capa superior de cada molde.","Hornear los moldes en el horno a 190 °C hasta que estén gratinados y dorados por encima.","Retirar los moldes del horno y dejar reposar antes de desmoldar.","Desmoldar con cuidado cada timbal sobre el plato y espolvorear con el perejil picado."}', 'Timbal de capas de patata y bacalao desmigado, gratinado al horno con queso.', NULL, '{}', true, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y colocarlas enteras en una olla cubiertas de agua fría con sal.","minutes":2,"kind":"prep"},{"text":"Llevar a ebullición y cocer a fuego medio hasta que estén tiernas.","minutes":25,"kind":"pasivo"},{"text":"Picar {{Cebolla}} en fino.","minutes":3,"kind":"paralelo","during":1},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"paralelo","during":1},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio y sofreír la cebolla picada hasta que esté tierna.","minutes":10,"kind":"activo"},{"text":"Añadir {{Bacalao desalado (desmigado)}} a la sartén y sofreír hasta que pierda el aspecto crudo.","minutes":4,"kind":"activo"},{"text":"Retirar la sartén del fuego y reservar el sofrito de bacalao y cebolla.","minutes":1,"kind":"prep"},{"text":"Escurrir las patatas cocidas y dejar templar.","minutes":5,"kind":"espera"},{"text":"Cortar las patatas templadas en rodajas de grosor uniforme.","minutes":3,"kind":"prep"},{"text":"Batir {{Huevo}} con {{Nata para cocinar}} en un bol hasta integrar.","minutes":1,"kind":"prep"},{"text":"Mezclar la mezcla de huevo y nata con el sofrito de bacalao y cebolla hasta obtener un relleno homogéneo.","minutes":1,"kind":"prep"},{"text":"Precalentar el horno a 190 °C y engrasar dos moldes individuales con aceite de oliva.","minutes":10,"kind":"pasivo"},{"text":"Disponer una primera capa de rodajas de patata en la base de cada molde.","minutes":1,"kind":"paralelo","during":11},{"text":"Cubrir con una capa del relleno de bacalao y repetir hasta agotar ingredientes, terminando con rodajas de patata.","minutes":2,"kind":"paralelo","during":11},{"text":"Espolvorear {{Queso rallado}} sobre la capa superior de cada molde.","minutes":1,"kind":"paralelo","during":11},{"text":"Hornear los moldes en el horno a 190 °C hasta que estén gratinados y dorados por encima.","minutes":22,"kind":"pasivo"},{"text":"Retirar los moldes del horno y dejar reposar antes de desmoldar.","minutes":5,"kind":"espera"},{"text":"Desmoldar con cuidado cada timbal sobre el plato y espolvorear con el perejil picado.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, true),
  ('pescados_117', 'Pastel de puerros y salmón', 'pescados', 'pescado_azul', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 90, 'normal', 'all', 500, 26, 8, 38, 4, true, true, '{"pescado","huevo","lactosa"}', '[{"name":"Salmón (lomos)","amount":350,"unit":"g"},{"name":"Puerro","amount":400,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Nata para cocinar","amount":200,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Forrar un molde rectangular con papel vegetal.","Limpiar puerro y cortarlos en rodajas finas.","Calentar mantequilla en sartén a fuego suave.","Sofreír el puerro en rodajas a fuego suave, removiendo de vez en cuando, hasta que esté muy tierno sin dorarse.","Salpimentar el puerro pochado y reservar para que temple.","Cocer salmón (lomos) en agua con sal a fuego medio hasta que estén hechos.","Retirar el salmón del agua y dejar templar.","Desmenuzar el salmón en trozos grandes, retirando piel y espinas.","Batir huevo con nata para cocinar en un bol grande.","Añadir nuez moscada al batido de huevo y nata y salpimentar al gusto.","Incorporar el puerro pochado y el salmón desmenuzado al batido, mezclando con cuidado.","Verter la mezcla en el molde preparado y repartir queso rallado por encima.","Colocar el molde dentro de una bandeja con agua caliente hasta la mitad del molde para el baño maría.","Hornear a 180 °C al baño maría hasta que el pastel esté cuajado y ligeramente dorado en la superficie.","Retirar el molde del horno y dejar templar a temperatura ambiente.","Refrigerar el pastel en el molde hasta que esté bien frío y firme para desmoldar.","Desmoldar el pastel sobre una fuente y cortar en lonchas.","Servir frío o templado."}', 'Pastel cuajado al horno con capas de puerro pochado y salmón desmenuzado, en lonchas rosadas y verdes.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, ARRAY['huevo']::main_protein[], false, '[{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Forrar un molde rectangular con papel vegetal.","minutes":2,"kind":"prep"},{"text":"Limpiar {{Puerro}} y cortarlos en rodajas finas.","minutes":5,"kind":"prep"},{"text":"Calentar {{Mantequilla}} en {{@Sartén}} a fuego suave.","minutes":1,"kind":"activo"},{"text":"Sofreír el puerro en rodajas a fuego suave, removiendo de vez en cuando, hasta que esté muy tierno sin dorarse.","minutes":14,"kind":"pasivo"},{"text":"Salpimentar el puerro pochado y reservar para que temple.","minutes":1,"kind":"activo"},{"text":"Cocer {{Salmón (lomos)}} en agua con sal a fuego medio hasta que estén hechos.","minutes":9,"kind":"pasivo"},{"text":"Retirar el salmón del agua y dejar templar.","minutes":5,"kind":"espera"},{"text":"Desmenuzar el salmón en trozos grandes, retirando piel y espinas.","minutes":3,"kind":"prep"},{"text":"Batir {{Huevo}} con {{Nata para cocinar}} en un bol grande.","minutes":2,"kind":"prep"},{"text":"Añadir {{Nuez moscada|pizca}} al batido de huevo y nata y salpimentar al gusto.","minutes":1,"kind":"prep"},{"text":"Incorporar el puerro pochado y el salmón desmenuzado al batido, mezclando con cuidado.","minutes":2,"kind":"activo"},{"text":"Verter la mezcla en el molde preparado y repartir {{Queso rallado}} por encima.","minutes":2,"kind":"activo"},{"text":"Colocar el molde dentro de una bandeja con agua caliente hasta la mitad del molde para el baño maría.","minutes":2,"kind":"activo"},{"text":"Hornear a 180 °C al baño maría hasta que el pastel esté cuajado y ligeramente dorado en la superficie.","minutes":43,"kind":"pasivo"},{"text":"Retirar el molde del horno y dejar templar a temperatura ambiente.","minutes":15,"kind":"espera"},{"text":"Refrigerar el pastel en el molde hasta que esté bien frío y firme para desmoldar.","minutes":120,"kind":"espera"},{"text":"Desmoldar el pastel sobre una fuente y cortar en lonchas.","minutes":2,"kind":"emplatado"},{"text":"Servir frío o templado.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, true)
