) values
  ('pescados_118', 'Empanadillas de bonito y pimientos', 'pescados', 'pescado_azul', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 760, 39, 76, 30, 2, true, false, '{"gluten","pescado","huevo"}', '[{"name":"Obleas para empanadillas","amount":16,"unit":"ud"},{"name":"Bonito en conserva","amount":200,"unit":"g"},{"name":"Pimiento rojo","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":80,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate frito","amount":100,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de oliva suave","amount":300,"unit":"ml"}]'::jsonb, '{"Picar cebolla en dados pequeños.","Picar pimiento rojo en dados pequeños.","Picar pimiento verde en dados pequeños.","Calentar aceite de oliva suave en sartén a fuego medio.","Sofreír la cebolla picada, el pimiento rojo y el pimiento verde hasta que estén tiernos.","Añadir tomate frito y cocer hasta que el conjunto espese ligeramente.","Retirar la sartén del fuego y dejar templar el sofrito.","Escurrir bonito en conserva y desmenuzarlo sobre el sofrito templado.","Mezclar el bonito con el sofrito hasta integrar bien. Reservar el relleno.","Extender obleas para empanadillas sobre una superficie limpia.","Colocar una cucharada de relleno en el centro de cada oblea.","Humedecer el borde de cada oblea con agua, doblarla por la mitad y sellar presionando con un tenedor.","Batir huevo en un bol pequeño.","Pincelar el borde de cada empanadilla con el huevo batido para reforzar el sellado.","Calentar el aceite de oliva suave restante en sartén honda a fuego fuerte hasta alcanzar 180 °C.","Freír las empanadillas en tandas 2 min por cada lado, hasta que estén doradas.","Escurrir las empanadillas sobre papel absorbente.","Servir las empanadillas calientes."}', 'Empanadillas fritas y crujientes, rellenas de bonito con un sofrito colorido de pimientos.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Cebolla}} en dados pequeños.","minutes":3,"kind":"prep"},{"text":"Picar {{Pimiento rojo}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Picar {{Pimiento verde}} en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva suave|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada, el pimiento rojo y el pimiento verde hasta que estén tiernos.","minutes":13,"kind":"pasivo"},{"text":"Añadir {{Tomate frito}} y cocer hasta que el conjunto espese ligeramente.","minutes":5,"kind":"pasivo"},{"text":"Retirar la sartén del fuego y dejar templar el sofrito.","minutes":5,"kind":"espera"},{"text":"Escurrir {{Bonito en conserva}} y desmenuzarlo sobre el sofrito templado.","minutes":2,"kind":"prep"},{"text":"Mezclar el bonito con el sofrito hasta integrar bien. Reservar el relleno.","minutes":1,"kind":"prep"},{"text":"Extender {{Obleas para empanadillas}} sobre una superficie limpia.","minutes":1,"kind":"prep"},{"text":"Colocar una cucharada de relleno en el centro de cada oblea.","minutes":3,"kind":"prep"},{"text":"Humedecer el borde de cada oblea con agua, doblarla por la mitad y sellar presionando con un tenedor.","minutes":4,"kind":"prep"},{"text":"Batir {{Huevo}} en un bol pequeño.","minutes":1,"kind":"prep"},{"text":"Pincelar el borde de cada empanadilla con el huevo batido para reforzar el sellado.","minutes":2,"kind":"prep"},{"text":"Calentar el aceite de oliva suave restante en {{@Sartén}} honda a fuego fuerte hasta alcanzar 180 °C.","minutes":3,"kind":"activo"},{"text":"Freír las empanadillas en tandas 2 min por cada lado, hasta que estén doradas.","minutes":4,"kind":"activo"},{"text":"Escurrir las empanadillas sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Servir las empanadillas calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, true),
  ('pescados_119', 'Salmón al horno con soja y patatas panaderas', 'pescados', 'pescado_azul', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'all', 490, 34, 32, 24, 2, true, true, '{"pescado","soja","gluten"}', '[{"name":"Lomos de salmón","amount":300,"unit":"g"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Salsa de soja","amount":30,"unit":"ml"},{"name":"Miel","amount":15,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Jengibre fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Cebollino","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Pelar patata y laminar en rodajas finas de 3 mm.","Pelar cebolla y cortar en aros finos.","Disponer la patata y la cebolla en una bandeja de horno.","Regar con aceite de oliva, salpimentar y mezclar bien hasta cubrir.","Hornear la bandeja 20 min hasta que las patatas empiecen a dorarse por los bordes.","Picar ajo muy fino.","Rallar jengibre fresco finamente.","Mezclar en un bol salsa de soja, miel, el ajo picado y el jengibre rallado.","Remover el glaseado hasta obtener una mezcla homogénea y reservar.","Retirar la bandeja del horno y colocar lomos de salmón sobre la cama de patatas.","Pincelar los lomos de salmón generosamente con el glaseado de soja y miel.","Hornear 13 min más hasta que el salmón esté opaco y el glaseado brille.","Picar cebollino fino y espolvorear sobre el salmón.","Servir los lomos de salmón sobre las patatas panaderas directamente en la bandeja."}', 'Salmón glaseado con soja, miel y jengibre al horno sobre una cama de patatas panaderas doradas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Patata}} y laminar en rodajas finas de 3 mm.","minutes":3,"kind":"prep"},{"text":"Pelar {{Cebolla}} y cortar en aros finos.","minutes":2,"kind":"prep"},{"text":"Disponer la patata y la cebolla en una bandeja de horno.","minutes":1,"kind":"prep"},{"text":"Regar con {{Aceite de oliva|chorrito}}, salpimentar y mezclar bien hasta cubrir.","minutes":1,"kind":"prep"},{"text":"Hornear la bandeja 20 min hasta que las patatas empiecen a dorarse por los bordes.","minutes":20,"kind":"pasivo"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"paralelo","during":5},{"text":"Rallar {{Jengibre fresco}} finamente.","minutes":1,"kind":"paralelo","during":5},{"text":"Mezclar en un bol {{Salsa de soja}}, {{Miel}}, el ajo picado y el jengibre rallado.","minutes":1,"kind":"paralelo","during":5},{"text":"Remover el glaseado hasta obtener una mezcla homogénea y reservar.","minutes":1,"kind":"paralelo","during":5},{"text":"Retirar la bandeja del horno y colocar {{Lomos de salmón}} sobre la cama de patatas.","minutes":1,"kind":"activo"},{"text":"Pincelar los lomos de salmón generosamente con el glaseado de soja y miel.","minutes":1,"kind":"activo"},{"text":"Hornear 13 min más hasta que el salmón esté opaco y el glaseado brille.","minutes":13,"kind":"pasivo"},{"text":"Picar {{Cebollino}} fino y espolvorear sobre el salmón.","minutes":1,"kind":"emplatado"},{"text":"Servir los lomos de salmón sobre las patatas panaderas directamente en la bandeja.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, true),
  ('pescados_120', 'Merluza a la romana con ensalada de naranja, hinojo y aceitunas negras', 'pescados', 'pescado_blanco', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 380, 32, 20, 18, 2, true, false, '{"pescado","gluten","huevo","sulfitos"}', '[{"name":"Merluza en lomos","amount":400,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Harina","amount":60,"unit":"g"},{"name":"Naranja","amount":1,"unit":"ud"},{"name":"Hinojo","amount":150,"unit":"g"},{"name":"Aceitunas negras","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"}]'::jsonb, '{"Salpimentar los lomos de merluza, pasarlos por harina y después por huevo batido.","Freír en aceite bien caliente hasta que estén dorados, unos 3-4 min por cada lado.","Escurrir sobre papel absorbente.","Laminar el hinojo muy fino y pelar la naranja en gajos.","Mezclar el hinojo, la naranja y las aceitunas negras, aliñar con un chorrito de aceite.","Servir la merluza con la ensalada al lado."}', 'Merluza rebozada a la romana con una ensalada fresca de naranja, hinojo y aceitunas negras.', NULL, '{}', NULL, NULL, NULL, '{"fruta","encurtido"}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, true, 'sarten', NULL, NULL),
  ('pescados_121', 'Salmón al horno con limón y eneldo', 'pescados', 'pescado_azul', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 360, 30, 2, 26, 2, true, true, '{"pescado"}', '[{"name":"Lomos de salmón","amount":400,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Eneldo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Ajo","amount":1,"unit":"ud"}]'::jsonb, '{"Precalentar el horno a 200°C.","Colocar los lomos de salmón en una bandeja de horno, salpimentar.","Regar con aceite de oliva y zumo de limón, espolvorear con ajo picado y eneldo.","Hornear 12-15 min hasta que esté hecho por dentro."}', 'Lomos de salmón al horno aromatizados con limón, ajo y eneldo fresco.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, NULL, 'horno', NULL, NULL),
  ('pescados_122', 'Atún encebollado con tomate', 'pescados', 'pescado_azul', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 25, 'facil', 'all', 340, 34, 12, 16, 2, true, true, '{"pescado"}', '[{"name":"Atún fresco","amount":400,"unit":"g"},{"name":"Cebolla","amount":2,"unit":"ud"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vino blanco","amount":30,"unit":"ml"}]'::jsonb, '{"Cortar la cebolla en juliana y pocharla en una sartén con aceite a fuego lento hasta que esté tierna, unos 15 min.","Añadir el tomate triturado y el vino blanco, cocinar 10 min.","Salpimentar el atún, incorporarlo a la salsa y cocinar 3-4 min por cada lado.","Servir caliente con la salsa por encima."}', 'Atún fresco cocinado con una salsa de cebolla pochada y tomate.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, NULL, 'sarten', NULL, true),
  ('pescados_123', 'Boquerones fritos con ensalada de pepino, yogur y menta', 'pescados', 'pescado_azul', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 20, 'facil', 'all', 380, 26, 22, 20, 2, true, false, '{"pescado","gluten","lactosa"}', '[{"name":"Boquerones limpios","amount":400,"unit":"g"},{"name":"Harina","amount":80,"unit":"g"},{"name":"Pepino","amount":1,"unit":"ud"},{"name":"Yogur natural","amount":125,"unit":"g"},{"name":"Menta fresca","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"}]'::jsonb, '{"Enharinar los boquerones.","Freír en aceite bien caliente hasta que estén dorados y crujientes, 2-3 min.","Escurrir en papel absorbente.","Pelar y cortar el pepino en dados pequeños, mezclar con el yogur y la menta picada.","Servir los boquerones con la ensalada de pepino al lado."}', 'Boquerones fritos crujientes con una ensalada refrescante de pepino, yogur y menta.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, NULL, 'sarten', NULL, NULL),
  ('pescados_124', 'Filetes de merluza a la plancha con ajada', 'pescados', 'pescado_blanco', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 290, 32, 4, 14, 2, true, true, '{"pescado"}', '[{"name":"Filetes de merluza","amount":400,"unit":"g"},{"name":"Ajo","amount":4,"unit":"ud"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"}]'::jsonb, '{"Salpimentar los filetes de merluza y marcarlos a la plancha 3-4 min por cada lado.","Laminar el ajo y dorarlo en aceite caliente en una sartén aparte.","Retirar del fuego y añadir el pimentón y el vinagre, remover rápido.","Verter la ajada caliente por encima del pescado y servir."}', 'Filetes de merluza a la plancha con una ajada de ajo, pimentón y vinagre.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, NULL, 'plancha', NULL, NULL),
  ('pescados_125', 'Salmón con parrillada de verduras al horno', 'pescados', 'pescado_azul', NULL, ARRAY['cena','segundo']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 400, 32, 18, 22, 2, true, true, '{"pescado"}', '[{"name":"Lomos de salmón","amount":400,"unit":"g"},{"name":"Calabacín","amount":1,"unit":"ud"},{"name":"Pimiento rojo","amount":1,"unit":"ud"},{"name":"Berenjena","amount":1,"unit":"ud"},{"name":"Cebolla","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200°C.","Cortar las verduras en tiras y colocarlas en una bandeja con aceite y sal.","Hornear 15 min.","Añadir los lomos de salmón salpimentados encima, regar con un poco de aceite.","Hornear 12-15 min más hasta que el salmón esté hecho."}', 'Salmón al horno servido sobre una parrillada de verduras asadas.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, NULL, 'plancha', NULL, NULL),
  ('pescados_126', 'Bacalao al pil pil sencillo', 'pescados', 'pescado_blanco', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 35, 'normal', 'all', 340, 30, 4, 22, 2, false, false, '{"pescado"}', '[{"name":"Lomos de bacalao desalado","amount":400,"unit":"g"},{"name":"Ajo","amount":6,"unit":"ud"},{"name":"Aceite de oliva","amount":150,"unit":"ml"},{"name":"Guindilla","amount":1,"unit":"ud"}]'::jsonb, '{"Laminar el ajo y confitarlo en el aceite a fuego muy suave hasta que esté dorado. Retirar y reservar.","En el mismo aceite, confitar los lomos de bacalao con la piel hacia arriba a fuego muy bajo, 8-10 min.","Retirar el pescado con cuidado y reservar el aceite.","Ligar el aceite con movimientos circulares (con ayuda de una cazuela o batidora de mano) hasta que emulsione y espese.","Napar el bacalao con la salsa y servir con el ajo dorado y la guindilla."}', 'Bacalao confitado a fuego suave con una salsa emulsionada de su propio aceite y ajo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, NULL, 'sarten', NULL, true),
  ('pescados_127', 'Lubina al horno con patatas panadera', 'pescados', 'pescado_blanco', 'patatas', ARRAY['segundo','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'facil', 'all', 420, 34, 30, 18, 2, true, true, '{"pescado"}', '[{"name":"Lubina entera limpia","amount":500,"unit":"g"},{"name":"Patatas","amount":300,"unit":"g"},{"name":"Cebolla","amount":0.5,"unit":"ud"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":25,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200°C.","Cortar las patatas y la cebolla en rodajas finas, colocar en la base de una bandeja con aceite y sal.","Hornear 20 min.","Colocar la lubina limpia encima con rodajas de limón dentro, salpimentar y regar con aceite.","Hornear 20-25 min más hasta que esté hecha."}', 'Lubina entera al horno sobre una cama de patatas panadera con limón.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, NULL, 'horno', NULL, NULL)
