insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('pescados_128', 'Trucha a la plancha con almendras tostadas', 'pescados', 'pescado_blanco', NULL, ARRAY['cena','segundo']::meal_role[], 'principal', NULL, NULL, 15, 'facil', 'all', 360, 32, 6, 22, 2, true, false, '{"pescado","frutos_secos"}', '[{"name":"Truchas limpias","amount":400,"unit":"g"},{"name":"Almendras laminadas","amount":40,"unit":"g"},{"name":"Ajo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Salpimentar las truchas y marcarlas a la plancha 3-4 min por cada lado hasta que estén hechas.","Tostar las almendras laminadas con el ajo picado en un poco de aceite hasta dorar.","Espolvorear las almendras y el perejil picado sobre las truchas.","Servir caliente."}', 'Truchas a la plancha con una guarnición crujiente de almendras tostadas al ajo.', NULL, '{}', NULL, NULL, NULL, '{"frutos_secos"}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, NULL, 'plancha', NULL, NULL),
  ('pescados_129', 'Merluza a la veracruzana con aceitunas y alcaparras', 'pescados', 'pescado_blanco', NULL, ARRAY['segundo']::meal_role[], 'principal', NULL, NULL, 30, 'facil', 'all', 380, 36, 12, 21, 2, false, true, '{"pescado","sulfitos"}', '[{"name":"Merluza en lomos","amount":500,"unit":"g"},{"name":"Tomate maduro","amount":400,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceitunas","amount":60,"unit":"g"},{"name":"Alcaparras","amount":20,"unit":"g"},{"name":"Laurel","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pochar la cebolla en juliana y el ajo picado en el aceite, sin que cojan color.","Añadir el tomate rallado y el laurel, y cocinar 12 minutos a fuego medio.","Incorporar las aceitunas y las alcaparras escurridas. Salar con cuidado, que ya salan ellas.","Colocar los lomos de merluza sobre la salsa, tapar y cocer 8 minutos a fuego suave.","Servir el pescado con su salsa por encima."}', 'Merluza cocinada en una salsa de tomate con aceitunas y alcaparras. El punto salado de los encurtidos es lo que la hace distinta.', NULL, '{}', NULL, NULL, NULL, '{"verdura","encurtido"}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, NULL, 'sarten', 'mexicana', NULL),
  ('platos_unicos_001', 'Paella valenciana', 'platos_unicos', 'pollo', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 528, 28, 58, 18, 2, true, false, '{}', '[{"name":"Arroz","amount":200,"unit":"g"},{"name":"Contramuslo de pollo","amount":200,"unit":"g"},{"name":"Judías verdes","amount":80,"unit":"g"},{"name":"Garrofón","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Pimentón","amount":4,"unit":"g"},{"name":"Azafrán","amount":1,"unit":"g"}]'::jsonb, '{"Cortar contramuslo de pollo en trozos de unos 4 cm.","Cortar judías verdes en trozos de unos 3 cm.","Calentar la paella a fuego fuerte y añadir aceite de oliva.","Dorar el pollo en la paella a fuego fuerte hasta que esté bien dorado por todos los lados.","Añadir las judías verdes y garrofón y saltear a fuego medio hasta que estén ligeramente dorados, unos 3 min.","Incorporar tomate triturado y sofreír a fuego medio hasta que pierda el agua y quede concentrado.","Añadir pimentón y remover durante 20 segundos hasta que se integre; retirar la paella del fuego para que no se queme.","Llevar a ebullición 600 ml de agua en un cazo aparte.","Disolver azafrán en un poco del agua caliente dentro del cazo y remover.","Verter el agua con azafrán en la paella y volver a poner a fuego fuerte hasta que rompa a hervir.","Cocer el caldo a fuego medio durante 10 min para que el pollo y las verduras se terminen de cocinar y el caldo coja sabor.","Añadir arroz distribuyéndolo de forma uniforme por toda la paella sin remover.","Cocer a fuego fuerte los primeros 5 min sin remover en ningún momento.","Bajar a fuego medio-suave y cocer hasta que el arroz absorba todo el caldo y esté en su punto, unos 13 min más.","Retirar del fuego y dejar reposar la paella tapada con papel de periódico o un paño limpio durante 2 min.","Servir la paella directamente en la mesa desde la misma paella."}', 'Paella valenciana de pollo con judías verdes y garrofón', '[{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Comienza dorando el pollo y las verduras en una paellera sobre la encimera. Añade el tomate, pimentón y arroz, luego el caldo con azafrán. Tras un hervor, hornea a 180°C durante 20-25 minutos hasta que el arroz absorba el líquido, logrando una cocción uniforme."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Contramuslo de pollo}} en trozos de unos 4 cm.","minutes":3,"kind":"prep"},{"text":"Cortar {{Judías verdes}} en trozos de unos 3 cm.","minutes":2,"kind":"prep"},{"text":"Calentar la paella a fuego fuerte y añadir {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"activo"},{"text":"Dorar el pollo en la paella a fuego fuerte hasta que esté bien dorado por todos los lados.","minutes":8,"kind":"activo"},{"text":"Añadir las judías verdes y {{Garrofón}} y saltear a fuego medio hasta que estén ligeramente dorados, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Incorporar {{Tomate triturado}} y sofreír a fuego medio hasta que pierda el agua y quede concentrado.","minutes":4,"kind":"activo"},{"text":"Añadir {{Pimentón|pizca}} y remover durante 20 segundos hasta que se integre; retirar la paella del fuego para que no se queme.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición 600 ml de agua en un cazo aparte.","minutes":4,"kind":"pasivo"},{"text":"Disolver {{Azafrán|pizca}} en un poco del agua caliente dentro del cazo y remover.","minutes":1,"kind":"activo"},{"text":"Verter el agua con azafrán en la paella y volver a poner a fuego fuerte hasta que rompa a hervir.","minutes":2,"kind":"activo"},{"text":"Cocer el caldo a fuego medio durante 10 min para que el pollo y las verduras se terminen de cocinar y el caldo coja sabor.","minutes":10,"kind":"pasivo"},{"text":"Añadir {{Arroz}} distribuyéndolo de forma uniforme por toda la paella sin remover.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego fuerte los primeros 5 min sin remover en ningún momento.","minutes":5,"kind":"activo"},{"text":"Bajar a fuego medio-suave y cocer hasta que el arroz absorba todo el caldo y esté en su punto, unos 13 min más.","minutes":13,"kind":"pasivo"},{"text":"Retirar del fuego y dejar reposar la paella tapada con papel de periódico o un paño limpio durante 2 min.","minutes":2,"kind":"espera"},{"text":"Servir la paella directamente en la mesa desde la misma paella.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('platos_unicos_002', 'Pizza casera', 'platos_unicos', 'none', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 40, 'normal', 'all', 518, 18, 62, 22, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Harina","amount":250,"unit":"g"},{"name":"Levadura fresca","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Mozzarella","amount":125,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Orégano","amount":3,"unit":"g"}]'::jsonb, '{"Desmenuzar levadura fresca en un bol con 150 ml de agua tibia y remover hasta que se disuelva por completo.","Añadir harina al bol y verter aceite de oliva; mezclar hasta obtener una masa homogénea.","Amasar la masa sobre la encimera enharinada durante 8 min hasta que esté elástica y no se pegue.","Tapar la masa con un paño húmedo y dejar reposar hasta que doble su volumen.","Precalentar el horno a 230 °C con calor arriba y abajo.","Estirar la masa sobre papel de hornear formando un disco fino de unos 30 cm de diámetro.","Extender tomate triturado sobre la masa dejando 1 cm de borde libre.","Laminar mozzarella y repartir las láminas de forma uniforme sobre el tomate.","Espolvorear orégano sobre la mozzarella.","Hornear la pizza en la rejilla central a 230 °C hasta que los bordes estén dorados y el queso burbujee.","Retirar la pizza del horno, cortar en porciones y servir de inmediato."}', 'Pizza casera con masa fina, tomate y mozzarella', '[{"appliance":"horno","time":40,"difficulty":"normal","prepSummary":"Prepara la masa siguiendo la receta y estírala sobre una bandeja. Hornea la pizza en un horno precalentado a 200-220°C durante 15-20 minutos, hasta que la base esté dorada y el queso burbujeante y fundido."},{"appliance":"airfryer","time":35,"difficulty":"normal","prepSummary":"Amasa y forma una o varias pizzas pequeñas que quepan en la cesta de la airfryer. Cocínalas en la airfryer precalentada a 180-190°C durante 10-15 minutos, vigilando que la masa quede crujiente y el queso bien fundido."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Desmenuzar {{Levadura fresca}} en un bol con 150 ml de agua tibia y remover hasta que se disuelva por completo.","minutes":2,"kind":"prep"},{"text":"Añadir {{Harina}} al bol y verter {{Aceite de oliva|chorrito}}; mezclar hasta obtener una masa homogénea.","minutes":3,"kind":"activo"},{"text":"Amasar la masa sobre la encimera enharinada durante 8 min hasta que esté elástica y no se pegue.","minutes":8,"kind":"activo"},{"text":"Tapar la masa con un paño húmedo y dejar reposar hasta que doble su volumen.","minutes":20,"kind":"espera"},{"text":"Precalentar el horno a 230 °C con calor arriba y abajo.","minutes":10,"kind":"paralelo","during":3},{"text":"Estirar la masa sobre papel de hornear formando un disco fino de unos 30 cm de diámetro.","minutes":3,"kind":"prep"},{"text":"Extender {{Tomate triturado}} sobre la masa dejando 1 cm de borde libre.","minutes":1,"kind":"prep"},{"text":"Laminar {{Mozzarella}} y repartir las láminas de forma uniforme sobre el tomate.","minutes":2,"kind":"prep"},{"text":"Espolvorear {{Orégano|pizca}} sobre la mozzarella.","minutes":1,"kind":"prep"},{"text":"Hornear la pizza en la rejilla central a 230 °C hasta que los bordes estén dorados y el queso burbujee.","minutes":10,"kind":"pasivo"},{"text":"Retirar la pizza del horno, cortar en porciones y servir de inmediato.","minutes":2,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'horno', 'italiana', NULL),
  ('platos_unicos_003', 'Croquetas de jamón', 'platos_unicos', 'none', NULL, ARRAY['cena','plato_unico']::meal_role[], 'principal', NULL, NULL, 45, 'normal', 'all', 428, 14, 32, 28, 2, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Jamón serrano","amount":80,"unit":"g"},{"name":"Leche","amount":300,"unit":"ml"},{"name":"Harina","amount":50,"unit":"g"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Nuez moscada","amount":2,"unit":"g"}]'::jsonb, '{"Picar el jamón serrano en dados muy finos","Fundir la mantequilla en un cazo a fuego medio-suave","Calentar la leche en otro cazo hasta que esté caliente sin hervir","Añadir la harina al roux y remover con varillas 2 min hasta obtener una pasta lisa","Incorporar la leche caliente poco a poco sin dejar de remover hasta obtener bechamel","Añadir el jamón picado y la nuez moscada; remover 1 min para integrar","Extender la bechamel en bandeja, cubrir con film a piel y refrigerar mínimo 3 horas","Batir el huevo en un bol y disponer el pan rallado en un plato aparte","Dar forma ovalada a las croquetas con las manos enharinadas","Pasar cada croqueta por huevo batido y luego por pan rallado cubriendo bien","Calentar el aceite en sartén profunda a fuego fuerte hasta alcanzar 180 °C","Freír por tandas 2-3 min hasta que estén doradas; escurrir y servir calientes"}', 'Croquetas cremosas de bechamel con jamón serrano', '[{"appliance":"thermomix","time":40,"difficulty":"normal","prepSummary":"La Thermomix es ideal para la bechamel: funde la mantequilla, sofríe la harina y añade la leche progresivamente a 90°C, velocidad 4, durante unos 7-8 minutos hasta obtener una crema perfecta y sin grumos. Luego, se enfría la masa, se forman las croquetas y se fríen de forma tradicional en abundante aceite caliente."},{"appliance":"airfryer","time":50,"difficulty":"normal","prepSummary":"Una vez formadas y empanadas las croquetas, rocíalas ligeramente con aceite de oliva y cocínalas en la airfryer precalentada a 190-200°C durante 12-15 minutos, dándoles la vuelta a mitad de cocción, hasta que estén doradas y crujientes."},{"appliance":"horno","time":55,"difficulty":"normal","prepSummary":"Para una versión más ligera, hornea las croquetas ya empanadas. Precalienta el horno a 200°C con calor arriba y abajo, rocía las croquetas con un poco de aceite y hornea durante 20-25 minutos, girándolas una vez, hasta que estén doradas."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, ARRAY['cerdo']::main_protein[], true, '[{"text":"Picar {{Jamón serrano}} en dados muy finos.","minutes":3,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego medio-suave sin que se dore.","minutes":2,"kind":"activo"},{"text":"Calentar {{Leche}} en otro cazo a fuego suave hasta que esté caliente, sin que llegue a hervir.","minutes":2,"kind":"paralelo","during":1},{"text":"Añadir {{Harina}} al roux de golpe y remover con varillas 2 min hasta obtener una pasta lisa y sin grumos.","minutes":2,"kind":"activo"},{"text":"Incorporar la leche caliente poco a poco sin dejar de remover, esperando a que cada adición se integre antes de añadir la siguiente.","minutes":8,"kind":"activo"},{"text":"Añadir el jamón picado y {{Nuez moscada|pizca}}; remover 1 min a fuego suave para integrar.","minutes":1,"kind":"activo"},{"text":"Extender la bechamel en una bandeja, cubrir con film a piel y refrigerar al menos 3 horas hasta que la masa esté compacta.","minutes":180,"kind":"espera"},{"text":"Batir {{Huevo}} en un bol hondo y disponer {{Pan rallado}} en un plato aparte.","minutes":2,"kind":"prep"},{"text":"Tomar porciones de masa fría y dar forma ovalada con las manos ligeramente enharinadas.","minutes":5,"kind":"activo"},{"text":"Pasar cada croqueta por el huevo batido y luego por el pan rallado, cubriendo bien toda la superficie.","minutes":4,"kind":"activo"},{"text":"Calentar {{Aceite de oliva|abundante}} en una sartén profunda a fuego fuerte hasta alcanzar 180 °C.","minutes":4,"kind":"activo"},{"text":"Freír las croquetas por tandas 2-3 min, sin amontonarlas, hasta que estén doradas y crujientes.","minutes":5,"kind":"activo"},{"text":"Escurrir sobre papel absorbente y servir calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL, NULL),
  ('platos_unicos_004', 'Empanada gallega de atún', 'platos_unicos', 'pescado_azul', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 60, 'normal', 'all', 468, 20, 46, 22, 2, true, true, '{"gluten","pescado","huevo"}', '[{"name":"Harina","amount":250,"unit":"g"},{"name":"Atún en conserva","amount":160,"unit":"g"},{"name":"Cebolla","amount":120,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"}]'::jsonb, '{"Picar cebolla en daditos finos.","Cortar pimiento rojo en tiras pequeñas.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír la cebolla picada y el pimiento rojo a fuego medio hasta que estén tiernos.","Añadir tomate triturado al sofrito y remover hasta integrar.","Cocer a fuego medio hasta que el sofrito reduzca y espese.","Escurrir atún en conserva y desmenuzarlo sobre un plato.","Añadir el atún desmenuzado al sofrito, mezclar bien y retirar del fuego. Reservar.","Precalentar el horno a 190 °C con calor arriba y abajo.","Poner harina en un bol grande. Añadir sal y el aceite de oliva restante.","Añadir 65 ml de agua tibia a la mezcla de harina y amasar hasta obtener una masa homogénea.","Dividir la masa en 2 porciones iguales.","Estirar cada porción con un rodillo hasta obtener 2 láminas finas del tamaño de la bandeja.","Disponer la primera lámina sobre una bandeja de horno ligeramente engrasada.","Repartir el relleno de atún sobre la lámina dejando 1 cm de borde libre en todo el contorno.","Cubrir con la segunda lámina de masa.","Sellar los bordes presionando con los dedos y doblar el borde hacia arriba pellizcándolo para cerrar bien.","Batir huevo en un bol pequeño hasta homogeneizar.","Pintar toda la superficie de la empanada con el huevo batido usando un pincel.","Hacer 2 o 3 cortes pequeños en el centro de la empanada para permitir la salida de vapor.","Hornear a 190 °C hasta que la superficie esté dorada.","Retirar del horno y dejar reposar la empanada antes de cortar.","Cortar la empanada en porciones y servir."}', 'Empanada gallega de masa casera rellena de atún y pimiento', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Prepara la masa y el relleno. Hornea la empanada a 180-190°C durante 35-40 minutos, o hasta que esté dorada y crujiente. Un truco es pintar con huevo batido para un acabado brillante."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Elabora la masa y el relleno. Forma una empanada de tamaño adecuado para tu airfryer y cocina a 170-180°C durante 20-25 minutos, volteándola a mitad, hasta que esté dorada. Asegúrate de no sobrecargar la cesta."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Cebolla}} en daditos finos.","minutes":3,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} en tiras pequeñas.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada y el pimiento rojo a fuego medio hasta que estén tiernos.","minutes":8,"kind":"pasivo"},{"text":"Añadir {{Tomate triturado}} al sofrito y remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio hasta que el sofrito reduzca y espese.","minutes":5,"kind":"pasivo"},{"text":"Escurrir {{Atún en conserva}} y desmenuzarlo sobre un plato.","minutes":2,"kind":"prep"},{"text":"Añadir el atún desmenuzado al sofrito, mezclar bien y retirar del fuego. Reservar.","minutes":1,"kind":"activo"},{"text":"Precalentar el horno a 190 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Poner {{Harina}} en un bol grande. Añadir {{Sal|gusto}} y el aceite de oliva restante.","minutes":1,"kind":"prep"},{"text":"Añadir 65 ml de agua tibia a la mezcla de harina y amasar hasta obtener una masa homogénea.","minutes":3,"kind":"activo"},{"text":"Dividir la masa en 2 porciones iguales.","minutes":1,"kind":"prep"},{"text":"Estirar cada porción con un rodillo hasta obtener 2 láminas finas del tamaño de la bandeja.","minutes":4,"kind":"prep"},{"text":"Disponer la primera lámina sobre una bandeja de horno ligeramente engrasada.","minutes":1,"kind":"activo"},{"text":"Repartir el relleno de atún sobre la lámina dejando 1 cm de borde libre en todo el contorno.","minutes":2,"kind":"activo"},{"text":"Cubrir con la segunda lámina de masa.","minutes":1,"kind":"activo"},{"text":"Sellar los bordes presionando con los dedos y doblar el borde hacia arriba pellizcándolo para cerrar bien.","minutes":2,"kind":"activo"},{"text":"Batir {{Huevo}} en un bol pequeño hasta homogeneizar.","minutes":1,"kind":"prep"},{"text":"Pintar toda la superficie de la empanada con el huevo batido usando un pincel.","minutes":1,"kind":"activo"},{"text":"Hacer 2 o 3 cortes pequeños en el centro de la empanada para permitir la salida de vapor.","minutes":1,"kind":"activo"},{"text":"Hornear a 190 °C hasta que la superficie esté dorada.","minutes":30,"kind":"pasivo"},{"text":"Retirar del horno y dejar reposar la empanada antes de cortar.","minutes":5,"kind":"espera"},{"text":"Cortar la empanada en porciones y servir.","minutes":2,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'horno', NULL, NULL),
  ('platos_unicos_005', 'Empanadillas de atún', 'platos_unicos', 'pescado_azul', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 412, 18, 38, 22, 2, true, true, '{"gluten","pescado","huevo"}', '[{"name":"Obleas de empanadilla","amount":8,"unit":"ud"},{"name":"Atún en conserva","amount":120,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Pimiento verde","amount":50,"unit":"g"},{"name":"Huevo cocido","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Pelar cebolla y cortar en brunoise fina. Lavar pimiento verde y cortar también en brunoise fina.","Escurrir atún en conserva y desmenuzar con un tenedor. Reservar.","Pelar huevo cocido y picar en trozos pequeños. Reservar.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír la cebolla y el pimiento verde picados a fuego medio hasta que estén tiernos, unos 6 min.","Añadir tomate triturado y remover. Cocer a fuego medio hasta que el líquido reduzca, unos 4 min.","Añadir el atún desmenuzado y el huevo cocido picado. Mezclar y retirar del fuego.","Dejar enfriar el relleno hasta que esté a temperatura ambiente antes de rellenar las obleas.","Disponer obleas de empanadilla sobre una superficie plana. Colocar una cucharada de relleno en el centro de cada oblea.","Doblar cada oblea por la mitad y sellar el borde presionando con un tenedor para que no se abran.","Calentar el aceite de oliva restante en sartén a fuego fuerte hasta que esté bien caliente.","Freír las empanadillas en el aceite caliente hasta que estén doradas por ambos lados, unos 2 min por lado.","Escurrir las empanadillas sobre papel absorbente y servir calientes."}', 'Empanadillas rellenas de atún con pimiento y huevo', '[{"appliance":"airfryer","time":30,"difficulty":"facil","prepSummary":"Prepara el sofrito en sartén. Rellena las obleas y cocina en la airfryer precalentada a 180-190°C durante 12-15 minutos, dándoles la vuelta a mitad para un dorado uniforme y crujiente."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Elabora el sofrito en una sartén. Rellena las obleas, séllalas y píntalas con huevo o aceite antes de hornear a 190-200°C durante 15-20 minutos, hasta que estén doradas y crujientes."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Cebolla}} y cortar en brunoise fina. Lavar {{Pimiento verde}} y cortar también en brunoise fina.","minutes":5,"kind":"prep"},{"text":"Escurrir {{Atún en conserva}} y desmenuzar con un tenedor. Reservar.","minutes":2,"kind":"prep"},{"text":"Pelar {{Huevo cocido}} y picar en trozos pequeños. Reservar.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el pimiento verde picados a fuego medio hasta que estén tiernos, unos 6 min.","minutes":6,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y remover. Cocer a fuego medio hasta que el líquido reduzca, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir el atún desmenuzado y el huevo cocido picado. Mezclar y retirar del fuego.","minutes":1,"kind":"activo"},{"text":"Dejar enfriar el relleno hasta que esté a temperatura ambiente antes de rellenar las obleas.","minutes":10,"kind":"espera"},{"text":"Disponer {{Obleas de empanadilla}} sobre una superficie plana. Colocar una cucharada de relleno en el centro de cada oblea.","minutes":2,"kind":"prep"},{"text":"Doblar cada oblea por la mitad y sellar el borde presionando con un tenedor para que no se abran.","minutes":2,"kind":"prep"},{"text":"Calentar el aceite de oliva restante en {{@Sartén}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Freír las empanadillas en el aceite caliente hasta que estén doradas por ambos lados, unos 2 min por lado.","minutes":4,"kind":"activo"},{"text":"Escurrir las empanadillas sobre papel absorbente y servir calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL, NULL),
  ('platos_unicos_006', 'Crepes de jamón y queso', 'platos_unicos', 'none', NULL, ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 398, 18, 32, 22, 2, true, false, '{"gluten","huevo","lactosa"}', '[{"name":"Harina","amount":100,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Leche","amount":200,"unit":"ml"},{"name":"Jamón cocido","amount":80,"unit":"g"},{"name":"Queso en lonchas","amount":60,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"}]'::jsonb, '{"Tamizar harina en un bol amplio y añadir huevo; batir con varillas hasta incorporar.","Incorporar leche poco a poco sin dejar de remover hasta obtener una masa fina y sin grumos.","Calentar sartén a fuego medio y fundir mantequilla hasta que cubra toda la base.","Verter un cucharón de masa y mover la sartén en círculos hasta que cubra la base con una capa fina.","Cocer la crepe hasta que los bordes se despeguen y la base esté dorada; girar y cocer 30 segundos más.","Repetir el proceso con el resto de la masa hasta obtener 4 crepes; reservar apiladas.","Cortar jamón cocido en tiras y disponer sobre cada crepe extendida.","Colocar queso en lonchas sobre el jamón cubriendo la mitad de la crepe.","Doblar cada crepe por la mitad y luego en cuartos para formar un triángulo.","Calentar la sartén a fuego suave y dorar las crepes rellenas 2 min por cada lado hasta que el queso se funda.","Servir las crepes calientes, 2 por ración, recién sacadas de la sartén."}', 'Crepes finas rellenas de jamón cocido y queso fundido', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para preparar la masa de los crepes de forma rápida y sin grumos. Mezcla todos los ingredientes (harina, huevos, leche, mantequilla derretida) durante 30 segundos a velocidad 5. Luego, cocina los crepes en una sartén tradicional."},{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Tras cocinar los crepes en sartén y rellenarlos con jamón y queso, colócalos en una fuente apta para horno. Gratina a 180°C durante 8-10 minutos hasta que el queso se funda y los crepes estén calientes y ligeramente dorados."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Tamizar {{Harina}} en un bol amplio y añadir {{Huevo}}; batir con varillas hasta incorporar.","minutes":2,"kind":"prep"},{"text":"Incorporar {{Leche}} poco a poco sin dejar de remover hasta obtener una masa fina y sin grumos.","minutes":2,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio y fundir {{Mantequilla}} hasta que cubra toda la base.","minutes":1,"kind":"activo"},{"text":"Verter un cucharón de masa y mover la sartén en círculos hasta que cubra la base con una capa fina.","minutes":1,"kind":"activo"},{"text":"Cocer la crepe hasta que los bordes se despeguen y la base esté dorada; girar y cocer 30 segundos más.","minutes":2,"kind":"activo"},{"text":"Repetir el proceso con el resto de la masa hasta obtener 4 crepes; reservar apiladas.","minutes":6,"kind":"activo"},{"text":"Cortar {{Jamón cocido}} en tiras y disponer sobre cada crepe extendida.","minutes":1,"kind":"prep"},{"text":"Colocar {{Queso en lonchas}} sobre el jamón cubriendo la mitad de la crepe.","minutes":1,"kind":"prep"},{"text":"Doblar cada crepe por la mitad y luego en cuartos para formar un triángulo.","minutes":1,"kind":"prep"},{"text":"Calentar la sartén a fuego suave y dorar las crepes rellenas 2 min por cada lado hasta que el queso se funda.","minutes":4,"kind":"activo"},{"text":"Servir las crepes calientes, 2 por ración, recién sacadas de la sartén.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', 'francesa', NULL),
  ('platos_unicos_007', 'Quiche de verduras', 'platos_unicos', 'huevo', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'all', 412, 14, 28, 28, 2, true, true, '{"gluten","huevo","lactosa"}', '[{"name":"Masa quebrada","amount":200,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Nata","amount":100,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 180 °C con calor arriba y abajo.","Lavar calabacín y cortar en dados pequeños.","Lavar puerro y cortar en rodajas finas.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír el puerro en la sartén a fuego medio hasta que esté tierno, unos 3 min.","Añadir el calabacín a la sartén y saltear a fuego medio hasta que esté dorado, unos 4 min.","Retirar la sartén del fuego y reservar las verduras.","Cascar huevo en un bol y batir con varillas hasta que estén bien integrados.","Añadir nata a los huevos batidos y mezclar hasta obtener una mezcla homogénea.","Añadir queso rallado a la mezcla de huevos y nata y remover hasta integrar.","Incorporar las verduras reservadas a la mezcla y remover para distribuirlas de manera uniforme.","Extender masa quebrada sobre el molde, presionar bien los bordes y pinchar el fondo con un tenedor.","Verter la mezcla de verduras y huevos sobre la masa quebrada en el molde de manera uniforme.","Hornear a 180 °C durante 30 min hasta que el relleno esté cuajado y la superficie dorada.","Retirar del horno, dejar reposar 5 min y servir cortada en porciones."}', 'Quiche de masa quebrada con calabacín, puerro y queso', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Precalienta el horno a 180°C. Hornea la masa quebrada unos minutos en blanco, luego añade el relleno de verduras sofritas con huevo, nata y queso. Hornea durante 45-50 minutos hasta que esté dorado y cuajado."},{"appliance":"airfryer","time":50,"difficulty":"normal","prepSummary":"Utiliza un molde apto para airfryer que quepa bien. Precalienta a 170°C. Cocina la masa quebrada unos 5-7 minutos, luego vierte el relleno y hornea por 30-35 minutos, vigilando que no se dore demasiado rápido por encima."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 180 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Lavar {{Calabacín}} y cortar en dados pequeños.","minutes":3,"kind":"prep"},{"text":"Lavar {{Puerro}} y cortar en rodajas finas.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el puerro en la sartén a fuego medio hasta que esté tierno, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Añadir el calabacín a la sartén y saltear a fuego medio hasta que esté dorado, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Retirar la sartén del fuego y reservar las verduras.","minutes":1,"kind":"prep"},{"text":"Cascar {{Huevo}} en un bol y batir con varillas hasta que estén bien integrados.","minutes":2,"kind":"prep"},{"text":"Añadir {{Nata}} a los huevos batidos y mezclar hasta obtener una mezcla homogénea.","minutes":1,"kind":"prep"},{"text":"Añadir {{Queso rallado}} a la mezcla de huevos y nata y remover hasta integrar.","minutes":1,"kind":"prep"},{"text":"Incorporar las verduras reservadas a la mezcla y remover para distribuirlas de manera uniforme.","minutes":1,"kind":"prep"},{"text":"Extender {{Masa quebrada}} sobre el molde, presionar bien los bordes y pinchar el fondo con un tenedor.","minutes":3,"kind":"prep"},{"text":"Verter la mezcla de verduras y huevos sobre la masa quebrada en el molde de manera uniforme.","minutes":1,"kind":"activo"},{"text":"Hornear a 180 °C durante 30 min hasta que el relleno esté cuajado y la superficie dorada.","minutes":30,"kind":"pasivo"},{"text":"Retirar del horno, dejar reposar 5 min y servir cortada en porciones.","minutes":5,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'horno', 'francesa', NULL),
  ('platos_unicos_008', 'Patatas rellenas de carne', 'platos_unicos', 'ternera', 'patatas', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'all', 462, 24, 38, 24, 2, true, true, '{"lactosa"}', '[{"name":"Patata grande","amount":4,"unit":"ud"},{"name":"Carne picada de ternera","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Queso rallado","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Lavar patata grande y pincharlas por varias partes con un tenedor.","Colocar las patatas en la bandeja del horno y hornear hasta que estén tiernas.","Pelar y picar cebolla en trozos muy finos.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada hasta que esté transparente, unos 5 min a fuego medio.","Añadir carne picada de ternera a la sartén y saltear hasta que pierda el color rosado.","Incorporar tomate triturado a la sartén y cocer a fuego suave hasta que se reduzca, unos 5 min.","Retirar las patatas del horno y dejar templar 2 min hasta que se puedan manipular.","Cortar cada patata por la mitad a lo largo y vaciar la pulpa con una cuchara, dejando 1 cm de borde.","Añadir la pulpa de las patatas a la sartén con la carne y mezclar bien hasta obtener un relleno homogéneo.","Rellenar cada mitad de patata con la mezcla de carne, presionando ligeramente para que quede compacta.","Repartir queso rallado por encima de cada patata rellena.","Hornear las patatas rellenas a 200 °C con gratinador hasta que el queso esté dorado y burbujeante.","Retirar del horno y servir las patatas rellenas inmediatamente."}', 'Patatas asadas rellenas de carne picada gratinadas con queso', '[{"appliance":"horno","time":60,"difficulty":"normal","prepSummary":"Hornea las patatas enteras a 200°C hasta que estén tiernas (aprox. 40-50 min). Vacía la pulpa, mezcla con el sofrito de carne y cebolla, rellena las patatas, cubre con queso y gratina a 180°C durante 15-20 min hasta dorar."},{"appliance":"airfryer","time":50,"difficulty":"normal","prepSummary":"Cocina las patatas en la airfryer a 190°C durante 30-40 min hasta que estén tiernas. Vacía la pulpa, mezcla con el relleno de carne previamente cocinado, rellena las patatas, espolvorea queso y cocina en la airfryer a 180°C por 10-15 min hasta que el queso esté fundido y dorado."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"prep"},{"text":"Lavar {{Patata grande}} y pincharlas por varias partes con un tenedor.","minutes":2,"kind":"prep"},{"text":"Colocar las patatas en la bandeja del horno y hornear hasta que estén tiernas.","minutes":30,"kind":"pasivo"},{"text":"Pelar y picar {{Cebolla}} en trozos muy finos.","minutes":3,"kind":"paralelo","during":2},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"paralelo","during":2},{"text":"Sofreír la cebolla picada hasta que esté transparente, unos 5 min a fuego medio.","minutes":5,"kind":"paralelo","during":2},{"text":"Añadir {{Carne picada de ternera}} a la sartén y saltear hasta que pierda el color rosado.","minutes":4,"kind":"paralelo","during":2},{"text":"Incorporar {{Tomate triturado}} a la sartén y cocer a fuego suave hasta que se reduzca, unos 5 min.","minutes":5,"kind":"paralelo","during":2},{"text":"Retirar las patatas del horno y dejar templar 2 min hasta que se puedan manipular.","minutes":2,"kind":"espera"},{"text":"Cortar cada patata por la mitad a lo largo y vaciar la pulpa con una cuchara, dejando 1 cm de borde.","minutes":4,"kind":"prep"},{"text":"Añadir la pulpa de las patatas a la sartén con la carne y mezclar bien hasta obtener un relleno homogéneo.","minutes":2,"kind":"activo"},{"text":"Rellenar cada mitad de patata con la mezcla de carne, presionando ligeramente para que quede compacta.","minutes":2,"kind":"prep"},{"text":"Repartir {{Queso rallado}} por encima de cada patata rellena.","minutes":1,"kind":"prep"},{"text":"Hornear las patatas rellenas a 200 °C con gratinador hasta que el queso esté dorado y burbujeante.","minutes":8,"kind":"pasivo"},{"text":"Retirar del horno y servir las patatas rellenas inmediatamente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'horno', NULL, NULL)
