insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('platos_unicos_009', 'Wrap de pollo', 'platos_unicos', 'pollo', 'pan', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 382, 28, 32, 16, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Pechuga de pollo","amount":200,"unit":"g"},{"name":"Lechuga","amount":50,"unit":"g"},{"name":"Tomate","amount":80,"unit":"g"},{"name":"Yogur natural","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pechuga de pollo en tiras de grosor uniforme y salpimentar al gusto.","Calentar plancha a fuego fuerte con aceite de oliva.","Dorar las tiras de pechuga en la plancha caliente durante 3 min por cada lado, hasta que estén doradas y cocidas por dentro.","Picar lechuga en tiras finas y cortar tomate en dados pequeños.","Retirar las tiras de pechuga de la plancha y reservar.","Mezclar yogur natural con sal en un bol pequeño hasta obtener una salsa homogénea.","Calentar tortilla de trigo en la plancha a fuego medio 30 segundos por cada lado, hasta que estén flexibles.","Extender la salsa de yogur sobre cada tortilla caliente, dejando un borde libre de 2 cm.","Distribuir la lechuga picada, el tomate en dados y las tiras de pechuga sobre cada tortilla.","Enrollar cada tortilla con firmeza, doblar los laterales hacia dentro y servir al momento."}', 'Tortilla de trigo enrollada con pollo a la plancha y verduras', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Corta la pechuga en tiras, rocía con aceite y cocina en la airfryer a 190°C durante 12-15 minutos, volteando a mitad, hasta que esté dorada y jugosa. Calienta las tortillas brevemente al final para que queden flexibles."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Hornea la pechuga de pollo cortada en tiras a 200°C durante 15-20 minutos, dándole la vuelta para que se dore uniformemente y quede cocida. Puedes calentar las tortillas en el horno durante los últimos minutos para ablandarlas."}]'::jsonb, '{}', NULL, true, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pechuga de pollo}} en tiras de grosor uniforme y salpimentar al gusto.","minutes":2,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"activo"},{"text":"Dorar las tiras de pechuga en la plancha caliente durante 3 min por cada lado, hasta que estén doradas y cocidas por dentro.","minutes":6,"kind":"activo"},{"text":"Picar {{Lechuga}} en tiras finas y cortar {{Tomate}} en dados pequeños.","minutes":2,"kind":"paralelo","during":2},{"text":"Retirar las tiras de pechuga de la plancha y reservar.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Yogur natural}} con {{Sal|gusto}} en un bol pequeño hasta obtener una salsa homogénea.","minutes":1,"kind":"prep"},{"text":"Calentar {{Tortilla de trigo}} en la plancha a fuego medio 30 segundos por cada lado, hasta que estén flexibles.","minutes":1,"kind":"activo"},{"text":"Extender la salsa de yogur sobre cada tortilla caliente, dejando un borde libre de 2 cm.","minutes":1,"kind":"emplatado"},{"text":"Distribuir la lechuga picada, el tomate en dados y las tiras de pechuga sobre cada tortilla.","minutes":1,"kind":"emplatado"},{"text":"Enrollar cada tortilla con firmeza, doblar los laterales hacia dentro y servir al momento.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'crudo', NULL, NULL),
  ('platos_unicos_010', 'Croquetas de bacalao', 'platos_unicos', 'pescado_blanco', NULL, ARRAY['cena','plato_unico']::meal_role[], 'principal', NULL, NULL, 45, 'normal', 'all', 418, 18, 30, 26, 2, true, true, '{"gluten","lactosa","huevo","pescado"}', '[{"name":"Bacalao desalado","amount":120,"unit":"g"},{"name":"Leche","amount":300,"unit":"ml"},{"name":"Harina","amount":50,"unit":"g"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Pan rallado","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Desmigar bacalao desalado con los dedos, retirando espinas y piel, hasta obtener hebras finas. Reservar.","Picar perejil muy fino. Reservar.","Fundir mantequilla en un cazo a fuego medio hasta que esté completamente líquida.","Añadir harina de golpe y remover sin parar con unas varillas a fuego medio hasta que la mezcla se despegue de las paredes.","Incorporar leche poco a poco, sin dejar de remover con las varillas a fuego medio, hasta que la bechamel esté espesa y sin grumos.","Añadir el bacalao desmigado y el perejil picado a la bechamel. Remover a fuego suave durante 2 min hasta que estén integrados.","Salpimentar la masa al gusto y remover para integrar.","Extender la masa en un recipiente plano y tapar con film a piel. Refrigerar hasta que esté completamente firme.","Batir huevo en un bol hondo. Disponer pan rallado en un recipiente plano aparte.","Tomar porciones de masa fría y dar forma alargada con las manos hasta obtener croquetas uniformes.","Pasar cada croqueta por el huevo batido y después por el pan rallado, presionando para que quede bien cubierta. Reservar en un plato.","Calentar aceite de oliva en sartén a fuego fuerte hasta que alcance unos 180 °C.","Freír las croquetas en tandas sin amontonar, girándolas, hasta que estén doradas por todos los lados.","Retirar las croquetas y escurrir sobre papel absorbente.","Servir las croquetas calientes."}', 'Croquetas cremosas de bechamel con bacalao desmigado', '[{"appliance":"airfryer","time":45,"difficulty":"normal","prepSummary":"Una vez formadas y empanadas, las croquetas se cocinan en la airfryer a 195°C durante 12-15 minutos, rociadas ligeramente con aceite, hasta que estén doradas y crujientes, volteándolas a mitad de cocción."},{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Tras formar y empanar las croquetas, se hornean a 200°C durante 18-22 minutos en una bandeja con papel de horno y un poco de aceite, hasta que estén doradas y crujientes, volteándolas a mitad de cocción."},{"appliance":"thermomix","time":40,"difficulty":"normal","prepSummary":"La Thermomix es ideal para cocer el bacalao y elaborar la bechamel de forma rápida y sin grumos. Una vez lista la masa de croquetas, se enfría, se forman y se fríen de la manera tradicional o se cocinan en airfryer/horno para el acabado final."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Desmigar {{Bacalao desalado}} con los dedos, retirando espinas y piel, hasta obtener hebras finas. Reservar.","minutes":5,"kind":"prep"},{"text":"Picar {{Perejil|gusto}} muy fino. Reservar.","minutes":2,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego medio hasta que esté completamente líquida.","minutes":2,"kind":"activo"},{"text":"Añadir {{Harina}} de golpe y remover sin parar con unas varillas a fuego medio hasta que la mezcla se despegue de las paredes.","minutes":2,"kind":"activo"},{"text":"Incorporar {{Leche}} poco a poco, sin dejar de remover con las varillas a fuego medio, hasta que la bechamel esté espesa y sin grumos.","minutes":6,"kind":"activo"},{"text":"Añadir el bacalao desmigado y el perejil picado a la bechamel. Remover a fuego suave durante 2 min hasta que estén integrados.","minutes":2,"kind":"activo"},{"text":"Salpimentar la masa al gusto y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Extender la masa en un recipiente plano y tapar con film a piel. Refrigerar hasta que esté completamente firme.","minutes":30,"kind":"espera"},{"text":"Batir {{Huevo}} en un bol hondo. Disponer {{Pan rallado}} en un recipiente plano aparte.","minutes":2,"kind":"prep"},{"text":"Tomar porciones de masa fría y dar forma alargada con las manos hasta obtener croquetas uniformes.","minutes":4,"kind":"prep"},{"text":"Pasar cada croqueta por el huevo batido y después por el pan rallado, presionando para que quede bien cubierta. Reservar en un plato.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego fuerte hasta que alcance unos 180 °C.","minutes":2,"kind":"activo"},{"text":"Freír las croquetas en tandas sin amontonar, girándolas, hasta que estén doradas por todos los lados.","minutes":4,"kind":"activo"},{"text":"Retirar las croquetas y escurrir sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Servir las croquetas calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL, NULL),
  ('platos_unicos_011', 'Migas manchegas', 'platos_unicos', 'cerdo', 'pan', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 30, 'normal', 'invierno', 498, 16, 42, 28, 2, true, false, '{"gluten"}', '[{"name":"Pan del día anterior","amount":200,"unit":"g"},{"name":"Chorizo","amount":60,"unit":"g"},{"name":"Panceta","amount":60,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Pimentón","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Uvas","amount":60,"unit":"g"}]'::jsonb, '{"Desmigar pan del día anterior en trozos pequeños con las manos.","Humedecer el pan desmigado con un poco de agua fría hasta que esté ligeramente húmedo pero no empapado.","Cortar chorizo en rodajas finas.","Cortar panceta en trozos pequeños.","Laminar ajo.","Lavar uvas y reservar en un bol.","Calentar aceite de oliva en sartén a fuego medio hasta que esté caliente.","Sofreír el ajo laminado a fuego suave hasta que se dore ligeramente.","Añadir la panceta y el chorizo a la sartén y sofreír a fuego medio hasta que estén dorados.","Retirar la sartén del fuego y añadir pimentón, removiendo rápido para que no se queme.","Incorporar el pan desmigado y húmedo a la sartén y mezclar bien con el sofrito.","Remover las migas a fuego medio sin parar hasta que queden sueltas y ligeramente doradas.","Servir las migas en plato hondo acompañadas de las uvas reservadas."}', 'Migas de pan con chorizo, panceta y uvas', '[]'::jsonb, '{}', NULL, NULL, NULL, '{"fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Desmigar {{Pan del día anterior}} en trozos pequeños con las manos.","minutes":3,"kind":"prep"},{"text":"Humedecer el pan desmigado con un poco de agua fría hasta que esté ligeramente húmedo pero no empapado.","minutes":2,"kind":"prep"},{"text":"Cortar {{Chorizo}} en rodajas finas.","minutes":2,"kind":"prep"},{"text":"Cortar {{Panceta}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Laminar {{Ajo}}.","minutes":1,"kind":"prep"},{"text":"Lavar {{Uvas}} y reservar en un bol.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego medio hasta que esté caliente.","minutes":2,"kind":"activo"},{"text":"Sofreír el ajo laminado a fuego suave hasta que se dore ligeramente.","minutes":2,"kind":"activo"},{"text":"Añadir la panceta y el chorizo a la sartén y sofreír a fuego medio hasta que estén dorados.","minutes":4,"kind":"activo"},{"text":"Retirar la sartén del fuego y añadir {{Pimentón|pizca}}, removiendo rápido para que no se queme.","minutes":1,"kind":"activo"},{"text":"Incorporar el pan desmigado y húmedo a la sartén y mezclar bien con el sofrito.","minutes":2,"kind":"activo"},{"text":"Remover las migas a fuego medio sin parar hasta que queden sueltas y ligeramente doradas.","minutes":6,"kind":"activo"},{"text":"Servir las migas en plato hondo acompañadas de las uvas reservadas.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL, NULL),
  ('platos_unicos_012', 'Pimientos rellenos de arroz', 'platos_unicos', 'none', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, 'horno', 45, 'normal', 'all', 368, 10, 48, 14, 2, true, true, '{}', '[{"name":"Pimientos rojos","amount":4,"unit":"ud"},{"name":"Arroz","amount":150,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Champiñones","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C con calor arriba y abajo.","Picar cebolla en trozos finos.","Picar ajo fino.","Laminar champiñones.","Cortar la parte superior de pimientos rojos a modo de tapa y retirar las semillas y venas del interior.","Llevar a ebullición agua con sal en un cazo a fuego fuerte, añadir arroz y cocer 12 min hasta que esté tierno. Escurrir y reservar.","Calentar aceite de oliva en sartén a fuego medio.","Sofreír la cebolla picada en la sartén a fuego medio hasta que esté transparente, unos 4 min.","Añadir el ajo picado y los champiñones laminados a la sartén y saltear a fuego medio hasta que los champiñones suelten su agua y se doren.","Añadir tomate triturado al sofrito y remover a fuego medio durante 2 min hasta que se integre. Retirar del fuego.","Mezclar el arroz escurrido con el sofrito en la sartén hasta obtener un relleno homogéneo.","Disponer los pimientos en una bandeja de horno y rellenar cada uno con la mezcla de arroz, apretando ligeramente.","Hornear los pimientos rellenos en el horno a 190 °C durante 25 min hasta que la piel esté tierna y ligeramente tostada.","Retirar los pimientos del horno y servir inmediatamente."}', 'Pimientos rojos rellenos de arroz con champiñones', '[{"appliance":"horno","time":65,"difficulty":"normal","prepSummary":"Prepara el sofrito con cebolla, ajo, champiñones, arroz y tomate triturado. Rellena los pimientos partidos por la mitad y hornea a 180-190°C durante unos 45-50 minutos, hasta que los pimientos estén tiernos y el relleno ligeramente gratinado."},{"appliance":"airfryer","time":55,"difficulty":"normal","prepSummary":"Prepara el relleno en una sartén. Rellena los pimientos y colócalos en la cesta de la airfryer. Cocina a 170-180°C durante 30-35 minutos, girando a mitad de cocción y añadiendo un poco de agua en la base si es necesario para mantener la humedad y evitar que se sequen."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","seta"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 190 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Picar {{Cebolla}} en trozos finos.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Laminar {{Champiñones}}.","minutes":2,"kind":"prep"},{"text":"Cortar la parte superior de {{Pimientos rojos}} a modo de tapa y retirar las semillas y venas del interior.","minutes":4,"kind":"prep"},{"text":"Llevar a ebullición agua con sal en un cazo a fuego fuerte, añadir {{Arroz}} y cocer 12 min hasta que esté tierno. Escurrir y reservar.","minutes":14,"kind":"pasivo"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada en la sartén a fuego medio hasta que esté transparente, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir el ajo picado y los champiñones laminados a la sartén y saltear a fuego medio hasta que los champiñones suelten su agua y se doren.","minutes":4,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} al sofrito y remover a fuego medio durante 2 min hasta que se integre. Retirar del fuego.","minutes":2,"kind":"activo"},{"text":"Mezclar el arroz escurrido con el sofrito en la sartén hasta obtener un relleno homogéneo.","minutes":1,"kind":"activo"},{"text":"Disponer los pimientos en una bandeja de horno y rellenar cada uno con la mezcla de arroz, apretando ligeramente.","minutes":3,"kind":"prep"},{"text":"Hornear los pimientos rellenos en el horno a 190 °C durante 25 min hasta que la piel esté tierna y ligeramente tostada.","minutes":25,"kind":"pasivo"},{"text":"Retirar los pimientos del horno y servir inmediatamente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'horno', NULL, NULL),
  ('platos_unicos_013', 'Calzone casero', 'platos_unicos', 'none', NULL, ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, 'horno', 40, 'normal', 'all', 492, 20, 56, 22, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Harina","amount":250,"unit":"g"},{"name":"Levadura fresca","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Mozzarella","amount":100,"unit":"g"},{"name":"Jamón cocido","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Desmenuzar levadura fresca en un bol con 150 ml de agua tibia y remover hasta que se disuelva por completo.","Añadir harina al bol y mezclar hasta obtener una masa homogénea.","Incorporar aceite de oliva a la masa y amasar sobre una superficie enharinada hasta que esté lisa y elástica.","Tapar la masa con un paño y dejar reposar hasta que doble su volumen.","Precalentar el horno a 220 °C con calor arriba y abajo.","Cortar jamón cocido en trozos pequeños y reservar.","Cortar mozzarella en láminas finas y reservar.","Estirar la masa sobre una superficie enharinada formando un círculo de unos 30 cm de diámetro.","Extender tomate triturado sobre la mitad del círculo de masa, dejando 2 cm libres en el borde.","Disponer la mozzarella laminada sobre el tomate triturado y repartir el jamón cocido encima.","Doblar la mitad de masa sin relleno sobre la mitad rellena y sellar el borde presionando con un tenedor.","Colocar el calzone en una bandeja de horno ligeramente enharinada y hornear a 220 °C hasta que esté dorado.","Retirar del horno, dejar reposar 2 min y servir el calzone cortado al gusto."}', 'Pizza cerrada rellena de tomate, mozzarella y jamón', '[{"appliance":"horno","time":95,"difficulty":"normal","prepSummary":"Precalienta el horno a 190-200°C. Hornea el calzone durante 35-40 minutos o hasta que esté bien dorado y el queso burbujee."},{"appliance":"airfryer","time":80,"difficulty":"normal","prepSummary":"Precalienta la airfryer a 175-185°C. Cocina el calzone (o calzones pequeños) durante 25-30 minutos, volteándolo a mitad del tiempo para un dorado uniforme."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, ARRAY['cerdo']::main_protein[], true, '[{"text":"Desmenuzar {{Levadura fresca}} en un bol con 150 ml de agua tibia y remover hasta que se disuelva por completo.","minutes":2,"kind":"prep"},{"text":"Añadir {{Harina}} al bol y mezclar hasta obtener una masa homogénea.","minutes":3,"kind":"prep"},{"text":"Incorporar {{Aceite de oliva|chorrito}} a la masa y amasar sobre una superficie enharinada hasta que esté lisa y elástica.","minutes":5,"kind":"activo"},{"text":"Tapar la masa con un paño y dejar reposar hasta que doble su volumen.","minutes":15,"kind":"espera"},{"text":"Precalentar el horno a 220 °C con calor arriba y abajo.","minutes":10,"kind":"paralelo","during":3},{"text":"Cortar {{Jamón cocido}} en trozos pequeños y reservar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Mozzarella}} en láminas finas y reservar.","minutes":2,"kind":"prep"},{"text":"Estirar la masa sobre una superficie enharinada formando un círculo de unos 30 cm de diámetro.","minutes":3,"kind":"activo"},{"text":"Extender {{Tomate triturado}} sobre la mitad del círculo de masa, dejando 2 cm libres en el borde.","minutes":1,"kind":"prep"},{"text":"Disponer la mozzarella laminada sobre el tomate triturado y repartir el jamón cocido encima.","minutes":1,"kind":"prep"},{"text":"Doblar la mitad de masa sin relleno sobre la mitad rellena y sellar el borde presionando con un tenedor.","minutes":2,"kind":"activo"},{"text":"Colocar el calzone en una bandeja de horno ligeramente enharinada y hornear a 220 °C hasta que esté dorado.","minutes":15,"kind":"pasivo"},{"text":"Retirar del horno, dejar reposar 2 min y servir el calzone cortado al gusto.","minutes":2,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'horno', 'italiana', NULL),
  ('platos_unicos_014', 'Tostas de aguacate y huevo', 'platos_unicos', 'huevo', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 342, 14, 28, 20, 2, true, false, '{"gluten","huevo"}', '[{"name":"Pan de hogaza","amount":120,"unit":"g"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Tomate cherry","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar pan de hogaza en 4 rebanadas de grosor medio y reservar.","Cortar tomate cherry por la mitad y reservar.","Partir aguacate por la mitad, retirar el hueso y extraer la pulpa con una cuchara.","Exprimir limón sobre la pulpa del aguacate y aplastar con un tenedor hasta obtener una crema rústica.","Calentar plancha a fuego fuerte y tostar las rebanadas de pan de hogaza 2 min por cada lado hasta que estén doradas.","Verter aceite de oliva en sartén y calentar a fuego medio.","Cascar huevo en la sartén con el aceite caliente y freír 2 min hasta que la clara esté cuajada y la yema tierna.","Extender la crema de aguacate sobre las rebanadas de pan de hogaza tostadas.","Colocar 1 huevo frito sobre cada tosta y distribuir los tomate cherry por encima."}', 'Tostadas de pan con aguacate machacado y huevo', '[{"appliance":"airfryer","time":15,"difficulty":"facil","prepSummary":"Tuesta el pan a 190°C durante 4-5 minutos hasta que esté dorado. Para el huevo, fríelo en un molde apto para airfryer a 160°C durante 8-10 minutos, logrando una yema jugosa."},{"appliance":"horno","time":20,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Tuesta las rebanadas de pan directamente en la rejilla durante 5-7 minutos. Para los huevos, hornéalos en cuencos individuales ligeramente engrasados durante 10-12 minutos hasta que la clara esté cuajada y la yema líquida."}]'::jsonb, '{}', NULL, true, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pan de hogaza}} en 4 rebanadas de grosor medio y reservar.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate cherry}} por la mitad y reservar.","minutes":1,"kind":"prep"},{"text":"Partir {{Aguacate}} por la mitad, retirar el hueso y extraer la pulpa con una cuchara.","minutes":1,"kind":"prep"},{"text":"Exprimir {{Limón}} sobre la pulpa del aguacate y aplastar con un tenedor hasta obtener una crema rústica.","minutes":1,"kind":"prep"},{"text":"Calentar {{@Plancha}} a fuego fuerte y tostar las rebanadas de pan de hogaza 2 min por cada lado hasta que estén doradas.","minutes":4,"kind":"activo"},{"text":"Verter {{Aceite de oliva|chorrito}} en {{@Sartén}} y calentar a fuego medio.","minutes":1,"kind":"activo"},{"text":"Cascar {{Huevo}} en la sartén con el aceite caliente y freír 2 min hasta que la clara esté cuajada y la yema tierna.","minutes":2,"kind":"activo"},{"text":"Extender la crema de aguacate sobre las rebanadas de pan de hogaza tostadas.","minutes":1,"kind":"emplatado"},{"text":"Colocar 1 huevo frito sobre cada tosta y distribuir los tomate cherry por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'crudo', NULL, NULL),
  ('platos_unicos_015', 'Patatas bravas con huevo', 'platos_unicos', 'huevo', 'patatas', ARRAY['cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 448, 14, 42, 26, 2, true, false, '{"huevo"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Tomate triturado","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Pimentón picante","amount":4,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en dados de unos 2 cm.","Laminar ajo.","Calentar aceite de oliva en sartén a fuego fuerte hasta que esté bien caliente.","Freír los dados de patata en el aceite caliente hasta que estén dorados y crujientes por fuera.","Retirar las patatas con una espumadera y escurrir sobre papel absorbente. Reservar.","Sofreír el ajo laminado en el aceite restante de la sartén a fuego suave hasta que se dore ligeramente.","Añadir pimentón picante al sofrito de ajo y remover durante 20 segundos para que no se queme.","Añadir tomate triturado, remover bien y cocer a fuego medio hasta que la salsa espese y reduzca.","Calentar un chorrito de aceite en otra sartén a fuego medio hasta que esté caliente.","Freír huevo de uno en uno en el aceite caliente hasta que la clara cuaje pero la yema quede líquida.","Disponer las patatas en el plato, cubrir con la salsa brava y colocar un huevo frito encima de cada ración. Servir de inmediato."}', 'Patatas fritas en dados con salsa brava y huevo frito', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Para las patatas, córtalas en dados, rocía con aceite y pimentón, y cocínalas en la airfryer a 190°C durante 20-25 minutos, agitándolas a mitad para un dorado uniforme. La salsa y el huevo se preparan aparte en sartén mientras las patatas se cocinan."},{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Asa las patatas cortadas en dados con aceite y pimentón en el horno precalentado a 200°C durante 35-40 minutos, volteándolas para que doren por todos lados. Prepara la salsa brava y el huevo frito en la sartén mientras las patatas se hornean."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en dados de unos 2 cm.","minutes":5,"kind":"prep"},{"text":"Laminar {{Ajo}}.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego fuerte hasta que esté bien caliente.","minutes":2,"kind":"activo"},{"text":"Freír los dados de patata en el aceite caliente hasta que estén dorados y crujientes por fuera.","minutes":12,"kind":"activo"},{"text":"Retirar las patatas con una espumadera y escurrir sobre papel absorbente. Reservar.","minutes":1,"kind":"prep"},{"text":"Sofreír el ajo laminado en el aceite restante de la {{@Sartén}} a fuego suave hasta que se dore ligeramente.","minutes":2,"kind":"activo"},{"text":"Añadir {{Pimentón picante}} al sofrito de ajo y remover durante 20 segundos para que no se queme.","minutes":1,"kind":"activo"},{"text":"Añadir {{Tomate triturado}}, remover bien y cocer a fuego medio hasta que la salsa espese y reduzca.","minutes":5,"kind":"pasivo"},{"text":"Calentar un chorrito de aceite en otra {{@Sartén}} a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Freír {{Huevo}} de uno en uno en el aceite caliente hasta que la clara cuaje pero la yema quede líquida.","minutes":2,"kind":"activo"},{"text":"Disponer las patatas en el plato, cubrir con la salsa brava y colocar un huevo frito encima de cada ración. Servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL, NULL),
  ('platos_unicos_016', 'Bocadillo de tortilla', 'platos_unicos', 'huevo', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 512, 16, 52, 26, 2, true, true, '{"gluten","huevo"}', '[{"name":"Pan de barra","amount":200,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Pelar patata y laminar en rodajas de unos 3 mm de grosor.","Pelar cebolla y cortar en juliana fina.","Calentar aceite de oliva en sartén a fuego suave hasta que esté templado.","Añadir las láminas de patata y la cebolla en juliana; confitar a fuego suave hasta que estén tiernas y sin color.","Cascar huevo en un bol amplio y batir hasta que estén bien integrados.","Escurrir la patata y la cebolla del aceite y reservar el aceite sobrante.","Añadir la patata y la cebolla escurridas al bol con el huevo batido y mezclar bien.","Dejar reposar la mezcla en el bol durante 2 min para que el huevo empape la patata.","Calentar 1 cucharada del aceite reservado en la sartén a fuego medio hasta que esté caliente.","Verter la mezcla de huevo, patata y cebolla en la sartén y extender de forma uniforme.","Cocer a fuego suave hasta que los bordes cuajen pero el centro quede ligeramente jugoso.","Dar la vuelta a la tortilla con la ayuda de un plato y deslizarla de nuevo a la sartén.","Cocer 1 min hasta que el exterior esté cuajado y el interior jugoso.","Retirar la tortilla de la sartén y dejar reposar 2 min antes de cortar.","Cortar pan de barra en 2 porciones iguales y abrir cada una por la mitad a lo largo.","Cortar la tortilla en porciones que encajen en el pan y disponer sobre la base de cada porción.","Tapar con la parte superior del pan, presionar ligeramente y servir de inmediato."}', 'Bocadillo de pan crujiente con tortilla de patata jugosa', '[]'::jsonb, '{}', NULL, true, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y laminar en rodajas de unos 3 mm de grosor.","minutes":3,"kind":"prep"},{"text":"Pelar {{Cebolla}} y cortar en juliana fina.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en {{@Sartén}} a fuego suave hasta que esté templado.","minutes":2,"kind":"activo"},{"text":"Añadir las láminas de patata y la cebolla en juliana; confitar a fuego suave hasta que estén tiernas y sin color.","minutes":12,"kind":"pasivo"},{"text":"Cascar {{Huevo}} en un bol amplio y batir hasta que estén bien integrados.","minutes":2,"kind":"paralelo","during":3},{"text":"Escurrir la patata y la cebolla del aceite y reservar el aceite sobrante.","minutes":1,"kind":"prep"},{"text":"Añadir la patata y la cebolla escurridas al bol con el huevo batido y mezclar bien.","minutes":1,"kind":"prep"},{"text":"Dejar reposar la mezcla en el bol durante 2 min para que el huevo empape la patata.","minutes":2,"kind":"espera"},{"text":"Calentar 1 cucharada del aceite reservado en la {{@Sartén}} a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla de huevo, patata y cebolla en la sartén y extender de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave hasta que los bordes cuajen pero el centro quede ligeramente jugoso.","minutes":3,"kind":"activo"},{"text":"Dar la vuelta a la tortilla con la ayuda de un plato y deslizarla de nuevo a la sartén.","minutes":1,"kind":"activo"},{"text":"Cocer 1 min hasta que el exterior esté cuajado y el interior jugoso.","minutes":1,"kind":"activo"},{"text":"Retirar la tortilla de la sartén y dejar reposar 2 min antes de cortar.","minutes":2,"kind":"espera"},{"text":"Cortar {{Pan de barra}} en 2 porciones iguales y abrir cada una por la mitad a lo largo.","minutes":1,"kind":"prep"},{"text":"Cortar la tortilla en porciones que encajen en el pan y disponer sobre la base de cada porción.","minutes":1,"kind":"emplatado"},{"text":"Tapar con la parte superior del pan, presionar ligeramente y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'crudo', NULL, NULL),
  ('platos_unicos_017', 'Burritos caseros de pollo', 'platos_unicos', 'pollo', 'pan', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 468, 30, 42, 20, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Pechuga de pollo","amount":250,"unit":"g"},{"name":"Pimiento rojo","amount":80,"unit":"g"},{"name":"Arroz cocido","amount":100,"unit":"g"},{"name":"Queso rallado","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pechuga de pollo en tiras de 1 cm de grosor.","Cortar pimiento rojo en tiras del mismo tamaño que el pollo.","Calentar aceite de oliva en sartén a fuego fuerte hasta que humee ligeramente.","Saltear las tiras de pollo en la sartén a fuego fuerte hasta que estén doradas por fuera y cocidas por dentro.","Añadir las tiras de pimiento rojo a la sartén y saltear a fuego fuerte hasta que estén tiernas pero con algo de mordida.","Incorporar arroz cocido a la sartén y mezclar con el pollo y el pimiento.","Saltear todo junto a fuego fuerte hasta que el arroz esté bien integrado y caliente.","Retirar la sartén del fuego y reservar el relleno.","Calentar tortilla de trigo en una sartén limpia y seca a fuego medio 30 segundos por cada cara hasta que estén flexibles.","Disponer cada tortilla en plano y repartir el relleno de pollo, pimiento y arroz en el centro, dejando 3 cm libres en los laterales.","Espolvorear queso rallado sobre el relleno de cada tortilla.","Plegar los extremos laterales de cada tortilla hacia dentro.","Enrollar cada tortilla desde el borde más cercano hasta cerrar el burrito con firmeza.","Colocar los burritos con el cierre hacia abajo en la sartén a fuego medio hasta que el exterior quede sellado y crujiente.","Servir de inmediato."}', 'Burritos de tortilla de trigo con pollo, arroz y queso', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Cocina el pollo troceado y el pimiento a 180°C durante 15-18 min. Luego, rellena las tortillas y calienta los burritos montados en la airfryer a 180°C por 5-7 min para que se doren y el queso se funda."},{"appliance":"horno","time":35,"difficulty":"facil","prepSummary":"Asa el pollo troceado y el pimiento en una bandeja a 200°C por 20-25 min. Rellena las tortillas y hornea los burritos a 180°C durante 10-12 min hasta que el queso se derrita y las tortillas estén ligeramente doradas."},{"appliance":"thermomix","time":25,"difficulty":"normal","prepSummary":"Prepara el sofrito de pimiento y cocina el pollo troceado en el vaso. Añade el arroz cocido para integrarlo y calentarlo, obteniendo un relleno jugoso. Las tortillas se calientan aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pechuga de pollo}} en tiras de 1 cm de grosor.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pimiento rojo}} en tiras del mismo tamaño que el pollo.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en {{@Sartén}} a fuego fuerte hasta que humee ligeramente.","minutes":1,"kind":"activo"},{"text":"Saltear las tiras de pollo en la sartén a fuego fuerte hasta que estén doradas por fuera y cocidas por dentro.","minutes":4,"kind":"activo"},{"text":"Añadir las tiras de pimiento rojo a la sartén y saltear a fuego fuerte hasta que estén tiernas pero con algo de mordida.","minutes":2,"kind":"activo"},{"text":"Incorporar {{Arroz cocido}} a la sartén y mezclar con el pollo y el pimiento.","minutes":1,"kind":"activo"},{"text":"Saltear todo junto a fuego fuerte hasta que el arroz esté bien integrado y caliente.","minutes":1,"kind":"activo"},{"text":"Retirar la sartén del fuego y reservar el relleno.","minutes":1,"kind":"prep"},{"text":"Calentar {{Tortilla de trigo}} en una sartén limpia y seca a fuego medio 30 segundos por cada cara hasta que estén flexibles.","minutes":2,"kind":"activo"},{"text":"Disponer cada tortilla en plano y repartir el relleno de pollo, pimiento y arroz en el centro, dejando 3 cm libres en los laterales.","minutes":1,"kind":"emplatado"},{"text":"Espolvorear {{Queso rallado}} sobre el relleno de cada tortilla.","minutes":1,"kind":"emplatado"},{"text":"Plegar los extremos laterales de cada tortilla hacia dentro.","minutes":1,"kind":"emplatado"},{"text":"Enrollar cada tortilla desde el borde más cercano hasta cerrar el burrito con firmeza.","minutes":1,"kind":"emplatado"},{"text":"Colocar los burritos con el cierre hacia abajo en la sartén a fuego medio hasta que el exterior quede sellado y crujiente.","minutes":1,"kind":"activo"},{"text":"Servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', 'mexicana', NULL),
  ('platos_unicos_018', 'Paella de marisco', 'platos_unicos', 'marisco', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', NULL, NULL, 50, 'normal', 'all', 482, 26, 56, 16, 2, false, false, '{"marisco","moluscos","pescado"}', '[{"name":"Arroz","amount":200,"unit":"g"},{"name":"Gambas","amount":150,"unit":"g"},{"name":"Mejillones","amount":150,"unit":"g"},{"name":"Sepia","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Azafrán","amount":1,"unit":"g"}]'::jsonb, '{"Picar ajo fino y reservar.","Cortar sepia en trozos pequeños y reservar.","Calentar aceite de oliva en una paella a fuego medio hasta que esté caliente.","Sofreír el ajo picado en el aceite caliente durante 1 min, hasta que esté dorado pero sin quemarse.","Añadir la sepia troceada y saltear a fuego medio hasta que pierda el agua y empiece a dorarse.","Incorporar tomate triturado y sofreír a fuego medio hasta que se evapore el líquido y el sofrito se oscurezca.","Disolver azafrán en 500 ml de agua caliente en un cazo y llevar a ebullición.","Verter el caldo con azafrán sobre el sofrito y cocer a fuego fuerte hasta que rompa a hervir.","Añadir arroz, repartir de forma uniforme por la paella y no remover más.","Cocer el arroz a fuego fuerte los primeros 5 min, luego reducir a fuego medio hasta que absorba casi todo el caldo.","Colocar gambas y mejillones sobre el arroz, distribuyéndolos de forma uniforme.","Cocer a fuego medio hasta que los mejillones se abran y las gambas estén rosadas.","Subir el fuego a fuerte durante los últimos 30 segundos hasta que el fondo suene seco y se forme el socarrat.","Retirar la paella del fuego y dejar reposar 2 min antes de servir.","Servir directamente desde la paella."}', 'Paella de arroz con gambas, mejillones y sepia', '[{"appliance":"horno","time":50,"difficulty":"normal","prepSummary":"Prepara el sofrito y saltea el marisco en una paellera apta para horno en la encimera. Añade el arroz y el caldo caliente, luego hornea a 200°C durante 20-25 minutos para una cocción uniforme y un socarrat perfecto."}]'::jsonb, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Ajo}} fino y reservar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Sepia}} en trozos pequeños y reservar.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una paella a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado en el aceite caliente durante 1 min, hasta que esté dorado pero sin quemarse.","minutes":1,"kind":"activo"},{"text":"Añadir la sepia troceada y saltear a fuego medio hasta que pierda el agua y empiece a dorarse.","minutes":4,"kind":"activo"},{"text":"Incorporar {{Tomate triturado}} y sofreír a fuego medio hasta que se evapore el líquido y el sofrito se oscurezca.","minutes":4,"kind":"activo"},{"text":"Disolver {{Azafrán|pizca}} en 500 ml de agua caliente en un cazo y llevar a ebullición.","minutes":3,"kind":"paralelo","during":5},{"text":"Verter el caldo con azafrán sobre el sofrito y cocer a fuego fuerte hasta que rompa a hervir.","minutes":2,"kind":"activo"},{"text":"Añadir {{Arroz}}, repartir de forma uniforme por la paella y no remover más.","minutes":1,"kind":"activo"},{"text":"Cocer el arroz a fuego fuerte los primeros 5 min, luego reducir a fuego medio hasta que absorba casi todo el caldo.","minutes":12,"kind":"pasivo"},{"text":"Colocar {{Gambas}} y {{Mejillones}} sobre el arroz, distribuyéndolos de forma uniforme.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio hasta que los mejillones se abran y las gambas estén rosadas.","minutes":6,"kind":"pasivo"},{"text":"Subir el fuego a fuerte durante los últimos 30 segundos hasta que el fondo suene seco y se forme el socarrat.","minutes":1,"kind":"activo"},{"text":"Retirar la paella del fuego y dejar reposar 2 min antes de servir.","minutes":2,"kind":"espera"},{"text":"Servir directamente desde la paella.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL)
