insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('platos_unicos_019', 'Quesadillas caseras', 'platos_unicos', 'none', 'pan', ARRAY['cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 388, 16, 34, 22, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Tortilla de trigo","amount":2,"unit":"ud"},{"name":"Queso rallado","amount":100,"unit":"g"},{"name":"Jamón cocido","amount":60,"unit":"g"},{"name":"Pimiento rojo","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Cortar pimiento rojo en tiras finas y reservar.","Cortar jamón cocido en trozos pequeños y reservar.","Calentar sartén a fuego medio con aceite de oliva.","Colocar tortilla de trigo en la sartén caliente.","Repartir queso rallado sobre toda la superficie de la tortilla.","Distribuir el jamón cocido y el pimiento rojo sobre la mitad de la tortilla.","Doblar la tortilla por la mitad, cubriendo el relleno con la mitad vacía.","Cocinar a fuego medio hasta que se dore por la parte inferior, unos 2 min.","Dar la vuelta con cuidado y cocinar hasta que se dore el otro lado, unos 2 min.","Retirar de la sartén y dejar reposar 1 min sobre una tabla.","Cortar en 3 triángulos y servir inmediatamente."}', 'Tortilla de trigo doblada con queso fundido, jamón y pimiento', '[{"appliance":"airfryer","time":12,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina la quesadilla montada durante 10-12 minutos, dándole la vuelta a mitad de cocción, hasta que el queso se derrita y la tortilla esté dorada y crujiente."},{"appliance":"horno","time":15,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C. Hornea la quesadilla montada sobre papel de horno durante 10-12 minutos, hasta que el queso esté fundido y la tortilla ligeramente dorada y crujiente."}]'::jsonb, '{}', NULL, true, NULL, '{"lacteo"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Cortar {{Pimiento rojo}} en tiras finas y reservar.","minutes":3,"kind":"prep"},{"text":"Cortar {{Jamón cocido}} en trozos pequeños y reservar.","minutes":2,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego medio con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"activo"},{"text":"Colocar {{Tortilla de trigo}} en la sartén caliente.","minutes":1,"kind":"activo"},{"text":"Repartir {{Queso rallado}} sobre toda la superficie de la tortilla.","minutes":1,"kind":"activo"},{"text":"Distribuir el jamón cocido y el pimiento rojo sobre la mitad de la tortilla.","minutes":1,"kind":"activo"},{"text":"Doblar la tortilla por la mitad, cubriendo el relleno con la mitad vacía.","minutes":1,"kind":"activo"},{"text":"Cocinar a fuego medio hasta que se dore por la parte inferior, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Dar la vuelta con cuidado y cocinar hasta que se dore el otro lado, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Retirar de la sartén y dejar reposar 1 min sobre una tabla.","minutes":1,"kind":"espera"},{"text":"Cortar en 3 triángulos y servir inmediatamente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'crudo', 'mexicana', NULL),
  ('platos_unicos_020', 'Huevos a la riojana', 'platos_unicos', 'huevo', 'patatas', ARRAY['plato_unico','cena']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 378, 16, 18, 26, 2, true, false, '{"huevo"}', '[{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Patata","amount":300,"unit":"g"},{"name":"Pimiento choricero","amount":2,"unit":"ud"},{"name":"Tomate triturado","amount":150,"unit":"ml"},{"name":"Chorizo","amount":50,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"}]'::jsonb, '{"Pelar y cortar patata en dados de 1 cm aproximadamente.","Pelar y picar cebolla en brunoise fina.","Picar ajo fino.","Cortar chorizo en rodajas de 0,5 cm.","Abrir pimiento choricero, raspar la pulpa con una cuchara y reservarla.","Calentar aceite de oliva en una sartén honda a fuego medio hasta que esté caliente.","Sofreír la cebolla picada en el aceite caliente a fuego suave hasta que esté transparente, unos 4 min.","Añadir el ajo picado y el chorizo en rodajas; sofreír a fuego medio hasta que el chorizo suelte su grasa, unos 2 min.","Añadir la patata en dados a la sartén y saltear a fuego medio hasta que empiece a dorarse por fuera, unos 5 min.","Incorporar la pulpa del pimiento choricero y tomate triturado; remover para mezclar bien.","Tapar la sartén y cocer a fuego suave hasta que la patata esté tierna y la salsa haya reducido, unos 10 min.","Hacer 4 huecos en la salsa con una cuchara y cascar huevo en cada uno con cuidado.","Tapar la sartén y cocer a fuego suave hasta que la clara esté cuajada y la yema quede cremosa, unos 5 min.","Servir directamente de la sartén, bien caliente."}', 'Huevos escalfados en salsa de tomate con chorizo, pimiento y patata en dados', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"Sofríe la cebolla, ajo y chorizo en una cazuela apta para horno. Incorpora el pimiento choricero y el tomate, cocina unos minutos. Haz huecos, casca los huevos y hornea a 180°C durante 10-15 minutos hasta que las claras estén cuajadas."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Pelar y cortar {{Patata}} en dados de 1 cm aproximadamente.","minutes":5,"kind":"prep"},{"text":"Pelar y picar {{Cebolla}} en brunoise fina.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Cortar {{Chorizo}} en rodajas de 0,5 cm.","minutes":1,"kind":"prep"},{"text":"Abrir {{Pimiento choricero}}, raspar la pulpa con una cuchara y reservarla.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una sartén honda a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada en el aceite caliente a fuego suave hasta que esté transparente, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir el ajo picado y el chorizo en rodajas; sofreír a fuego medio hasta que el chorizo suelte su grasa, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Añadir la patata en dados a la {{@Sartén}} y saltear a fuego medio hasta que empiece a dorarse por fuera, unos 5 min.","minutes":5,"kind":"activo"},{"text":"Incorporar la pulpa del pimiento choricero y {{Tomate triturado}}; remover para mezclar bien.","minutes":1,"kind":"activo"},{"text":"Tapar la sartén y cocer a fuego suave hasta que la patata esté tierna y la salsa haya reducido, unos 10 min.","minutes":10,"kind":"pasivo"},{"text":"Hacer 4 huecos en la salsa con una cuchara y cascar {{Huevo}} en cada uno con cuidado.","minutes":1,"kind":"activo"},{"text":"Tapar la sartén y cocer a fuego suave hasta que la clara esté cuajada y la yema quede cremosa, unos 5 min.","minutes":5,"kind":"pasivo"},{"text":"Servir directamente de la sartén, bien caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'sarten', NULL, NULL),
  ('postres_001', 'Macedonia de fruta fresca', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 10, 'facil', 'all', 140, 2, 33, 1, 4, true, true, '{}', '[{"name":"Manzana","amount":1,"unit":"ud"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Naranja","amount":2,"unit":"ud"},{"name":"Fresas","amount":150,"unit":"g"},{"name":"Zumo de limón","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar manzana y cortar en dados de 1 cm.","Pelar plátano y cortar en rodajas de 1 cm.","Pelar 1 naranja, separar en gajos y cortar cada gajo en 2 o 3 trozos.","Limpiar fresas, retirar el rabillo y cortar en cuartos.","Exprimir la naranja restante y mezclar su zumo con zumo de limón en un bol pequeño.","Reunir la manzana, el plátano, la naranja troceada y las fresas en un bol grande.","Verter la mezcla de zumos sobre la fruta y remover con suavidad hasta que toda la fruta quede impregnada.","Tapar el bol y refrigerar hasta que esté bien fría, al menos 15 min.","Servir la macedonia repartida en 4 cuencos fríos."}', 'Macedonia fresca de manzana, plátano, naranja y fresas con un toque de cítrico', NULL, '{}', NULL, NULL, NULL, '{"fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Manzana}} y cortar en dados de 1 cm.","minutes":2,"kind":"prep"},{"text":"Pelar {{Plátano}} y cortar en rodajas de 1 cm.","minutes":1,"kind":"prep"},{"text":"Pelar 1 {{Naranja}}, separar en gajos y cortar cada gajo en 2 o 3 trozos.","minutes":2,"kind":"prep"},{"text":"Limpiar {{Fresas}}, retirar el rabillo y cortar en cuartos.","minutes":1,"kind":"prep"},{"text":"Exprimir la naranja restante y mezclar su zumo con {{Zumo de limón}} en un bol pequeño.","minutes":1,"kind":"prep"},{"text":"Reunir la manzana, el plátano, la naranja troceada y las fresas en un bol grande.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla de zumos sobre la fruta y remover con suavidad hasta que toda la fruta quede impregnada.","minutes":1,"kind":"activo"},{"text":"Tapar el bol y refrigerar hasta que esté bien fría, al menos 15 min.","minutes":15,"kind":"espera"},{"text":"Servir la macedonia repartida en 4 cuencos fríos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, NULL),
  ('postres_002', 'Yogur con miel y nueces', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 4, 'facil', 'all', 280, 11, 28, 14, 2, false, false, '{"lactosa","frutos_secos"}', '[{"name":"Yogur natural","amount":250,"unit":"g"},{"name":"Miel","amount":20,"unit":"ml"},{"name":"Nueces","amount":40,"unit":"g"}]'::jsonb, '{"Cortar nueces en trozos gruesos con un cuchillo.","Repartir yogur natural en 2 cuencos individuales a partes iguales.","Distribuir las nueces troceadas sobre el yogur de cada cuenco.","Verter miel en hilo fino sobre cada cuenco y servir de inmediato."}', 'Yogur natural con nueces troceadas y miel, un postre sencillo y saciante', NULL, '{}', NULL, NULL, NULL, '{"lacteo","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Nueces}} en trozos gruesos con un cuchillo.","minutes":1,"kind":"prep"},{"text":"Repartir {{Yogur natural}} en 2 cuencos individuales a partes iguales.","minutes":1,"kind":"emplatado"},{"text":"Distribuir las nueces troceadas sobre el yogur de cada cuenco.","minutes":1,"kind":"emplatado"},{"text":"Verter {{Miel|chorrito}} en hilo fino sobre cada cuenco y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, NULL),
  ('postres_003', 'Fruta de temporada', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 3, 'facil', 'all', 90, 1, 22, 0, 2, true, true, '{}', '[{"name":"Manzana","amount":1,"unit":"ud"},{"name":"Naranja","amount":1,"unit":"ud"}]'::jsonb, '{"Lavar manzana bajo el grifo con agua fría hasta que esté limpia.","Lavar naranja bajo el grifo con agua fría hasta que esté limpia.","Pelar la naranja y separar los gajos; cortar la manzana en láminas o trozos al gusto.","Servir la fruta en un plato o bol."}', 'Pieza de fruta de temporada como postre ligero. El planner elige naranja, fresa, melocotón o uva según el mes.', NULL, '{}', NULL, NULL, NULL, '{"fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Manzana}} bajo el grifo con agua fría hasta que esté limpia.","minutes":1,"kind":"prep"},{"text":"Lavar {{Naranja}} bajo el grifo con agua fría hasta que esté limpia.","kind":"paralelo","during":0},{"text":"Pelar la naranja y separar los gajos; cortar la manzana en láminas o trozos al gusto.","minutes":2,"kind":"prep"},{"text":"Servir la fruta en un plato o bol.","kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, NULL),
  ('postres_007', 'Manzana asada', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'invierno', 160, 1, 38, 1, 4, true, true, '{}', '[{"name":"Manzana","amount":4,"unit":"ud"},{"name":"Azúcar","amount":40,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Lavar manzana bajo el grifo y secar bien con un paño.","Descorazonar cada manzana con un descorazonador o cuchillo, sin llegar al fondo, para crear un hueco central.","Exprimir limón y reservar el zumo en un bol pequeño.","Precalentar el horno a 180 °C con calor arriba y abajo.","Colocar las manzanas en pie sobre una fuente de horno, dejando espacio entre ellas.","Repartir azúcar en partes iguales dentro del hueco de cada manzana.","Verter unas gotas del zumo de limón sobre cada manzana para aromatizar y evitar la oxidación.","Hornear la fuente en el centro del horno a 180 °C durante 35 min, hasta que las manzanas estén tiernas al pincharlas con una brocheta.","Retirar la fuente del horno y dejar reposar las manzanas 5 min antes de servir.","Servir cada manzana en un plato individual, regando con el jugo caramelizado que haya quedado en la fuente."}', 'Manzanas asadas al horno con azúcar y limón', '[{"appliance":"horno","time":40,"difficulty":"facil","prepSummary":"Precalienta el horno a 180°C. Descorazona las manzanas, colócalas en una fuente con un poco de azúcar y unas gotas de limón, y hornea unos 35-40 minutos hasta que estén tiernas."}]'::jsonb, '{}', NULL, NULL, NULL, '{"fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Manzana}} bajo el grifo y secar bien con un paño.","minutes":2,"kind":"prep"},{"text":"Descorazonar cada manzana con un descorazonador o cuchillo, sin llegar al fondo, para crear un hueco central.","minutes":5,"kind":"prep"},{"text":"Exprimir {{Limón}} y reservar el zumo en un bol pequeño.","minutes":2,"kind":"prep"},{"text":"Precalentar el horno a 180 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Colocar las manzanas en pie sobre una fuente de horno, dejando espacio entre ellas.","minutes":1,"kind":"prep"},{"text":"Repartir {{Azúcar}} en partes iguales dentro del hueco de cada manzana.","minutes":2,"kind":"prep"},{"text":"Verter unas gotas del zumo de limón sobre cada manzana para aromatizar y evitar la oxidación.","minutes":1,"kind":"prep"},{"text":"Hornear la fuente en el centro del horno a 180 °C durante 35 min, hasta que las manzanas estén tiernas al pincharlas con una brocheta.","minutes":35,"kind":"pasivo"},{"text":"Retirar la fuente del horno y dejar reposar las manzanas 5 min antes de servir.","minutes":5,"kind":"espera"},{"text":"Servir cada manzana en un plato individual, regando con el jugo caramelizado que haya quedado en la fuente.","minutes":2,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('postres_008', 'Yogur natural', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 2, 'facil', 'all', 65, 5, 6, 3, 2, true, true, '{"lactosa"}', '[{"name":"Yogur natural","amount":250,"unit":"g"}]'::jsonb, '{"Reparte el yogur en dos cuencos","Sirve frío"}', 'Yogur natural sin nada más, el postre de siempre', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, NULL, true, NULL, NULL, 'sarten', NULL, NULL),
  ('postres_009', 'Yogur con fruta', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 5, 'facil', 'all', 150, 6, 24, 3, 2, true, true, '{"lactosa"}', '[{"name":"Yogur natural","amount":250,"unit":"g"},{"name":"Plátano","amount":1,"unit":"ud"},{"name":"Fresas","amount":100,"unit":"g"}]'::jsonb, '{"Pelar plátano y cortar en rodajas de 1 cm.","Lavar fresas, retirar el pedúnculo y cortar en cuartos.","Repartir yogur natural en 2 cuencos individuales a partes iguales.","Distribuir las rodajas de plátano y las fresas en cuartos sobre el yogur de cada cuenco."}', 'Yogur natural con plátano y fresas troceadas', NULL, '{}', NULL, NULL, NULL, '{"lacteo","fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Plátano}} y cortar en rodajas de 1 cm.","minutes":1,"kind":"prep"},{"text":"Lavar {{Fresas}}, retirar el pedúnculo y cortar en cuartos.","minutes":1,"kind":"prep"},{"text":"Repartir {{Yogur natural}} en 2 cuencos individuales a partes iguales.","minutes":1,"kind":"activo"},{"text":"Distribuir las rodajas de plátano y las fresas en cuartos sobre el yogur de cada cuenco.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, NULL),
  ('postres_013', 'Yogur de sabores', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 1, 'facil', 'all', 110, 4, 16, 3, 2, true, true, '{"lactosa"}', '[{"name":"Yogur de sabores","amount":250,"unit":"g"}]'::jsonb, '{"Abre los yogures","Sirve fríos"}', 'Yogur procesado de frutas de nevera (frambuesa/fresa), el postre más rápido', NULL, '{"Yogur de fresa","Yogur de frutas"}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, NULL, true, NULL, NULL, 'sarten', NULL, NULL),
  ('postres_014', 'Compota de manzana', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'invierno', 130, 1, 32, 0, 4, true, true, '{}', '[{"name":"Manzana","amount":4,"unit":"ud"},{"name":"Azúcar","amount":40,"unit":"g"},{"name":"Canela","amount":2,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"}]'::jsonb, '{"Pelar manzana y cortar en trozos de tamaño similar.","Exprimir limón y reservar el zumo.","Poner los trozos de manzana en un cazo con azúcar, canela y el zumo de limón.","Añadir 2 cucharadas de agua y remover para mezclar todos los ingredientes.","Tapar el cazo y cocer a fuego suave hasta que la manzana esté tierna, unos 20 min.","Retirar del fuego y triturar o dejar en trozos según la textura deseada.","Servir la compota tibia o dejar enfriar antes de llevar a la mesa."}', 'Compota de manzana casera con canela, de cazo', NULL, '{}', NULL, NULL, NULL, '{"fruta"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Manzana}} y cortar en trozos de tamaño similar.","minutes":5,"kind":"prep"},{"text":"Exprimir {{Limón}} y reservar el zumo.","minutes":1,"kind":"prep"},{"text":"Poner los trozos de manzana en un cazo con {{Azúcar}}, {{Canela|pizca}} y el zumo de limón.","minutes":2,"kind":"activo"},{"text":"Añadir 2 cucharadas de agua y remover para mezclar todos los ingredientes.","minutes":1,"kind":"activo"},{"text":"Tapar el cazo y cocer a fuego suave hasta que la manzana esté tierna, unos 20 min.","minutes":20,"kind":"pasivo"},{"text":"Retirar del fuego y triturar o dejar en trozos según la textura deseada.","minutes":1,"kind":"activo"},{"text":"Servir la compota tibia o dejar enfriar antes de llevar a la mesa.","kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, NULL)
