insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('postres_019', 'Tarta de queso vasca', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 65, 'normal', 'all', 580, 9, 29, 46, 8, true, true, '{"lactosa","huevo","gluten"}', '[{"name":"Queso crema","amount":600,"unit":"g"},{"name":"Nata para montar","amount":400,"unit":"ml"},{"name":"Azúcar","amount":220,"unit":"g"},{"name":"Huevo","amount":5,"unit":"ud"},{"name":"Harina","amount":25,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 220 °C con calor arriba y abajo.","Forrar un molde desmontable de 22 cm con papel de horno, dejando que sobresalga por los bordes.","Batir queso crema con azúcar y sal hasta obtener una crema lisa sin grumos.","Añadir huevo de uno en uno, batiendo bien después de cada uno.","Incorporar nata para montar poco a poco sin dejar de batir hasta integrarla por completo.","Tamizar harina sobre la mezcla y batir a velocidad baja solo hasta que desaparezca.","Verter la mezcla en el molde forrado.","Hornear 50 min, hasta que la superficie esté muy oscura y el centro tiemble ligeramente al mover el molde.","Dejar enfriar dentro del molde a temperatura ambiente hasta que se atempere por completo.","Refrigerar un mínimo de 3 h antes de desmoldar y cortar en porciones.","Desmoldar, cortar en porciones y servir fría."}', 'Tarta de queso cremosa y quemada por fuera al estilo vasco, sin base de galleta.', NULL, '{}', true, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 220 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Forrar un molde desmontable de 22 cm con papel de horno, dejando que sobresalga por los bordes.","minutes":3,"kind":"prep"},{"text":"Batir {{Queso crema}} con {{Azúcar}} y {{Sal}} hasta obtener una crema lisa sin grumos.","minutes":3,"kind":"activo"},{"text":"Añadir {{Huevo}} de uno en uno, batiendo bien después de cada uno.","minutes":4,"kind":"activo"},{"text":"Incorporar {{Nata para montar}} poco a poco sin dejar de batir hasta integrarla por completo.","minutes":3,"kind":"activo"},{"text":"Tamizar {{Harina}} sobre la mezcla y batir a velocidad baja solo hasta que desaparezca.","minutes":2,"kind":"activo"},{"text":"Verter la mezcla en el molde forrado.","minutes":1,"kind":"activo"},{"text":"Hornear 50 min, hasta que la superficie esté muy oscura y el centro tiemble ligeramente al mover el molde.","minutes":50,"kind":"pasivo"},{"text":"Dejar enfriar dentro del molde a temperatura ambiente hasta que se atempere por completo.","minutes":60,"kind":"espera"},{"text":"Refrigerar un mínimo de 3 h antes de desmoldar y cortar en porciones.","minutes":180,"kind":"espera"},{"text":"Desmoldar, cortar en porciones y servir fría.","minutes":2,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('postres_020', 'Tarta Tatin de manzana caramelizada', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 70, 'elaborada', 'all', 480, 3, 65, 23, 6, true, true, '{"gluten","lactosa"}', '[{"name":"Manzana reineta","amount":1000,"unit":"g"},{"name":"Mantequilla","amount":100,"unit":"g"},{"name":"Azúcar","amount":150,"unit":"g"},{"name":"Hojaldre","amount":230,"unit":"g"},{"name":"Canela en polvo","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C con calor arriba y abajo.","Pelar manzana reineta, descorazonarlas y cortarlas por la mitad.","Fundir mantequilla en una sartén apta para horno de 24 cm a fuego medio.","Añadir azúcar a la sartén sin remover hasta que se forme un caramelo dorado.","Retirar la sartén del fuego.","Colocar las mitades de manzana bien apretadas sobre el caramelo, con la parte redondeada hacia abajo.","Espolvorear canela en polvo de manera uniforme sobre las manzanas.","Volver a poner la sartén a fuego medio-suave hasta que las manzanas empiecen a ablandarse por la base.","Extender hojaldre sobre la sartén cubriendo las manzanas completamente.","Remeter los bordes del hojaldre hacia dentro con una cuchara para sellar.","Pinchar el hojaldre por toda la superficie con un tenedor.","Hornear a 190 °C hasta que el hojaldre esté dorado y crujiente.","Retirar la sartén del horno y dejar templar fuera del fuego.","Colocar un plato grande boca abajo sobre la sartén.","Volcar la sartén con cuidado usando guantes para desmoldar la tarta con las manzanas arriba.","Servir templada, cortada en porciones."}', 'Tarta de manzana caramelizada que se vuelca al servir, con el caramelo brillante quedando por encima.', NULL, '{}', true, NULL, NULL, '{"fruta"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 190 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Manzana reineta}}, descorazonarlas y cortarlas por la mitad.","minutes":10,"kind":"paralelo","during":0},{"text":"Fundir {{Mantequilla}} en una sartén apta para horno de 24 cm a fuego medio.","minutes":2,"kind":"activo"},{"text":"Añadir {{Azúcar}} a la sartén sin remover hasta que se forme un caramelo dorado.","minutes":8,"kind":"activo"},{"text":"Retirar la sartén del fuego.","minutes":1,"kind":"activo"},{"text":"Colocar las mitades de manzana bien apretadas sobre el caramelo, con la parte redondeada hacia abajo.","minutes":3,"kind":"activo"},{"text":"Espolvorear {{Canela en polvo|pizca}} de manera uniforme sobre las manzanas.","minutes":1,"kind":"activo"},{"text":"Volver a poner la sartén a fuego medio-suave hasta que las manzanas empiecen a ablandarse por la base.","minutes":9,"kind":"pasivo"},{"text":"Extender {{Hojaldre}} sobre la sartén cubriendo las manzanas completamente.","minutes":2,"kind":"activo"},{"text":"Remeter los bordes del hojaldre hacia dentro con una cuchara para sellar.","minutes":1,"kind":"activo"},{"text":"Pinchar el hojaldre por toda la superficie con un tenedor.","minutes":1,"kind":"activo"},{"text":"Hornear a 190 °C hasta que el hojaldre esté dorado y crujiente.","minutes":27,"kind":"pasivo"},{"text":"Retirar la sartén del horno y dejar templar fuera del fuego.","minutes":5,"kind":"espera"},{"text":"Colocar un plato grande boca abajo sobre la sartén.","minutes":1,"kind":"emplatado"},{"text":"Volcar la sartén con cuidado usando guantes para desmoldar la tarta con las manzanas arriba.","minutes":1,"kind":"emplatado"},{"text":"Servir templada, cortada en porciones.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('postres_021', 'Brownie de chocolate con nueces', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 45, 'facil', 'all', 500, 6, 48, 31, 8, true, true, '{"gluten","lactosa","huevo","frutos_secos"}', '[{"name":"Chocolate negro","amount":200,"unit":"g"},{"name":"Mantequilla","amount":150,"unit":"g"},{"name":"Azúcar","amount":200,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Harina","amount":100,"unit":"g"},{"name":"Nueces","amount":80,"unit":"g"},{"name":"Cacao en polvo","amount":20,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Forrar un molde rectangular de 20x20 cm con papel de horno.","Trocear chocolate negro en trozos pequeños.","Fundir el chocolate troceado con mantequilla al baño maría, removiendo hasta que la mezcla esté lisa.","Retirar del calor y dejar templar la mezcla de chocolate y mantequilla.","Trocear nueces en trozos gruesos y reservar.","Batir huevo con azúcar en un bol hasta que la mezcla blanquee ligeramente.","Añadir la mezcla de chocolate templada al bol con los huevos y remover hasta integrar.","Tamizar harina, cacao en polvo y sal sobre la mezcla.","Remover con espátula hasta que no queden restos de harina, sin trabajar la masa en exceso.","Añadir las nueces troceadas y mezclar suavemente para repartirlas por toda la masa.","Verter la masa en el molde forrado y extender de manera uniforme con la espátula.","Hornear a 180 °C durante 23 min, hasta que la superficie esté cuarteada y el centro siga húmedo.","Dejar enfriar el brownie por completo dentro del molde antes de desmoldar.","Cortar el brownie en 8 cuadrados iguales y servir."}', 'Brownie denso y húmedo con corteza crujiente y trozos de nuez.', NULL, '{}', NULL, NULL, NULL, '{"frutos_secos"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Forrar un molde rectangular de 20x20 cm con papel de horno.","minutes":2,"kind":"prep"},{"text":"Trocear {{Chocolate negro}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Fundir el chocolate troceado con {{Mantequilla}} al baño maría, removiendo hasta que la mezcla esté lisa.","minutes":5,"kind":"activo"},{"text":"Retirar del calor y dejar templar la mezcla de chocolate y mantequilla.","minutes":5,"kind":"espera"},{"text":"Trocear {{Nueces}} en trozos gruesos y reservar.","minutes":2,"kind":"prep"},{"text":"Batir {{Huevo}} con {{Azúcar}} en un bol hasta que la mezcla blanquee ligeramente.","minutes":3,"kind":"activo"},{"text":"Añadir la mezcla de chocolate templada al bol con los huevos y remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Tamizar {{Harina}}, {{Cacao en polvo}} y {{Sal|gusto}} sobre la mezcla.","minutes":1,"kind":"prep"},{"text":"Remover con espátula hasta que no queden restos de harina, sin trabajar la masa en exceso.","minutes":1,"kind":"activo"},{"text":"Añadir las nueces troceadas y mezclar suavemente para repartirlas por toda la masa.","minutes":1,"kind":"activo"},{"text":"Verter la masa en el molde forrado y extender de manera uniforme con la espátula.","minutes":1,"kind":"activo"},{"text":"Hornear a 180 °C durante 23 min, hasta que la superficie esté cuarteada y el centro siga húmedo.","minutes":23,"kind":"pasivo"},{"text":"Dejar enfriar el brownie por completo dentro del molde antes de desmoldar.","minutes":30,"kind":"espera"},{"text":"Cortar el brownie en 8 cuadrados iguales y servir.","minutes":2,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('postres_022', 'Tarta de limón con merengue', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 90, 'elaborada', 'all', 460, 6, 70, 17, 8, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Harina","amount":200,"unit":"g"},{"name":"Mantequilla","amount":140,"unit":"g"},{"name":"Azúcar","amount":360,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Agua fría","amount":30,"unit":"ml"},{"name":"Zumo de limón","amount":150,"unit":"ml"},{"name":"Ralladura de limón","amount":10,"unit":"g"},{"name":"Maicena","amount":40,"unit":"g"},{"name":"Agua","amount":250,"unit":"ml"},{"name":"Yema de huevo","amount":4,"unit":"ud"},{"name":"Clara de huevo","amount":4,"unit":"ud"}]'::jsonb, '{"Cortar mantequilla fría en dados pequeños.","Mezclar harina con los dados de mantequilla fría con las yemas de los dedos hasta obtener una textura arenosa.","Añadir huevo y agua fría a la mezcla arenosa.","Amasar lo justo hasta formar una bola homogénea, sin trabajar en exceso la masa.","Envolver la bola en film transparente y refrigerar hasta que esté firme.","Precalentar el horno a 180 °C.","Estirar la masa sobre una superficie enharinada hasta formar un disco de unos 28 cm de diámetro.","Forrar un molde de 24 cm con la masa estirada, presionando bien los bordes.","Pinchar la base con un tenedor por toda la superficie para evitar que suba al hornear.","Cubrir la masa con papel de horno y peso (legumbres o bolas de cerámica) y hornear a 180 °C.","Retirar el peso y el papel, y hornear a 180 °C hasta que la base esté dorada.","Retirar la base del horno y dejar enfriar completamente sobre una rejilla.","Disolver maicena en agua dentro de un cazo, removiendo hasta que no queden grumos.","Añadir zumo de limón, ralladura de limón y 180 g de azúcar al cazo.","Calentar a fuego medio, removiendo sin parar, hasta que la mezcla espese y se despegue del fondo.","Retirar el cazo del fuego.","Añadir yema de huevo una a una, removiendo con rapidez tras cada incorporación.","Volver a calentar a fuego suave, removiendo, hasta que la crema esté bien ligada y brillante.","Retirar del fuego y añadir 40 g de mantequilla, removiendo hasta que se funda por completo.","Verter el relleno de limón caliente sobre la base horneada y alisar la superficie con una espátula.","Dejar enfriar el relleno a temperatura ambiente hasta que esté templado.","Montar clara de huevo con unas varillas a punto de nieve firme.","Añadir los 180 g de azúcar restantes poco a poco, sin dejar de batir, hasta lograr un merengue brillante y firme.","Cubrir el relleno de limón con el merengue, distribuyéndolo por toda la superficie.","Formar picos en el merengue con ayuda de una espátula o el dorso de una cuchara.","Tostar el merengue con un soplete de cocina o bajo el grill del horno hasta que se dore ligeramente, vigilando que no se queme.","Refrigerar la tarta hasta que esté bien fría y el relleno firme antes de cortar.","Servir en porciones, cortando con un cuchillo limpio y pasado por agua caliente entre corte y corte."}', 'Tarta de limón ácida bajo un merengue tostado con soplete, dulce y cítrica a la vez.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Mantequilla}} fría en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Mezclar {{Harina}} con los dados de mantequilla fría con las yemas de los dedos hasta obtener una textura arenosa.","minutes":4,"kind":"activo"},{"text":"Añadir {{Huevo}} y {{Agua fría}} a la mezcla arenosa.","minutes":1,"kind":"activo"},{"text":"Amasar lo justo hasta formar una bola homogénea, sin trabajar en exceso la masa.","minutes":2,"kind":"activo"},{"text":"Envolver la bola en film transparente y refrigerar hasta que esté firme.","minutes":30,"kind":"espera"},{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Estirar la masa sobre una superficie enharinada hasta formar un disco de unos 28 cm de diámetro.","minutes":3,"kind":"paralelo","during":5},{"text":"Forrar un molde de 24 cm con la masa estirada, presionando bien los bordes.","minutes":2,"kind":"paralelo","during":5},{"text":"Pinchar la base con un tenedor por toda la superficie para evitar que suba al hornear.","minutes":1,"kind":"paralelo","during":5},{"text":"Cubrir la masa con papel de horno y peso (legumbres o bolas de cerámica) y hornear a 180 °C.","minutes":15,"kind":"pasivo"},{"text":"Retirar el peso y el papel, y hornear a 180 °C hasta que la base esté dorada.","minutes":9,"kind":"pasivo"},{"text":"Retirar la base del horno y dejar enfriar completamente sobre una rejilla.","minutes":20,"kind":"espera"},{"text":"Disolver {{Maicena}} en {{Agua}} dentro de un cazo, removiendo hasta que no queden grumos.","minutes":2,"kind":"activo"},{"text":"Añadir {{Zumo de limón}}, {{Ralladura de limón}} y 180 g de {{Azúcar}} al cazo.","minutes":1,"kind":"activo"},{"text":"Calentar a fuego medio, removiendo sin parar, hasta que la mezcla espese y se despegue del fondo.","minutes":6,"kind":"activo"},{"text":"Retirar el cazo del fuego.","minutes":1,"kind":"activo"},{"text":"Añadir {{Yema de huevo}} una a una, removiendo con rapidez tras cada incorporación.","minutes":2,"kind":"activo"},{"text":"Volver a calentar a fuego suave, removiendo, hasta que la crema esté bien ligada y brillante.","minutes":2,"kind":"activo"},{"text":"Retirar del fuego y añadir 40 g de mantequilla, removiendo hasta que se funda por completo.","minutes":1,"kind":"activo"},{"text":"Verter el relleno de limón caliente sobre la base horneada y alisar la superficie con una espátula.","minutes":2,"kind":"activo"},{"text":"Dejar enfriar el relleno a temperatura ambiente hasta que esté templado.","minutes":30,"kind":"espera"},{"text":"Montar {{Clara de huevo}} con unas varillas a punto de nieve firme.","minutes":3,"kind":"activo"},{"text":"Añadir los 180 g de azúcar restantes poco a poco, sin dejar de batir, hasta lograr un merengue brillante y firme.","minutes":4,"kind":"activo"},{"text":"Cubrir el relleno de limón con el merengue, distribuyéndolo por toda la superficie.","minutes":2,"kind":"activo"},{"text":"Formar picos en el merengue con ayuda de una espátula o el dorso de una cuchara.","minutes":1,"kind":"activo"},{"text":"Tostar el merengue con un soplete de cocina o bajo el grill del horno hasta que se dore ligeramente, vigilando que no se queme.","minutes":2,"kind":"activo"},{"text":"Refrigerar la tarta hasta que esté bien fría y el relleno firme antes de cortar.","minutes":120,"kind":"espera"},{"text":"Servir en porciones, cortando con un cuchillo limpio y pasado por agua caliente entre corte y corte.","minutes":3,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('postres_023', 'Tiramisú clásico', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 35, 'normal', 'all', 610, 11, 47, 42, 6, false, true, '{"gluten","huevo","lactosa"}', '[{"name":"Bizcochos de soletilla","amount":200,"unit":"g"},{"name":"Café espresso","amount":300,"unit":"ml"},{"name":"Mascarpone","amount":500,"unit":"g"},{"name":"Yema de huevo","amount":4,"unit":"ud"},{"name":"Clara de huevo","amount":4,"unit":"ud"},{"name":"Azúcar","amount":100,"unit":"g"},{"name":"Cacao en polvo","amount":15,"unit":"g"},{"name":"Licor de café","amount":30,"unit":"ml"}]'::jsonb, '{"Preparar café espresso y dejar enfriar a temperatura ambiente.","Verter el café frío en un plato hondo y añadir licor de café. Mezclar y reservar.","Batir yema de huevo con la mitad de azúcar en un bol hasta que blanqueen y doblen su volumen.","Añadir mascarpone a las yemas y mezclar con suavidad hasta obtener una crema homogénea. Reservar.","Montar clara de huevo en un bol limpio a velocidad media hasta que empiecen a espumar.","Añadir el resto del azúcar poco a poco y seguir batiendo hasta lograr picos firmes.","Incorporar las claras montadas a la crema de mascarpone en 3 tandas, con movimientos envolventes.","Mojar bizcochos de soletilla en la mezcla de café, 1 segundo por cada lado, sin empaparlos.","Colocar una capa de bizcochos en el fondo de una fuente, cubriendo toda la base.","Extender la mitad de la crema de mascarpone sobre los bizcochos y alisar la superficie.","Mojar el resto de los bizcochos de soletilla en el café y formar una segunda capa sobre la crema.","Cubrir con el resto de la crema de mascarpone y alisar bien la superficie.","Tapar la fuente con film transparente y refrigerar un mínimo de 4 h, mejor toda la noche.","Espolvorear cacao en polvo por toda la superficie justo antes de servir."}', 'Tiramisú clásico en capas de café y mascarpone, con cacao espolvoreado por encima.', NULL, '{}', true, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Preparar {{Café espresso}} y dejar enfriar a temperatura ambiente.","minutes":10,"kind":"espera"},{"text":"Verter el café frío en un plato hondo y añadir {{Licor de café}}. Mezclar y reservar.","minutes":1,"kind":"prep"},{"text":"Batir {{Yema de huevo}} con la mitad de {{Azúcar}} en un bol hasta que blanqueen y doblen su volumen.","minutes":5,"kind":"activo"},{"text":"Añadir {{Mascarpone}} a las yemas y mezclar con suavidad hasta obtener una crema homogénea. Reservar.","minutes":2,"kind":"activo"},{"text":"Montar {{Clara de huevo}} en un bol limpio a velocidad media hasta que empiecen a espumar.","minutes":2,"kind":"activo"},{"text":"Añadir el resto del azúcar poco a poco y seguir batiendo hasta lograr picos firmes.","minutes":3,"kind":"activo"},{"text":"Incorporar las claras montadas a la crema de mascarpone en 3 tandas, con movimientos envolventes.","minutes":2,"kind":"activo"},{"text":"Mojar {{Bizcochos de soletilla}} en la mezcla de café, 1 segundo por cada lado, sin empaparlos.","minutes":2,"kind":"activo"},{"text":"Colocar una capa de bizcochos en el fondo de una fuente, cubriendo toda la base.","minutes":1,"kind":"activo"},{"text":"Extender la mitad de la crema de mascarpone sobre los bizcochos y alisar la superficie.","minutes":1,"kind":"activo"},{"text":"Mojar el resto de los bizcochos de soletilla en el café y formar una segunda capa sobre la crema.","minutes":2,"kind":"activo"},{"text":"Cubrir con el resto de la crema de mascarpone y alisar bien la superficie.","minutes":1,"kind":"activo"},{"text":"Tapar la fuente con film transparente y refrigerar un mínimo de 4 h, mejor toda la noche.","minutes":480,"kind":"espera"},{"text":"Espolvorear {{Cacao en polvo}} por toda la superficie justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('postres_024', 'Mousse de chocolate', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 340, 9, 20, 24, 4, true, true, '{"huevo"}', '[{"name":"Chocolate negro","amount":200,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Trocear chocolate negro en piezas pequeñas y colocarlas en un bol apto para microondas.","Fundir el chocolate en el microondas en tandas de 30 s, removiendo entre cada tanda, hasta que esté liso.","Dejar templar el chocolate fundido hasta que esté tibio al tacto.","Separar huevo: yemas en un bol grande y claras en otro bol grande y limpio.","Añadir las yemas al chocolate templado de una en una, removiendo bien tras cada adición.","Montar las claras con sal con unas varillas a velocidad alta hasta que estén a punto de nieve firme.","Añadir un tercio de las claras montadas al chocolate y remover con energía hasta integrar.","Incorporar el resto de las claras montadas con movimientos envolventes hasta que no queden restos blancos.","Repartir la mousse en 4 copas o vasitos individuales.","Refrigerar las copas al menos 120 min, hasta que la mousse esté cuajada y firme."}', 'Mousse de chocolate aireada y sedosa, hecha solo con chocolate y huevo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['huevo']::main_protein[], false, '[{"text":"Trocear {{Chocolate negro}} en piezas pequeñas y colocarlas en un bol apto para microondas.","minutes":2,"kind":"prep"},{"text":"Fundir el chocolate en el microondas en tandas de 30 s, removiendo entre cada tanda, hasta que esté liso.","minutes":3,"kind":"activo"},{"text":"Dejar templar el chocolate fundido hasta que esté tibio al tacto.","minutes":5,"kind":"espera"},{"text":"Separar {{Huevo}}: yemas en un bol grande y claras en otro bol grande y limpio.","minutes":2,"kind":"prep"},{"text":"Añadir las yemas al chocolate templado de una en una, removiendo bien tras cada adición.","minutes":2,"kind":"activo"},{"text":"Montar las claras con {{Sal|pizca}} con unas varillas a velocidad alta hasta que estén a punto de nieve firme.","minutes":4,"kind":"activo"},{"text":"Añadir un tercio de las claras montadas al chocolate y remover con energía hasta integrar.","minutes":1,"kind":"activo"},{"text":"Incorporar el resto de las claras montadas con movimientos envolventes hasta que no queden restos blancos.","minutes":2,"kind":"activo"},{"text":"Repartir la mousse en 4 copas o vasitos individuales.","minutes":2,"kind":"emplatado"},{"text":"Refrigerar las copas al menos 120 min, hasta que la mousse esté cuajada y firme.","minutes":120,"kind":"espera"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, NULL),
  ('postres_025', 'Crumble de manzana y canela', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 55, 'facil', 'all', 470, 4, 68, 21, 6, true, true, '{"gluten","lactosa"}', '[{"name":"Manzana","amount":800,"unit":"g"},{"name":"Azúcar","amount":60,"unit":"g"},{"name":"Canela en polvo","amount":5,"unit":"g"},{"name":"Mantequilla","amount":150,"unit":"g"},{"name":"Harina","amount":150,"unit":"g"},{"name":"Azúcar moreno","amount":100,"unit":"g"},{"name":"Copos de avena","amount":50,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 190 °C con calor arriba y abajo.","Pelar manzana y descorazonarlas.","Cortar las manzanas peladas en dados de 2 cm.","Cortar mantequilla fría en dados pequeños y reservar en frío.","Mezclar los dados de manzana con azúcar y la mitad de canela en polvo en una fuente de horno.","Repartir la mezcla de manzana en la base de la fuente formando una capa uniforme.","Mezclar harina, azúcar moreno, copos de avena, el resto de la canela en polvo y sal en un bol.","Añadir los dados de mantequilla fría al bol y desmigar con las yemas de los dedos hasta obtener migas gruesas.","Repartir las migas sobre la manzana cubriendo toda la superficie sin apretar.","Hornear a 190 °C durante 38 min, hasta que la manzana burbujee por los bordes y las migas estén doradas.","Retirar del horno y dejar templar 10 min antes de servir.","Servir el crumble templado directamente de la fuente."}', 'Crumble de manzana blanda bajo una capa de migas doradas y crujientes con canela.', NULL, '{}', NULL, NULL, NULL, '{"lacteo","fruta"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 190 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Manzana}} y descorazonarlas.","minutes":5,"kind":"prep"},{"text":"Cortar las manzanas peladas en dados de 2 cm.","minutes":3,"kind":"prep"},{"text":"Cortar {{Mantequilla}} fría en dados pequeños y reservar en frío.","minutes":2,"kind":"prep"},{"text":"Mezclar los dados de manzana con {{Azúcar}} y la mitad de {{Canela en polvo}} en una fuente de horno.","minutes":2,"kind":"activo"},{"text":"Repartir la mezcla de manzana en la base de la fuente formando una capa uniforme.","minutes":1,"kind":"activo"},{"text":"Mezclar {{Harina}}, {{Azúcar moreno}}, {{Copos de avena}}, el resto de la canela en polvo y {{Sal|gusto}} en un bol.","minutes":2,"kind":"prep"},{"text":"Añadir los dados de mantequilla fría al bol y desmigar con las yemas de los dedos hasta obtener migas gruesas.","minutes":4,"kind":"activo"},{"text":"Repartir las migas sobre la manzana cubriendo toda la superficie sin apretar.","minutes":2,"kind":"activo"},{"text":"Hornear a 190 °C durante 38 min, hasta que la manzana burbujee por los bordes y las migas estén doradas.","minutes":38,"kind":"pasivo"},{"text":"Retirar del horno y dejar templar 10 min antes de servir.","minutes":10,"kind":"espera"},{"text":"Servir el crumble templado directamente de la fuente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('postres_026', 'Profiteroles con chocolate caliente', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 90, 'elaborada', 'all', 740, 10, 40, 58, 6, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Agua","amount":250,"unit":"ml"},{"name":"Mantequilla","amount":100,"unit":"g"},{"name":"Harina","amount":150,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Nata para montar","amount":500,"unit":"ml"},{"name":"Azúcar","amount":30,"unit":"g"},{"name":"Chocolate negro","amount":200,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C con calor arriba y abajo.","Forrar dos bandejas de horno con papel de horno.","Calentar agua, mantequilla y sal en un cazo a fuego medio hasta que rompa a hervir.","Retirar el cazo del fuego y añadir harina de golpe.","Remover con fuerza hasta que la masa forme una bola y se despegue de las paredes del cazo.","Volver a poner el cazo a fuego suave y remover 2 min hasta que la masa quede ligeramente seca.","Pasar la masa a un bol y dejar templar.","Añadir huevo de uno en uno a la masa, batiendo bien tras cada uno hasta que quede lisa y brillante.","Introducir la masa en una manga pastelera con boquilla redonda.","Formar bolitas de unos 3 cm sobre las bandejas, separadas entre sí al menos 3 cm.","Hornear 28 min sin abrir el horno, hasta que los profiteroles estén dorados e inflados.","Retirar las bandejas del horno y dejar enfriar los profiteroles sobre una rejilla.","Verter nata para montar en un bol frío, reservando 100 ml aparte para la salsa de chocolate.","Añadir azúcar a los 400 ml de nata y montar con varillas a velocidad alta hasta que esté firme.","Introducir la nata montada en una manga pastelera con boquilla fina.","Rellenar cada profiterol inyectando nata montada por la base hasta notar que se hincha ligeramente.","Trocear chocolate negro y colocarlo en un bol resistente al calor sobre un cazo con agua caliente.","Calentar el cazo a fuego suave y añadir los 100 ml de nata reservados al chocolate.","Remover sin parar hasta que el chocolate y la nata formen una salsa lisa y brillante.","Apilar los profiteroles rellenos en platos o fuente y bañar con la salsa de chocolate caliente."}', 'Bolitas de pasta choux rellenas de nata, bañadas en chocolate caliente al momento.', NULL, '{}', true, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":10,"kind":"pasivo"},{"text":"Forrar dos bandejas de horno con papel de horno.","minutes":2,"kind":"prep"},{"text":"Calentar {{Agua}}, {{Mantequilla}} y {{Sal}} en un cazo a fuego medio hasta que rompa a hervir.","minutes":5,"kind":"activo"},{"text":"Retirar el cazo del fuego y añadir {{Harina}} de golpe.","minutes":1,"kind":"activo"},{"text":"Remover con fuerza hasta que la masa forme una bola y se despegue de las paredes del cazo.","minutes":2,"kind":"activo"},{"text":"Volver a poner el cazo a fuego suave y remover 2 min hasta que la masa quede ligeramente seca.","minutes":2,"kind":"activo"},{"text":"Pasar la masa a un bol y dejar templar.","minutes":5,"kind":"espera"},{"text":"Añadir {{Huevo}} de uno en uno a la masa, batiendo bien tras cada uno hasta que quede lisa y brillante.","minutes":5,"kind":"activo"},{"text":"Introducir la masa en una manga pastelera con boquilla redonda.","minutes":2,"kind":"prep"},{"text":"Formar bolitas de unos 3 cm sobre las bandejas, separadas entre sí al menos 3 cm.","minutes":5,"kind":"prep"},{"text":"Hornear 28 min sin abrir el horno, hasta que los profiteroles estén dorados e inflados.","minutes":28,"kind":"pasivo"},{"text":"Retirar las bandejas del horno y dejar enfriar los profiteroles sobre una rejilla.","minutes":20,"kind":"espera"},{"text":"Verter {{Nata para montar}} en un bol frío, reservando 100 ml aparte para la salsa de chocolate.","minutes":1,"kind":"prep"},{"text":"Añadir {{Azúcar}} a los 400 ml de nata y montar con varillas a velocidad alta hasta que esté firme.","minutes":4,"kind":"activo"},{"text":"Introducir la nata montada en una manga pastelera con boquilla fina.","minutes":1,"kind":"prep"},{"text":"Rellenar cada profiterol inyectando nata montada por la base hasta notar que se hincha ligeramente.","minutes":8,"kind":"activo"},{"text":"Trocear {{Chocolate negro}} y colocarlo en un bol resistente al calor sobre un cazo con agua caliente.","minutes":2,"kind":"prep"},{"text":"Calentar el cazo a fuego suave y añadir los 100 ml de nata reservados al chocolate.","minutes":1,"kind":"activo"},{"text":"Remover sin parar hasta que el chocolate y la nata formen una salsa lisa y brillante.","minutes":5,"kind":"activo"},{"text":"Apilar los profiteroles rellenos en platos o fuente y bañar con la salsa de chocolate caliente.","minutes":3,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('postres_027', 'Cookies rellenas de chocolate fundente', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 40, 'normal', 'all', 590, 7, 70, 30, 6, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Harina","amount":250,"unit":"g"},{"name":"Mantequilla","amount":150,"unit":"g"},{"name":"Azúcar moreno","amount":120,"unit":"g"},{"name":"Azúcar","amount":60,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Chocolate negro","amount":150,"unit":"g"},{"name":"Bicarbonato","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Extracto de vainilla","amount":5,"unit":"ml"}]'::jsonb, '{"Templar mantequilla hasta que esté en pomada (blanda pero sin fundir).","Batir la mantequilla en pomada con azúcar moreno y azúcar hasta obtener una crema pálida y esponjosa.","Añadir huevo y extracto de vainilla a la crema y batir hasta que estén completamente integrados.","Mezclar harina, bicarbonato y sal en un bol aparte hasta que estén bien combinados.","Añadir la mezcla de harina a la crema de mantequilla y remover lo justo hasta que se forme una masa homogénea.","Tapar la masa con film y refrigerar hasta que esté firme y manejable.","Precalentar el horno a 180 °C y forrar una bandeja con papel de horno.","Cortar chocolate negro en 12 trozos iguales para usar como relleno.","Dividir la masa fría en 12 porciones del mismo tamaño.","Aplanar cada porción en la palma de la mano hasta formar un disco.","Colocar un trozo de chocolate negro en el centro de cada disco.","Cerrar la masa alrededor del chocolate, sellando bien los bordes para que no se escape al hornear.","Disponer las bolas en la bandeja separadas al menos 5 cm entre sí.","Hornear a 180 °C hasta que los bordes estén dorados y el centro siga pálido.","Reposar las cookies en la bandeja fuera del horno para que se asienten sin romperse.","Servir templadas para que el chocolate del interior esté fundido."}', 'Cookies con el centro relleno de chocolate fundente que se derrama al partirlas.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Templar {{Mantequilla}} hasta que esté en pomada (blanda pero sin fundir).","minutes":5,"kind":"prep"},{"text":"Batir la mantequilla en pomada con {{Azúcar moreno}} y {{Azúcar}} hasta obtener una crema pálida y esponjosa.","minutes":3,"kind":"activo"},{"text":"Añadir {{Huevo}} y {{Extracto de vainilla}} a la crema y batir hasta que estén completamente integrados.","minutes":2,"kind":"activo"},{"text":"Mezclar {{Harina}}, {{Bicarbonato}} y {{Sal|gusto}} en un bol aparte hasta que estén bien combinados.","minutes":1,"kind":"prep"},{"text":"Añadir la mezcla de harina a la crema de mantequilla y remover lo justo hasta que se forme una masa homogénea.","minutes":2,"kind":"activo"},{"text":"Tapar la masa con film y refrigerar hasta que esté firme y manejable.","minutes":30,"kind":"espera"},{"text":"Precalentar el horno a 180 °C y forrar una bandeja con papel de horno.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Chocolate negro}} en 12 trozos iguales para usar como relleno.","minutes":2,"kind":"paralelo","during":6},{"text":"Dividir la masa fría en 12 porciones del mismo tamaño.","minutes":2,"kind":"prep"},{"text":"Aplanar cada porción en la palma de la mano hasta formar un disco.","minutes":2,"kind":"prep"},{"text":"Colocar un trozo de chocolate negro en el centro de cada disco.","minutes":1,"kind":"prep"},{"text":"Cerrar la masa alrededor del chocolate, sellando bien los bordes para que no se escape al hornear.","minutes":3,"kind":"prep"},{"text":"Disponer las bolas en la bandeja separadas al menos 5 cm entre sí.","minutes":1,"kind":"prep"},{"text":"Hornear a 180 °C hasta que los bordes estén dorados y el centro siga pálido.","minutes":11,"kind":"pasivo"},{"text":"Reposar las cookies en la bandeja fuera del horno para que se asienten sin romperse.","minutes":5,"kind":"espera"},{"text":"Servir templadas para que el chocolate del interior esté fundido.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('postres_028', 'Red velvet con glaseado de queso crema', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 80, 'elaborada', 'all', 720, 8, 96, 32, 8, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Harina","amount":280,"unit":"g"},{"name":"Cacao en polvo","amount":15,"unit":"g"},{"name":"Bicarbonato","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Mantequilla","amount":200,"unit":"g"},{"name":"Azúcar","amount":300,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Suero de leche","amount":240,"unit":"ml"},{"name":"Colorante rojo alimentario","amount":10,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Extracto de vainilla","amount":5,"unit":"ml"},{"name":"Queso crema","amount":250,"unit":"g"},{"name":"Azúcar glas","amount":250,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 175 °C.","Engrasar dos moldes redondos de 18 cm y forrar la base con papel de horno.","Tamizar harina, cacao en polvo, bicarbonato y sal juntos en un bol grande.","Mezclar en un bol pequeño suero de leche, colorante rojo alimentario, vinagre y extracto de vainilla.","Batir mantequilla con azúcar en un bol grande a velocidad alta hasta obtener una mezcla pálida y esponjosa.","Añadir huevo de uno en uno, batiendo bien tras cada incorporación hasta que quede integrado.","Añadir un tercio de la mezcla de harina a la masa y mezclar a velocidad baja hasta que se integre.","Añadir la mitad de la mezcla de suero de leche y mezclar a velocidad baja hasta que se integre.","Repetir alternando: un tercio de harina, el resto del suero de leche y, por último, el tercer tercio de harina.","Repartir la masa a partes iguales entre los dos moldes preparados y alisar la superficie con una espátula.","Hornear los dos moldes a 175 °C durante 30 min, hasta que al pinchar el centro con un palillo salga limpio.","Sacar los moldes del horno y dejar reposar los bizcochos dentro 10 min.","Batir queso crema con la mantequilla restante en un bol hasta obtener una mezcla lisa y sin grumos.","Añadir azúcar glas tamizado en 2 tandas, batiendo a velocidad baja hasta lograr un glaseado liso y cremoso.","Desmoldar los bizcochos sobre una rejilla y dejar enfriar por completo.","Colocar un bizcocho sobre el plato de servir y extender una capa generosa de glaseado sobre la superficie.","Colocar el segundo bizcocho encima y cubrir toda la tarta con el resto del glaseado.","Refrigerar la tarta 30 min hasta que el glaseado asiente antes de cortar y servir."}', 'Bizcocho rojo intenso de cacao con un cremoso glaseado blanco de queso.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 175 °C.","minutes":10,"kind":"pasivo"},{"text":"Engrasar dos moldes redondos de 18 cm y forrar la base con papel de horno.","minutes":3,"kind":"prep"},{"text":"Tamizar {{Harina}}, {{Cacao en polvo}}, {{Bicarbonato}} y {{Sal}} juntos en un bol grande.","minutes":3,"kind":"prep"},{"text":"Mezclar en un bol pequeño {{Suero de leche}}, {{Colorante rojo alimentario}}, {{Vinagre}} y {{Extracto de vainilla}}.","minutes":2,"kind":"prep"},{"text":"Batir {{Mantequilla}} con {{Azúcar}} en un bol grande a velocidad alta hasta obtener una mezcla pálida y esponjosa.","minutes":4,"kind":"activo"},{"text":"Añadir {{Huevo}} de uno en uno, batiendo bien tras cada incorporación hasta que quede integrado.","minutes":2,"kind":"activo"},{"text":"Añadir un tercio de la mezcla de harina a la masa y mezclar a velocidad baja hasta que se integre.","minutes":1,"kind":"activo"},{"text":"Añadir la mitad de la mezcla de suero de leche y mezclar a velocidad baja hasta que se integre.","minutes":1,"kind":"activo"},{"text":"Repetir alternando: un tercio de harina, el resto del suero de leche y, por último, el tercer tercio de harina.","minutes":2,"kind":"activo"},{"text":"Repartir la masa a partes iguales entre los dos moldes preparados y alisar la superficie con una espátula.","minutes":2,"kind":"activo"},{"text":"Hornear los dos moldes a 175 °C durante 30 min, hasta que al pinchar el centro con un palillo salga limpio.","minutes":30,"kind":"pasivo"},{"text":"Sacar los moldes del horno y dejar reposar los bizcochos dentro 10 min.","minutes":10,"kind":"espera"},{"text":"Batir {{Queso crema}} con la mantequilla restante en un bol hasta obtener una mezcla lisa y sin grumos.","minutes":2,"kind":"activo"},{"text":"Añadir {{Azúcar glas}} tamizado en 2 tandas, batiendo a velocidad baja hasta lograr un glaseado liso y cremoso.","minutes":3,"kind":"activo"},{"text":"Desmoldar los bizcochos sobre una rejilla y dejar enfriar por completo.","minutes":30,"kind":"espera"},{"text":"Colocar un bizcocho sobre el plato de servir y extender una capa generosa de glaseado sobre la superficie.","minutes":2,"kind":"emplatado"},{"text":"Colocar el segundo bizcocho encima y cubrir toda la tarta con el resto del glaseado.","minutes":3,"kind":"emplatado"},{"text":"Refrigerar la tarta 30 min hasta que el glaseado asiente antes de cortar y servir.","minutes":30,"kind":"espera"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL)
