insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('postres_029', 'Tarta de zanahoria con glaseado de queso', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 75, 'normal', 'all', 560, 7, 62, 30, 8, true, true, '{"gluten","lactosa","huevo","frutos_secos"}', '[{"name":"Zanahoria","amount":300,"unit":"g"},{"name":"Harina","amount":280,"unit":"g"},{"name":"Azúcar moreno","amount":200,"unit":"g"},{"name":"Aceite de girasol","amount":150,"unit":"ml"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Canela en polvo","amount":5,"unit":"g"},{"name":"Nuez moscada","amount":2,"unit":"g"},{"name":"Bicarbonato","amount":6,"unit":"g"},{"name":"Levadura química","amount":6,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Nueces","amount":60,"unit":"g"},{"name":"Queso crema","amount":180,"unit":"g"},{"name":"Mantequilla","amount":50,"unit":"g"},{"name":"Azúcar glas","amount":180,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 175 °C.","Rallar zanahoria con un rallador fino y reservar.","Picar nueces en trozos pequeños y reservar.","Engrasar un molde redondo de 22 cm y forrar la base con papel de horno.","Mezclar harina, bicarbonato, levadura química, canela en polvo, nuez moscada y sal en un bol hasta integrar.","Batir huevo con azúcar moreno en un bol grande hasta que la mezcla blanquee y doble su volumen.","Añadir aceite de girasol en hilo fino sin dejar de batir hasta que quede integrado.","Incorporar la mezcla de harina en 3 tandas con movimientos envolventes hasta que no queden restos de harina.","Añadir la zanahoria rallada y las nueces picadas y mezclar con espátula hasta distribuirlas de forma homogénea.","Verter la masa en el molde preparado y alisar la superficie con una espátula.","Hornear a 175 °C durante 50 min, hasta que al pinchar el centro con un palillo salga limpio.","Retirar el molde del horno y dejar enfriar sobre una rejilla hasta que esté a temperatura ambiente.","Sacar queso crema y mantequilla de la nevera 20 min antes para que estén a temperatura ambiente.","Batir el queso crema con la mantequilla a velocidad media hasta obtener una crema lisa y sin grumos.","Añadir azúcar glas tamizado poco a poco sin dejar de batir hasta lograr un glaseado liso y firme.","Desmoldar la tarta fría con cuidado sobre una rejilla o plato de servir.","Cubrir la superficie y los laterales de la tarta con el glaseado, extendiéndolo con una espátula."}', 'Bizcocho húmedo y especiado de zanahoria cubierto con un glaseado cremoso de queso.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 175 °C.","minutes":10,"kind":"pasivo"},{"text":"Rallar {{Zanahoria}} con un rallador fino y reservar.","minutes":5,"kind":"prep"},{"text":"Picar {{Nueces}} en trozos pequeños y reservar.","minutes":2,"kind":"prep"},{"text":"Engrasar un molde redondo de 22 cm y forrar la base con papel de horno.","minutes":2,"kind":"prep"},{"text":"Mezclar {{Harina}}, {{Bicarbonato}}, {{Levadura química}}, {{Canela en polvo}}, {{Nuez moscada|pizca}} y {{Sal|gusto}} en un bol hasta integrar.","minutes":2,"kind":"prep"},{"text":"Batir {{Huevo}} con {{Azúcar moreno}} en un bol grande hasta que la mezcla blanquee y doble su volumen.","minutes":4,"kind":"activo"},{"text":"Añadir {{Aceite de girasol}} en hilo fino sin dejar de batir hasta que quede integrado.","minutes":2,"kind":"activo"},{"text":"Incorporar la mezcla de harina en 3 tandas con movimientos envolventes hasta que no queden restos de harina.","minutes":3,"kind":"activo"},{"text":"Añadir la zanahoria rallada y las nueces picadas y mezclar con espátula hasta distribuirlas de forma homogénea.","minutes":2,"kind":"activo"},{"text":"Verter la masa en el molde preparado y alisar la superficie con una espátula.","minutes":1,"kind":"activo"},{"text":"Hornear a 175 °C durante 50 min, hasta que al pinchar el centro con un palillo salga limpio.","minutes":50,"kind":"pasivo"},{"text":"Retirar el molde del horno y dejar enfriar sobre una rejilla hasta que esté a temperatura ambiente.","minutes":60,"kind":"espera"},{"text":"Sacar {{Queso crema}} y {{Mantequilla}} de la nevera 20 min antes para que estén a temperatura ambiente.","minutes":20,"kind":"espera"},{"text":"Batir el queso crema con la mantequilla a velocidad media hasta obtener una crema lisa y sin grumos.","minutes":3,"kind":"activo"},{"text":"Añadir {{Azúcar glas}} tamizado poco a poco sin dejar de batir hasta lograr un glaseado liso y firme.","minutes":3,"kind":"activo"},{"text":"Desmoldar la tarta fría con cuidado sobre una rejilla o plato de servir.","minutes":1,"kind":"activo"},{"text":"Cubrir la superficie y los laterales de la tarta con el glaseado, extendiéndolo con una espátula.","minutes":5,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('postres_030', 'Panna cotta de vainilla con frutos rojos', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 25, 'normal', 'all', 460, 3, 32, 36, 4, true, true, '{"lactosa"}', '[{"name":"Nata para montar","amount":400,"unit":"ml"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Azúcar","amount":90,"unit":"g"},{"name":"Extracto de vainilla","amount":5,"unit":"ml"},{"name":"Hojas de gelatina","amount":6,"unit":"g"},{"name":"Frutos rojos","amount":200,"unit":"g"},{"name":"Agua","amount":30,"unit":"ml"}]'::jsonb, '{"Sumergir hojas de gelatina en un bol con agua fría hasta que estén blandas.","Calentar nata para montar, leche, azúcar y extracto de vainilla en un cazo a fuego medio hasta que esté caliente sin que llegue a hervir.","Escurrir las hojas de gelatina y añadirlas al cazo fuera del fuego.","Remover hasta que la gelatina se disuelva por completo en la mezcla de nata.","Repartir la mezcla en 4 moldes o vasos individuales.","Refrigerar los moldes hasta que la panna cotta cuaje por completo.","Calentar frutos rojos, el azúcar restante y agua en un cazo a fuego medio.","Cocer a fuego medio hasta que los frutos rojos suelten su jugo y la salsa espese ligeramente.","Retirar el cazo del fuego y triturar la mitad de la salsa, dejando el resto con los frutos enteros.","Dejar enfriar la salsa de frutos rojos a temperatura ambiente.","Desmoldar cada panna cotta pasando un cuchillo fino por el borde o servir directamente en el vaso.","Cubrir cada panna cotta con la salsa de frutos rojos y servir."}', 'Panna cotta cremosa de vainilla que tiembla al moverla, con una salsa brillante de frutos rojos.', NULL, '{}', true, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Sumergir {{Hojas de gelatina}} en un bol con agua fría hasta que estén blandas.","minutes":5,"kind":"espera"},{"text":"Calentar {{Nata para montar}}, {{Leche}}, {{Azúcar}} y {{Extracto de vainilla}} en un cazo a fuego medio hasta que esté caliente sin que llegue a hervir.","minutes":5,"kind":"activo"},{"text":"Escurrir las hojas de gelatina y añadirlas al cazo fuera del fuego.","minutes":1,"kind":"activo"},{"text":"Remover hasta que la gelatina se disuelva por completo en la mezcla de nata.","minutes":1,"kind":"activo"},{"text":"Repartir la mezcla en 4 moldes o vasos individuales.","minutes":2,"kind":"activo","part":"principal"},{"text":"Refrigerar los moldes hasta que la panna cotta cuaje por completo.","minutes":240,"kind":"espera","part":"principal"},{"text":"Calentar {{Frutos rojos}}, el azúcar restante y {{Agua}} en un cazo a fuego medio.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Cocer a fuego medio hasta que los frutos rojos suelten su jugo y la salsa espese ligeramente.","minutes":6,"kind":"pasivo","part":"salsa"},{"text":"Retirar el cazo del fuego y triturar la mitad de la salsa, dejando el resto con los frutos enteros.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Dejar enfriar la salsa de frutos rojos a temperatura ambiente.","minutes":15,"kind":"espera","part":"salsa"},{"text":"Desmoldar cada panna cotta pasando un cuchillo fino por el borde o servir directamente en el vaso.","minutes":2,"kind":"emplatado","part":"combinado"},{"text":"Cubrir cada panna cotta con la salsa de frutos rojos y servir.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, NULL),
  ('postres_031', 'Helado casero de vainilla sin heladora', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 500, 7, 39, 35, 6, true, true, '{"lactosa"}', '[{"name":"Nata para montar","amount":500,"unit":"ml"},{"name":"Leche condensada","amount":400,"unit":"g"},{"name":"Extracto de vainilla","amount":10,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Introducir el bol y las varillas en el congelador para enfriarlos.","Verter nata para montar en el bol frío y montar con las varillas hasta que forme picos firmes al levantar.","Mezclar leche condensada, extracto de vainilla y sal en un bol grande hasta integrar.","Añadir la nata montada sobre la mezcla de leche condensada en 3 tandas, con movimientos envolventes de abajo hacia arriba.","Verter la mezcla en un recipiente hermético apto para congelador.","Alisar la superficie con una espátula o el dorso de una cuchara.","Tapar el recipiente y congelar hasta que el helado esté completamente firme.","Sacar el helado del congelador y dejar atemperar hasta que sea posible bolear con facilidad.","Servir en boles o copas con una cuchara de helado."}', 'Helado cremoso de vainilla sin necesitar heladora, solo nata, leche condensada y paciencia.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Introducir el bol y las varillas en el congelador para enfriarlos.","minutes":10,"kind":"espera"},{"text":"Verter {{Nata para montar}} en el bol frío y montar con las varillas hasta que forme picos firmes al levantar.","minutes":5,"kind":"activo"},{"text":"Mezclar {{Leche condensada}}, {{Extracto de vainilla}} y {{Sal}} en un bol grande hasta integrar.","minutes":2,"kind":"prep"},{"text":"Añadir la nata montada sobre la mezcla de leche condensada en 3 tandas, con movimientos envolventes de abajo hacia arriba.","minutes":3,"kind":"activo"},{"text":"Verter la mezcla en un recipiente hermético apto para congelador.","minutes":1,"kind":"ac