  ('postres_032', 'Sorbete de limón', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'verano', 190, 0, 48, 0, 4, true, true, '{}', '[{"name":"Zumo de limón","amount":200,"unit":"ml"},{"name":"Agua","amount":350,"unit":"ml"},{"name":"Azúcar","amount":180,"unit":"g"},{"name":"Ralladura de limón","amount":5,"unit":"g"}]'::jsonb, '{"Calentar agua con azúcar en un cazo a fuego medio hasta que el azúcar se disuelva por completo.","Retirar el cazo del fuego y añadir ralladura de limón. Remover para integrar.","Dejar enfriar el almíbar por completo a temperatura ambiente.","Añadir zumo de limón al almíbar frío. Mezclar hasta obtener una mezcla homogénea.","Verter la mezcla en un recipiente bajo y ancho apto para congelador.","Congelar la mezcla durante 60 min.","Raspar la mezcla con un tenedor, rompiendo los cristales de hielo de los bordes hacia el centro.","Congelar de nuevo durante 35 min.","Raspar de nuevo con el tenedor, removiendo toda la superficie para airear la textura.","Repetir el ciclo de congelado 35 min y raspado 3 veces más hasta lograr una textura granizada y suelta.","Servir el sorbete directamente del congelador en copas frías."}', 'Sorbete de limón refrescante y ácido, con esa textura granizada tan característica.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Calentar {{Agua}} con {{Azúcar}} en un cazo a fuego medio hasta que el azúcar se disuelva por completo.","minutes":5,"kind":"activo"},{"text":"Retirar el cazo del fuego y añadir {{Ralladura de limón}}. Remover para integrar.","minutes":1,"kind":"activo"},{"text":"Dejar enfriar el almíbar por completo a temperatura ambiente.","minutes":30,"kind":"espera"},{"text":"Añadir {{Zumo de limón}} al almíbar frío. Mezclar hasta obtener una mezcla homogénea.","minutes":1,"kind":"activo"},{"text":"Verter la mezcla en un recipiente bajo y ancho apto para congelador.","minutes":1,"kind":"activo"},{"text":"Congelar la mezcla durante 60 min.","minutes":60,"kind":"pasivo"},{"text":"Raspar la mezcla con un tenedor, rompiendo los cristales de hielo de los bordes hacia el centro.","minutes":2,"kind":"activo"},{"text":"Congelar de nuevo durante 35 min.","minutes":35,"kind":"pasivo"},{"text":"Raspar de nuevo con el tenedor, removiendo toda la superficie para airear la textura.","minutes":2,"kind":"activo"},{"text":"Repetir el ciclo de congelado 35 min y raspado 3 veces más hasta lograr una textura granizada y suelta.","minutes":115,"kind":"pasivo"},{"text":"Servir el sorbete directamente del congelador en copas frías.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, NULL),
  ('postres_033', 'Coulant de chocolate', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 25, 'normal', 'all', 680, 10, 45, 49, 4, true, false, '{"gluten","lactosa","huevo"}', '[{"name":"Chocolate negro","amount":150,"unit":"g"},{"name":"Mantequilla","amount":150,"unit":"g"},{"name":"Azúcar","amount":80,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Yema de huevo","amount":2,"unit":"ud"},{"name":"Harina","amount":60,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Engrasar 4 moldes individuales con mantequilla y enharinar con harina, sacudiendo el exceso.","Trocear chocolate negro en trozos pequeños y colocar en un bol resistente al calor.","Fundir el chocolate troceado con el resto de la mantequilla al baño maría hasta que esté liso y homogéneo.","Retirar el bol del calor y dejar templar hasta que esté tibio al tacto.","Batir huevo y yema de huevo con azúcar en un bol grande hasta que la mezcla blanquee ligeramente.","Añadir el chocolate fundido templado a la mezcla de huevos y remover hasta integrar completamente.","Incorporar el resto de la harina a la mezcla y remover con espátula hasta que no queden grumos.","Repartir la masa entre los 4 moldes preparados llenando hasta ¾ de su capacidad.","Hornear a 200 °C durante 10 min, hasta que la superficie esté cuajada pero el centro siga líquido.","Retirar los moldes del horno y dejar reposar 1 min sin desmoldar.","Desmoldar cada coulant volcando con cuidado sobre el plato de servicio y servir de inmediato."}', 'Bizcocho de chocolate que se abre al partirlo, dejando salir un centro líquido y caliente.', NULL, '{}', true, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Engrasar 4 moldes individuales con {{Mantequilla}} y enharinar con {{Harina}}, sacudiendo el exceso.","minutes":3,"kind":"prep"},{"text":"Trocear {{Chocolate negro}} en trozos pequeños y colocar en un bol resistente al calor.","minutes":2,"kind":"prep"},{"text":"Fundir el chocolate troceado con el resto de la mantequilla al baño maría hasta que esté liso y homogéneo.","minutes":5,"kind":"activo"},{"text":"Retirar el bol del calor y dejar templar hasta que esté tibio al tacto.","minutes":3,"kind":"espera"},{"text":"Batir {{Huevo}} y {{Yema de huevo}} con {{Azúcar}} en un bol grande hasta que la mezcla blanquee ligeramente.","minutes":3,"kind":"activo"},{"text":"Añadir el chocolate fundido templado a la mezcla de huevos y remover hasta integrar completamente.","minutes":2,"kind":"activo"},{"text":"Incorporar el resto de la harina a la mezcla y remover con espátula hasta que no queden grumos.","minutes":2,"kind":"activo"},{"text":"Repartir la masa entre los 4 moldes preparados llenando hasta ¾ de su capacidad.","minutes":2,"kind":"activo"},{"text":"Hornear a 200 °C durante 10 min, hasta que la superficie esté cuajada pero el centro siga líquido.","minutes":10,"kind":"pasivo"},{"text":"Retirar los moldes del horno y dejar reposar 1 min sin desmoldar.","minutes":1,"kind":"espera"},{"text":"Desmoldar cada coulant volcando con cuidado sobre el plato de servicio y servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('postres_034', 'Tarta borracha de ron', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 65, 'normal', 'all', 400, 6, 60, 13, 8, false, true, '{"gluten","lactosa","huevo"}', '[{"name":"Harina","amount":250,"unit":"g"},{"name":"Azúcar","amount":300,"unit":"g"},{"name":"Huevo","amount":4,"unit":"ud"},{"name":"Levadura química","amount":8,"unit":"g"},{"name":"Leche","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":100,"unit":"g"},{"name":"Agua","amount":200,"unit":"ml"},{"name":"Ron","amount":80,"unit":"ml"},{"name":"Ralladura de limón","amount":5,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 175 °C.","Engrasar y enharinar un molde de 22 cm.","Fundir mantequilla en un cazo a fuego suave hasta que esté líquida. Reservar y dejar templar.","Batir huevo con 150 g de azúcar en un bol hasta que la mezcla blanquee y duplique su volumen.","Añadir leche y la mantequilla fundida al bol y mezclar hasta integrar.","Tamizar harina junto con levadura química directamente sobre el bol.","Incorporar la harina tamizada con movimientos envolventes hasta que no queden grumos.","Verter la masa en el molde y hornear 38 min, hasta que al pinchar con un palillo salga limpio.","Calentar agua con los 150 g de azúcar restantes y ralladura de limón en un cazo a fuego medio.","Remover hasta que la azúcar se disuelva y el almíbar rompa a hervir. Retirar del fuego.","Dejar templar el almíbar 5 min y añadir ron. Remover y reservar.","Retirar el bizcocho del horno cuando el palillo salga limpio. Dejar en el molde.","Pinchar toda la superficie del bizcocho con un palillo, haciendo agujeros uniformes.","Verter el almíbar despacio sobre el bizcocho, en varias veces, dejando que lo absorba entre cada adición.","Dejar reposar el bizcocho en el molde al menos 30 min hasta que quede bien empapado.","Desmoldar y servir."}', 'Bizcocho jugoso empapado en almíbar de ron, muy húmedo y aromático.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 175 °C.","minutes":10,"kind":"pasivo"},{"text":"Engrasar y enharinar un molde de 22 cm.","minutes":2,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego suave hasta que esté líquida. Reservar y dejar templar.","minutes":3,"kind":"activo"},{"text":"Batir {{Huevo}} con 150 g de {{Azúcar}} en un bol hasta que la mezcla blanquee y duplique su volumen.","minutes":5,"kind":"activo"},{"text":"Añadir {{Leche}} y la mantequilla fundida al bol y mezclar hasta integrar.","minutes":2,"kind":"activo"},{"text":"Tamizar {{Harina}} junto con {{Levadura química}} directamente sobre el bol.","minutes":2,"kind":"prep"},{"text":"Incorporar la harina tamizada con movimientos envolventes hasta que no queden grumos.","minutes":3,"kind":"activo"},{"text":"Verter la masa en el molde y hornear 38 min, hasta que al pinchar con un palillo salga limpio.","minutes":38,"kind":"pasivo"},{"text":"Calentar {{Agua}} con los 150 g de azúcar restantes y {{Ralladura de limón}} en un cazo a fuego medio.","minutes":3,"kind":"activo"},{"text":"Remover hasta que la azúcar se disuelva y el almíbar rompa a hervir. Retirar del fuego.","minutes":2,"kind":"activo"},{"text":"Dejar templar el almíbar 5 min y añadir {{Ron}}. Remover y reservar.","minutes":5,"kind":"espera"},{"text":"Retirar el bizcocho del horno cuando el palillo salga limpio. Dejar en el molde.","minutes":1,"kind":"activo"},{"text":"Pinchar toda la superficie del bizcocho con un palillo, haciendo agujeros uniformes.","minutes":2,"kind":"activo"},{"text":"Verter el almíbar despacio sobre el bizcocho, en varias veces, dejando que lo absorba entre cada adición.","minutes":3,"kind":"activo"},{"text":"Dejar reposar el bizcocho en el molde al menos 30 min hasta que quede bien empapado.","minutes":30,"kind":"espera"},{"text":"Desmoldar y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('postres_035', 'Galletas de mantequilla decoradas', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 50, 'facil', 'all', 620, 7, 82, 28, 6, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Harina","amount":300,"unit":"g"},{"name":"Mantequilla","amount":200,"unit":"g"},{"name":"Azúcar glas","amount":270,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Extracto de vainilla","amount":5,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Clara de huevo","amount":1,"unit":"ud"},{"name":"Zumo de limón","amount":5,"unit":"ml"}]'::jsonb, '{"Templar mantequilla hasta que esté en pomada, blanda pero sin derretir.","Batir la mantequilla en pomada con azúcar glas (120 g) hasta obtener una crema lisa y homogénea.","Añadir huevo y extracto de vainilla a la crema y mezclar hasta integrar.","Tamizar harina junto con sal sobre la crema.","Mezclar lo justo hasta que la masa se despegue de las manos y sea uniforme; no amasar en exceso.","Formar un disco con la masa, envolverlo en film transparente y refrigerar hasta que esté firme.","Precalentar el horno a 170 °C.","Estirar la masa sobre una superficie enharinada hasta un grosor de 4 mm.","Cortar formas con cortapastas y colocarlas en una bandeja con papel de horno, separadas entre sí.","Hornear las galletas a 170 °C hasta que los bordes empiecen a dorarse.","Retirar la bandeja del horno y dejar enfriar las galletas por completo sobre una rejilla.","Batir clara de huevo con los 150 g restantes de azúcar glas y zumo de limón hasta obtener una glasa espesa y brillante.","Decorar las galletas frías con la glasa y dejar secar hasta que esté completamente sólida.","Servir las galletas una vez la glasa esté seca y firme."}', 'Galletas de mantequilla doradas por los bordes, perfectas para decorar en familia.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Templar {{Mantequilla}} hasta que esté en pomada, blanda pero sin derretir.","minutes":10,"kind":"espera"},{"text":"Batir la mantequilla en pomada con {{Azúcar glas}} (120 g) hasta obtener una crema lisa y homogénea.","minutes":3,"kind":"activo"},{"text":"Añadir {{Huevo}} y {{Extracto de vainilla}} a la crema y mezclar hasta integrar.","minutes":2,"kind":"activo"},{"text":"Tamizar {{Harina}} junto con {{Sal|pizca}} sobre la crema.","minutes":2,"kind":"prep"},{"text":"Mezclar lo justo hasta que la masa se despegue de las manos y sea uniforme; no amasar en exceso.","minutes":2,"kind":"activo"},{"text":"Formar un disco con la masa, envolverlo en film transparente y refrigerar hasta que esté firme.","minutes":60,"kind":"espera"},{"text":"Precalentar el horno a 170 °C.","minutes":10,"kind":"pasivo"},{"text":"Estirar la masa sobre una superficie enharinada hasta un grosor de 4 mm.","minutes":3,"kind":"activo"},{"text":"Cortar formas con cortapastas y colocarlas en una bandeja con papel de horno, separadas entre sí.","minutes":3,"kind":"prep"},{"text":"Hornear las galletas a 170 °C hasta que los bordes empiecen a dorarse.","minutes":10,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y dejar enfriar las galletas por completo sobre una rejilla.","minutes":20,"kind":"espera"},{"text":"Batir {{Clara de huevo}} con los 150 g restantes de azúcar glas y {{Zumo de limón}} hasta obtener una glasa espesa y brillante.","minutes":3,"kind":"activo"},{"text":"Decorar las galletas frías con la glasa y dejar secar hasta que esté completamente sólida.","minutes":60,"kind":"espera"},{"text":"Servir las galletas una vez la glasa esté seca y firme.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('postres_036', 'Bizcocho de yogur y limón', 'postres', 'none', NULL, ARRAY['postre']::meal_role[], 'completo', NULL, 'horno', 55, 'facil', 'all', 430, 6, 53, 21, 8, true, true, '{"gluten","lactosa","huevo"}', '[{"name":"Yogur natural","amount":125,"unit":"g"},{"name":"Azúcar","amount":200,"unit":"g"},{"name":"Aceite de girasol","amount":150,"unit":"ml"},{"name":"Harina","amount":300,"unit":"g"},{"name":"Huevo","amount":3,"unit":"ud"},{"name":"Levadura química","amount":16,"unit":"g"},{"name":"Ralladura de limón","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 180 °C.","Engrasar un molde de 22 cm con aceite de girasol y espolvorear harina hasta cubrir toda la superficie.","Rallar ralladura de limón hasta obtener la cantidad necesaria y reservar.","Verter yogur natural en un bol grande junto con azúcar y la ralladura de limón.","Batir la mezcla de yogur, azúcar y ralladura hasta obtener una crema homogénea.","Añadir huevo de uno en uno, batiendo bien tras cada incorporación antes de añadir el siguiente.","Incorporar el aceite de girasol en hilo fino sin dejar de batir hasta que la mezcla emulsione.","Tamizar la harina restante junto con levadura química y sal sobre un bol aparte.","Añadir los ingredientes secos tamizados sobre la mezcla húmeda en dos tandas.","Remover con espátula con movimientos envolventes hasta que no queden grumos, sin batir en exceso.","Verter la masa en el molde preparado y alisar la superficie con la espátula.","Hornear a 180 °C durante 42 min, hasta que al pinchar con un palillo en el centro salga limpio.","Retirar el molde del horno y dejar templar 10 min dentro del molde antes de desmoldar.","Desmoldar el bizcocho sobre una rejilla y dejar enfriar por completo antes de cortar.","Cortar en porciones y servir."}', 'Bizcocho esponjoso de yogur y limón, el clásico sencillo de toda la vida.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 180 °C.","minutes":10,"kind":"pasivo"},{"text":"Engrasar un molde de 22 cm con {{Aceite de girasol|chorrito}} y espolvorear {{Harina}} hasta cubrir toda la superficie.","minutes":2,"kind":"prep"},{"text":"Rallar {{Ralladura de limón}} hasta obtener la cantidad necesaria y reservar.","minutes":2,"kind":"prep"},{"text":"Verter {{Yogur natural}} en un bol grande junto con {{Azúcar}} y la ralladura de limón.","minutes":1,"kind":"prep"},{"text":"Batir la mezcla de yogur, azúcar y ralladura hasta obtener una crema homogénea.","minutes":2,"kind":"activo"},{"text":"Añadir {{Huevo}} de uno en uno, batiendo bien tras cada incorporación antes de añadir el siguiente.","minutes":3,"kind":"activo"},{"text":"Incorporar el aceite de girasol en hilo fino sin dejar de batir hasta que la mezcla emulsione.","minutes":2,"kind":"activo"},{"text":"Tamizar la harina restante junto con {{Levadura química}} y {{Sal|gusto}} sobre un bol aparte.","minutes":2,"kind":"prep"},{"text":"Añadir los ingredientes secos tamizados sobre la mezcla húmeda en dos tandas.","minutes":1,"kind":"activo"},{"text":"Remover con espátula con movimientos envolventes hasta que no queden grumos, sin batir en exceso.","minutes":2,"kind":"activo"},{"text":"Verter la masa en el molde preparado y alisar la superficie con la espátula.","minutes":1,"kind":"activo"},{"text":"Hornear a 180 °C durante 42 min, hasta que al pinchar con un palillo en el centro salga limpio.","minutes":42,"kind":"pasivo"},{"text":"Retirar el molde del horno y dejar templar 10 min dentro del molde antes de desmoldar.","minutes":10,"kind":"espera"},{"text":"Desmoldar el bizcocho sobre una rejilla y dejar enfriar por completo antes de cortar.","minutes":30,"kind":"espera"},{"text":"Cortar en porciones y servir.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('salsas_001', 'Vinagreta clásica', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 5, 'facil', 'all', 130, 0, 1, 14, 4, true, true, '{"mostaza"}', '[{"name":"Aceite de oliva virgen extra","amount":60,"unit":"ml"},{"name":"Vinagre de Jerez","amount":20,"unit":"ml"},{"name":"Mostaza de Dijon","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Añadir vinagre de jerez, mostaza de dijon y sal en un bol pequeño.","Mezclar con unas varillas hasta que la sal se disuelva y la mostaza quede integrada.","Verter aceite de oliva virgen extra en hilo muy fino mientras se bate sin parar hasta emulsionar.","Añadir pimienta negra y rectificar de sal al gusto.","Servir en salsera o verter directamente sobre la ensalada."}', 'Vinagreta clásica de mostaza y vinagre de Jerez, para aliñar ensaladas y verduras.', NULL, '{"Vinagreta"}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Añadir {{Vinagre de Jerez}}, {{Mostaza de Dijon}} y {{Sal|gusto}} en un bol pequeño.","minutes":1,"kind":"prep"},{"text":"Mezclar con unas varillas hasta que la sal se disuelva y la mostaza quede integrada.","minutes":1,"kind":"activo"},{"text":"Verter {{Aceite de oliva virgen extra}} en hilo muy fino mientras se bate sin parar hasta emulsionar.","minutes":2,"kind":"activo"},{"text":"Añadir {{Pimienta negra|pizca}} y rectificar de sal al gusto.","minutes":1,"kind":"activo"},{"text":"Servir en salsera o verter directamente sobre la ensalada.","kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_002', 'Alioli', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'normal', 'all', 180, 0, 1, 20, 4, false, true, '{}', '[{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva suave","amount":150,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Zumo de limón","amount":5,"unit":"ml"}]'::jsonb, '{"Pelar ajo y retirar el germen interior.","Machacar el ajo pelado en un mortero con sal hasta obtener una pasta fina y homogénea.","Añadir aceite de oliva suave en hilo muy fino, sin parar de remover con el mortero, hasta que emulsione.","Añadir zumo de limón y remover hasta integrar.","Reservar el alioli en frío hasta el momento de servir."}', 'Alioli tradicional de ajo y aceite, sin huevo, para carnes, pescados y marisco a la plancha.', NULL, '{"Alioli"}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Ajo}} y retirar el germen interior.","minutes":1,"kind":"prep"},{"text":"Machacar el ajo pelado en un mortero con {{Sal|gusto}} hasta obtener una pasta fina y homogénea.","minutes":3,"kind":"activo"},{"text":"Añadir {{Aceite de oliva suave}} en hilo muy fino, sin parar de remover con el mortero, hasta que emulsione.","minutes":4,"kind":"activo"},{"text":"Añadir {{Zumo de limón}} y remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Reservar el alioli en frío hasta el momento de servir.","kind":"espera"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL)
