insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('salsas_003', 'Salsa de tomate casera', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 25, 'facil', 'all', 70, 1, 8, 4, 4, true, true, '{}', '[{"name":"Tomate triturado","amount":400,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Azúcar","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en trozos muy finos.","Pelar y picar ajo en trozos muy finos.","Calentar aceite de oliva en un cazo a fuego suave.","Sofreír la cebolla picada en el cazo hasta que esté transparente.","Añadir el ajo picado y sofreír hasta que se dore ligeramente.","Añadir tomate triturado y azúcar. Remover para mezclar bien.","Cocer a fuego suave durante 20 min, removiendo de vez en cuando.","Añadir sal y remover para integrar.","Triturar la salsa con un batidor hasta obtener una textura fina.","Servir la salsa de tomate caliente o reservar en un tarro hermético."}', 'El clásico tomate frito casero: para arroz blanco, huevos o cualquier plato sencillo.', NULL, '{"Tomate frito","Salsa de tomate"}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Cebolla}} en trozos muy finos.","minutes":3,"kind":"prep"},{"text":"Pelar y picar {{Ajo}} en trozos muy finos.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en un cazo a fuego suave.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada en el cazo hasta que esté transparente.","minutes":5,"kind":"activo"},{"text":"Añadir el ajo picado y sofreír hasta que se dore ligeramente.","minutes":2,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y {{Azúcar}}. Remover para mezclar bien.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave durante 20 min, removiendo de vez en cuando.","minutes":20,"kind":"pasivo"},{"text":"Añadir {{Sal|gusto}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Triturar la salsa con un batidor hasta obtener una textura fina.","minutes":1,"kind":"opcional"},{"text":"Servir la salsa de tomate caliente o reservar en un tarro hermético.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_004', 'Salsa de carne (jugo de asado)', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 30, 'normal', 'all', 90, 2, 4, 6, 4, true, true, '{"gluten","lactosa"}', '[{"name":"Caldo de carne","amount":300,"unit":"ml"},{"name":"Vino tinto","amount":50,"unit":"ml"},{"name":"Cebolla","amount":40,"unit":"g"},{"name":"Zanahoria","amount":30,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Harina","amount":10,"unit":"g"}]'::jsonb, '{"Picar cebolla en trozos pequeños.","Picar zanahoria en trozos pequeños.","Calentar mantequilla en un cazo a fuego medio hasta que se derrita.","Sofreír la cebolla picada y la zanahoria picada en la mantequilla fundida a fuego medio hasta que estén tiernas.","Añadir vino tinto y remover hasta que se evapore el alcohol.","Añadir caldo de carne y llevar a ebullición a fuego fuerte.","Cocer a fuego suave hasta que el caldo reduzca a la mitad.","Mezclar harina con un poco de agua fría en un bol pequeño hasta obtener una pasta sin grumos.","Colar la salsa a través de un colador fino sobre un cazo limpio.","Añadir la pasta de harina a la salsa colada y remover a fuego medio hasta que esté ligada y sin grumos.","Servir la salsa caliente sobre el plato principal."}', 'Jugo de asado clásico, reducido aparte: para carnes al horno o a la plancha.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Cebolla}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Picar {{Zanahoria}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Mantequilla}} en un cazo a fuego medio hasta que se derrita.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada y la zanahoria picada en la mantequilla fundida a fuego medio hasta que estén tiernas.","minutes":5,"kind":"activo"},{"text":"Añadir {{Vino tinto}} y remover hasta que se evapore el alcohol.","minutes":5,"kind":"activo"},{"text":"Añadir {{Caldo de carne}} y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego suave hasta que el caldo reduzca a la mitad.","minutes":15,"kind":"pasivo"},{"text":"Mezclar {{Harina}} con un poco de agua fría en un bol pequeño hasta obtener una pasta sin grumos.","minutes":1,"kind":"paralelo","during":6},{"text":"Colar la salsa a través de un colador fino sobre un cazo limpio.","minutes":2,"kind":"activo"},{"text":"Añadir la pasta de harina a la salsa colada y remover a fuego medio hasta que esté ligada y sin grumos.","minutes":2,"kind":"activo"},{"text":"Servir la salsa caliente sobre el plato principal.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_005', 'Salsa verde clásica', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 110, 0, 1, 12, 4, true, true, '{"sulfitos"}', '[{"name":"Perejil fresco","amount":30,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Alcaparras","amount":10,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Picar perejil fresco muy fino con un cuchillo hasta obtener una textura menuda y uniforme.","Picar ajo muy fino.","Picar alcaparras muy fino.","Mezclar el perejil picado, el ajo picado y las alcaparras picadas en un bol.","Añadir aceite de oliva y zumo de limón, y remover hasta integrar.","Añadir sal y remover.","Dejar reposar la salsa 10 min para que los sabores se asienten.","Servir la salsa verde."}', 'Salsa verde en crudo de perejil y alcaparras, para pescado blanco, azul o carnes blancas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Perejil fresco}} muy fino con un cuchillo hasta obtener una textura menuda y uniforme.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Picar {{Alcaparras}} muy fino.","minutes":1,"kind":"prep"},{"text":"Mezclar el perejil picado, el ajo picado y las alcaparras picadas en un bol.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} y {{Zumo de limón}}, y remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y remover.","minutes":1,"kind":"activo"},{"text":"Dejar reposar la salsa 10 min para que los sabores se asienten.","minutes":10,"kind":"espera"},{"text":"Servir la salsa verde.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_006', 'Mojo verde canario', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 115, 0, 1, 13, 4, true, true, '{}', '[{"name":"Cilantro fresco","amount":30,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Comino","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Vinagre","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar ajo.","Lavar cilantro fresco y escurrir bien.","Introducir el cilantro fresco y el ajo en el vaso de la batidora o picadora.","Añadir comino y triturar hasta obtener una pasta fina.","Añadir vinagre y triturar de nuevo hasta integrar.","Incorporar aceite de oliva en hilo fino mientras se tritura hasta emulsionar la salsa.","Añadir sal y triturar 10 segundos más para integrar. Rectificar de sal si fuera necesario.","Servir el mojo verde en un bol o salsera."}', 'Mojo verde canario de cilantro y comino, para carnes blancas, pescado, marisco o verduras.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Ajo}}.","minutes":1,"kind":"prep"},{"text":"Lavar {{Cilantro fresco}} y escurrir bien.","minutes":1,"kind":"prep"},{"text":"Introducir el cilantro fresco y el ajo en el vaso de la batidora o picadora.","minutes":1,"kind":"prep"},{"text":"Añadir {{Comino}} y triturar hasta obtener una pasta fina.","minutes":1,"kind":"activo"},{"text":"Añadir {{Vinagre}} y triturar de nuevo hasta integrar.","minutes":1,"kind":"activo"},{"text":"Incorporar {{Aceite de oliva}} en hilo fino mientras se tritura hasta emulsionar la salsa.","minutes":2,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y triturar 10 segundos más para integrar. Rectificar de sal si fuera necesario.","minutes":1,"kind":"activo"},{"text":"Servir el mojo verde en un bol o salsera.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_007', 'Mojo rojo picón canario', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 20, 'normal', 'all', 120, 0, 2, 13, 4, false, true, '{}', '[{"name":"Pimiento choricero (ñora)","amount":10,"unit":"g"},{"name":"Pimentón picante","amount":5,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Comino","amount":2,"unit":"g"},{"name":"Vinagre","amount":15,"unit":"ml"},{"name":"Aceite de oliva","amount":80,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cubrir pimiento choricero (ñora) con agua muy caliente en un bol pequeño.","Dejar en remojo hasta que la ñora esté blanda y rehidratada.","Retirar la ñora del agua y raspar la pulpa interior con una cuchara.","Añadir la pulpa de ñora al vaso de la batidora junto con ajo.","Añadir pimentón picante, comino y vinagre al vaso.","Triturar todo hasta obtener una pasta homogénea y fina.","Añadir aceite de oliva en hilo fino mientras se sigue triturando hasta emulsionar.","Rectificar con sal y triturar 10 segundos más para integrar."}', 'Mojo picón canario, picante, de pimentón y ñora: para carnes y verduras asadas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Cubrir {{Pimiento choricero (ñora)}} con agua muy caliente en un bol pequeño.","minutes":1,"kind":"prep"},{"text":"Dejar en remojo hasta que la ñora esté blanda y rehidratada.","minutes":15,"kind":"espera"},{"text":"Retirar la ñora del agua y raspar la pulpa interior con una cuchara.","minutes":2,"kind":"prep"},{"text":"Añadir la pulpa de ñora al vaso de la batidora junto con {{Ajo}}.","minutes":1,"kind":"prep"},{"text":"Añadir {{Pimentón picante}}, {{Comino}} y {{Vinagre}} al vaso.","minutes":1,"kind":"prep"},{"text":"Triturar todo hasta obtener una pasta homogénea y fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} en hilo fino mientras se sigue triturando hasta emulsionar.","minutes":2,"kind":"activo"},{"text":"Rectificar con {{Sal|gusto}} y triturar 10 segundos más para integrar.","minutes":1,"kind":"activo"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_008', 'Chimichurri', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 15, 'facil', 'all', 125, 0, 1, 14, 4, true, true, '{}', '[{"name":"Perejil fresco","amount":30,"unit":"g"},{"name":"Orégano seco","amount":3,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":90,"unit":"ml"},{"name":"Vinagre de vino","amount":25,"unit":"ml"},{"name":"Guindilla","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Picar ajo muy fino sobre la tabla.","Picar perejil fresco muy fino hasta obtener trozos menudos.","Mezclar en un bol el perejil picado, el ajo picado, orégano seco, guindilla y sal.","Añadir vinagre de vino y remover hasta integrar.","Añadir aceite de oliva en hilo fino mientras se remueve para emulsionar.","Reposar el chimichurri tapado a temperatura ambiente hasta que los sabores se integren.","Servir el chimichurri en un cuenco o directamente sobre el plato."}', 'Chimichurri argentino de perejil y orégano, el clásico para carnes a la parrilla.', NULL, '{"Chimichurri"}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Ajo}} muy fino sobre la tabla.","minutes":2,"kind":"prep"},{"text":"Picar {{Perejil fresco}} muy fino hasta obtener trozos menudos.","minutes":3,"kind":"prep"},{"text":"Mezclar en un bol el perejil picado, el ajo picado, {{Orégano seco}}, {{Guindilla}} y {{Sal|gusto}}.","minutes":1,"kind":"activo"},{"text":"Añadir {{Vinagre de vino}} y remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} en hilo fino mientras se remueve para emulsionar.","minutes":1,"kind":"activo"},{"text":"Reposar el chimichurri tapado a temperatura ambiente hasta que los sabores se integren.","minutes":30,"kind":"espera"},{"text":"Servir el chimichurri en un cuenco o directamente sobre el plato.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_009', 'Salsa de mostaza y miel', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 5, 'facil', 'all', 95, 0, 8, 7, 4, true, true, '{"mostaza"}', '[{"name":"Mostaza de Dijon","amount":30,"unit":"g"},{"name":"Miel","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Mezclar mostaza de dijon y miel en un bol hasta obtener una mezcla homogénea.","Añadir aceite de oliva en hilo fino mientras se bate sin parar hasta emulsionar.","Incorporar zumo de limón y mezclar hasta integrar.","Añadir sal y remover. Rectificar el punto de acidez o dulzor si es necesario."}', 'Salsa agridulce de mostaza y miel, clásica para pollo, pavo o carnes a la plancha.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Mezclar {{Mostaza de Dijon}} y {{Miel}} en un bol hasta obtener una mezcla homogénea.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva}} en hilo fino mientras se bate sin parar hasta emulsionar.","minutes":2,"kind":"activo"},{"text":"Incorporar {{Zumo de limón}} y mezclar hasta integrar.","minutes":1,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y remover. Rectificar el punto de acidez o dulzor si es necesario.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_010', 'Romesco', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 35, 'normal', 'all', 160, 3, 6, 14, 4, true, true, '{"frutos_secos","gluten"}', '[{"name":"Tomate maduro","amount":100,"unit":"g"},{"name":"Pimiento choricero (ñora)","amount":10,"unit":"g"},{"name":"Almendra tostada","amount":30,"unit":"g"},{"name":"Avellana tostada","amount":20,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pan frito","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Vinagre","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Sumergir pimiento choricero (ñora) en agua muy caliente hasta que se hidrate.","Colocar tomate maduro y ajo en una bandeja y hornear hasta que estén asados.","Retirar la ñora hidratada del agua y extraer la pulpa raspando con una cuchara.","Añadir el tomate asado, el ajo asado, la pulpa de ñora, almendra tostada, avellana tostada y pan frito al vaso de la batidora.","Incorporar aceite de oliva y vinagre al vaso.","Triturar todo hasta obtener una crema homogénea.","Añadir sal y triturar de nuevo hasta integrar.","Servir el romesco en un cuenco o directamente como acompañamiento."}', 'Romesco catalán de almendra, avellana y ñora: para pescado o verduras asadas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Sumergir {{Pimiento choricero (ñora)}} en agua muy caliente hasta que se hidrate.","minutes":15,"kind":"pasivo"},{"text":"Colocar {{Tomate maduro}} y {{Ajo}} en una bandeja y hornear hasta que estén asados.","minutes":20,"kind":"pasivo"},{"text":"Retirar la ñora hidratada del agua y extraer la pulpa raspando con una cuchara.","minutes":2,"kind":"prep"},{"text":"Añadir el tomate asado, el ajo asado, la pulpa de ñora, {{Almendra tostada}}, {{Avellana tostada}} y {{Pan frito}} al vaso de la batidora.","minutes":1,"kind":"prep"},{"text":"Incorporar {{Aceite de oliva|chorrito}} y {{Vinagre}} al vaso.","minutes":1,"kind":"prep"},{"text":"Triturar todo hasta obtener una crema homogénea.","minutes":2,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y triturar de nuevo hasta integrar.","minutes":1,"kind":"activo"},{"text":"Servir el romesco en un cuenco o directamente como acompañamiento.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_011', 'Salsa tahini y limón', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 5, 'facil', 'all', 110, 3, 3, 10, 4, true, true, '{"sesamo"}', '[{"name":"Tahini","amount":60,"unit":"g"},{"name":"Zumo de limón","amount":30,"unit":"ml"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Agua","amount":40,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Picar ajo muy fino hasta obtener una pasta casi homogénea.","Verter tahini en un bol y añadir zumo de limón. Mezclar con unas varillas hasta que espese y se integre.","Añadir agua poco a poco sin dejar de remover hasta que la salsa tenga textura fluida y homogénea.","Añadir el ajo picado y sal. Mezclar bien hasta integrar.","Añadir un poco más de agua si la salsa ha quedado demasiado espesa y remover hasta conseguir la textura deseada.","Servir en un bol o salsera lista para acompañar."}', 'Crema de tahini y limón, para ensaladas, verduras asadas o carnes blancas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Ajo}} muy fino hasta obtener una pasta casi homogénea.","minutes":2,"kind":"prep"},{"text":"Verter {{Tahini}} en un bol y añadir {{Zumo de limón}}. Mezclar con unas varillas hasta que espese y se integre.","minutes":1,"kind":"activo"},{"text":"Añadir {{Agua}} poco a poco sin dejar de remover hasta que la salsa tenga textura fluida y homogénea.","minutes":1,"kind":"activo"},{"text":"Añadir el ajo picado y {{Sal|gusto}}. Mezclar bien hasta integrar.","minutes":1,"kind":"activo"},{"text":"Añadir un poco más de agua si la salsa ha quedado demasiado espesa y remover hasta conseguir la textura deseada.","kind":"opcional"},{"text":"Servir en un bol o salsera lista para acompañar.","kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_012', 'Salsa de yogur, eneldo y pepino', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 60, 4, 3, 3, 4, true, true, '{"lactosa"}', '[{"name":"Yogur griego","amount":150,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Eneldo fresco","amount":5,"unit":"g"},{"name":"Ajo","amount":2,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Rallar pepino con un rallador fino sobre un bol.","Escurrir el pepino rallado apretándolo con las manos hasta eliminar el exceso de agua.","Picar eneldo fresco fino con un cuchillo.","Rallar ajo o picarlo muy fino.","Mezclar yogur griego con el pepino escurrido, el eneldo picado y el ajo en un bol.","Añadir aceite de oliva y sal; remover hasta integrar.","Refrigerar la salsa tapada hasta que esté bien fría.","Servir la salsa fría como acompañamiento."}', 'Salsa fresca de yogur, pepino y eneldo, tipo tzatziki: para carnes blancas, pescado o ensaladas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Rallar {{Pepino}} con un rallador fino sobre un bol.","minutes":2,"kind":"prep"},{"text":"Escurrir el pepino rallado apretándolo con las manos hasta eliminar el exceso de agua.","minutes":1,"kind":"prep"},{"text":"Picar {{Eneldo fresco}} fino con un cuchillo.","minutes":1,"kind":"prep"},{"text":"Rallar {{Ajo}} o picarlo muy fino.","minutes":1,"kind":"prep"},{"text":"Mezclar {{Yogur griego}} con el pepino escurrido, el eneldo picado y el ajo en un bol.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} y {{Sal|gusto}}; remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Refrigerar la salsa tapada hasta que esté bien fría.","minutes":10,"kind":"espera"},{"text":"Servir la salsa fría como acompañamiento.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL)
