insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('salsas_013', 'Miso y mantequilla', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 140, 2, 5, 12, 4, true, true, '{"soja","lactosa"}', '[{"name":"Miso blanco","amount":40,"unit":"g"},{"name":"Mantequilla","amount":40,"unit":"g"},{"name":"Mirin","amount":15,"unit":"ml"},{"name":"Agua","amount":20,"unit":"ml"}]'::jsonb, '{"Calentar mantequilla en un cazo pequeño a fuego suave hasta que se funda por completo.","Añadir miso blanco y remover con una espátula hasta que se disuelva sin grumos.","Incorporar mirin y agua y remover a fuego suave hasta que la salsa ligue y quede homogénea.","Retirar el cazo del fuego y reservar la salsa templada hasta el momento de servir."}', 'Glaseado de miso y mantequilla, untuoso y umami, para pescado o verduras asadas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Calentar {{Mantequilla}} en un cazo pequeño a fuego suave hasta que se funda por completo.","minutes":2,"kind":"activo"},{"text":"Añadir {{Miso blanco}} y remover con una espátula hasta que se disuelva sin grumos.","minutes":2,"kind":"activo"},{"text":"Incorporar {{Mirin}} y {{Agua}} y remover a fuego suave hasta que la salsa ligue y quede homogénea.","minutes":2,"kind":"activo"},{"text":"Retirar el cazo del fuego y reservar la salsa templada hasta el momento de servir.","minutes":2,"kind":"espera"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_014', 'Gremolata', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 5, 'facil', 'all', 15, 1, 2, 0, 4, true, true, '{}', '[{"name":"Perejil fresco","amount":25,"unit":"g"},{"name":"Ralladura de limón","amount":5,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"}]'::jsonb, '{"Picar perejil fresco muy fino con un cuchillo.","Picar ajo muy fino.","Mezclar el perejil picado, el ajo picado y ralladura de limón en un bol hasta integrar.","Reservar la gremolata y espolvorear sobre el plato justo antes de servir."}', 'Gremolata italiana de perejil, limón y ajo: un toque fresco final para carnes, pescado o verduras.', NULL, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Perejil fresco}} muy fino con un cuchillo.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Mezclar el perejil picado, el ajo picado y {{Ralladura de limón}} en un bol hasta integrar.","minutes":1,"kind":"activo"},{"text":"Reservar la gremolata y espolvorear sobre el plato justo antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_015', 'Anchoas, ajo y limón', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 130, 2, 1, 14, 4, false, true, '{"pescado"}', '[{"name":"Filetes de anchoa en aceite","amount":20,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":60,"unit":"ml"},{"name":"Zumo de limón","amount":15,"unit":"ml"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Picar ajo muy fino hasta obtener una pasta.","Picar perejil fresco fino y reservar.","Machacar filetes de anchoa en aceite junto con el ajo picado en un mortero hasta obtener una pasta homogénea.","Añadir aceite de oliva muy despacio sobre la pasta de anchoa y ajo, removiendo sin parar hasta emulsionar.","Añadir zumo de limón y remover hasta integrar por completo.","Añadir el perejil picado y remover. Probar antes de salar, ya que las anchoas aportan sal."}', 'Salsa untuosa de anchoas, ajo y limón, con mucho carácter: para pescado blanco o verduras.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['pescado_azul']::main_protein[], false, '[{"text":"Picar {{Ajo}} muy fino hasta obtener una pasta.","minutes":2,"kind":"prep"},{"text":"Picar {{Perejil fresco}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Machacar {{Filetes de anchoa en aceite}} junto con el ajo picado en un mortero hasta obtener una pasta homogénea.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} muy despacio sobre la pasta de anchoa y ajo, removiendo sin parar hasta emulsionar.","minutes":2,"kind":"activo"},{"text":"Añadir {{Zumo de limón}} y remover hasta integrar por completo.","minutes":1,"kind":"activo"},{"text":"Añadir el perejil picado y remover. Probar antes de salar, ya que las anchoas aportan sal.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_016', 'Harissa y yogur', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 5, 'facil', 'all', 70, 4, 4, 4, 4, false, true, '{"lactosa"}', '[{"name":"Harissa","amount":20,"unit":"g"},{"name":"Yogur griego","amount":120,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Mezclar yogur griego con harissa en un bol hasta integrar por completo.","Añadir zumo de limón y remover hasta homogeneizar.","Añadir sal y remover.","Refrigerar la salsa hasta el momento de servir.","Servir la salsa fría como acompañamiento."}', 'Yogur picante con harissa, para carnes a la plancha o verduras asadas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Mezclar {{Yogur griego}} con {{Harissa}} en un bol hasta integrar por completo.","minutes":1,"kind":"activo"},{"text":"Añadir {{Zumo de limón}} y remover hasta homogeneizar.","minutes":1,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y remover.","minutes":1,"kind":"activo"},{"text":"Refrigerar la salsa hasta el momento de servir.","minutes":10,"kind":"espera"},{"text":"Servir la salsa fría como acompañamiento.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_017', 'Pistacho y albahaca', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 190, 4, 3, 18, 4, true, true, '{"frutos_secos","lactosa"}', '[{"name":"Pistacho pelado","amount":40,"unit":"g"},{"name":"Albahaca fresca","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":70,"unit":"ml"},{"name":"Queso parmesano","amount":15,"unit":"g"},{"name":"Ajo","amount":3,"unit":"g"}]'::jsonb, '{"Rallar queso parmesano y reservar.","Introducir pistacho pelado, albahaca fresca y ajo en el vaso de la batidora.","Triturar los ingredientes del vaso hasta obtener una pasta homogénea.","Añadir aceite de oliva en hilo fino mientras se tritura, hasta emulsionar la salsa.","Incorporar el queso parmesano rallado y triturar hasta integrarlo por completo.","Rectificar de sal al gusto y remover para homogeneizar la salsa antes de servir."}', 'Pesto de pistacho y albahaca, para ensaladas, pescado blanco o carnes blancas.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Rallar {{Queso parmesano}} y reservar.","minutes":1,"kind":"prep"},{"text":"Introducir {{Pistacho pelado}}, {{Albahaca fresca}} y {{Ajo}} en el vaso de la batidora.","minutes":1,"kind":"prep"},{"text":"Triturar los ingredientes del vaso hasta obtener una pasta homogénea.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva}} en hilo fino mientras se tritura, hasta emulsionar la salsa.","minutes":2,"kind":"activo"},{"text":"Incorporar el queso parmesano rallado y triturar hasta integrarlo por completo.","minutes":1,"kind":"activo"},{"text":"Rectificar de sal al gusto y remover para homogeneizar la salsa antes de servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_019', 'Beurre noisette y salvia', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'normal', 'all', 135, 0, 0, 15, 4, true, false, '{"lactosa"}', '[{"name":"Mantequilla","amount":60,"unit":"g"},{"name":"Salvia fresca","amount":3,"unit":"g"},{"name":"Zumo de limón","amount":5,"unit":"ml"}]'::jsonb, '{"Separar las hojas de salvia fresca de los tallos y reservar.","Calentar mantequilla en un cazo a fuego medio hasta que se funda por completo.","Continuar calentando hasta que la mantequilla tome color avellana y desprenda aroma a frutos secos.","Añadir las hojas de salvia reservadas y freír hasta que crujan, sin apartar la vista.","Retirar el cazo del fuego y añadir zumo de limón para detener la cocción.","Servir templada sobre el plato elegido."}', 'Mantequilla avellanada con salvia crujiente, clásico italiano para pescado blanco o verduras.', NULL, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Separar las hojas de {{Salvia fresca}} de los tallos y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Mantequilla}} en un cazo a fuego medio hasta que se funda por completo.","minutes":2,"kind":"activo"},{"text":"Continuar calentando hasta que la mantequilla tome color avellana y desprenda aroma a frutos secos.","minutes":3,"kind":"activo"},{"text":"Añadir las hojas de salvia reservadas y freír hasta que crujan, sin apartar la vista.","minutes":1,"kind":"activo"},{"text":"Retirar el cazo del fuego y añadir {{Zumo de limón}} para detener la cocción.","minutes":1,"kind":"activo"},{"text":"Servir templada sobre el plato elegido.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_020', 'Naranja y jengibre', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 15, 'facil', 'all', 55, 0, 12, 0, 4, true, true, '{"soja","gluten"}', '[{"name":"Zumo de naranja","amount":100,"unit":"ml"},{"name":"Jengibre fresco rallado","amount":10,"unit":"g"},{"name":"Miel","amount":15,"unit":"g"},{"name":"Salsa de soja","amount":10,"unit":"ml"},{"name":"Maicena","amount":5,"unit":"g"}]'::jsonb, '{"Disolver maicena en 1 cucharada de agua fría hasta obtener una mezcla sin grumos. Reservar.","Verter zumo de naranja en un cazo pequeño y añadir jengibre fresco rallado.","Añadir miel y salsa de soja. Remover hasta integrar.","Llevar a ebullición a fuego medio, luego bajar a fuego suave y cocer 5 min hasta que reduzca ligeramente.","Añadir la mezcla de maicena reservada sin dejar de remover hasta que la salsa espese.","Retirar del fuego y servir caliente como acompañamiento."}', 'Glaseado de naranja y jengibre, agridulce, para pollo, pavo o pescado azul.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Disolver {{Maicena}} en 1 cucharada de agua fría hasta obtener una mezcla sin grumos. Reservar.","minutes":2,"kind":"prep"},{"text":"Verter {{Zumo de naranja}} en un cazo pequeño y añadir {{Jengibre fresco rallado}}.","minutes":1,"kind":"activo"},{"text":"Añadir {{Miel}} y {{Salsa de soja}}. Remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición a fuego medio, luego bajar a fuego suave y cocer 5 min hasta que reduzca ligeramente.","minutes":6,"kind":"pasivo"},{"text":"Añadir la mezcla de maicena reservada sin dejar de remover hasta que la salsa espese.","minutes":2,"kind":"activo"},{"text":"Retirar del fuego y servir caliente como acompañamiento.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_021', 'Alioli de azafrán', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 15, 'normal', 'all', 180, 0, 1, 20, 4, false, true, '{}', '[{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva suave","amount":150,"unit":"ml"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Zumo de limón","amount":5,"unit":"ml"}]'::jsonb, '{"Calentar un poco de agua hasta que esté muy caliente, sin llegar a hervir.","Infusionar azafrán en hebras en el agua caliente durante 5 min hasta que suelte el color.","Pelar ajo y colocarlo en un mortero.","Añadir sal al mortero y machacar el ajo con la sal hasta obtener una pasta fina.","Incorporar aceite de oliva suave en hilo muy fino sobre la pasta de ajo, removiendo sin parar con el mortero.","Añadir el azafrán infusionado con su agua y zumo de limón a la emulsión mientras se remueve.","Remover hasta que la salsa esté homogénea y con un color dorado uniforme.","Servir el alioli en un bol o directamente como acompañamiento."}', 'Alioli con un toque de azafrán, para pescado blanco, marisco o arroz.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Calentar un poco de agua hasta que esté muy caliente, sin llegar a hervir.","minutes":2,"kind":"activo"},{"text":"Infusionar {{Azafrán en hebras}} en el agua caliente durante 5 min hasta que suelte el color.","minutes":5,"kind":"espera"},{"text":"Pelar {{Ajo}} y colocarlo en un mortero.","minutes":1,"kind":"prep"},{"text":"Añadir {{Sal|gusto}} al mortero y machacar el ajo con la sal hasta obtener una pasta fina.","minutes":3,"kind":"activo"},{"text":"Incorporar {{Aceite de oliva suave}} en hilo muy fino sobre la pasta de ajo, removiendo sin parar con el mortero.","minutes":3,"kind":"activo"},{"text":"Añadir el azafrán infusionado con su agua y {{Zumo de limón}} a la emulsión mientras se remueve.","minutes":1,"kind":"activo"},{"text":"Remover hasta que la salsa esté homogénea y con un color dorado uniforme.","minutes":1,"kind":"activo"},{"text":"Servir el alioli en un bol o directamente como acompañamiento.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_023', 'Sésamo, soja y miel', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 90, 2, 10, 4, 4, true, true, '{"soja","sesamo","gluten"}', '[{"name":"Salsa de soja","amount":40,"unit":"ml"},{"name":"Miel","amount":20,"unit":"g"},{"name":"Aceite de sésamo","amount":10,"unit":"ml"},{"name":"Semillas de sésamo","amount":10,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Jengibre fresco rallado","amount":5,"unit":"g"}]'::jsonb, '{"Rallar jengibre fresco rallado con un rallador fino hasta obtener 5 g.","Picar ajo muy fino.","Verter salsa de soja en un cazo pequeño a fuego suave.","Añadir miel y aceite de sésamo al cazo y remover hasta integrar.","Añadir el ajo picado y el jengibre rallado al cazo y remover.","Calentar a fuego suave hasta que la salsa espese ligeramente, sin dejar de remover.","Retirar del fuego y añadir semillas de sésamo removiendo para distribuirlas."}', 'Aliño agridulce de sésamo, soja y miel, para ensaladas, pollo o pescado azul.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Rallar {{Jengibre fresco rallado}} con un rallador fino hasta obtener 5 g.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} muy fino.","minutes":1,"kind":"prep"},{"text":"Verter {{Salsa de soja}} en un cazo pequeño a fuego suave.","minutes":1,"kind":"activo"},{"text":"Añadir {{Miel}} y {{Aceite de sésamo}} al cazo y remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Añadir el ajo picado y el jengibre rallado al cazo y remover.","minutes":1,"kind":"activo"},{"text":"Calentar a fuego suave hasta que la salsa espese ligeramente, sin dejar de remover.","minutes":2,"kind":"activo"},{"text":"Retirar del fuego y añadir {{Semillas de sésamo|gusto}} removiendo para distribuirlas.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_024', 'Roquefort ligera', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 95, 5, 3, 7, 4, false, true, '{"lactosa"}', '[{"name":"Queso roquefort","amount":40,"unit":"g"},{"name":"Yogur griego","amount":100,"unit":"g"},{"name":"Leche","amount":20,"unit":"ml"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Desmenuzar queso roquefort con un tenedor hasta obtener migas finas.","Machacar las migas de roquefort con el tenedor hasta conseguir una pasta lo más homogénea posible.","Añadir yogur griego y leche a la pasta de roquefort.","Mezclar con el tenedor o una varilla hasta obtener una crema fluida y sin grumos.","Añadir pimienta negra y remover para integrar.","Refrigerar la salsa al menos 10 min antes de servir para que asiente el sabor.","Servir la salsa fría como acompañamiento."}', 'Crema ligera de roquefort, para carne roja a la plancha o ensaladas con fruta.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Desmenuzar {{Queso roquefort}} con un tenedor hasta obtener migas finas.","minutes":2,"kind":"prep"},{"text":"Machacar las migas de roquefort con el tenedor hasta conseguir una pasta lo más homogénea posible.","minutes":2,"kind":"activo"},{"text":"Añadir {{Yogur griego}} y {{Leche}} a la pasta de roquefort.","minutes":1,"kind":"activo"},{"text":"Mezclar con el tenedor o una varilla hasta obtener una crema fluida y sin grumos.","minutes":2,"kind":"activo"},{"text":"Añadir {{Pimienta negra|pizca}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Refrigerar la salsa al menos 10 min antes de servir para que asiente el sabor.","minutes":10,"kind":"espera"},{"text":"Servir la salsa fría como acompañamiento.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL)
