insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('salsas_025', 'Mayonesa casera', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'normal', 'all', 190, 1, 0, 21, 4, true, true, '{"huevo"}', '[{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Aceite de girasol","amount":200,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Colocar huevo en el vaso de la batidora sin romper la yema.","Añadir sal y zumo de limón sobre el huevo.","Introducir el brazo de la batidora hasta el fondo del vaso sin moverlo.","Verter aceite de girasol despacio sobre el huevo, cubriéndolo por completo.","Batir a velocidad máxima sin mover el brazo hasta que emulsione la base.","Subir el brazo de la batidora muy despacio hasta que el aceite quede integrado.","Comprobar la textura: debe ser espesa y homogénea; batir 10 segundos más si no ha ligado.","Tapar el vaso y reservar en el frigorífico hasta el momento de servir.","Servir la mayonesa fría en un bol o directamente como acompañamiento."}', 'Mayonesa casera clásica, para pescado, marisco, ensaladas o huevos.', NULL, '{"Mayonesa"}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Colocar {{Huevo}} en el vaso de la batidora sin romper la yema.","minutes":1,"kind":"prep"},{"text":"Añadir {{Sal|gusto}} y {{Zumo de limón}} sobre el huevo.","minutes":1,"kind":"prep"},{"text":"Introducir el brazo de la batidora hasta el fondo del vaso sin moverlo.","minutes":1,"kind":"prep"},{"text":"Verter {{Aceite de girasol}} despacio sobre el huevo, cubriéndolo por completo.","minutes":1,"kind":"prep"},{"text":"Batir a velocidad máxima sin mover el brazo hasta que emulsione la base.","minutes":1,"kind":"activo"},{"text":"Subir el brazo de la batidora muy despacio hasta que el aceite quede integrado.","minutes":2,"kind":"activo"},{"text":"Comprobar la textura: debe ser espesa y homogénea; batir 10 segundos más si no ha ligado.","minutes":1,"kind":"activo"},{"text":"Tapar el vaso y reservar en el frigorífico hasta el momento de servir.","minutes":5,"kind":"espera"},{"text":"Servir la mayonesa fría en un bol o directamente como acompañamiento.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_026', 'Salsa brava', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 20, 'facil', 'all', 45, 1, 5, 2, 4, false, true, '{"gluten"}', '[{"name":"Tomate triturado","amount":150,"unit":"g"},{"name":"Pimentón picante","amount":5,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Cayena","amount":1,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Harina","amount":5,"unit":"g"}]'::jsonb, '{"Picar ajo muy fino.","Calentar aceite de oliva en una sartén a fuego medio.","Sofreír el ajo picado hasta que esté dorado sin quemarse.","Añadir harina y remover sin parar hasta que se tueste ligeramente.","Añadir pimentón picante, pimentón dulce y cayena, removiendo para integrar con la harina.","Incorporar tomate triturado y mezclar bien hasta obtener una salsa homogénea.","Cocer a fuego suave removiendo con frecuencia hasta que la salsa espese y los sabores se integren.","Triturar la salsa con una batidora hasta obtener una textura fina y sin grumos.","Servir caliente como acompañamiento."}', 'La clásica salsa brava española, picante, para patatas, huevos o verduras.', NULL, '{"Salsa brava"}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Ajo}} muy fino.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una sartén a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo picado hasta que esté dorado sin quemarse.","minutes":2,"kind":"activo"},{"text":"Añadir {{Harina}} y remover sin parar hasta que se tueste ligeramente.","minutes":1,"kind":"activo"},{"text":"Añadir {{Pimentón picante}}, {{Pimentón dulce}} y {{Cayena}}, removiendo para integrar con la harina.","minutes":1,"kind":"activo"},{"text":"Incorporar {{Tomate triturado}} y mezclar bien hasta obtener una salsa homogénea.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave removiendo con frecuencia hasta que la salsa espese y los sabores se integren.","minutes":10,"kind":"pasivo"},{"text":"Triturar la salsa con una batidora hasta obtener una textura fina y sin grumos.","minutes":2,"kind":"activo"},{"text":"Servir caliente como acompañamiento.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_027', 'Pesto genovés', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 10, 'facil', 'all', 180, 4, 2, 18, 4, true, true, '{"frutos_secos","lactosa"}', '[{"name":"Albahaca fresca","amount":30,"unit":"g"},{"name":"Piñones","amount":20,"unit":"g"},{"name":"Queso parmesano","amount":20,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":80,"unit":"ml"}]'::jsonb, '{"Rallar queso parmesano con un rallador fino y reservar.","Pelar ajo y retirar el germen interior si lo tiene.","Introducir albahaca fresca, piñones y el ajo pelado en el vaso de la batidora o mortero.","Triturar los ingredientes del vaso hasta obtener una pasta gruesa.","Añadir aceite de oliva en hilo fino mientras se sigue triturando, hasta emulsionar.","Incorporar el queso parmesano rallado y mezclar a mano con una espátula, sin triturar."}', 'Pesto genovés clásico, para ensaladas, pollo a la plancha o pescado blanco.', NULL, '{"Pesto"}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Rallar {{Queso parmesano}} con un rallador fino y reservar.","minutes":2,"kind":"prep"},{"text":"Pelar {{Ajo}} y retirar el germen interior si lo tiene.","minutes":1,"kind":"prep"},{"text":"Introducir {{Albahaca fresca}}, {{Piñones}} y el ajo pelado en el vaso de la batidora o mortero.","minutes":1,"kind":"prep"},{"text":"Triturar los ingredientes del vaso hasta obtener una pasta gruesa.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} en hilo fino mientras se sigue triturando, hasta emulsionar.","minutes":2,"kind":"activo"},{"text":"Incorporar el queso parmesano rallado y mezclar a mano con una espátula, sin triturar.","minutes":1,"kind":"activo"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_028', 'Salsa holandesa', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 20, 'normal', 'all', 210, 2, 0, 23, 4, true, false, '{"huevo","lactosa"}', '[{"name":"Yema de huevo","amount":2,"unit":"ud"},{"name":"Mantequilla","amount":100,"unit":"g"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Agua","amount":15,"unit":"ml"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Fundir mantequilla en un cazo a fuego suave hasta que esté completamente líquida, sin que llegue a dorarse.","Retirar la mantequilla fundida del fuego y reservar templada.","Llenar un cazo amplio con agua hasta la mitad y llevar a ebullición; bajar a fuego suave para mantener el vapor.","Colocar un bol resistente al calor sobre el cazo sin que toque el agua; verter yema de huevo y agua.","Batir las yemas con el agua al baño maría de forma continua hasta que la mezcla espese y deje trazo al levantar las varillas.","Retirar el bol del baño maría y colocarlo sobre una superficie estable.","Añadir la mantequilla templada en hilo muy fino sin dejar de batir hasta que la salsa emulsione y quede cremosa.","Añadir zumo de limón y sal; remover para integrar.","Servir de inmediato o mantener templada al baño maría tapada, sin superar 60 °C para que no se corte."}', 'Salsa holandesa clásica, para espárragos, verduras al vapor o pescado blanco.', NULL, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Fundir {{Mantequilla}} en un cazo a fuego suave hasta que esté completamente líquida, sin que llegue a dorarse.","minutes":3,"kind":"activo"},{"text":"Retirar la mantequilla fundida del fuego y reservar templada.","minutes":1,"kind":"prep"},{"text":"Llenar un cazo amplio con agua hasta la mitad y llevar a ebullición; bajar a fuego suave para mantener el vapor.","minutes":3,"kind":"activo"},{"text":"Colocar un bol resistente al calor sobre el cazo sin que toque el agua; verter {{Yema de huevo}} y {{Agua}}.","minutes":1,"kind":"prep"},{"text":"Batir las yemas con el agua al baño maría de forma continua hasta que la mezcla espese y deje trazo al levantar las varillas.","minutes":4,"kind":"activo"},{"text":"Retirar el bol del baño maría y colocarlo sobre una superficie estable.","minutes":1,"kind":"activo"},{"text":"Añadir la mantequilla templada en hilo muy fino sin dejar de batir hasta que la salsa emulsione y quede cremosa.","minutes":3,"kind":"activo"},{"text":"Añadir {{Zumo de limón}} y {{Sal|gusto}}; remover para integrar.","minutes":1,"kind":"activo"},{"text":"Servir de inmediato o mantener templada al baño maría tapada, sin superar 60 °C para que no se corte.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_029', 'Bechamel', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 20, 'facil', 'all', 90, 2, 6, 6, 4, true, true, '{"gluten","lactosa"}', '[{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Harina","amount":30,"unit":"g"},{"name":"Leche","amount":400,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Medir harina y reservar en un cuenco pequeño.","Fundir mantequilla en un cazo a fuego medio hasta que esté completamente líquida.","Añadir la harina reservada de golpe y remover sin parar con una varilla durante 2 min hasta que la mezcla esté seca y sin color.","Verter leche poco a poco, en 3 o 4 tandas, removiendo sin parar con la varilla después de cada adición.","Cocer a fuego suave, removiendo con frecuencia, hasta que la bechamel espese y cubra el dorso de una cuchara.","Añadir sal y nuez moscada, remover y retirar del fuego."}', 'Bechamel clásica, para gratinar verduras o napar huevos y croquetas.', NULL, '{"Bechamel"}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Medir {{Harina}} y reservar en un cuenco pequeño.","minutes":1,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en un cazo a fuego medio hasta que esté completamente líquida.","minutes":2,"kind":"activo"},{"text":"Añadir la harina reservada de golpe y remover sin parar con una varilla durante 2 min hasta que la mezcla esté seca y sin color.","minutes":2,"kind":"activo"},{"text":"Verter {{Leche}} poco a poco, en 3 o 4 tandas, removiendo sin parar con la varilla después de cada adición.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego suave, removiendo con frecuencia, hasta que la bechamel espese y cubra el dorso de una cuchara.","minutes":8,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y {{Nuez moscada|pizca}}, remover y retirar del fuego.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('salsas_030', 'Salsa de Pedro Ximénez', 'salsas', 'none', NULL, ARRAY['salsa']::meal_role[], 'salsa', NULL, NULL, 25, 'normal', 'all', 140, 0, 18, 5, 4, false, true, '{"sulfitos","lactosa"}', '[{"name":"Vino Pedro Ximénez","amount":200,"unit":"ml"},{"name":"Chalota","amount":30,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Sal","amount":1,"unit":"g"}]'::jsonb, '{"Picar chalota muy fina.","Calentar mantequilla en un cazo a fuego suave hasta que se funda.","Sofreír la chalota picada en la mantequilla fundida a fuego suave hasta que esté transparente y blanda.","Añadir vino pedro ximénez y subir a fuego medio.","Reducir a fuego medio hasta que la salsa espese y tenga textura de jarabe.","Añadir sal y remover para integrar.","Colar la salsa por un colador fino para obtener una textura más lisa.","Servir la salsa caliente sobre el plato elegido."}', 'Reducción de vino Pedro Ximénez, dulce y untuosa: la clásica salsa de solomillo.', NULL, '{}', true, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Chalota}} muy fina.","minutes":3,"kind":"prep"},{"text":"Calentar {{Mantequilla}} en un cazo a fuego suave hasta que se funda.","minutes":2,"kind":"activo"},{"text":"Sofreír la chalota picada en la mantequilla fundida a fuego suave hasta que esté transparente y blanda.","minutes":5,"kind":"activo"},{"text":"Añadir {{Vino Pedro Ximénez}} y subir a fuego medio.","minutes":1,"kind":"activo"},{"text":"Reducir a fuego medio hasta que la salsa espese y tenga textura de jarabe.","minutes":15,"kind":"pasivo"},{"text":"Añadir {{Sal|gusto}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Colar la salsa por un colador fino para obtener una textura más lisa.","minutes":2,"kind":"opcional"},{"text":"Servir la salsa caliente sobre el plato elegido.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL),
  ('sopas_cremas_001', 'Crema de calabacín', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 168, 4, 14, 10, 2, true, true, '{"lactosa"}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Quesito en porciones","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Pelar patata y cortar en dados de 2 cm aproximadamente.","Lavar calabacín y cortar en rodajas de 1 cm sin pelar.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada hasta que esté transparente, unos 4 min a fuego medio.","Añadir el calabacín y la patata a la olla y remover para mezclar con el sofrito.","Cubrir las verduras con agua fría hasta sobrepasarlas 2 cm y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que la patata y el calabacín estén tiernos, unos 15 min.","Retirar del fuego y añadir quesito en porciones al caldo con las verduras.","Triturar el conjunto con una batidora de mano hasta obtener una textura fina y homogénea.","Servir la crema bien caliente en boles, ajustando la textura con un poco de agua si fuera necesario."}', 'Crema suave de calabacín con patata y quesito', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla, añade el resto de verduras troceadas con agua o caldo y cocina a temperatura Varoma durante 20 minutos. Tritura a velocidad progresiva hasta obtener una crema fina, incorporando el quesito al final."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla en la olla, añade el resto de verduras troceadas con agua o caldo. Cierra y cocina a presión durante 5-7 minutos. Una vez despresurizada, tritura hasta obtener una crema fina y añade el quesito."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Cebolla}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados de 2 cm aproximadamente.","minutes":2,"kind":"prep"},{"text":"Lavar {{Calabacín}} y cortar en rodajas de 1 cm sin pelar.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada hasta que esté transparente, unos 4 min a fuego medio.","minutes":4,"kind":"activo"},{"text":"Añadir el calabacín y la patata a la olla y remover para mezclar con el sofrito.","minutes":1,"kind":"activo"},{"text":"Cubrir las verduras con agua fría hasta sobrepasarlas 2 cm y llevar a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la patata y el calabacín estén tiernos, unos 15 min.","minutes":15,"kind":"pasivo"},{"text":"Retirar del fuego y añadir {{Quesito en porciones}} al caldo con las verduras.","minutes":1,"kind":"activo"},{"text":"Triturar el conjunto con una batidora de mano hasta obtener una textura fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Servir la crema bien caliente en boles, ajustando la textura con un poco de agua si fuera necesario.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_002', 'Sopa de fideos', 'sopas_cremas', 'none', 'pasta', ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'invierno', 182, 6, 28, 4, 2, true, true, '{"gluten"}', '[{"name":"Fideos finos","amount":80,"unit":"g"},{"name":"Caldo de pollo","amount":600,"unit":"ml"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Pelar y rallar zanahoria con un rallador fino. Reservar.","Verter caldo de pollo en una olla y llevar a ebullición a fuego fuerte.","Añadir la zanahoria rallada al caldo cuando rompa a hervir. Remover.","Incorporar fideos finos y cocer a fuego medio hasta que estén tiernos, unos 5 min.","Picar perejil fino mientras cuecen los fideos.","Retirar la olla del fuego. Repartir la sopa en 2 boles.","Añadir aceite de oliva sobre cada bol y espolvorear el perejil picado. Servir."}', 'Sopa caliente de fideos finos en caldo de pollo', '[{"appliance":"thermomix","time":18,"difficulty":"facil","prepSummary":"Pica la zanahoria 3 seg/vel 5. Sofríe con aceite 3 min/120°C/vel 1. Añade el caldo y los fideos, cocina 12 min/100°C/giro inverso/vel cuchara. Sirve con perejil."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Sofríe la zanahoria en la olla con aceite. Añade el caldo y los fideos, cierra la olla y cocina 3-4 minutos desde que sube la válvula. Despresuriza y sirve con perejil."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['pollo']::main_protein[], false, '[{"text":"Pelar y rallar {{Zanahoria}} con un rallador fino. Reservar.","minutes":2,"kind":"prep"},{"text":"Verter {{Caldo de pollo}} en una olla y llevar a ebullición a fuego fuerte.","minutes":4,"kind":"activo"},{"text":"Añadir la zanahoria rallada al caldo cuando rompa a hervir. Remover.","minutes":1,"kind":"activo"},{"text":"Incorporar {{Fideos finos}} y cocer a fuego medio hasta que estén tiernos, unos 5 min.","minutes":5,"kind":"pasivo"},{"text":"Picar {{Perejil}} fino mientras cuecen los fideos.","minutes":2,"kind":"paralelo","during":3},{"text":"Retirar la olla del fuego. Repartir la sopa en 2 boles.","minutes":1,"kind":"emplatado"},{"text":"Añadir {{Aceite de oliva|chorrito}} sobre cada bol y espolvorear el perejil picado. Servir.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_003', 'Crema de calabaza', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'invierno', 178, 3, 22, 8, 2, true, true, '{}', '[{"name":"Calabaza","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Nuez moscada","amount":2,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Pelar calabaza y cortar en trozos de unos 3 cm.","Pelar patata y cortar en trozos similares a la calabaza.","Pelar zanahoria y cortar en rodajas de 1 cm.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada a fuego medio hasta que esté transparente, unos 4 min.","Añadir la calabaza, la patata y la zanahoria a la olla y remover para mezclar con el sofrito.","Cubrir las verduras con agua fría hasta superarlas 2 cm y llevar a ebullición a fuego fuerte.","Tapar la olla y cocer a fuego suave hasta que la calabaza y la patata estén tiernas, unos 18 min.","Retirar la olla del fuego y escurrir parte del caldo, reservándolo en un bol aparte.","Añadir nuez moscada a las verduras y triturar con una batidora hasta obtener una textura cremosa y homogénea.","Incorporar el caldo reservado poco a poco hasta alcanzar la consistencia deseada y remover bien.","Servir la crema caliente en cuencos."}', 'Crema de calabaza con zanahoria y un toque de nuez moscada', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Asa las verduras troceadas con un chorrito de aceite de oliva en el horno precalentado a 200°C durante 30-40 minutos, hasta que estén muy tiernas y ligeramente doradas. Luego, tritura con caldo caliente hasta obtener una crema suave y con un sabor más profundo."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Trocea las verduras en la Thermomix y sofríelas con aceite. Añade agua o caldo y cocina a 100°C, velocidad cuchara, durante 20-25 minutos. Finalmente, tritura a velocidad progresiva hasta obtener una crema fina y homogénea."},{"appliance":"vaporera","time":35,"difficulty":"facil","prepSummary":"Cocina las verduras troceadas en la vaporera hasta que estén muy tiernas (aproximadamente 25-30 minutos). Después, tritura con un poco del agua de cocción o caldo caliente y un chorrito de aceite de oliva para una crema ligera y nutritiva."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla express con aceite. Añade agua o caldo, cierra la olla y cocina a presión durante 5-7 minutos desde que sube la válvula. Libera la presión y tritura hasta obtener una crema homogénea en tiempo récord."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Cebolla}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Pelar {{Calabaza}} y cortar en trozos de unos 3 cm.","minutes":3,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en trozos similares a la calabaza.","minutes":2,"kind":"prep"},{"text":"Pelar {{Zanahoria}} y cortar en rodajas de 1 cm.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una olla a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada a fuego medio hasta que esté transparente, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir la calabaza, la patata y la zanahoria a la olla y remover para mezclar con el sofrito.","minutes":1,"kind":"activo"},{"text":"Cubrir las verduras con agua fría hasta superarlas 2 cm y llevar a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Tapar la olla y cocer a fuego suave hasta que la calabaza y la patata estén tiernas, unos 18 min.","minutes":18,"kind":"pasivo"},{"text":"Retirar la olla del fuego y escurrir parte del caldo, reservándolo en un bol aparte.","minutes":1,"kind":"activo"},{"text":"Añadir {{Nuez moscada|pizca}} a las verduras y triturar con una batidora hasta obtener una textura cremosa y homogénea.","minutes":2,"kind":"activo"},{"text":"Incorporar el caldo reservado poco a poco hasta alcanzar la consistencia deseada y remover bien.","minutes":1,"kind":"activo"},{"text":"Servir la crema caliente en cuencos.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_004', 'Gazpacho andaluz', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 152, 3, 12, 10, 2, true, true, '{"gluten","sulfitos"}', '[{"name":"Tomate maduro","amount":500,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Pimiento verde","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Pan del día anterior","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de Jerez","amount":15,"unit":"ml"}]'::jsonb, '{"Cortar tomate maduro en trozos grandes y reservar en el vaso de la batidora.","Pelar pepino, cortar en trozos y añadir al vaso.","Retirar las semillas de pimiento verde, cortar en trozos y añadir al vaso.","Pelar ajo y añadir al vaso.","Sumergir pan del día anterior en agua fría durante 2 min hasta que se ablande, escurrir y añadir al vaso.","Triturar todos los ingredientes del vaso a potencia máxima durante 2 min hasta obtener una crema fina y homogénea.","Añadir aceite de oliva y vinagre de jerez al vaso y triturar 30 segundos más hasta que estén integrados.","Pasar la crema por un colador fino presionando con una cuchara hasta que escurra todo el líquido; descartar los sólidos.","Refrigerar el gazpacho en la nevera hasta que esté muy frío, mínimo 30 min antes de servir.","Servir el gazpacho bien frío en cuencos o vasos."}', 'Sopa fría de tomate, pepino y pimiento al estilo andaluz', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para el gazpacho. Introduce todos los ingredientes troceados y tritura a velocidad progresiva 1-10 durante 2-3 minutos hasta obtener una textura muy fina. Sirve bien frío."}]'::jsonb, '{"Gazpacho"}', NULL, true, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Tomate maduro}} en trozos grandes y reservar en el vaso de la batidora.","minutes":2,"kind":"prep"},{"text":"Pelar {{Pepino}}, cortar en trozos y añadir al vaso.","minutes":1,"kind":"prep"},{"text":"Retirar las semillas de {{Pimiento verde}}, cortar en trozos y añadir al vaso.","minutes":1,"kind":"prep"},{"text":"Pelar {{Ajo}} y añadir al vaso.","minutes":1,"kind":"prep"},{"text":"Sumergir {{Pan del día anterior}} en agua fría durante 2 min hasta que se ablande, escurrir y añadir al vaso.","minutes":2,"kind":"espera"},{"text":"Triturar todos los ingredientes del vaso a potencia máxima durante 2 min hasta obtener una crema fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} y {{Vinagre de Jerez}} al vaso y triturar 30 segundos más hasta que estén integrados.","minutes":1,"kind":"activo"},{"text":"Pasar la crema por un colador fino presionando con una cuchara hasta que escurra todo el líquido; descartar los sólidos.","minutes":3,"kind":"activo"},{"text":"Refrigerar el gazpacho en la nevera hasta que esté muy frío, mínimo 30 min antes de servir.","minutes":30,"kind":"espera"},{"text":"Servir el gazpacho bien frío en cuencos o vasos.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'crudo', NULL, NULL)
