insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('sopas_cremas_005', 'Salmorejo cordobés', 'sopas_cremas', 'none', 'pan', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 10, 'facil', 'verano', 228, 5, 18, 16, 2, true, true, '{"gluten","huevo","sulfitos"}', '[{"name":"Tomate maduro","amount":500,"unit":"g"},{"name":"Pan del día anterior","amount":80,"unit":"g"},{"name":"Aceite de oliva","amount":50,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Jamón serrano","amount":20,"unit":"g"},{"name":"Huevo cocido","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar tomate maduro en trozos grandes y reservar en el vaso de la batidora.","Cortar pan del día anterior en trozos y añadir al vaso junto con los tomates.","Añadir ajo, vinagre de jerez y triturar a máxima potencia hasta que la mezcla esté completamente lisa.","Añadir aceite de oliva en hilo fino y continuo mientras la batidora sigue funcionando a velocidad media, hasta que emulsione.","Refrigerar el salmorejo en la nevera hasta que esté bien frío.","Picar jamón serrano en trozos pequeños y reservar.","Picar huevo cocido en trozos pequeños y reservar.","Servir el salmorejo en cuencos y repartir por encima el jamón picado y el huevo cocido picado."}', 'Crema fría espesa de tomate y pan con jamón y huevo', '[{"appliance":"thermomix","time":10,"difficulty":"facil","prepSummary":"Introduce los tomates, pan, ajo, vinagre y sal en el vaso y tritura a velocidad progresiva hasta obtener una crema muy fina. Añade el aceite en hilo mientras sigues batiendo a velocidad media para mezclar bien perfectamente."}]'::jsonb, '{"Salmorejo"}', NULL, true, NULL, '{"verdura"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Cortar {{Tomate maduro}} en trozos grandes y reservar en el vaso de la batidora.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pan del día anterior}} en trozos y añadir al vaso junto con los tomates.","minutes":1,"kind":"prep"},{"text":"Añadir {{Ajo}}, {{Vinagre de Jerez}} y triturar a máxima potencia hasta que la mezcla esté completamente lisa.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} en hilo fino y continuo mientras la batidora sigue funcionando a velocidad media, hasta que emulsione.","minutes":1,"kind":"activo"},{"text":"Refrigerar el salmorejo en la nevera hasta que esté bien frío.","minutes":60,"kind":"espera"},{"text":"Picar {{Jamón serrano}} en trozos pequeños y reservar.","minutes":1,"kind":"prep"},{"text":"Picar {{Huevo cocido}} en trozos pequeños y reservar.","minutes":1,"kind":"prep"},{"text":"Servir el salmorejo en cuencos y repartir por encima el jamón picado y el huevo cocido picado.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'crudo', NULL, NULL),
  ('sopas_cremas_006', 'Crema de zanahoria', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 158, 3, 18, 8, 2, true, true, '{}', '[{"name":"Zanahoria","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Jengibre fresco","amount":5,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Pelar zanahoria y cortar en rodajas de 1 cm.","Pelar patata y cortar en dados de 2 cm.","Pelar jengibre fresco y picar fino.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente, unos 3 min.","Añadir la zanahoria, la patata y el jengibre picado; remover 1 min para integrar.","Cubrir con agua fría hasta sobrepasar las verduras unos 2 cm y llevar a ebullición.","Tapar y cocer a fuego suave hasta que la zanahoria y la patata estén tiernas.","Retirar del fuego y triturar con un batidor de mano hasta obtener una crema lisa y homogénea.","Servir la crema en boles calientes."}', 'Crema suave de zanahoria con un toque de jengibre', '[{"appliance":"horno","time":50,"difficulty":"facil","prepSummary":"Asa las zanahorias, patatas y cebolla con el aceite y jengibre a 200°C durante 25-30 minutos para intensificar su sabor. Luego, hierve brevemente con agua o caldo y tritura hasta obtener una crema suave."},{"appliance":"thermomix","time":30,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el jengibre con el aceite, añade las zanahorias y patatas, cubre con agua o caldo y cocina a 100°C, velocidad cuchara, durante 20-25 minutos. Finalmente, tritura a velocidad progresiva hasta obtener una crema fina."},{"appliance":"vaporera","time":35,"difficulty":"facil","prepSummary":"Cocina al vapor las zanahorias, patatas, cebolla y jengibre hasta que estén muy tiernas, unos 25-30 minutos. Luego, tritura los vegetales con el aceite de oliva y un poco de agua o caldo hasta conseguir la textura deseada."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el jengibre en la olla, añade las zanahorias y patatas, cubre con agua o caldo. Cierra la olla y cocina 5-7 minutos desde que sube la válvula. Despresuriza y tritura hasta obtener una crema homogénea."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Cebolla}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Pelar {{Zanahoria}} y cortar en rodajas de 1 cm.","minutes":3,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados de 2 cm.","minutes":2,"kind":"prep"},{"text":"Pelar {{Jengibre fresco}} y picar fino.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada hasta que esté transparente, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Añadir la zanahoria, la patata y el jengibre picado; remover 1 min para integrar.","minutes":1,"kind":"activo"},{"text":"Cubrir con agua fría hasta sobrepasar las verduras unos 2 cm y llevar a ebullición.","minutes":3,"kind":"activo"},{"text":"Tapar y cocer a fuego suave hasta que la zanahoria y la patata estén tiernas.","minutes":15,"kind":"pasivo"},{"text":"Retirar del fuego y triturar con un batidor de mano hasta obtener una crema lisa y homogénea.","minutes":2,"kind":"activo"},{"text":"Servir la crema en boles calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_007', 'Sopa castellana', 'sopas_cremas', 'huevo', 'pan', ARRAY['primero','plato_unico']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'invierno', 248, 12, 22, 12, 2, true, false, '{"gluten","huevo"}', '[{"name":"Pan del día anterior","amount":80,"unit":"g"},{"name":"Ajo","amount":12,"unit":"g"},{"name":"Pimentón","amount":6,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de carne","amount":500,"unit":"ml"}]'::jsonb, '{"Pelar ajo y laminar finamente.","Cortar jamón serrano en tiras o tacos pequeños.","Cortar pan del día anterior en rebanadas de 1 cm.","Calentar aceite de oliva en una cazuela de barro o olla a fuego medio.","Sofreír el ajo laminado hasta que se dore ligeramente; retirar si se dora demasiado rápido.","Añadir el jamón serrano y saltear 1 min hasta que suelte su grasa.","Retirar la cazuela del fuego, añadir pimentón y remover rápido para que no se queme.","Incorporar las rebanadas de pan y remover para que se impregnen bien del sofrito.","Verter caldo de carne caliente, llevar a ebullición y reducir a fuego suave.","Cocer a fuego suave, tapado, hasta que el pan se deshaga y la sopa espese.","Precalentar el horno a 200 °C con calor arriba y abajo.","Cascar huevo uno a uno sobre la sopa directamente en la cazuela apta para horno.","Hornear la cazuela a 200 °C hasta que la clara cuaje pero la yema quede ligeramente líquida.","Retirar del horno con cuidado y servir la sopa castellana directamente en la cazuela."}', 'Sopa de ajo con pan, jamón y huevo escalfado', '[{"appliance":"horno","time":30,"difficulty":"facil","prepSummary":"En una cazuela apta para horno, sofríe el ajo y el jamón. Añade el pimentón y el caldo, luego hornea a 180°C durante 20 minutos para que los sabores se integren, añadiendo los huevos al final para que se escalfen con el calor residual."},{"appliance":"olla_express","time":22,"difficulty":"facil","prepSummary":"Sofríe el ajo y el jamón en la olla abierta. Añade el pimentón, el pan y el caldo, cierra la olla y cocina 5 minutos desde que suba la válvula. Despresuriza, abre y escalfa los huevos con el calor residual."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], true, '[{"text":"Pelar {{Ajo}} y laminar finamente.","minutes":2,"kind":"prep"},{"text":"Cortar {{Jamón serrano}} en tiras o tacos pequeños.","minutes":1,"kind":"prep"},{"text":"Cortar {{Pan del día anterior}} en rebanadas de 1 cm.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela de barro o olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo laminado hasta que se dore ligeramente; retirar si se dora demasiado rápido.","minutes":2,"kind":"activo"},{"text":"Añadir el jamón serrano y saltear 1 min hasta que suelte su grasa.","minutes":1,"kind":"activo"},{"text":"Retirar la cazuela del fuego, añadir {{Pimentón|pizca}} y remover rápido para que no se queme.","minutes":1,"kind":"activo"},{"text":"Incorporar las rebanadas de pan y remover para que se impregnen bien del sofrito.","minutes":1,"kind":"activo"},{"text":"Verter {{Caldo de carne}} caliente, llevar a ebullición y reducir a fuego suave.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego suave, tapado, hasta que el pan se deshaga y la sopa espese.","minutes":8,"kind":"pasivo"},{"text":"Precalentar el horno a 200 °C con calor arriba y abajo.","minutes":5,"kind":"paralelo","during":9},{"text":"Cascar {{Huevo}} uno a uno sobre la sopa directamente en la cazuela apta para horno.","minutes":1,"kind":"activo"},{"text":"Hornear la cazuela a 200 °C hasta que la clara cuaje pero la yema quede ligeramente líquida.","minutes":5,"kind":"pasivo"},{"text":"Retirar del horno con cuidado y servir la sopa castellana directamente en la cazuela.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_008', 'Vichyssoise', 'sopas_cremas', 'none', 'patatas', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'verano', 192, 4, 22, 10, 2, true, true, '{"lactosa"}', '[{"name":"Puerro","amount":250,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Nata","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar y cortar puerro en rodajas finas, desechando la parte verde más oscura.","Pelar y cortar cebolla en trozos medianos.","Pelar y cortar patata en dados de unos 2 cm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír el puerro y la cebolla en la olla hasta que estén blandos y transparentes, sin que se doren.","Añadir la patata a la olla y cubrir con agua fría hasta superar los ingredientes unos 2 cm.","Llevar a ebullición a fuego fuerte; cuando rompa a hervir, reducir a fuego medio y cocer hasta que la patata esté tierna.","Retirar la olla del fuego y triturar el contenido con un batidor de mano hasta obtener una crema completamente fina.","Añadir nata a la crema y remover hasta que quede integrada de forma homogénea.","Dejar enfriar la crema a temperatura ambiente y después refrigerar en la nevera hasta que esté bien fría.","Servir la vichyssoise bien fría en boles o tazas."}', 'Crema fría de puerro y patata con nata', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para la Vichyssoise, ya que sofríe, cocina y tritura en un solo recipiente. Sofríe las verduras 5 min a 120°C, luego añade patatas y agua, cocina 15 min a 100°C y tritura progresivamente hasta obtener una crema fina con la nata."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"La olla express reduce drásticamente el tiempo de cocción de las verduras. Sofríe los puerros y cebolla en la olla, añade las patatas y agua, cierra y cocina 7-10 minutos a presión, luego tritura con la nata hasta lograr una crema suave."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar y cortar {{Puerro}} en rodajas finas, desechando la parte verde más oscura.","minutes":3,"kind":"prep"},{"text":"Pelar y cortar {{Cebolla}} en trozos medianos.","minutes":2,"kind":"prep"},{"text":"Pelar y cortar {{Patata}} en dados de unos 2 cm.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el puerro y la cebolla en la olla hasta que estén blandos y transparentes, sin que se doren.","minutes":8,"kind":"activo"},{"text":"Añadir la patata a la olla y cubrir con agua fría hasta superar los ingredientes unos 2 cm.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición a fuego fuerte; cuando rompa a hervir, reducir a fuego medio y cocer hasta que la patata esté tierna.","minutes":20,"kind":"pasivo"},{"text":"Retirar la olla del fuego y triturar el contenido con un batidor de mano hasta obtener una crema completamente fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nata}} a la crema y remover hasta que quede integrada de forma homogénea.","minutes":1,"kind":"activo"},{"text":"Dejar enfriar la crema a temperatura ambiente y después refrigerar en la nevera hasta que esté bien fría.","minutes":120,"kind":"espera"},{"text":"Servir la vichyssoise bien fría en boles o tazas.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_009', 'Crema de puerros', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'invierno', 172, 4, 18, 8, 2, true, true, '{}', '[{"name":"Puerro","amount":300,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en dados de 2 cm.","Retirar la raíz y las hojas exteriores duras de puerro.","Cortar la parte blanca y verde claro del puerro en rodajas de 1 cm.","Pelar cebolla y picar en trozos medianos.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír el puerro y la cebolla en el aceite caliente a fuego medio, removiendo de vez en cuando, hasta que estén blandos y transparentes.","Añadir los dados de patata a la olla y remover para integrar con el sofrito.","Cubrir las verduras con 400 ml de agua fría y llevar a ebullición a fuego fuerte.","Bajar a fuego suave, tapar la olla y cocer hasta que la patata esté tierna.","Retirar la olla del fuego y triturar el contenido con un túrmix hasta obtener una textura cremosa y homogénea.","Servir la crema caliente en boles."}', 'Crema caliente de puerros con patata', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Sofríe las verduras picadas con aceite 5 min/120°C/vel 1. Añade agua o caldo y cocina 15 min/100°C/vel 1. Tritura progresivamente 1 min/vel 5-10 hasta obtener una crema fina y homogénea."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla con aceite. Añade agua o caldo hasta cubrir, cierra la olla y cocina 5-7 minutos desde que sube la válvula. Despresuriza y tritura hasta obtener una crema suave."}]'::jsonb, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y cortar en dados de 2 cm.","minutes":3,"kind":"prep"},{"text":"Retirar la raíz y las hojas exteriores duras de {{Puerro}}.","minutes":1,"kind":"prep"},{"text":"Cortar la parte blanca y verde claro del puerro en rodajas de 1 cm.","minutes":2,"kind":"prep"},{"text":"Pelar {{Cebolla}} y picar en trozos medianos.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el puerro y la cebolla en el aceite caliente a fuego medio, removiendo de vez en cuando, hasta que estén blandos y transparentes.","minutes":5,"kind":"activo"},{"text":"Añadir los dados de patata a la olla y remover para integrar con el sofrito.","minutes":1,"kind":"activo"},{"text":"Cubrir las verduras con 400 ml de agua fría y llevar a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Bajar a fuego suave, tapar la olla y cocer hasta que la patata esté tierna.","minutes":12,"kind":"pasivo"},{"text":"Retirar la olla del fuego y triturar el contenido con un túrmix hasta obtener una textura cremosa y homogénea.","minutes":2,"kind":"activo"},{"text":"Servir la crema caliente en boles.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_010', 'Sopa de cebolla', 'sopas_cremas', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, 'horno', 40, 'facil', 'invierno', 218, 8, 22, 10, 2, false, false, '{"gluten","lactosa"}', '[{"name":"Cebolla","amount":400,"unit":"g"},{"name":"Caldo de carne","amount":500,"unit":"ml"},{"name":"Pan","amount":60,"unit":"g"},{"name":"Queso gruyère","amount":40,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Vino blanco","amount":40,"unit":"ml"}]'::jsonb, '{"Laminar cebolla en juliana fina.","Calentar mantequilla en una olla a fuego medio hasta que se funda.","Añadir la cebolla laminada a la olla y sofreír a fuego suave, removiendo con frecuencia, hasta que esté dorada y muy tierna.","Incorporar vino blanco y remover hasta que se evapore el alcohol.","Añadir caldo de carne, llevar a ebullición y cocer a fuego suave hasta que la sopa esté sabrosa y bien integrada.","Cortar pan en rebanadas y tostar en el horno a 180 °C hasta que estén doradas y crujientes.","Rallar queso gruyère finamente.","Distribuir la sopa en cazuelas individuales aptas para horno y colocar las rebanadas de pan tostado encima.","Cubrir la superficie de cada cazuela con el queso gruyère rallado y gratinar en el horno a 200 °C hasta que el queso esté fundido y dorado.","Servir las cazuelas inmediatamente, con cuidado de no quemarse."}', 'Sopa de cebolla caramelizada gratinada con queso', '[{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Comienza caramelizando las cebollas lentamente en una olla a fuego medio-bajo. Luego, añade el vino y el caldo, y cocina a fuego suave. Sirve la sopa en cuencos individuales aptos para horno, cubre con el pan y el queso, y gratina a 200°C durante 5-10 minutos hasta que el queso esté fundido y dorado."},{"appliance":"thermomix","time":45,"difficulty":"facil","prepSummary":"Pica las cebollas y sofríelas con la mantequilla a 120°C, velocidad cuchara, durante 20 minutos. Añade el vino y el caldo, y cocina a 100°C, velocidad cuchara, durante 15 minutos. Sirve la sopa en cuencos aptos para horno, cubre con pan y queso, y gratina en el horno precalentado a 200°C durante 5-10 minutos hasta que el queso se funda y dore."},{"appliance":"olla_express","time":40,"difficulty":"normal","prepSummary":"Sofríe las cebollas con la mantequilla en la olla express abierta a fuego medio hasta que estén bien caramelizadas (aprox. 15-20 min). Añade el vino y el caldo, cierra la olla y cocina a presión durante 10-12 minutos. Sirve la sopa en cuencos individuales, cubre con pan y queso, y gratina en el horno a 200°C durante 5-10 minutos hasta que el queso se funda y dore."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Laminar {{Cebolla}} en juliana fina.","minutes":5,"kind":"prep"},{"text":"Calentar {{Mantequilla}} en una olla a fuego medio hasta que se funda.","minutes":2,"kind":"activo"},{"text":"Añadir la cebolla laminada a la olla y sofreír a fuego suave, removiendo con frecuencia, hasta que esté dorada y muy tierna.","minutes":20,"kind":"activo"},{"text":"Incorporar {{Vino blanco}} y remover hasta que se evapore el alcohol.","minutes":3,"kind":"activo"},{"text":"Añadir {{Caldo de carne}}, llevar a ebullición y cocer a fuego suave hasta que la sopa esté sabrosa y bien integrada.","minutes":15,"kind":"pasivo"},{"text":"Cortar {{Pan}} en rebanadas y tostar en el horno a 180 °C hasta que estén doradas y crujientes.","minutes":8,"kind":"paralelo","during":4},{"text":"Rallar {{Queso gruyère}} finamente.","minutes":2,"kind":"paralelo","during":4},{"text":"Distribuir la sopa en cazuelas individuales aptas para horno y colocar las rebanadas de pan tostado encima.","minutes":2,"kind":"emplatado"},{"text":"Cubrir la superficie de cada cazuela con el queso gruyère rallado y gratinar en el horno a 200 °C hasta que el queso esté fundido y dorado.","minutes":5,"kind":"activo"},{"text":"Servir las cazuelas inmediatamente, con cuidado de no quemarse.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'horno', NULL, NULL),
  ('sopas_cremas_011', 'Crema de verduras', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 148, 4, 16, 8, 2, true, true, '{}', '[{"name":"Calabacín","amount":150,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Limpiar puerro y cortar en rodajas finas.","Pelar zanahoria y cortar en rodajas de 1 cm.","Pelar patata y cortar en trozos medianos.","Cortar calabacín en trozos medianos, sin pelar.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada y el puerro en rodajas hasta que estén blandos y translúcidos, unos 5 min.","Añadir la zanahoria, la patata y el calabacín a la olla y remover para integrar con el sofrito.","Cubrir las verduras con agua fría hasta superarlas 2 cm y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que la patata y la zanahoria estén tiernas, unos 15 min.","Retirar la olla del fuego y triturar todas las verduras con el caldo hasta obtener una textura fina y homogénea.","Servir la crema caliente en boles."}', 'Crema suave de verduras variadas con patata', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica las verduras, sofríelas con el aceite, añade agua o caldo y cocina a 100°C durante 15-20 minutos. Luego, tritura a velocidad progresiva hasta obtener una crema fina."},{"appliance":"vaporera","time":25,"difficulty":"facil","prepSummary":"Corta las verduras y cocínalas al vapor hasta que estén muy tiernas (aprox. 15-20 min). Luego, tritura con un poco de agua o caldo y el aceite de oliva hasta obtener una crema suave."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el puerro en la olla. Añade el resto de verduras, agua o caldo y cocina a presión alta durante 5-7 minutos. Libera la presión y tritura con el aceite de oliva."},{"appliance":"microondas","time":20,"difficulty":"facil","prepSummary":"Corta las verduras y cocínalas en un recipiente apto para microondas con un poco de agua durante 10-15 minutos a máxima potencia hasta que estén tiernas. Luego, tritura con el aceite de oliva y un poco de líquido de cocción."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Cebolla}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Limpiar {{Puerro}} y cortar en rodajas finas.","minutes":2,"kind":"prep"},{"text":"Pelar {{Zanahoria}} y cortar en rodajas de 1 cm.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en trozos medianos.","minutes":2,"kind":"prep"},{"text":"Cortar {{Calabacín}} en trozos medianos, sin pelar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una olla a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada y el puerro en rodajas hasta que estén blandos y translúcidos, unos 5 min.","minutes":5,"kind":"activo"},{"text":"Añadir la zanahoria, la patata y el calabacín a la olla y remover para integrar con el sofrito.","minutes":1,"kind":"activo"},{"text":"Cubrir las verduras con agua fría hasta superarlas 2 cm y llevar a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la patata y la zanahoria estén tiernas, unos 15 min.","minutes":15,"kind":"pasivo"},{"text":"Retirar la olla del fuego y triturar todas las verduras con el caldo hasta obtener una textura fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Servir la crema caliente en boles.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_012', 'Crema de champiñones', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'invierno', 186, 6, 12, 12, 2, true, true, '{"lactosa"}', '[{"name":"Champiñones","amount":300,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Nata","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Pelar y picar ajo fino.","Limpiar champiñones y cortar en cuartos.","Pelar patata y cortar en dados de unos 2 cm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada en la olla hasta que esté transparente, unos 3 min.","Añadir el ajo picado y sofreír 1 min hasta que desprenda aroma.","Incorporar los champiñones cortados y saltear a fuego fuerte hasta que suelten el agua y se doren, unos 3 min.","Añadir los dados de patata y cubrir con 400 ml de agua. Llevar a ebullición.","Tapar la olla y cocer a fuego suave hasta que la patata esté tierna, unos 15 min.","Calentar nata en un cazo pequeño a fuego suave hasta que esté caliente, sin que llegue a hervir.","Retirar la olla del fuego y triturar el contenido con un batidor de mano hasta obtener una crema lisa.","Añadir la nata caliente a la crema y mezclar hasta integrar. Salpimentar al gusto.","Servir la crema en boles calientes."}', 'Crema de champiñones con nata y un toque de ajo', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríe con aceite. Añade los champiñones y la patata, cubre con agua/caldo y cocina 15-20 min a 100°C. Tritura a velocidad progresiva hasta obtener una crema fina, incorporando la nata al final."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla con aceite. Añade los champiñones y la patata, cubre con agua/caldo y cocina a presión alta durante 5-7 minutos. Libera la presión, añade la nata y tritura con una batidora de mano."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo","seta"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Cebolla}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Pelar y picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Limpiar {{Champiñones}} y cortar en cuartos.","minutes":3,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados de unos 2 cm.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada en la olla hasta que esté transparente, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Añadir el ajo picado y sofreír 1 min hasta que desprenda aroma.","minutes":1,"kind":"activo"},{"text":"Incorporar los champiñones cortados y saltear a fuego fuerte hasta que suelten el agua y se doren, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Añadir los dados de patata y cubrir con 400 ml de agua. Llevar a ebullición.","minutes":2,"kind":"activo"},{"text":"Tapar la olla y cocer a fuego suave hasta que la patata esté tierna, unos 15 min.","minutes":15,"kind":"pasivo"},{"text":"Calentar {{Nata}} en un cazo pequeño a fuego suave hasta que esté caliente, sin que llegue a hervir.","minutes":2,"kind":"paralelo","during":9},{"text":"Retirar la olla del fuego y triturar el contenido con un batidor de mano hasta obtener una crema lisa.","minutes":2,"kind":"activo"},{"text":"Añadir la nata caliente a la crema y mezclar hasta integrar. Salpimentar al gusto.","minutes":1,"kind":"activo"},{"text":"Servir la crema en boles calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_013', 'Puré de patatas gratinado', 'sopas_cremas', 'none', 'patatas', ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 228, 4, 30, 10, 2, true, true, '{"lactosa"}', '[{"name":"Patata","amount":400,"unit":"g"},{"name":"Leche","amount":80,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Nuez moscada","amount":2,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en trozos de tamaño similar.","Llevar a ebullición una olla con agua abundante a fuego fuerte.","Cocer los trozos de patata en el agua hirviendo a fuego medio hasta que estén tiernos, unos 20 min.","Calentar leche en un cazo a fuego suave hasta que esté caliente, sin que llegue a hervir.","Escurrir las patatas cocidas y aplastar con un pasapurés hasta obtener una textura lisa.","Añadir mantequilla y la leche caliente al puré y remover a fuego suave hasta integrar.","Añadir nuez moscada y remover hasta que el puré quede homogéneo.","Extender el puré en una fuente apta para horno y gratinar a 200 °C hasta que la superficie esté dorada, unos 5 min.","Retirar del horno y servir de inmediato en plato hondo o cuenco."}', 'Puré de patatas cremoso con mantequilla y nuez moscada', '[{"appliance":"horno","time":55,"difficulty":"facil","prepSummary":"Asa las patatas enteras a 200°C durante unos 45-55 minutos hasta que estén muy tiernas. Luego pélalas, machácalas y mezcla con la leche, mantequilla y nuez moscada para un puré más seco y con sabor concentrado."},{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Cocina las patatas troceadas en el cestillo o varoma durante 20-25 minutos a temperatura Varoma, velocidad 1. Luego, tritúralas con la leche, mantequilla y nuez moscada a velocidad 4-5 hasta obtener la textura deseada."},{"appliance":"vaporera","time":30,"difficulty":"facil","prepSummary":"Corta las patatas en trozos y cuécelas al vapor durante 25-30 minutos hasta que estén muy tiernas. Machácalas bien y luego incorpora la leche caliente, la mantequilla y la nuez moscada para un puré ligero y sabroso."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Cocina las patatas troceadas con un poco de agua en la olla express durante 6-8 minutos desde que sube la válvula. Despresuriza, escurre y machaca, añadiendo luego la leche, mantequilla y nuez moscada para un puré muy rápido y cremoso."},{"appliance":"microondas","time":15,"difficulty":"facil","prepSummary":"Pincha las patatas enteras o trocéalas y cocínalas en el microondas a máxima potencia durante 10-12 minutos, volteando a mitad, hasta que estén muy tiernas. Luego machaca y mezcla con el resto de ingredientes para un puré exprés."}]'::jsonb, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Patata}} y cortar en trozos de tamaño similar.","minutes":5,"kind":"prep"},{"text":"Llevar a ebullición una olla con agua abundante a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer los trozos de patata en el agua hirviendo a fuego medio hasta que estén tiernos, unos 20 min.","minutes":20,"kind":"pasivo"},{"text":"Calentar {{Leche}} en un cazo a fuego suave hasta que esté caliente, sin que llegue a hervir.","minutes":3,"kind":"paralelo","during":2},{"text":"Escurrir las patatas cocidas y aplastar con un pasapurés hasta obtener una textura lisa.","minutes":2,"kind":"activo"},{"text":"Añadir {{Mantequilla}} y la leche caliente al puré y remover a fuego suave hasta integrar.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nuez moscada|pizca}} y remover hasta que el puré quede homogéneo.","minutes":1,"kind":"activo"},{"text":"Extender el puré en una fuente apta para horno y gratinar a 200 °C hasta que la superficie esté dorada, unos 5 min.","minutes":5,"kind":"pasivo"},{"text":"Retirar del horno y servir de inmediato en plato hondo o cuenco.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'horno', NULL, NULL),
  ('sopas_cremas_014', 'Crema de espárragos', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 142, 5, 12, 8, 2, true, true, '{}', '[{"name":"Espárragos trigueros","amount":300,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Ajo","amount":6,"unit":"g"}]'::jsonb, '{"Pelar patata y cortar en dados de 1 cm aproximadamente.","Cortar cebolla en trozos pequeños y laminar ajo.","Retirar la parte leñosa de espárragos trigueros y cortar en trozos de 3 cm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el ajo en el aceite caliente hasta que estén translúcidos, unos 4 min.","Añadir los espárragos y la patata a la olla y remover para integrar con el sofrito.","Cubrir las verduras con agua fría hasta superarlas en 1 cm y llevar a ebullición a fuego fuerte.","Tapar la olla, bajar a fuego suave y cocer hasta que la patata esté tierna, unos 15 min.","Retirar del fuego y triturar el conjunto con un túrmix hasta obtener una crema fina.","Servir la crema caliente en boles."}', 'Crema de espárragos trigueros con patata', '[{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Pica la cebolla y el ajo, sofríe con aceite. Añade los espárragos y patata troceados con agua o caldo. Cocina 12-15 minutos a 100°C, velocidad cuchara, luego tritura a velocidad progresiva hasta obtener una crema fina y homogénea."},{"appliance":"olla_express","time":18,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla. Incorpora los espárragos, patata y líquido. Cierra y cocina a presión alta 5-7 minutos. Despresuriza y tritura con una batidora de mano hasta lograr una crema suave."},{"appliance":"vaporera","time":28,"difficulty":"facil","prepSummary":"Cocina los espárragos, patata, cebolla y ajo al vapor hasta que estén muy tiernos (aprox. 20-25 minutos). Transfiere a una batidora, añade el aceite de oliva y un poco de agua o caldo de la cocción, y tritura hasta obtener una crema suave."},{"appliance":"microondas","time":15,"difficulty":"facil","prepSummary":"Corta las verduras y cocínalas en un recipiente apto para microondas con un poco de agua durante 10-12 minutos a máxima potencia, hasta que estén tiernas. Luego, tritura con el aceite de oliva y un poco de líquido hasta obtener una crema fina."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y cortar en dados de 1 cm aproximadamente.","minutes":3,"kind":"prep"},{"text":"Cortar {{Cebolla}} en trozos pequeños y laminar {{Ajo}}.","minutes":2,"kind":"prep"},{"text":"Retirar la parte leñosa de {{Espárragos trigueros}} y cortar en trozos de 3 cm.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el ajo en el aceite caliente hasta que estén translúcidos, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir los espárragos y la patata a la olla y remover para integrar con el sofrito.","minutes":1,"kind":"activo"},{"text":"Cubrir las verduras con agua fría hasta superarlas en 1 cm y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Tapar la olla, bajar a fuego suave y cocer hasta que la patata esté tierna, unos 15 min.","minutes":15,"kind":"pasivo"},{"text":"Retirar del fuego y triturar el conjunto con un túrmix hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Servir la crema caliente en boles.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL)
