insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('sopas_cremas_015', 'Ajoblanco', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 268, 8, 16, 20, 2, false, true, '{"gluten","frutos_secos","sulfitos"}', '[{"name":"Almendras crudas","amount":100,"unit":"g"},{"name":"Pan del día anterior","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"},{"name":"Vinagre de Jerez","amount":15,"unit":"ml"},{"name":"Uvas","amount":60,"unit":"g"}]'::jsonb, '{"Cubrir pan del día anterior con agua fría y dejar reposar hasta que esté completamente empapado.","Escurrir el pan remojado y reservar el agua de remojo.","Pelar ajo y retirar el germen central para suavizar el sabor.","Lavar uvas, pelarlas y reservarlas en frío hasta el momento de servir.","Introducir almendras crudas, el pan escurrido y el ajo en el vaso de la batidora.","Triturar a máxima potencia durante 2 min hasta obtener una pasta muy fina y homogénea.","Añadir aceite de oliva en hilo fino mientras sigue triturando, hasta que emulsione.","Añadir vinagre de jerez y triturar 30 segundos más hasta integrar.","Agregar agua fría del remojo poco a poco y triturar hasta lograr la consistencia deseada.","Refrigerar el ajoblanco en la nevera hasta que esté muy frío, mínimo 30 min.","Servir el ajoblanco en boles fríos y repartir las uvas peladas por encima."}', 'Sopa fría de almendras y ajo con uvas, típica de Málaga', '[{"appliance":"thermomix","time":15,"difficulty":"facil","prepSummary":"La Thermomix es perfecta para el ajoblanco. Tritura todos los ingredientes (almendras, pan, ajo, agua, aceite, vinagre y sal) a velocidad progresiva hasta lograr una crema muy fina y emulsionada. Sirve bien frío con las uvas."}]'::jsonb, '{}', NULL, true, NULL, '{"fruta","frutos_secos"}', NULL, '{}'::main_protein[], false, '[{"text":"Cubrir {{Pan del día anterior}} con agua fría y dejar reposar hasta que esté completamente empapado.","minutes":5,"kind":"espera"},{"text":"Escurrir el pan remojado y reservar el agua de remojo.","minutes":1,"kind":"prep"},{"text":"Pelar {{Ajo}} y retirar el germen central para suavizar el sabor.","minutes":1,"kind":"prep"},{"text":"Lavar {{Uvas}}, pelarlas y reservarlas en frío hasta el momento de servir.","minutes":3,"kind":"prep"},{"text":"Introducir {{Almendras crudas}}, el pan escurrido y el ajo en el vaso de la batidora.","minutes":1,"kind":"prep"},{"text":"Triturar a máxima potencia durante 2 min hasta obtener una pasta muy fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} en hilo fino mientras sigue triturando, hasta que emulsione.","minutes":1,"kind":"activo"},{"text":"Añadir {{Vinagre de Jerez}} y triturar 30 segundos más hasta integrar.","minutes":1,"kind":"activo"},{"text":"Agregar agua fría del remojo poco a poco y triturar hasta lograr la consistencia deseada.","minutes":1,"kind":"activo"},{"text":"Refrigerar el ajoblanco en la nevera hasta que esté muy frío, mínimo 30 min.","minutes":30,"kind":"espera"},{"text":"Servir el ajoblanco en boles fríos y repartir las uvas peladas por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'crudo', NULL, NULL),
  ('sopas_cremas_016', 'Sopa de tomate', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 162, 3, 16, 10, 2, true, true, '{}', '[{"name":"Tomate maduro","amount":500,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Orégano","amount":3,"unit":"g"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Pelar y picar ajo fino.","Cortar tomate maduro en trozos irregulares.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada en el aceite caliente a fuego medio hasta que esté transparente, unos 4 min.","Añadir el ajo picado y sofreír 1 min más hasta que desprenda aroma.","Añadir el tomate troceado y orégano y remover para mezclar todo.","Tapar la olla y cocer a fuego suave hasta que el tomate esté muy tierno, unos 15 min.","Retirar del fuego y triturar la mezcla con una batidora hasta obtener una crema fina y homogénea.","Servir la sopa caliente en boles."}', 'Sopa caliente de tomate natural con orégano', '[{"appliance":"airfryer","time":25,"difficulty":"facil","prepSummary":"Asa los tomates, cebolla y ajo en la airfryer a 190°C durante 15-20 minutos hasta que estén tiernos y ligeramente caramelizados. Luego, tritúralos con un poco de agua o caldo y el orégano hasta obtener una sopa cremosa."},{"appliance":"horno","time":45,"difficulty":"facil","prepSummary":"Asa los tomates, cebolla y ajo en el horno a 180°C durante 30-40 minutos hasta que estén bien tiernos y con un ligero tostado. Después, tritúralos con el aceite de oliva, orégano y un poco de agua o caldo hasta conseguir una sopa suave."},{"appliance":"thermomix","time":22,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo con el aceite. Añade los tomates troceados y el orégano, cocina a temperatura Varoma durante 15 minutos y finalmente tritura a velocidad progresiva hasta obtener una crema fina y homogénea."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla express. Incorpora los tomates y el orégano, cierra la olla y cocina a presión durante 5-7 minutos. Una vez despresurizada, tritura todo hasta lograr una sopa cremosa."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Cebolla}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Pelar y picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate maduro}} en trozos irregulares.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada en el aceite caliente a fuego medio hasta que esté transparente, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir el ajo picado y sofreír 1 min más hasta que desprenda aroma.","minutes":1,"kind":"activo"},{"text":"Añadir el tomate troceado y {{Orégano|pizca}} y remover para mezclar todo.","minutes":1,"kind":"activo"},{"text":"Tapar la olla y cocer a fuego suave hasta que el tomate esté muy tierno, unos 15 min.","minutes":15,"kind":"pasivo"},{"text":"Retirar del fuego y triturar la mezcla con una batidora hasta obtener una crema fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Servir la sopa caliente en boles.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_017', 'Crema de brócoli', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 20, 'facil', 'invierno', 152, 6, 12, 8, 2, true, true, '{}', '[{"name":"Brócoli","amount":350,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Ajo","amount":6,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños. Pelar ajo y picar fino. Pelar patata y cortar en trozos de unos 2 cm.","Separar brócoli en ramilletes medianos, desechando el tronco más grueso.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír la cebolla picada y el ajo picado hasta que estén blandos y translúcidos, unos 3 min.","Añadir los ramilletes de brócoli y la patata cortada. Remover para mezclar con el sofrito.","Cubrir las verduras con agua hasta que queden justas sumergidas y llevar a ebullición a fuego fuerte.","Reducir a fuego medio y cocer hasta que la patata y el brócoli estén tiernos, unos 12 min.","Retirar del fuego y triturar con un batidor de mano hasta obtener una textura fina y cremosa.","Servir la crema caliente en boles."}', 'Crema de brócoli con patata, suave y nutritiva', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo, añade el resto de ingredientes y agua, cocina 18 min a 100°C, velocidad cuchara. Luego tritura 1 min a velocidad progresiva 5-10 hasta obtener una crema fina."},{"appliance":"vaporera","time":20,"difficulty":"facil","prepSummary":"Cocina el brócoli, la patata, cebolla y ajo al vapor durante 15-18 minutos hasta que estén tiernos. Luego, tritura los vegetales con el aceite de oliva y un poco del agua de cocción hasta lograr una crema suave."},{"appliance":"olla_express","time":15,"difficulty":"facil","prepSummary":"Sofríe la cebolla y el ajo en la olla. Añade el brócoli, la patata y un poco de agua, cierra y cocina 5 minutos desde que sube la válvula. Libera la presión y tritura directamente en la olla hasta obtener una crema homogénea."},{"appliance":"microondas","time":18,"difficulty":"facil","prepSummary":"Coloca todos los vegetales troceados con un chorrito de agua en un recipiente apto para microondas. Cocina a máxima potencia durante 12-15 minutos hasta que estén muy tiernos. Luego, tritura con el aceite de oliva hasta obtener una crema suave."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Cebolla}} en trozos pequeños. Pelar {{Ajo}} y picar fino. Pelar {{Patata}} y cortar en trozos de unos 2 cm.","minutes":5,"kind":"prep"},{"text":"Separar {{Brócoli}} en ramilletes medianos, desechando el tronco más grueso.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada y el ajo picado hasta que estén blandos y translúcidos, unos 3 min.","minutes":3,"kind":"activo"},{"text":"Añadir los ramilletes de brócoli y la patata cortada. Remover para mezclar con el sofrito.","minutes":1,"kind":"activo"},{"text":"Cubrir las verduras con agua hasta que queden justas sumergidas y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Reducir a fuego medio y cocer hasta que la patata y el brócoli estén tiernos, unos 12 min.","minutes":12,"kind":"pasivo"},{"text":"Retirar del fuego y triturar con un batidor de mano hasta obtener una textura fina y cremosa.","minutes":2,"kind":"activo"},{"text":"Servir la crema caliente en boles.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_018', 'Sopa de ajo', 'sopas_cremas', 'huevo', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'invierno', 212, 10, 18, 10, 2, false, false, '{"gluten","huevo"}', '[{"name":"Ajo","amount":15,"unit":"g"},{"name":"Pan del día anterior","amount":60,"unit":"g"},{"name":"Pimentón","amount":6,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de carne","amount":500,"unit":"ml"}]'::jsonb, '{"Laminar ajo en láminas finas y uniformes.","Cortar pan del día anterior en rebanadas de aproximadamente 1 cm de grosor.","Calentar aceite de oliva en una olla a fuego suave hasta que esté caliente.","Añadir el ajo laminado y sofreír a fuego suave hasta que se dore ligeramente, sin que se queme.","Retirar la olla del fuego y añadir pimentón removiendo rápidamente para que no se queme.","Añadir las rebanadas de pan y remover para que se impregnen bien del aceite con pimentón.","Verter caldo de carne en la olla, llevar a ebullición a fuego fuerte y después bajar a fuego medio.","Cocer a fuego medio durante 10 min hasta que el pan se deshaga y la sopa espese.","Cascar huevo sobre la sopa con cuidado, uno a uno, sin romper la yema.","Tapar la olla y cocer a fuego suave durante 3 min hasta que la clara cuaje pero la yema quede líquida.","Servir la sopa en cuencos hondos calientes, con un huevo por ración."}', 'Sopa de ajo tradicional con pan, pimentón y huevo', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], false, '[{"text":"Laminar {{Ajo}} en láminas finas y uniformes.","minutes":2,"kind":"prep"},{"text":"Cortar {{Pan del día anterior}} en rebanadas de aproximadamente 1 cm de grosor.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego suave hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Añadir el ajo laminado y sofreír a fuego suave hasta que se dore ligeramente, sin que se queme.","minutes":3,"kind":"activo"},{"text":"Retirar la olla del fuego y añadir {{Pimentón|pizca}} removiendo rápidamente para que no se queme.","minutes":1,"kind":"activo"},{"text":"Añadir las rebanadas de pan y remover para que se impregnen bien del aceite con pimentón.","minutes":1,"kind":"activo"},{"text":"Verter {{Caldo de carne}} en la olla, llevar a ebullición a fuego fuerte y después bajar a fuego medio.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio durante 10 min hasta que el pan se deshaga y la sopa espese.","minutes":10,"kind":"pasivo"},{"text":"Cascar {{Huevo}} sobre la sopa con cuidado, uno a uno, sin romper la yema.","minutes":1,"kind":"activo"},{"text":"Tapar la olla y cocer a fuego suave durante 3 min hasta que la clara cuaje pero la yema quede líquida.","minutes":3,"kind":"pasivo"},{"text":"Servir la sopa en cuencos hondos calientes, con un huevo por ración.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_019', 'Sopa juliana', 'sopas_cremas', 'none', NULL, ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'invierno', 128, 3, 14, 6, 2, true, true, '{}', '[{"name":"Puerro","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Judías verdes","amount":80,"unit":"g"},{"name":"Nabo","amount":60,"unit":"g"},{"name":"Repollo","amount":60,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Caldo de verduras","amount":500,"unit":"ml"}]'::jsonb, '{"Limpiar y laminar puerro en tiras finas de unos 3 mm.","Pelar y cortar zanahoria en tiras finas de juliana de unos 3 mm.","Despuntar y cortar judías verdes en tiras finas del mismo tamaño.","Pelar y cortar nabo en tiras finas de juliana.","Retirar las hojas exteriores y cortar repollo en tiras finas de juliana.","Calentar aceite de oliva en una olla a fuego medio hasta que esté caliente.","Sofreír el puerro, la zanahoria, las judías verdes, el nabo y el repollo en la olla durante 3 min, removiendo con frecuencia.","Añadir caldo de verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego suave, tapado, hasta que las verduras estén tiernas.","Servir la sopa bien caliente en boles hondos."}', 'Sopa ligera de verduras cortadas en tiras finas', '[{"appliance":"thermomix","time":25,"difficulty":"facil","prepSummary":"Pica las verduras en el vaso, sofríelas con el aceite y luego añade el caldo. Cocina a 100°C durante 20 minutos a velocidad cuchara con giro inverso, logrando una sopa perfectamente cocida y homogénea."},{"appliance":"olla_express","time":20,"difficulty":"facil","prepSummary":"Sofríe las verduras en la olla con el aceite, añade el caldo y cierra la tapa. Cocina a presión durante 6 minutos desde que sube la válvula, obteniendo una sopa rápida y con verduras perfectamente tiernas."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Limpiar y laminar {{Puerro}} en tiras finas de unos 3 mm.","minutes":2,"kind":"prep"},{"text":"Pelar y cortar {{Zanahoria}} en tiras finas de juliana de unos 3 mm.","minutes":2,"kind":"prep"},{"text":"Despuntar y cortar {{Judías verdes}} en tiras finas del mismo tamaño.","minutes":2,"kind":"prep"},{"text":"Pelar y cortar {{Nabo}} en tiras finas de juliana.","minutes":1,"kind":"prep"},{"text":"Retirar las hojas exteriores y cortar {{Repollo}} en tiras finas de juliana.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio hasta que esté caliente.","minutes":1,"kind":"activo"},{"text":"Sofreír el puerro, la zanahoria, las judías verdes, el nabo y el repollo en la olla durante 3 min, removiendo con frecuencia.","minutes":3,"kind":"activo"},{"text":"Añadir {{Caldo de verduras}} y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego suave, tapado, hasta que las verduras estén tiernas.","minutes":15,"kind":"pasivo"},{"text":"Servir la sopa bien caliente en boles hondos.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_020', 'Crema de lentejas', 'sopas_cremas', 'legumbre', 'legumbre', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'invierno', 272, 14, 34, 8, 2, true, true, '{}', '[{"name":"Lentejas rojas","amount":150,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Comino","amount":3,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar y picar cebolla en trozos pequeños.","Pelar zanahoria y cortar en rodajas de unos 5 mm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente, unos 4 min.","Añadir la zanahoria cortada y sofreír 3 min hasta que empiece a ablandarse.","Añadir tomate triturado y comino y remover 2 min a fuego medio.","Añadir lentejas rojas y cubrir con 600 ml de agua fría.","Llevar a ebullición a fuego fuerte y bajar a fuego suave cuando rompa a hervir.","Tapar y cocer a fuego suave hasta que las lentejas estén completamente tiernas, unos 18 min.","Retirar del fuego y triturar con un túrmix hasta obtener una crema lisa y homogénea.","Servir la crema caliente en boles."}', 'Crema espesa de lentejas rojas con zanahoria y comino', '[{"appliance":"thermomix","time":35,"difficulty":"facil","prepSummary":"Trocea las verduras y sofríelas con aceite. Añade las lentejas, tomate triturado, comino y agua. Cocina a temperatura Varoma/100°C y velocidad cuchara durante 25-30 minutos. Finalmente, tritura a velocidad progresiva hasta obtener una crema fina y homogénea."},{"appliance":"olla_express","time":25,"difficulty":"facil","prepSummary":"Sofríe las verduras picadas en la olla con aceite. Incorpora las lentejas, tomate triturado, comino y agua. Cierra la olla y cocina a presión durante 8-10 minutos desde que sube la válvula. Despresuriza, y tritura directamente en la olla con una batidora de mano hasta conseguir u"}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar y picar {{Cebolla}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Pelar {{Zanahoria}} y cortar en rodajas de unos 5 mm.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada hasta que esté transparente, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Añadir la zanahoria cortada y sofreír 3 min hasta que empiece a ablandarse.","minutes":3,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y {{Comino|pizca}} y remover 2 min a fuego medio.","minutes":2,"kind":"activo"},{"text":"Añadir {{Lentejas rojas}} y cubrir con 600 ml de agua fría.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición a fuego fuerte y bajar a fuego suave cuando rompa a hervir.","minutes":3,"kind":"activo"},{"text":"Tapar y cocer a fuego suave hasta que las lentejas estén completamente tiernas, unos 18 min.","minutes":18,"kind":"pasivo"},{"text":"Retirar del fuego y triturar con un túrmix hasta obtener una crema lisa y homogénea.","minutes":2,"kind":"activo"},{"text":"Servir la crema caliente en boles.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_021', 'Gazpacho de bote mejorado con toppings', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'verano', 185, 7, 15, 11, 2, true, true, '{"huevo","gluten","sulfitos"}', '[{"name":"Gazpacho de bote","amount":500,"unit":"ml"},{"name":"Huevo","amount":1,"unit":"ud"},{"name":"Jamón serrano","amount":30,"unit":"g"},{"name":"Pan","amount":30,"unit":"g"},{"name":"Pepino","amount":50,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":10,"unit":"ml"}]'::jsonb, '{"Cocer huevo en agua hirviendo durante 10 min.","Cortar pan en dados pequeños de 1 cm.","Picar pepino en dados pequeños para el topping.","Picar jamón serrano en taquitos finos.","Enfriar el huevo cocido en agua fría hasta que esté templado.","Pelar el huevo y picarlo en dados pequeños.","Calentar sartén a fuego fuerte con aceite de oliva virgen extra.","Freír los dados de pan hasta que estén dorados y crujientes.","Escurrir los picatostes sobre papel absorbente y reservar.","Verter gazpacho de bote en una jarra o bol grande y remover.","Servir el gazpacho bien frío en boles individuales.","Repartir por encima el huevo picado, el jamón serrano, los picatostes y el pepino."}', 'Gazpacho de bote con un remate casero de huevo duro, jamón y picatostes que lo convierte en plato completo.', NULL, '{}', NULL, true, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Cocer {{Huevo}} en agua hirviendo durante 10 min.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Pan}} en dados pequeños de 1 cm.","minutes":2,"kind":"prep"},{"text":"Picar {{Pepino}} en dados pequeños para el topping.","minutes":2,"kind":"prep"},{"text":"Picar {{Jamón serrano}} en taquitos finos.","minutes":1,"kind":"prep"},{"text":"Enfriar el huevo cocido en agua fría hasta que esté templado.","minutes":3,"kind":"espera"},{"text":"Pelar el huevo y picarlo en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{@Sartén}} a fuego fuerte con {{Aceite de oliva virgen extra}}.","minutes":1,"kind":"activo"},{"text":"Freír los dados de pan hasta que estén dorados y crujientes.","minutes":3,"kind":"activo"},{"text":"Escurrir los picatostes sobre papel absorbente y reservar.","minutes":1,"kind":"prep"},{"text":"Verter {{Gazpacho de bote}} en una jarra o bol grande y remover.","minutes":1,"kind":"prep"},{"text":"Servir el gazpacho bien frío en boles individuales.","minutes":1,"kind":"emplatado"},{"text":"Repartir por encima el huevo picado, el jamón serrano, los picatostes y el pepino.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, NULL),
  ('sopas_cremas_022', 'Crema de boletus con perejil frito', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'normal', 'all', 212, 5, 16, 14, 2, true, true, '{"lactosa"}', '[{"name":"Boletus","amount":300,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Caldo de verduras","amount":500,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Perejil fresco","amount":15,"unit":"g"}]'::jsonb, '{"Limpiar boletus con un paño húmedo y laminar, reservando unas pocas láminas para el perejil frito.","Pelar y picar cebolla finamente.","Limpiar y picar puerro finamente.","Pelar patata y cortar en dados pequeños.","Calentar mantequilla y aceite de oliva en una olla a fuego medio hasta que la mantequilla se funda.","Sofreír el puerro picado y la cebolla picada a fuego medio hasta que estén blandos y transparentes.","Añadir los boletus laminados y sofreír hasta que suelten el agua y se doren ligeramente.","Incorporar los dados de patata y caldo de verduras y llevar a ebullición.","Cocer a fuego medio hasta que la patata esté tierna.","Separar las hojas de perejil fresco reservadas para el perejil frito.","Retirar la olla del fuego y triturar con la batidora hasta obtener una crema fina.","Añadir nata para cocinar y triturar de nuevo hasta integrar por completo.","Calentar aceite abundante en sartén a fuego fuerte hasta que humee.","Freír las hojas de perejil en el aceite caliente unos segundos hasta que estén crujientes.","Escurrir el perejil frito sobre papel absorbente y reservar.","Servir la crema caliente en boles y coronar con el perejil frito crujiente."}', 'Crema aterciopelada de boletus con un crujiente de perejil frito que corona cada bol.', NULL, '{}', true, NULL, NULL, '{"verdura","lacteo","seta"}', NULL, '{}'::main_protein[], true, '[{"text":"Limpiar {{Boletus}} con un paño húmedo y laminar, reservando unas pocas láminas para el perejil frito.","minutes":4,"kind":"prep"},{"text":"Pelar y picar {{Cebolla}} finamente.","minutes":2,"kind":"prep"},{"text":"Limpiar y picar {{Puerro}} finamente.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados pequeños.","minutes":3,"kind":"prep"},{"text":"Calentar {{Mantequilla}} y {{Aceite de oliva|chorrito}} en una olla a fuego medio hasta que la mantequilla se funda.","minutes":1,"kind":"activo"},{"text":"Sofreír el puerro picado y la cebolla picada a fuego medio hasta que estén blandos y transparentes.","minutes":6,"kind":"activo"},{"text":"Añadir los boletus laminados y sofreír hasta que suelten el agua y se doren ligeramente.","minutes":5,"kind":"activo"},{"text":"Incorporar los dados de patata y {{Caldo de verduras}} y llevar a ebullición.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la patata esté tierna.","minutes":15,"kind":"pasivo"},{"text":"Separar las hojas de {{Perejil fresco}} reservadas para el perejil frito.","minutes":1,"kind":"paralelo","during":8},{"text":"Retirar la olla del fuego y triturar con la batidora hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} y triturar de nuevo hasta integrar por completo.","minutes":1,"kind":"activo"},{"text":"Calentar aceite abundante en {{@Sartén}} a fuego fuerte hasta que humee.","minutes":1,"kind":"activo"},{"text":"Freír las hojas de perejil en el aceite caliente unos segundos hasta que estén crujientes.","minutes":1,"kind":"activo"},{"text":"Escurrir el perejil frito sobre papel absorbente y reservar.","minutes":1,"kind":"prep"},{"text":"Servir la crema caliente en boles y coronar con el perejil frito crujiente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'sarten', NULL, NULL),
  ('sopas_cremas_023', 'Bisque de marisco', 'sopas_cremas', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 75, 'elaborada', 'all', 265, 15, 12, 17, 2, true, true, '{"marisco","lactosa","sulfitos"}', '[{"name":"Cáscaras y cabezas de langostinos","amount":300,"unit":"g"},{"name":"Langostinos pelados","amount":150,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Brandy","amount":40,"unit":"ml"},{"name":"Vino blanco","amount":80,"unit":"ml"},{"name":"Arroz","amount":30,"unit":"g"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pimentón dulce","amount":4,"unit":"g"},{"name":"Agua","amount":800,"unit":"ml"}]'::jsonb, '{"Picar cebolla, zanahoria, puerro y ajo en trozos pequeños.","Calentar aceite de oliva en una olla a fuego fuerte.","Añadir cáscaras y cabezas de langostinos y saltear 5 min, aplastándolas con una cuchara hasta que estén bien tostadas.","Verter brandy sobre las cáscaras y flambear con cuidado hasta que se apague la llama.","Añadir la verdura picada a la olla y sofreír a fuego medio hasta que esté blanda.","Incorporar tomate triturado y pimentón dulce y remover hasta integrar.","Verter vino blanco y remover hasta que se evapore el alcohol.","Añadir arroz y agua, llevar a ebullición y cocer a fuego medio hasta que el arroz esté tierno.","Triturar todo el conjunto, incluidas las cáscaras, con un túrmix hasta obtener una crema muy fina.","Colar la crema apretando con una cuchara para extraer todo el líquido y sabor.","Devolver la crema colada a la olla, añadir nata para cocinar y calentar a fuego suave sin que llegue a hervir.","Calentar un chorrito del aceite de oliva restante en sartén a fuego fuerte.","Saltear langostinos pelados 2 min por cada lado hasta que estén dorados y rosas.","Servir la bisque en boles y repartir los langostinos salteados por encima."}', 'Bisque cremosa de marisco, con todo el sabor extraído de las cáscaras y langostinos salteados de guarnición.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Cebolla}}, {{Zanahoria}}, {{Puerro}} y {{Ajo}} en trozos pequeños.","minutes":5,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Añadir {{Cáscaras y cabezas de langostinos}} y saltear 5 min, aplastándolas con una cuchara hasta que estén bien tostadas.","minutes":5,"kind":"activo"},{"text":"Verter {{Brandy}} sobre las cáscaras y flambear con cuidado hasta que se apague la llama.","minutes":1,"kind":"activo"},{"text":"Añadir la verdura picada a la olla y sofreír a fuego medio hasta que esté blanda.","minutes":8,"kind":"activo"},{"text":"Incorporar {{Tomate triturado}} y {{Pimentón dulce}} y remover hasta integrar.","minutes":2,"kind":"activo"},{"text":"Verter {{Vino blanco}} y remover hasta que se evapore el alcohol.","minutes":2,"kind":"activo"},{"text":"Añadir {{Arroz}} y {{Agua}}, llevar a ebullición y cocer a fuego medio hasta que el arroz esté tierno.","minutes":25,"kind":"pasivo"},{"text":"Triturar todo el conjunto, incluidas las cáscaras, con un túrmix hasta obtener una crema muy fina.","minutes":2,"kind":"activo"},{"text":"Colar la crema apretando con una cuchara para extraer todo el líquido y sabor.","minutes":3,"kind":"activo"},{"text":"Devolver la crema colada a la olla, añadir {{Nata para cocinar}} y calentar a fuego suave sin que llegue a hervir.","minutes":4,"kind":"activo"},{"text":"Calentar un chorrito del aceite de oliva restante en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Saltear {{Langostinos pelados}} 2 min por cada lado hasta que estén dorados y rosas.","minutes":4,"kind":"activo"},{"text":"Servir la bisque en boles y repartir los langostinos salteados por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, 'especial', NULL, 'olla', NULL, true),
  ('sopas_cremas_024', 'Crema de calabaza y jengibre', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'invierno', 165, 3, 20, 8, 2, true, true, '{"lactosa"}', '[{"name":"Calabaza","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Jengibre fresco","amount":15,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Nata para cocinar","amount":50,"unit":"ml"}]'::jsonb, '{"Pelar calabaza y cortar en dados de unos 3 cm.","Pelar patata y cortar en dados de unos 3 cm.","Picar cebolla finamente.","Rallar jengibre fresco.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada y el jengibre rallado a fuego medio hasta que la cebolla esté transparente.","Añadir los dados de calabaza y patata a la olla y remover para integrar con el sofrito.","Verter caldo de verduras hasta cubrir las verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que la calabaza y la patata estén tiernas.","Retirar la olla del fuego y triturar el contenido con la batidora hasta obtener una crema fina.","Añadir nata para cocinar y triturar de nuevo hasta integrar completamente.","Servir la crema bien caliente en boles."}', 'Crema de calabaza con un punto picante de jengibre que la despierta.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Calabaza}} y cortar en dados de unos 3 cm.","minutes":3,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados de unos 3 cm.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}} finamente.","minutes":2,"kind":"prep"},{"text":"Rallar {{Jengibre fresco}}.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada y el jengibre rallado a fuego medio hasta que la cebolla esté transparente.","minutes":4,"kind":"activo"},{"text":"Añadir los dados de calabaza y patata a la olla y remover para integrar con el sofrito.","minutes":1,"kind":"activo"},{"text":"Verter {{Caldo de verduras}} hasta cubrir las verduras y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la calabaza y la patata estén tiernas.","minutes":18,"kind":"pasivo"},{"text":"Retirar la olla del fuego y triturar el contenido con la batidora hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} y triturar de nuevo hasta integrar completamente.","minutes":1,"kind":"activo"},{"text":"Servir la crema bien caliente en boles.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL)
