insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('sopas_cremas_025', 'Gazpacho de sandía', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 112, 2, 17, 5, 2, true, true, '{"sulfitos"}', '[{"name":"Sandía","amount":500,"unit":"g"},{"name":"Tomate maduro","amount":150,"unit":"g"},{"name":"Pepino","amount":80,"unit":"g"},{"name":"Pimiento verde","amount":40,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar sandía en trozos, retirando las pepitas y la corteza.","Pelar pepino y cortar en trozos.","Cortar tomate maduro en trozos.","Cortar pimiento verde en trozos.","Pelar ajo y retirar el germen central para que no repita.","Triturar la sandía, el tomate maduro, el pepino, el pimiento verde y el ajo hasta obtener una crema fina.","Añadir vinagre de jerez, aceite de oliva virgen extra y sal y triturar de nuevo hasta integrar.","Enfriar el gazpacho en la nevera hasta que esté bien frío.","Servir bien frío con un chorrito de aceite de oliva virgen extra por encima."}', 'Gazpacho rosado y refrescante que sorprende con el dulzor de la sandía.', NULL, '{}', NULL, true, NULL, '{"verdura","fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Sandía}} en trozos, retirando las pepitas y la corteza.","minutes":3,"kind":"prep"},{"text":"Pelar {{Pepino}} y cortar en trozos.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tomate maduro}} en trozos.","minutes":1,"kind":"prep"},{"text":"Cortar {{Pimiento verde}} en trozos.","minutes":1,"kind":"prep"},{"text":"Pelar {{Ajo}} y retirar el germen central para que no repita.","minutes":1,"kind":"prep"},{"text":"Triturar la sandía, el tomate maduro, el pepino, el pimiento verde y el ajo hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Vinagre de jerez}}, {{Aceite de oliva virgen extra}} y {{Sal|gusto}} y triturar de nuevo hasta integrar.","minutes":1,"kind":"activo"},{"text":"Enfriar el gazpacho en la nevera hasta que esté bien frío.","minutes":60,"kind":"espera"},{"text":"Servir bien frío con un chorrito de aceite de oliva virgen extra por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, NULL),
  ('sopas_cremas_026', 'Salmorejo con jamón y huevo duro', 'sopas_cremas', 'none', 'pan', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 20, 'facil', 'verano', 232, 9, 22, 12, 2, true, true, '{"gluten","huevo","sulfitos"}', '[{"name":"Tomate maduro","amount":500,"unit":"g"},{"name":"Pan del día anterior","amount":100,"unit":"g"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":60,"unit":"ml"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Sal","amount":4,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Huevo","amount":1,"unit":"ud"}]'::jsonb, '{"Lavar tomate maduro y cortar en trozos grandes, retirando el pedúnculo.","Trocear pan del día anterior y sumergir en agua fría hasta que se ablande.","Cocer huevo en agua hirviendo hasta que esté duro.","Escurrir el pan y reservar.","Enfriar el huevo cocido en agua fría hasta que esté templado, pelar y reservar.","Triturar el tomate troceado, el pan escurrido y ajo hasta obtener una crema fina.","Añadir aceite de oliva virgen extra en hilo fino mientras se sigue triturando hasta que la crema sea homogénea.","Añadir vinagre de jerez y sal, triturar de nuevo hasta integrar.","Enfriar el salmorejo en la nevera hasta que esté bien frío.","Cortar jamón serrano en taquitos pequeños.","Cortar el huevo cocido en taquitos pequeños.","Servir el salmorejo bien frío con el jamón y el huevo repartidos por encima."}', 'Salmorejo cordobés espeso, rematado con jamón y huevo duro picados.', NULL, '{}', NULL, true, NULL, '{"verdura"}', NULL, ARRAY['cerdo','huevo']::main_protein[], false, '[{"text":"Lavar {{Tomate maduro}} y cortar en trozos grandes, retirando el pedúnculo.","minutes":3,"kind":"prep"},{"text":"Trocear {{Pan del día anterior}} y sumergir en agua fría hasta que se ablande.","minutes":10,"kind":"pasivo"},{"text":"Cocer {{Huevo}} en agua hirviendo hasta que esté duro.","minutes":10,"kind":"pasivo"},{"text":"Escurrir el pan y reservar.","minutes":1,"kind":"prep"},{"text":"Enfriar el huevo cocido en agua fría hasta que esté templado, pelar y reservar.","minutes":3,"kind":"activo"},{"text":"Triturar el tomate troceado, el pan escurrido y {{Ajo}} hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva virgen extra}} en hilo fino mientras se sigue triturando hasta que la crema sea homogénea.","minutes":1,"kind":"activo"},{"text":"Añadir {{Vinagre de jerez}} y {{Sal|gusto}}, triturar de nuevo hasta integrar.","minutes":1,"kind":"activo"},{"text":"Enfriar el salmorejo en la nevera hasta que esté bien frío.","minutes":60,"kind":"espera"},{"text":"Cortar {{Jamón serrano}} en taquitos pequeños.","minutes":2,"kind":"prep"},{"text":"Cortar el huevo cocido en taquitos pequeños.","minutes":1,"kind":"prep"},{"text":"Servir el salmorejo bien frío con el jamón y el huevo repartidos por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, NULL),
  ('sopas_cremas_027', 'Crema de puerros y patata con beicon crujiente', 'sopas_cremas', 'none', 'patatas', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'facil', 'invierno', 232, 6, 20, 14, 2, true, true, '{"lactosa"}', '[{"name":"Puerro","amount":300,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Caldo de pollo","amount":500,"unit":"ml"},{"name":"Nata para cocinar","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Beicon en lonchas","amount":60,"unit":"g"}]'::jsonb, '{"Limpiar puerro retirando la capa exterior y las raíces, y cortar en rodajas finas usando la parte blanca y la verde clara.","Pelar patata y cebolla, y cortar ambas en dados medianos.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el puerro en la olla hasta que estén blandos y ligeramente dorados.","Añadir la patata y caldo de pollo a la olla y llevar a ebullición a fuego fuerte.","Cocer la olla tapada a fuego medio hasta que la patata esté tierna.","Calentar sartén a fuego fuerte sin aceite y disponer beicon en lonchas en una sola capa.","Dorar el beicon hasta que quede crujiente, dándole la vuelta a mitad.","Retirar el beicon de la sartén y escurrir sobre papel absorbente.","Retirar la olla del fuego y triturar la sopa con la batidora hasta obtener una crema fina.","Añadir nata para cocinar a la crema y triturar de nuevo hasta integrar.","Cortar el beicon crujiente en trozos pequeños.","Servir la crema caliente en boles y repartir el beicon troceado por encima."}', 'Crema suave de puerro y patata con el contraste crujiente del beicon dorado.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, ARRAY['cerdo']::main_protein[], true, '[{"text":"Limpiar {{Puerro}} retirando la capa exterior y las raíces, y cortar en rodajas finas usando la parte blanca y la verde clara.","minutes":3,"kind":"prep"},{"text":"Pelar {{Patata}} y {{Cebolla}}, y cortar ambas en dados medianos.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el puerro en la olla hasta que estén blandos y ligeramente dorados.","minutes":8,"kind":"activo"},{"text":"Añadir la patata y {{Caldo de pollo}} a la olla y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocer la olla tapada a fuego medio hasta que la patata esté tierna.","minutes":20,"kind":"pasivo"},{"text":"Calentar {{@Sartén}} a fuego fuerte sin aceite y disponer {{Beicon en lonchas}} en una sola capa.","minutes":1,"kind":"paralelo","during":5},{"text":"Dorar el beicon hasta que quede crujiente, dándole la vuelta a mitad.","minutes":4,"kind":"activo"},{"text":"Retirar el beicon de la sartén y escurrir sobre papel absorbente.","minutes":1,"kind":"prep"},{"text":"Retirar la olla del fuego y triturar la sopa con la batidora hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} a la crema y triturar de nuevo hasta integrar.","minutes":1,"kind":"activo"},{"text":"Cortar el beicon crujiente en trozos pequeños.","minutes":1,"kind":"prep"},{"text":"Servir la crema caliente en boles y repartir el beicon troceado por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'olla', NULL, NULL),
  ('sopas_cremas_028', 'Crema de guisantes con menta', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 20, 'facil', 'all', 175, 7, 16, 9, 2, true, true, '{"lactosa"}', '[{"name":"Guisantes congelados","amount":350,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Nata para cocinar","amount":40,"unit":"ml"}]'::jsonb, '{"Picar cebolla fino.","Pelar patata y cortar en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada a fuego medio hasta que esté transparente.","Añadir la patata en dados y caldo de verduras.","Llevar a ebullición y cocer hasta que la patata esté tierna.","Añadir guisantes congelados y cocer hasta que estén tiernos y mantengan el color verde vivo.","Retirar la olla del fuego.","Reservar unas hojas de menta fresca para el emplatado y añadir el resto a la olla.","Triturar el contenido de la olla con la batidora hasta obtener una crema fina.","Añadir nata para cocinar y triturar de nuevo hasta integrar.","Picar fino las hojas de menta reservadas.","Servir la crema caliente o templada espolvoreada con la menta picada."}', 'Crema de guisantes de un verde vivo, refrescada con menta fresca.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Picar {{Cebolla}} fino.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada a fuego medio hasta que esté transparente.","minutes":5,"kind":"activo"},{"text":"Añadir la patata en dados y {{Caldo de verduras}}.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición y cocer hasta que la patata esté tierna.","minutes":10,"kind":"pasivo"},{"text":"Añadir {{Guisantes congelados}} y cocer hasta que estén tiernos y mantengan el color verde vivo.","minutes":5,"kind":"pasivo"},{"text":"Retirar la olla del fuego.","minutes":1,"kind":"activo"},{"text":"Reservar unas hojas de {{Menta fresca}} para el emplatado y añadir el resto a la olla.","minutes":1,"kind":"prep"},{"text":"Triturar el contenido de la olla con la batidora hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} y triturar de nuevo hasta integrar.","minutes":1,"kind":"activo"},{"text":"Picar fino las hojas de menta reservadas.","minutes":1,"kind":"prep"},{"text":"Servir la crema caliente o templada espolvoreada con la menta picada.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'olla', NULL, NULL),
  ('sopas_cremas_029', 'Velouté de champiñones', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'normal', 'all', 215, 5, 14, 15, 2, true, true, '{"gluten","lactosa"}', '[{"name":"Champiñones","amount":350,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Harina de trigo","amount":25,"unit":"g"},{"name":"Caldo de pollo","amount":500,"unit":"ml"},{"name":"Nata para cocinar","amount":80,"unit":"ml"},{"name":"Zumo de limón","amount":5,"unit":"ml"}]'::jsonb, '{"Limpiar champiñones con un paño húmedo para retirar la suciedad.","Laminar los champiñones en láminas finas y uniformes.","Picar cebolla en trozos pequeños.","Fundir mantequilla en una olla a fuego medio hasta que esté derretida.","Sofreír la cebolla picada en la olla hasta que esté blanda y transparente.","Añadir los champiñones laminados y zumo de limón a la olla.","Saltear a fuego fuerte hasta que los champiñones suelten el agua y se doren.","Espolvorear harina de trigo sobre los champiñones y remover sin parar.","Verter caldo de pollo poco a poco sin dejar de remover hasta integrarlo.","Llevar a ebullición y cocer a fuego medio hasta que la sopa espese ligeramente.","Triturar la sopa con una batidora hasta obtener una crema fina y sedosa.","Añadir nata para cocinar y calentar a fuego suave sin que llegue a hervir.","Servir la velouté caliente en cuencos."}', 'Velouté sedoso de champiñones, con el aroma tostado del sofrito envolviendo cada cucharada.', NULL, '{}', NULL, NULL, NULL, '{"lacteo","seta"}', NULL, ARRAY['pollo']::main_protein[], true, '[{"text":"Limpiar {{Champiñones}} con un paño húmedo para retirar la suciedad.","minutes":3,"kind":"prep"},{"text":"Laminar los champiñones en láminas finas y uniformes.","minutes":3,"kind":"prep"},{"text":"Picar {{Cebolla}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en una olla a fuego medio hasta que esté derretida.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada en la olla hasta que esté blanda y transparente.","minutes":5,"kind":"activo"},{"text":"Añadir los champiñones laminados y {{Zumo de limón}} a la olla.","minutes":1,"kind":"activo"},{"text":"Saltear a fuego fuerte hasta que los champiñones suelten el agua y se doren.","minutes":8,"kind":"activo"},{"text":"Espolvorear {{Harina de trigo}} sobre los champiñones y remover sin parar.","minutes":2,"kind":"activo"},{"text":"Verter {{Caldo de pollo}} poco a poco sin dejar de remover hasta integrarlo.","minutes":2,"kind":"activo"},{"text":"Llevar a ebullición y cocer a fuego medio hasta que la sopa espese ligeramente.","minutes":10,"kind":"pasivo"},{"text":"Triturar la sopa con una batidora hasta obtener una crema fina y sedosa.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} y calentar a fuego suave sin que llegue a hervir.","minutes":2,"kind":"activo"},{"text":"Servir la velouté caliente en cuencos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, true),
  ('sopas_cremas_030', 'Sopa de cebolla gratinada', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'invierno', 310, 12, 26, 17, 2, true, true, '{"gluten","lactosa","sulfitos"}', '[{"name":"Cebolla","amount":400,"unit":"g"},{"name":"Mantequilla","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Caldo de carne","amount":600,"unit":"ml"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Pan tostado","amount":60,"unit":"g"},{"name":"Queso gruyère rallado","amount":80,"unit":"g"},{"name":"Azúcar","amount":5,"unit":"g"},{"name":"Tomillo","amount":2,"unit":"g"}]'::jsonb, '{"Pelar cebolla y laminar en juliana fina.","Calentar mantequilla y aceite de oliva en una olla a fuego medio hasta que la mantequilla se funda.","Añadir la cebolla y azúcar a la olla. Remover para integrar.","Sofreír la cebolla a fuego suave, removiendo de vez en cuando, hasta que esté muy dorada y caramelizada.","Añadir vino blanco y remover hasta que se evapore el alcohol.","Añadir caldo de carne y tomillo. Llevar a ebullición.","Cocer a fuego medio hasta que la sopa esté sabrosa y ligeramente reducida.","Precalentar el horno en modo grill a 220 °C.","Repartir la sopa en 2 cazuelitas individuales aptas para horno.","Colocar pan tostado sobre cada cazuelita, cubriendo la superficie.","Cubrir el pan tostado con queso gruyère rallado de forma generosa.","Gratinar en el horno con el grill hasta que el queso esté fundido y dorado.","Servir las cazuelitas muy calientes, con cuidado al manipularlas."}', 'Sopa de cebolla lentamente caramelizada, coronada de pan y queso fundido gratinado.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Cebolla}} y laminar en juliana fina.","minutes":5,"kind":"prep"},{"text":"Calentar {{Mantequilla}} y {{Aceite de oliva|chorrito}} en una olla a fuego medio hasta que la mantequilla se funda.","minutes":2,"kind":"activo"},{"text":"Añadir la cebolla y {{Azúcar}} a la olla. Remover para integrar.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla a fuego suave, removiendo de vez en cuando, hasta que esté muy dorada y caramelizada.","minutes":30,"kind":"pasivo"},{"text":"Añadir {{Vino blanco}} y remover hasta que se evapore el alcohol.","minutes":2,"kind":"activo"},{"text":"Añadir {{Caldo de carne}} y {{Tomillo|pizca}}. Llevar a ebullición.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la sopa esté sabrosa y ligeramente reducida.","minutes":15,"kind":"pasivo"},{"text":"Precalentar el horno en modo grill a 220 °C.","minutes":5,"kind":"paralelo","during":6},{"text":"Repartir la sopa en 2 cazuelitas individuales aptas para horno.","minutes":1,"kind":"emplatado"},{"text":"Colocar {{Pan tostado}} sobre cada cazuelita, cubriendo la superficie.","minutes":1,"kind":"emplatado"},{"text":"Cubrir el pan tostado con {{Queso gruyère rallado}} de forma generosa.","minutes":1,"kind":"emplatado"},{"text":"Gratinar en el horno con el grill hasta que el queso esté fundido y dorado.","minutes":5,"kind":"pasivo"},{"text":"Servir las cazuelitas muy calientes, con cuidado al manipularlas.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('sopas_cremas_031', 'Crema de coliflor asada', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 45, 'facil', 'all', 160, 5, 14, 9, 2, true, true, '{"lactosa"}', '[{"name":"Coliflor","amount":500,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Nata para cocinar","amount":50,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Separar coliflor en ramilletes y cortar cebolla en trozos grandes.","Disponer los ramilletes de coliflor y la cebolla en una bandeja de horno junto con ajo entero con piel.","Regar con la mitad de aceite de oliva y salpimentar.","Hornear en el centro del horno hasta que la coliflor esté dorada en los bordes.","Retirar la bandeja del horno y dejar templar hasta que el ajo esté tibio.","Pelar el ajo asado presionando la base de cada diente para extraer la pulpa.","Poner la coliflor asada, la cebolla y el ajo pelado en una olla. Verter caldo de verduras.","Llevar a ebullición a fuego fuerte y, cuando rompa a hervir, cocer a fuego medio.","Retirar del fuego y triturar con la batidora hasta obtener una crema fina.","Añadir nata para cocinar y triturar de nuevo hasta integrar.","Ajustar de sal y servir con un hilo de aceite de oliva y pimentón dulce por encima."}', 'Crema de coliflor con el fondo tostado que deja el horno, más profunda que la versión hervida.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Separar {{Coliflor}} en ramilletes y cortar {{Cebolla}} en trozos grandes.","minutes":5,"kind":"paralelo","during":0},{"text":"Disponer los ramilletes de coliflor y la cebolla en una bandeja de horno junto con {{Ajo}} entero con piel.","minutes":2,"kind":"prep"},{"text":"Regar con la mitad de {{Aceite de oliva}} y salpimentar.","minutes":1,"kind":"prep"},{"text":"Hornear en el centro del horno hasta que la coliflor esté dorada en los bordes.","minutes":25,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y dejar templar hasta que el ajo esté tibio.","minutes":5,"kind":"espera"},{"text":"Pelar el ajo asado presionando la base de cada diente para extraer la pulpa.","minutes":1,"kind":"prep"},{"text":"Poner la coliflor asada, la cebolla y el ajo pelado en una olla. Verter {{Caldo de verduras}}.","minutes":2,"kind":"activo"},{"text":"Llevar a ebullición a fuego fuerte y, cuando rompa a hervir, cocer a fuego medio.","minutes":10,"kind":"pasivo"},{"text":"Retirar del fuego y triturar con la batidora hasta obtener una crema fina.","minutes":3,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} y triturar de nuevo hasta integrar.","minutes":1,"kind":"activo"},{"text":"Ajustar de sal y servir con un hilo de aceite de oliva y {{Pimentón dulce|pizca}} por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('sopas_cremas_032', 'Crema de espárragos con langostinos', 'sopas_cremas', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'normal', 'all', 200, 12, 12, 11, 2, true, true, '{"marisco","lactosa"}', '[{"name":"Espárragos verdes","amount":350,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Langostinos pelados","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Nata para cocinar","amount":50,"unit":"ml"}]'::jsonb, '{"Lavar espárragos verdes, retirar la parte leñosa del tallo y reservar las puntas para decorar.","Cortar los espárragos (sin las puntas reservadas) en trozos de unos 3 cm.","Limpiar puerro y picar fino.","Pelar patata y cortar en dados pequeños.","Calentar la mitad de aceite de oliva en una olla a fuego medio.","Sofreír el puerro picado a fuego medio hasta que esté blando y transparente.","Añadir los trozos de espárragos y la patata en dados, y sofreír removiendo 3 min.","Verter caldo de verduras hasta cubrir las verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio-suave hasta que las verduras estén tiernas.","Calentar el resto del aceite de oliva en sartén a fuego fuerte.","Saltear las puntas de espárrago reservadas y langostinos pelados hasta que los langostinos estén rosados.","Retirar la olla del fuego y triturar la sopa con la batidora hasta obtener una crema fina.","Añadir nata para cocinar a la crema y triturar de nuevo hasta integrar por completo.","Servir la crema caliente repartida en boles, con los langostinos y las puntas de espárrago por encima."}', 'Crema fina de espárragos verdes coronada con langostinos salteados.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Espárragos verdes}}, retirar la parte leñosa del tallo y reservar las puntas para decorar.","minutes":2,"kind":"prep"},{"text":"Cortar los espárragos (sin las puntas reservadas) en trozos de unos 3 cm.","minutes":2,"kind":"prep"},{"text":"Limpiar {{Puerro}} y picar fino.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar la mitad de {{Aceite de oliva}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el puerro picado a fuego medio hasta que esté blando y transparente.","minutes":5,"kind":"activo"},{"text":"Añadir los trozos de espárragos y la patata en dados, y sofreír removiendo 3 min.","minutes":3,"kind":"activo"},{"text":"Verter {{Caldo de verduras}} hasta cubrir las verduras y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio-suave hasta que las verduras estén tiernas.","minutes":15,"kind":"pasivo"},{"text":"Calentar el resto del aceite de oliva en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"paralelo","during":8},{"text":"Saltear las puntas de espárrago reservadas y {{Langostinos pelados}} hasta que los langostinos estén rosados.","minutes":3,"kind":"paralelo","during":8},{"text":"Retirar la olla del fuego y triturar la sopa con la batidora hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} a la crema y triturar de nuevo hasta integrar por completo.","minutes":1,"kind":"activo"},{"text":"Servir la crema caliente repartida en boles, con los langostinos y las puntas de espárrago por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_033', 'Gazpacho de remolacha', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 20, 'facil', 'verano', 132, 3, 17, 6, 2, true, true, '{"gluten","sulfitos"}', '[{"name":"Remolacha cocida","amount":250,"unit":"g"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Pepino","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":40,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Pan del día anterior","amount":30,"unit":"g"},{"name":"Vinagre de jerez","amount":10,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":25,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Trocear remolacha cocida en trozos grandes.","Pelar pepino y cortar en trozos grandes.","Cortar tomate maduro en trozos grandes.","Cortar pimiento verde en trozos grandes.","Sumergir pan del día anterior en agua fría hasta que esté bien empapado.","Escurrir el pan con las manos para retirar el exceso de agua.","Triturar la remolacha, el tomate, el pepino, el pimiento verde, ajo y el pan escurrido hasta obtener una crema fina.","Añadir vinagre de jerez, aceite de oliva virgen extra y sal y triturar de nuevo hasta que la mezcla esté homogénea.","Colar la crema a través de un colador fino presionando con una espátula hasta que esté completamente lisa.","Refrigerar el gazpacho en la nevera hasta que esté bien frío.","Servir el gazpacho bien frío en boles o vasos."}', 'Gazpacho de un magenta intenso, la vuelta de tuerca de la remolacha al clásico veraniego.', NULL, '{}', NULL, true, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Trocear {{Remolacha cocida}} en trozos grandes.","minutes":2,"kind":"prep"},{"text":"Pelar {{Pepino}} y cortar en trozos grandes.","minutes":2,"kind":"prep"},{"text":"Cortar {{Tomate maduro}} en trozos grandes.","minutes":1,"kind":"prep"},{"text":"Cortar {{Pimiento verde}} en trozos grandes.","minutes":1,"kind":"prep"},{"text":"Sumergir {{Pan del día anterior}} en agua fría hasta que esté bien empapado.","minutes":3,"kind":"espera"},{"text":"Escurrir el pan con las manos para retirar el exceso de agua.","minutes":1,"kind":"prep"},{"text":"Triturar la remolacha, el tomate, el pepino, el pimiento verde, {{Ajo}} y el pan escurrido hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Vinagre de jerez}}, {{Aceite de oliva virgen extra}} y {{Sal|gusto}} y triturar de nuevo hasta que la mezcla esté homogénea.","minutes":1,"kind":"activo"},{"text":"Colar la crema a través de un colador fino presionando con una espátula hasta que esté completamente lisa.","minutes":3,"kind":"activo"},{"text":"Refrigerar el gazpacho en la nevera hasta que esté bien frío.","minutes":60,"kind":"espera"},{"text":"Servir el gazpacho bien frío en boles o vasos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, NULL),
  ('sopas_cremas_034', 'Crema fría de pepino y yogur', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 120, 6, 8, 7, 2, true, true, '{"lactosa"}', '[{"name":"Pepino","amount":400,"unit":"g"},{"name":"Yogur griego natural","amount":200,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar pepino y partir por la mitad a lo largo para retirar las semillas con una cuchara.","Cortar el pepino pelado en trozos grandes y reservar.","Pelar ajo y retirar el germen central partiéndolo por la mitad.","Separar la mitad de menta fresca para triturar y reservar el resto para el emplatado.","Triturar el pepino, yogur griego natural, el ajo y la mitad de la menta fresca hasta obtener una crema fina.","Añadir zumo de limón y triturar de nuevo hasta integrar.","Añadir aceite de oliva virgen extra en hilo fino mientras se sigue triturando hasta emulsionar.","Añadir sal y triturar unos segundos más hasta integrar.","Colar la crema por un colador fino presionando con una cuchara hasta obtener una textura sedosa.","Tapar el recipiente y enfriar en la nevera hasta que la crema esté bien fría.","Picar fino el resto de la menta fresca reservada.","Servir la crema fría en boles, con un chorrito de aceite de oliva virgen extra y la menta picada por encima."}', 'Crema fría de pepino y yogur, ligera y refrescante para los días de más calor.', NULL, '{}', NULL, true, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Pepino}} y partir por la mitad a lo largo para retirar las semillas con una cuchara.","minutes":3,"kind":"prep"},{"text":"Cortar el pepino pelado en trozos grandes y reservar.","minutes":1,"kind":"prep"},{"text":"Pelar {{Ajo}} y retirar el germen central partiéndolo por la mitad.","minutes":1,"kind":"prep"},{"text":"Separar la mitad de {{Menta fresca}} para triturar y reservar el resto para el emplatado.","minutes":1,"kind":"prep"},{"text":"Triturar el pepino, {{Yogur griego natural}}, el ajo y la mitad de la menta fresca hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Zumo de limón}} y triturar de nuevo hasta integrar.","minutes":1,"kind":"activo"},{"text":"Añadir {{Aceite de oliva virgen extra}} en hilo fino mientras se sigue triturando hasta emulsionar.","minutes":1,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y triturar unos segundos más hasta integrar.","minutes":1,"kind":"activo"},{"text":"Colar la crema por un colador fino presionando con una cuchara hasta obtener una textura sedosa.","minutes":2,"kind":"opcional"},{"text":"Tapar el recipiente y enfriar en la nevera hasta que la crema esté bien fría.","minutes":60,"kind":"espera"},{"text":"Picar fino el resto de la menta fresca reservada.","minutes":1,"kind":"prep"},{"text":"Servir la crema fría en boles, con un chorrito de aceite de oliva virgen extra y la menta picada por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, true)
