insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('sopas_cremas_035', 'Crema de castañas', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'normal', 'invierno', 230, 5, 28, 10, 2, true, true, '{"lactosa"}', '[{"name":"Castañas cocidas y peladas","amount":300,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Caldo de pollo","amount":500,"unit":"ml"},{"name":"Nata para cocinar","amount":80,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Picar puerro y cebolla fino.","Calentar mantequilla y aceite de oliva en una olla a fuego medio hasta que la mantequilla se funda.","Sofreír el puerro picado y la cebolla picada en la olla a fuego medio hasta que estén blandos y transparentes.","Añadir castañas cocidas y peladas y caldo de pollo a la olla.","Llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que las castañas estén muy tiernas.","Triturar la mezcla con la batidora hasta obtener una crema fina y untuosa.","Añadir nata para cocinar y triturar de nuevo hasta integrar.","Servir la crema caliente con un chorrito de aceite de oliva por encima."}', 'Crema de castañas con dulzor de otoño y un fondo suave de nata.', NULL, '{}', NULL, NULL, NULL, '{"lacteo","frutos_secos"}', NULL, ARRAY['pollo']::main_protein[], true, '[{"text":"Picar {{Puerro}} y {{Cebolla}} fino.","minutes":4,"kind":"prep"},{"text":"Calentar {{Mantequilla}} y {{Aceite de oliva|chorrito}} en una olla a fuego medio hasta que la mantequilla se funda.","minutes":1,"kind":"activo"},{"text":"Sofreír el puerro picado y la cebolla picada en la olla a fuego medio hasta que estén blandos y transparentes.","minutes":6,"kind":"activo"},{"text":"Añadir {{Castañas cocidas y peladas}} y {{Caldo de pollo}} a la olla.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que las castañas estén muy tiernas.","minutes":20,"kind":"pasivo"},{"text":"Triturar la mezcla con la batidora hasta obtener una crema fina y untuosa.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} y triturar de nuevo hasta integrar.","minutes":1,"kind":"activo"},{"text":"Servir la crema caliente con un chorrito de aceite de oliva por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_036', 'Sopa fría de aguacate y lima', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 202, 4, 10, 17, 2, true, true, '{}', '[{"name":"Aguacate","amount":300,"unit":"g"},{"name":"Pepino","amount":150,"unit":"g"},{"name":"Caldo de verduras","amount":300,"unit":"ml"},{"name":"Lima (zumo)","amount":30,"unit":"ml"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Aceite de oliva virgen extra","amount":15,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar aguacate y retirar el hueso.","Pelar pepino y cortar en trozos grandes.","Introducir el aguacate, el pepino, caldo de verduras, lima (zumo) y cilantro fresco en el vaso de la batidora.","Triturar hasta obtener una crema fina y homogénea.","Añadir aceite de oliva virgen extra y sal y triturar unos segundos más.","Probar y rectificar de sal o lima al gusto.","Enfriar en la nevera hasta que esté bien fría.","Servir bien fría con unas hojas de cilantro fresco y un chorrito de aceite de oliva virgen extra."}', 'Sopa fría cremosa de aguacate y lima, sin necesidad de nata para conseguir esa textura untuosa.', NULL, '{}', NULL, true, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Aguacate}} y retirar el hueso.","minutes":2,"kind":"prep"},{"text":"Pelar {{Pepino}} y cortar en trozos grandes.","minutes":1,"kind":"prep"},{"text":"Introducir el aguacate, el pepino, {{Caldo de verduras}}, {{Lima (zumo)}} y {{Cilantro fresco}} en el vaso de la batidora.","minutes":1,"kind":"prep"},{"text":"Triturar hasta obtener una crema fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva virgen extra}} y {{Sal|gusto}} y triturar unos segundos más.","minutes":1,"kind":"activo"},{"text":"Probar y rectificar de sal o lima al gusto.","minutes":1,"kind":"activo"},{"text":"Enfriar en la nevera hasta que esté bien fría.","minutes":30,"kind":"espera"},{"text":"Servir bien fría con unas hojas de cilantro fresco y un chorrito de aceite de oliva virgen extra.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, NULL),
  ('sopas_cremas_037', 'Crema de zanahoria y jengibre', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 150, 3, 20, 6, 2, true, true, '{}', '[{"name":"Zanahoria","amount":400,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Jengibre fresco","amount":15,"unit":"g"},{"name":"Caldo de verduras","amount":450,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Zumo de naranja","amount":30,"unit":"ml"}]'::jsonb, '{"Pelar zanahoria, patata y cebolla y cortar en trozos medianos.","Rallar jengibre fresco finamente y reservar.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el jengibre rallado a fuego medio hasta que la cebolla esté transparente.","Añadir la zanahoria y la patata y remover para integrar con el sofrito.","Verter caldo de verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que la zanahoria y la patata estén tiernas.","Retirar la olla del fuego y añadir zumo de naranja.","Triturar todo con la batidora hasta obtener una crema fina y homogénea.","Servir la crema caliente en boles."}', 'Crema de zanahoria de un naranja brillante, con un punto picante de jengibre muy suave.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Zanahoria}}, {{Patata}} y {{Cebolla}} y cortar en trozos medianos.","minutes":5,"kind":"prep"},{"text":"Rallar {{Jengibre fresco}} finamente y reservar.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el jengibre rallado a fuego medio hasta que la cebolla esté transparente.","minutes":5,"kind":"activo"},{"text":"Añadir la zanahoria y la patata y remover para integrar con el sofrito.","minutes":1,"kind":"activo"},{"text":"Verter {{Caldo de verduras}} y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la zanahoria y la patata estén tiernas.","minutes":20,"kind":"pasivo"},{"text":"Retirar la olla del fuego y añadir {{Zumo de naranja}}.","minutes":1,"kind":"activo"},{"text":"Triturar todo con la batidora hasta obtener una crema fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Servir la crema caliente en boles.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_038', 'Crema de brócoli y queso azul', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 245, 9, 12, 18, 2, false, true, '{"lactosa"}', '[{"name":"Brócoli","amount":400,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Queso azul","amount":60,"unit":"g"},{"name":"Nata para cocinar","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Separar brócoli en arbolitos pequeños.","Pelar patata y cortar en trozos de unos 2 cm.","Pelar cebolla y picar fino.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté blanda y transparente.","Añadir la patata troceada y caldo de verduras y llevar a ebullición.","Cocer a fuego medio hasta que la patata esté casi tierna.","Añadir los arbolitos de brócoli y cocer hasta que estén tiernos pero de color verde vivo.","Retirar la olla del fuego.","Desmenuzar queso azul sobre la crema.","Añadir nata para cocinar y remover para integrar.","Triturar todo con la batidora hasta obtener una crema fina.","Servir la crema caliente en boles."}', 'Crema de brócoli con vetas de queso azul fundiéndose en cada cucharada.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Separar {{Brócoli}} en arbolitos pequeños.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en trozos de unos 2 cm.","minutes":2,"kind":"prep"},{"text":"Pelar {{Cebolla}} y picar fino.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada hasta que esté blanda y transparente.","minutes":5,"kind":"activo"},{"text":"Añadir la patata troceada y {{Caldo de verduras}} y llevar a ebullición.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la patata esté casi tierna.","minutes":10,"kind":"pasivo"},{"text":"Añadir los arbolitos de brócoli y cocer hasta que estén tiernos pero de color verde vivo.","minutes":8,"kind":"pasivo"},{"text":"Retirar la olla del fuego.","minutes":1,"kind":"activo"},{"text":"Desmenuzar {{Queso azul}} sobre la crema.","minutes":1,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Triturar todo con la batidora hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Servir la crema caliente en boles.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_039', 'Caldo gallego', 'sopas_cremas', 'legumbre', 'patatas', ARRAY['primero','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 75, 'normal', 'invierno', 320, 18, 30, 14, 4, true, true, '{}', '[{"name":"Patata","amount":500,"unit":"g"},{"name":"Grelos","amount":300,"unit":"g"},{"name":"Judías blancas cocidas","amount":400,"unit":"g"},{"name":"Chorizo","amount":150,"unit":"g"},{"name":"Lacón","amount":150,"unit":"g"},{"name":"Unto","amount":30,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Agua","amount":1500,"unit":"ml"}]'::jsonb, '{"Pelar patata y cortar en trozos medianos de unos 3 cm.","Lavar grelos bajo agua fría y trocear en trozos de unos 4 cm.","Cortar chorizo en rodajas gruesas y lacón en trozos generosos.","Pelar ajo y laminar finamente.","Colocar en una olla grande el lacón troceado, unto, el chorizo y agua fría.","Llevar a ebullición a fuego fuerte, retirando con una cuchara la espuma que suba.","Añadir el ajo laminado y pimentón dulce removiendo para integrarlo.","Bajar a fuego suave, tapar y cocer 30 min hasta que las carnes suelten su sabor.","Añadir la patata troceada a la olla.","Añadir los grelos troceados y tapar de nuevo.","Cocer a fuego suave 20 min hasta que la patata esté tierna y los grelos blandos.","Añadir judías blancas cocidas y cocer 10 min más para integrar todos los sabores.","Retirar el lacón y el chorizo de la olla y reservar en un plato.","Añadir sal con cuidado, teniendo en cuenta que el unto y el chorizo ya salan.","Servir el caldo muy caliente en cuencos hondos, repartiendo las carnes en cada uno."}', 'Caldo gallego contundente, con grelos, patata y todo el sabor del compango de cerdo.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], true, '[{"text":"Pelar {{Patata}} y cortar en trozos medianos de unos 3 cm.","minutes":5,"kind":"prep"},{"text":"Lavar {{Grelos}} bajo agua fría y trocear en trozos de unos 4 cm.","minutes":3,"kind":"prep"},{"text":"Cortar {{Chorizo}} en rodajas gruesas y {{Lacón}} en trozos generosos.","minutes":3,"kind":"prep"},{"text":"Pelar {{Ajo}} y laminar finamente.","minutes":2,"kind":"prep"},{"text":"Colocar en una olla grande el lacón troceado, {{Unto}}, el chorizo y {{Agua}} fría.","minutes":2,"kind":"activo"},{"text":"Llevar a ebullición a fuego fuerte, retirando con una cuchara la espuma que suba.","minutes":8,"kind":"activo"},{"text":"Añadir el ajo laminado y {{Pimentón dulce|pizca}} removiendo para integrarlo.","minutes":1,"kind":"activo"},{"text":"Bajar a fuego suave, tapar y cocer 30 min hasta que las carnes suelten su sabor.","minutes":30,"kind":"pasivo"},{"text":"Añadir la patata troceada a la olla.","minutes":1,"kind":"activo"},{"text":"Añadir los grelos troceados y tapar de nuevo.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave 20 min hasta que la patata esté tierna y los grelos blandos.","minutes":20,"kind":"pasivo"},{"text":"Añadir {{Judías blancas cocidas}} y cocer 10 min más para integrar todos los sabores.","minutes":10,"kind":"pasivo"},{"text":"Retirar el lacón y el chorizo de la olla y reservar en un plato.","minutes":2,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} con cuidado, teniendo en cuenta que el unto y el chorizo ya salan.","minutes":1,"kind":"activo"},{"text":"Servir el caldo muy caliente en cuencos hondos, repartiendo las carnes en cada uno.","minutes":2,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_040', 'Crema de calabacín con menta', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 140, 4, 10, 9, 2, true, true, '{"lactosa"}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Patata","amount":60,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Queso en porciones","amount":30,"unit":"g"}]'::jsonb, '{"Lavar calabacín y cortar en rodajas sin pelar.","Pelar patata y cebolla y cortar en trozos pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla a fuego medio hasta que esté transparente.","Añadir el calabacín y la patata y remover para integrar.","Cubrir con caldo de verduras y llevar a ebullición.","Cocer a fuego medio hasta que las verduras estén tiernas.","Retirar del fuego y añadir queso en porciones.","Añadir la mitad de menta fresca a la olla.","Triturar todo con la batidora hasta obtener una crema fina.","Picar el resto de la menta fresca en tiras finas y reservar.","Servir la crema en boles y decorar con la menta picada."}', 'Crema muy ligera de calabacín, aromatizada con menta fresca.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Lavar {{Calabacín}} y cortar en rodajas sin pelar.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y {{Cebolla}} y cortar en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla a fuego medio hasta que esté transparente.","minutes":4,"kind":"activo"},{"text":"Añadir el calabacín y la patata y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Cubrir con {{Caldo de verduras}} y llevar a ebullición.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que las verduras estén tiernas.","minutes":15,"kind":"pasivo"},{"text":"Retirar del fuego y añadir {{Queso en porciones}}.","minutes":1,"kind":"activo"},{"text":"Añadir la mitad de {{Menta fresca}} a la olla.","minutes":1,"kind":"activo"},{"text":"Triturar todo con la batidora hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Picar el resto de la menta fresca en tiras finas y reservar.","minutes":1,"kind":"prep"},{"text":"Servir la crema en boles y decorar con la menta picada.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'olla', NULL, NULL),
  ('sopas_cremas_041', 'Sopa de marisco', 'sopas_cremas', 'marisco', NULL, ARRAY['primero','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 60, 'elaborada', 'all', 280, 22, 14, 15, 2, true, true, '{"marisco","moluscos","pescado","sulfitos"}', '[{"name":"Mejillones","amount":200,"unit":"g"},{"name":"Langostinos","amount":200,"unit":"g"},{"name":"Rape","amount":150,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":40,"unit":"g"},{"name":"Vino blanco","amount":60,"unit":"ml"},{"name":"Fumet de pescado","amount":600,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Limpiar mejillones raspando las conchas y retirando las barbas.","Pelar langostinos, reservando las cáscaras y la mitad de los langostinos enteros para emplatar.","Cortar rape en trozos de bocado.","Picar cebolla, ajo y pimiento verde muy fino.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla, el ajo y el pimiento verde picados hasta que estén blandos, unos 8 min.","Añadir tomate triturado y pimentón dulce y sofreír 2 min removiendo sin parar.","Verter vino blanco y cocer a fuego fuerte hasta que el alcohol se evapore, unos 2 min.","Añadir fumet de pescado y llevar a ebullición a fuego fuerte.","Cocer a fuego medio durante 10 min.","Añadir los mejillones limpios, tapar la olla y cocer hasta que se abran, unos 5 min.","Retirar los mejillones que no se hayan abierto.","Incorporar el rape y los langostinos y cocer a fuego medio hasta que estén hechos, unos 4 min.","Picar perejil fino.","Servir la sopa muy caliente repartiendo el marisco y el pescado, y espolvorear con el perejil picado."}', 'Sopa de marisco con un caldo rojizo intenso y piezas enteras de mejillón, pescado y langostino.', NULL, '{}', true, NULL, NULL, '{}', NULL, ARRAY['pescado_blanco']::main_protein[], false, '[{"text":"Limpiar {{Mejillones}} raspando las conchas y retirando las barbas.","minutes":5,"kind":"prep"},{"text":"Pelar {{Langostinos}}, reservando las cáscaras y la mitad de los langostinos enteros para emplatar.","minutes":4,"kind":"prep"},{"text":"Cortar {{Rape}} en trozos de bocado.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}}, {{Ajo}} y {{Pimiento verde}} muy fino.","minutes":4,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, el ajo y el pimiento verde picados hasta que estén blandos, unos 8 min.","minutes":8,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y {{Pimentón dulce|pizca}} y sofreír 2 min removiendo sin parar.","minutes":2,"kind":"activo"},{"text":"Verter {{Vino blanco}} y cocer a fuego fuerte hasta que el alcohol se evapore, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Añadir {{Fumet de pescado}} y llevar a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego medio durante 10 min.","minutes":10,"kind":"pasivo"},{"text":"Añadir los mejillones limpios, tapar la olla y cocer hasta que se abran, unos 5 min.","minutes":5,"kind":"activo"},{"text":"Retirar los mejillones que no se hayan abierto.","minutes":1,"kind":"activo"},{"text":"Incorporar el rape y los langostinos y cocer a fuego medio hasta que estén hechos, unos 4 min.","minutes":4,"kind":"activo"},{"text":"Picar {{Perejil}} fino.","minutes":1,"kind":"activo"},{"text":"Servir la sopa muy caliente repartiendo el marisco y el pescado, y espolvorear con el perejil picado.","minutes":2,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_042', 'Crema de tomate asado', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 50, 'facil', 'all', 250, 4, 18, 18, 2, true, true, '{}', '[{"name":"Tomate maduro","amount":800,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Azúcar","amount":5,"unit":"g"},{"name":"Albahaca fresca","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Cortar tomate maduro por la mitad.","Cortar cebolla en cuartos.","Disponer el tomate y la cebolla en una bandeja de horno junto con ajo entero y sin pelar.","Rociar aceite de oliva sobre las verduras.","Añadir sal y pimienta negra sobre las verduras.","Hornear a 200 °C durante 30 min, hasta que las verduras estén blandas y ligeramente tostadas por los bordes.","Retirar la bandeja del horno y dejar templar 5 min.","Pelar el ajo asado apretando cada diente para extraer la pulpa.","Triturar el tomate, la cebolla y la pulpa de ajo asados con caldo de verduras hasta obtener una crema fina.","Colar la crema por un chino para eliminar pieles y semillas hasta obtener una textura sedosa.","Calentar la crema en un cazo a fuego medio hasta que esté caliente, sin que llegue a hervir.","Añadir azúcar si la crema resulta muy ácida y remover hasta integrar.","Servir la crema en cuencos con hojas de albahaca fresca y un chorrito de aceite de oliva por encima."}', 'Crema de tomate asado al horno hasta caramelizar, de color rojo intenso y dulzor natural.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Tomate maduro}} por la mitad.","minutes":2,"kind":"prep"},{"text":"Cortar {{Cebolla}} en cuartos.","minutes":1,"kind":"paralelo","during":0},{"text":"Disponer el tomate y la cebolla en una bandeja de horno junto con {{Ajo}} entero y sin pelar.","minutes":1,"kind":"prep"},{"text":"Rociar {{Aceite de oliva|chorrito}} sobre las verduras.","minutes":1,"kind":"prep"},{"text":"Añadir {{Sal|gusto}} y {{Pimienta negra|pizca}} sobre las verduras.","minutes":1,"kind":"prep"},{"text":"Hornear a 200 °C durante 30 min, hasta que las verduras estén blandas y ligeramente tostadas por los bordes.","minutes":30,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y dejar templar 5 min.","minutes":5,"kind":"espera"},{"text":"Pelar el ajo asado apretando cada diente para extraer la pulpa.","minutes":1,"kind":"prep"},{"text":"Triturar el tomate, la cebolla y la pulpa de ajo asados con {{Caldo de verduras}} hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Colar la crema por un chino para eliminar pieles y semillas hasta obtener una textura sedosa.","minutes":3,"kind":"activo"},{"text":"Calentar la crema en un cazo a fuego medio hasta que esté caliente, sin que llegue a hervir.","minutes":4,"kind":"activo"},{"text":"Añadir {{Azúcar}} si la crema resulta muy ácida y remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Servir la crema en cuencos con hojas de {{Albahaca fresca}} y un chorrito de aceite de oliva por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'horno', NULL, NULL),
  ('sopas_cremas_043', 'Crema de tres quesos', 'sopas_cremas', 'none', 'patatas', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 485, 18, 22, 36, 2, true, true, '{"lactosa"}', '[{"name":"Patata","amount":200,"unit":"g"},{"name":"Puerro","amount":100,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Queso Emmental","amount":40,"unit":"g"},{"name":"Queso Gruyère","amount":40,"unit":"g"},{"name":"Queso crema","amount":40,"unit":"g"},{"name":"Mantequilla","amount":15,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"},{"name":"Nuez moscada","amount":1,"unit":"g"}]'::jsonb, '{"Pelar patata y cortarla en dados pequeños.","Limpiar puerro, retirando la parte verde oscura y las capas externas, y picarlo fino.","Rallar queso emmental y queso gruyère y reservar.","Calentar mantequilla en una olla a fuego medio hasta que se funda.","Sofreír el puerro picado a fuego medio hasta que esté blando y transparente.","Añadir la patata en dados y caldo de verduras y llevar a ebullición.","Cocer a fuego medio hasta que la patata esté tierna.","Retirar la olla del fuego y triturar con la batidora hasta obtener una crema fina.","Volver a calentar la crema a fuego suave y añadir nata para cocinar.","Añadir el queso Emmental rallado, el queso Gruyère rallado y queso crema.","Remover a fuego suave hasta que los quesos se fundan y la crema quede untuosa.","Añadir sal, pimienta negra y nuez moscada y remover.","Servir la crema bien caliente en boles."}', 'Crema untuosa y dorada de patata y puerro fundida con tres quesos, para los días de capricho.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Patata}} y cortarla en dados pequeños.","minutes":3,"kind":"prep"},{"text":"Limpiar {{Puerro}}, retirando la parte verde oscura y las capas externas, y picarlo fino.","minutes":3,"kind":"prep"},{"text":"Rallar {{Queso Emmental}} y {{Queso Gruyère}} y reservar.","minutes":3,"kind":"prep"},{"text":"Calentar {{Mantequilla}} en una olla a fuego medio hasta que se funda.","minutes":1,"kind":"activo"},{"text":"Sofreír el puerro picado a fuego medio hasta que esté blando y transparente.","minutes":5,"kind":"activo"},{"text":"Añadir la patata en dados y {{Caldo de verduras}} y llevar a ebullición.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la patata esté tierna.","minutes":15,"kind":"pasivo"},{"text":"Retirar la olla del fuego y triturar con la batidora hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Volver a calentar la crema a fuego suave y añadir {{Nata para cocinar}}.","minutes":1,"kind":"activo"},{"text":"Añadir el queso Emmental rallado, el queso Gruyère rallado y {{Queso crema}}.","minutes":1,"kind":"activo"},{"text":"Remover a fuego suave hasta que los quesos se fundan y la crema quede untuosa.","minutes":3,"kind":"activo"},{"text":"Añadir {{Sal|gusto}}, {{Pimienta negra|pizca}} y {{Nuez moscada|pizca}} y remover.","minutes":1,"kind":"activo"},{"text":"Servir la crema bien caliente en boles.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_044', 'Sopa de pescado y marisco', 'sopas_cremas', 'pescado_blanco', 'patatas', ARRAY['primero','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'normal', 'all', 370, 34, 22, 16, 2, false, true, '{"pescado","marisco","moluscos","sulfitos"}', '[{"name":"Merluza","amount":200,"unit":"g"},{"name":"Gambas","amount":150,"unit":"g"},{"name":"Mejillones","amount":200,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Tomate triturado","amount":100,"unit":"g"},{"name":"Pimiento verde","amount":50,"unit":"g"},{"name":"Fumet de pescado","amount":500,"unit":"ml"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Azafrán","amount":1,"unit":"g"},{"name":"Patata","amount":150,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Perejil","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Limpiar mejillones raspando las valvas y retirando las barbas.","Pelar gambas y reservar las cáscaras por separado.","Pelar patata y cortar en dados de unos 2 cm.","Picar cebolla y pimiento verde en trozos pequeños.","Picar ajo fino.","Picar perejil fino y reservar.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír las cáscaras de gamba reservadas hasta que estén doradas, unos 2 min.","Retirar las cáscaras de gamba y desechar.","Sofreír la cebolla picada, el ajo picado y el pimiento verde picado en el mismo aceite a fuego medio.","Añadir tomate triturado y cocinar a fuego medio hasta que pierda el agua, unos 5 min.","Verter vino blanco y remover hasta que se evapore el alcohol, unos 2 min.","Incorporar los dados de patata, fumet de pescado y azafrán.","Llevar a ebullición y cocer a fuego medio hasta que la patata esté tierna, unos 15 min.","Cortar merluza en trozos de unos 3 cm.","Añadir los trozos de merluza y los mejillones limpios; tapar y cocer 5 min.","Incorporar las gambas peladas y cocer hasta que estén rosadas y los mejillones abiertos, unos 2 min.","Salpimentar con sal y espolvorear el perejil picado.","Servir la sopa bien caliente en cuencos hondos."}', 'Sopa de pescado y marisco en caldo dorado de azafrán, con trocitos de merluza, gambas y mejillones.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['marisco']::main_protein[], false, '[{"text":"Limpiar {{Mejillones}} raspando las valvas y retirando las barbas.","minutes":3,"kind":"prep"},{"text":"Pelar {{Gambas}} y reservar las cáscaras por separado.","minutes":3,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados de unos 2 cm.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}} y {{Pimiento verde}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Picar {{Perejil}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír las cáscaras de gamba reservadas hasta que estén doradas, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Retirar las cáscaras de gamba y desechar.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada, el ajo picado y el pimiento verde picado en el mismo aceite a fuego medio.","minutes":5,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y cocinar a fuego medio hasta que pierda el agua, unos 5 min.","minutes":5,"kind":"activo"},{"text":"Verter {{Vino blanco}} y remover hasta que se evapore el alcohol, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Incorporar los dados de patata, {{Fumet de pescado}} y {{Azafrán|pizca}}.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición y cocer a fuego medio hasta que la patata esté tierna, unos 15 min.","minutes":15,"kind":"pasivo"},{"text":"Cortar {{Merluza}} en trozos de unos 3 cm.","minutes":2,"kind":"paralelo","during":13},{"text":"Añadir los trozos de merluza y los mejillones limpios; tapar y cocer 5 min.","minutes":5,"kind":"activo"},{"text":"Incorporar las gambas peladas y cocer hasta que estén rosadas y los mejillones abiertos, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Salpimentar con {{Sal|gusto}} y espolvorear el perejil picado.","minutes":1,"kind":"emplatado"},{"text":"Servir la sopa bien caliente en cuencos hondos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL)
