) values
  ('sopas_cremas_045', 'Crema de tomate y albahaca', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 225, 3, 15, 17, 2, true, true, '{"lactosa"}', '[{"name":"Tomate maduro","amount":600,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Zanahoria","amount":50,"unit":"g"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Albahaca fresca","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Azúcar","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar cebolla y zanahoria, y cortar en trozos pequeños.","Llevar agua a ebullición en una olla. Escaldar tomate maduro 30 segundos y retirar.","Pelar los tomates escaldados y cortar en trozos.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y la zanahoria hasta que estén blandas.","Añadir el tomate troceado y remover a fuego medio durante 5 min.","Verter caldo de verduras y añadir azúcar. Remover y llevar a ebullición.","Cocer a fuego medio 15 min hasta que las verduras estén muy tiernas.","Retirar del fuego y añadir albahaca fresca, reservando unas hojas para decorar.","Triturar la mezcla hasta obtener una crema fina.","Añadir nata para cocinar y remover. Calentar a fuego suave sin que llegue a hervir.","Añadir sal y remover para integrar.","Servir la crema en boles y decorar con las hojas de albahaca reservadas."}', 'Crema fina de tomate maduro con nata y un toque fresco de albahaca.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Cebolla}} y {{Zanahoria}}, y cortar en trozos pequeños.","minutes":3,"kind":"prep"},{"text":"Llevar agua a ebullición en una olla. Escaldar {{Tomate maduro}} 30 segundos y retirar.","minutes":5,"kind":"activo"},{"text":"Pelar los tomates escaldados y cortar en trozos.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y la zanahoria hasta que estén blandas.","minutes":5,"kind":"activo"},{"text":"Añadir el tomate troceado y remover a fuego medio durante 5 min.","minutes":5,"kind":"activo"},{"text":"Verter {{Caldo de verduras}} y añadir {{Azúcar}}. Remover y llevar a ebullición.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio 15 min hasta que las verduras estén muy tiernas.","minutes":15,"kind":"pasivo"},{"text":"Retirar del fuego y añadir {{Albahaca fresca}}, reservando unas hojas para decorar.","minutes":1,"kind":"activo"},{"text":"Triturar la mezcla hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} y remover. Calentar a fuego suave sin que llegue a hervir.","minutes":2,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Servir la crema en boles y decorar con las hojas de albahaca reservadas.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'olla', NULL, NULL),
  ('sopas_cremas_046', 'Gazpacho de fresas', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 20, 'facil', 'verano', 275, 3, 23, 19, 2, true, true, '{"gluten","sulfitos"}', '[{"name":"Fresas","amount":400,"unit":"g"},{"name":"Tomate maduro","amount":200,"unit":"g"},{"name":"Pepino","amount":100,"unit":"g"},{"name":"Pimiento rojo","amount":50,"unit":"g"},{"name":"Pan","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Lavar fresas y retirar el pedúnculo.","Cortar las fresas en trozos y reservar.","Lavar tomate maduro y cortar en trozos.","Pelar parcialmente pepino y cortar en trozos.","Retirar las semillas de pimiento rojo y cortar en trozos.","Pelar ajo, retirar el germen y cortar en trozos.","Sumergir pan en agua fría durante 5 min.","Escurrir el pan con las manos para eliminar el exceso de agua.","Triturar las fresas, el tomate, el pepino, el pimiento, el ajo y el pan hasta obtener una mezcla fina.","Añadir aceite de oliva y vinagre de jerez y triturar de nuevo hasta emulsionar.","Colar la mezcla por un chino o colador fino para eliminar pieles y semillas.","Añadir sal y remover para integrar.","Enfriar el gazpacho en la nevera durante al menos 60 min antes de servir.","Servir bien frío en cuencos o vasos."}', 'Gazpacho rosado de fresas y tomate, dulce y ácido a la vez, para servir bien frío.', NULL, '{}', NULL, true, NULL, '{"verdura","fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Lavar {{Fresas}} y retirar el pedúnculo.","minutes":2,"kind":"prep"},{"text":"Cortar las fresas en trozos y reservar.","minutes":2,"kind":"prep"},{"text":"Lavar {{Tomate maduro}} y cortar en trozos.","minutes":1,"kind":"prep"},{"text":"Pelar parcialmente {{Pepino}} y cortar en trozos.","minutes":1,"kind":"prep"},{"text":"Retirar las semillas de {{Pimiento rojo}} y cortar en trozos.","minutes":1,"kind":"prep"},{"text":"Pelar {{Ajo}}, retirar el germen y cortar en trozos.","minutes":1,"kind":"prep"},{"text":"Sumergir {{Pan}} en agua fría durante 5 min.","minutes":5,"kind":"espera"},{"text":"Escurrir el pan con las manos para eliminar el exceso de agua.","minutes":1,"kind":"prep"},{"text":"Triturar las fresas, el tomate, el pepino, el pimiento, el ajo y el pan hasta obtener una mezcla fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} y {{Vinagre de Jerez}} y triturar de nuevo hasta emulsionar.","minutes":1,"kind":"activo"},{"text":"Colar la mezcla por un chino o colador fino para eliminar pieles y semillas.","minutes":2,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Enfriar el gazpacho en la nevera durante al menos 60 min antes de servir.","minutes":60,"kind":"espera"},{"text":"Servir bien frío en cuencos o vasos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, NULL),
  ('sopas_cremas_047', 'Crema de alcachofas', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 40, 'normal', 'all', 271, 5, 20, 19, 2, true, true, '{"lactosa","sulfitos"}', '[{"name":"Corazones de alcachofa","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Zumo de limón","amount":10,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta blanca","amount":1,"unit":"g"}]'::jsonb, '{"Cortar corazones de alcachofa en trozos y rociar con zumo de limón para evitar la oxidación.","Pelar patata y cortar en dados pequeños.","Picar puerro y cebolla fino.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír el puerro y la cebolla a fuego suave hasta que estén tiernos y transparentes.","Añadir los corazones de alcachofa troceados y la patata en dados y saltear 3 min a fuego medio.","Añadir caldo de verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que las alcachofas y la patata estén muy tiernas.","Triturar el contenido de la olla con la batidora hasta obtener una crema fina y homogénea.","Calentar la crema a fuego suave y añadir nata para cocinar, removiendo sin que llegue a hervir.","Sazonar con sal y pimienta blanca y remover para integrar.","Servir la crema bien caliente en boles."}', 'Crema suave y elegante de alcachofas con patata y un toque de nata.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Corazones de alcachofa}} en trozos y rociar con {{Zumo de limón}} para evitar la oxidación.","minutes":3,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Picar {{Puerro}} y {{Cebolla}} fino.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el puerro y la cebolla a fuego suave hasta que estén tiernos y transparentes.","minutes":8,"kind":"activo"},{"text":"Añadir los corazones de alcachofa troceados y la patata en dados y saltear 3 min a fuego medio.","minutes":3,"kind":"activo"},{"text":"Añadir {{Caldo de verduras}} y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que las alcachofas y la patata estén muy tiernas.","minutes":20,"kind":"pasivo"},{"text":"Triturar el contenido de la olla con la batidora hasta obtener una crema fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Calentar la crema a fuego suave y añadir {{Nata para cocinar}}, removiendo sin que llegue a hervir.","minutes":3,"kind":"activo"},{"text":"Sazonar con {{Sal|gusto}} y {{Pimienta blanca|pizca}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Servir la crema bien caliente en boles.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_048', 'Sopa de miso con verduras', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 123, 7, 8, 7, 2, true, true, '{"soja","sesamo","gluten"}', '[{"name":"Miso","amount":40,"unit":"g"},{"name":"Alga wakame","amount":5,"unit":"g"},{"name":"Tofu firme","amount":100,"unit":"g"},{"name":"Champiñones","amount":80,"unit":"g"},{"name":"Cebolleta","amount":30,"unit":"g"},{"name":"Agua","amount":600,"unit":"ml"},{"name":"Salsa de soja","amount":10,"unit":"ml"},{"name":"Aceite de sésamo","amount":5,"unit":"ml"}]'::jsonb, '{"Hidratar alga wakame en agua fría durante 5 min.","Escurrir el alga wakame y reservar.","Cortar tofu firme en dados de unos 1 cm.","Laminar champiñones en láminas finas.","Picar cebolleta en aros finos, separando la parte blanca de la verde.","Llevar agua a ebullición suave en una olla a fuego medio, sin que llegue a borbotón fuerte.","Añadir los champiñones laminados y la parte blanca de la cebolleta; cocer 3 min.","Retirar un cazo de caldo caliente a un bol aparte.","Disolver miso en el caldo del bol removiendo hasta integrar por completo.","Incorporar el miso disuelto a la olla fuera del fuego o a fuego muy suave, sin que hierva.","Añadir el tofu en dados y el alga wakame escurrida; calentar 2 min sin que llegue a hervir.","Añadir salsa de soja y aceite de sésamo; remover con suavidad.","Servir la sopa caliente en cuencos y decorar con los aros verdes de cebolleta."}', 'Sopa de miso japonesa con tofu, champiñones y algas, ligera y reconfortante.', NULL, '{}', NULL, NULL, NULL, '{"seta"}', NULL, '{}'::main_protein[], false, '[{"text":"Hidratar {{Alga wakame}} en agua fría durante 5 min.","minutes":5,"kind":"espera"},{"text":"Escurrir el alga wakame y reservar.","minutes":1,"kind":"prep"},{"text":"Cortar {{Tofu firme}} en dados de unos 1 cm.","minutes":2,"kind":"prep"},{"text":"Laminar {{Champiñones}} en láminas finas.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolleta}} en aros finos, separando la parte blanca de la verde.","minutes":1,"kind":"prep"},{"text":"Llevar {{Agua}} a ebullición suave en una olla a fuego medio, sin que llegue a borbotón fuerte.","minutes":3,"kind":"activo"},{"text":"Añadir los champiñones laminados y la parte blanca de la cebolleta; cocer 3 min.","minutes":3,"kind":"activo"},{"text":"Retirar un cazo de caldo caliente a un bol aparte.","minutes":1,"kind":"activo"},{"text":"Disolver {{Miso}} en el caldo del bol removiendo hasta integrar por completo.","minutes":1,"kind":"activo"},{"text":"Incorporar el miso disuelto a la olla fuera del fuego o a fuego muy suave, sin que hierva.","minutes":1,"kind":"activo"},{"text":"Añadir el tofu en dados y el alga wakame escurrida; calentar 2 min sin que llegue a hervir.","minutes":2,"kind":"activo"},{"text":"Añadir {{Salsa de soja}} y {{Aceite de sésamo}}; remover con suavidad.","minutes":1,"kind":"activo"},{"text":"Servir la sopa caliente en cuencos y decorar con los aros verdes de cebolleta.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_049', 'Crema de garbanzos especiada', 'sopas_cremas', 'legumbre', 'legumbre', ARRAY['primero','cena','plato_unico']::meal_role[], 'completo', NULL, 'batidora', 35, 'facil', 'all', 388, 16, 45, 16, 2, true, true, '{}', '[{"name":"Garbanzos cocidos","amount":400,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Comino molido","amount":3,"unit":"g"},{"name":"Cúrcuma","amount":2,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimentón dulce","amount":2,"unit":"g"}]'::jsonb, '{"Picar cebolla y ajo en trozos finos.","Cortar zanahoria en trozos pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el ajo hasta que estén transparentes.","Añadir la zanahoria y sofreír 3 min más a fuego medio.","Añadir comino molido, cúrcuma y pimentón dulce y remover 1 min para tostar las especias.","Añadir garbanzos cocidos y caldo de verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio tapado hasta que la zanahoria esté tierna.","Retirar del fuego y triturar con la batidora hasta obtener una crema fina.","Añadir sal y remover para integrar.","Servir la crema caliente con un chorrito de aceite de oliva y una pizca de comino molido."}', 'Crema especiada de garbanzos con comino y cúrcuma, cálida y reconfortante.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Cebolla}} y {{Ajo}} en trozos finos.","minutes":3,"kind":"prep"},{"text":"Cortar {{Zanahoria}} en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el ajo hasta que estén transparentes.","minutes":5,"kind":"activo"},{"text":"Añadir la zanahoria y sofreír 3 min más a fuego medio.","minutes":3,"kind":"activo"},{"text":"Añadir {{Comino molido|pizca}}, {{Cúrcuma|pizca}} y {{Pimentón dulce|pizca}} y remover 1 min para tostar las especias.","minutes":1,"kind":"activo"},{"text":"Añadir {{Garbanzos cocidos}} y {{Caldo de verduras}} y llevar a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego medio tapado hasta que la zanahoria esté tierna.","minutes":15,"kind":"pasivo"},{"text":"Retirar del fuego y triturar con la batidora hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Servir la crema caliente con un chorrito de aceite de oliva y una pizca de comino molido.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_050', 'Sopa juliana con jamón', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 157, 8, 11, 9, 2, true, true, '{}', '[{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Judía verde","amount":60,"unit":"g"},{"name":"Nabo","amount":50,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Caldo de pollo","amount":600,"unit":"ml"},{"name":"Aceite de oliva","amount":10,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Lavar y cortar zanahoria en juliana fina.","Lavar y cortar puerro en juliana fina.","Lavar y cortar judía verde en juliana fina.","Pelar y cortar nabo en juliana fina.","Cortar jamón serrano en tiras finas.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la zanahoria, el puerro, la judía verde y el nabo en juliana hasta que empiecen a ablandar.","Añadir el jamón serrano y sofreír hasta que suelte su aroma.","Verter caldo de pollo y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que las verduras estén tiernas pero con algo de textura.","Añadir sal, teniendo en cuenta que el jamón ya aporta salinidad.","Servir bien caliente en boles individuales."}', 'Sopa juliana de verduras finas cortadas en tiras con jamón serrano.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['cerdo']::main_protein[], true, '[{"text":"Lavar y cortar {{Zanahoria}} en juliana fina.","minutes":2,"kind":"prep"},{"text":"Lavar y cortar {{Puerro}} en juliana fina.","minutes":1,"kind":"prep"},{"text":"Lavar y cortar {{Judía verde}} en juliana fina.","minutes":1,"kind":"prep"},{"text":"Pelar y cortar {{Nabo}} en juliana fina.","minutes":1,"kind":"prep"},{"text":"Cortar {{Jamón serrano}} en tiras finas.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la zanahoria, el puerro, la judía verde y el nabo en juliana hasta que empiecen a ablandar.","minutes":5,"kind":"activo"},{"text":"Añadir el jamón serrano y sofreír hasta que suelte su aroma.","minutes":2,"kind":"activo"},{"text":"Verter {{Caldo de pollo}} y llevar a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego medio hasta que las verduras estén tiernas pero con algo de textura.","minutes":15,"kind":"pasivo"},{"text":"Añadir {{Sal|gusto}}, teniendo en cuenta que el jamón ya aporta salinidad.","minutes":1,"kind":"activo"},{"text":"Servir bien caliente en boles individuales.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_051', 'Crema de espinacas con nata', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 223, 6, 16, 15, 2, true, true, '{"lactosa"}', '[{"name":"Espinacas frescas","amount":400,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Caldo de verduras","amount":300,"unit":"ml"},{"name":"Nata para cocinar","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Lavar espinacas frescas bajo el grifo para eliminar restos de tierra.","Pelar cebolla y picarla fina.","Pelar patata y cortarla en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir los dados de patata y sofreír 2 min removiendo para que no se peguen.","Verter caldo de verduras y llevar a ebullición a fuego medio.","Cocer tapado a fuego medio hasta que la patata esté tierna.","Añadir las espinacas lavadas y cocer hasta que reduzcan de volumen.","Retirar del fuego y triturar todo con la batidora hasta obtener una crema fina.","Volver a calentar la crema a fuego suave.","Añadir nata para cocinar y remover sin dejar que hierva.","Añadir nuez moscada y sal y remover para integrar.","Servir la crema bien caliente en cuencos."}', 'Crema de espinacas frescas con nata, verde intenso y muy suave.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Lavar {{Espinacas frescas}} bajo el grifo para eliminar restos de tierra.","minutes":2,"kind":"prep"},{"text":"Pelar {{Cebolla}} y picarla fina.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortarla en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada hasta que esté transparente.","minutes":4,"kind":"activo"},{"text":"Añadir los dados de patata y sofreír 2 min removiendo para que no se peguen.","minutes":2,"kind":"activo"},{"text":"Verter {{Caldo de verduras}} y llevar a ebullición a fuego medio.","minutes":2,"kind":"activo"},{"text":"Cocer tapado a fuego medio hasta que la patata esté tierna.","minutes":12,"kind":"pasivo"},{"text":"Añadir las espinacas lavadas y cocer hasta que reduzcan de volumen.","minutes":3,"kind":"activo"},{"text":"Retirar del fuego y triturar todo con la batidora hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Volver a calentar la crema a fuego suave.","minutes":1,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} y remover sin dejar que hierva.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nuez moscada|pizca}} y {{Sal|gusto}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Servir la crema bien caliente en cuencos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'olla', NULL, NULL),
  ('sopas_cremas_052', 'Sopa de tomate con albahaca fresca', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'all', 222, 4, 20, 14, 2, true, true, '{"gluten"}', '[{"name":"Tomate maduro","amount":500,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Albahaca fresca","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pan tostado","amount":40,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Azúcar","amount":3,"unit":"g"}]'::jsonb, '{"Llevar agua a ebullición en una olla.","Escaldar tomate maduro en el agua hirviendo durante 30 segundos.","Retirar los tomates y pelarlos cuando estén fríos al tacto.","Cortar los tomates pelados en dados y reservar.","Picar cebolla finamente.","Picar ajo finamente.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada y el ajo picado hasta que estén blandos, sin que se doren.","Añadir los dados de tomate y remover a fuego medio durante 5 min.","Verter caldo de verduras y añadir azúcar.","Llevar a ebullición a fuego fuerte.","Cocer a fuego suave 15 min, aplastando el tomate con una cuchara hasta que se deshaga.","Trocear albahaca fresca a mano, reservando unas hojas enteras para emplatar.","Salpimentar con sal y retirar la olla del fuego.","Añadir la albahaca troceada a la sopa y remover.","Servir la sopa con pan tostado y las hojas de albahaca enteras por encima."}', 'Sopa ligera de tomate con hojas de albahaca fresca y picatostes.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Llevar agua a ebullición en una olla.","minutes":3,"kind":"activo"},{"text":"Escaldar {{Tomate maduro}} en el agua hirviendo durante 30 segundos.","minutes":1,"kind":"activo"},{"text":"Retirar los tomates y pelarlos cuando estén fríos al tacto.","minutes":2,"kind":"prep"},{"text":"Cortar los tomates pelados en dados y reservar.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}} finamente.","minutes":2,"kind":"prep"},{"text":"Picar {{Ajo}} finamente.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada y el ajo picado hasta que estén blandos, sin que se doren.","minutes":5,"kind":"activo"},{"text":"Añadir los dados de tomate y remover a fuego medio durante 5 min.","minutes":5,"kind":"activo"},{"text":"Verter {{Caldo de verduras}} y añadir {{Azúcar}}.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego suave 15 min, aplastando el tomate con una cuchara hasta que se deshaga.","minutes":15,"kind":"pasivo"},{"text":"Trocear {{Albahaca fresca}} a mano, reservando unas hojas enteras para emplatar.","minutes":1,"kind":"paralelo","during":11},{"text":"Salpimentar con {{Sal|gusto}} y retirar la olla del fuego.","minutes":1,"kind":"activo"},{"text":"Añadir la albahaca troceada a la sopa y remover.","minutes":1,"kind":"activo"},{"text":"Servir la sopa con {{Pan tostado}} y las hojas de albahaca enteras por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_053', 'Crema de setas variadas', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'normal', 'invierno', 240, 6, 18, 16, 2, true, true, '{"lactosa"}', '[{"name":"Setas variadas","amount":400,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Caldo de verduras","amount":350,"unit":"ml"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Tomillo fresco","amount":3,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Limpiar setas variadas con un paño húmedo, sin lavarlas bajo el grifo.","Laminar las setas limpias.","Pelar y picar cebolla fino.","Pelar y picar ajo fino.","Pelar patata y cortarla en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el ajo picados hasta que estén transparentes.","Añadir las setas laminadas y saltear a fuego fuerte hasta que suelten su agua y se doren ligeramente.","Retirar un puñado de setas salteadas y reservar en un plato para emplatar.","Añadir la patata en dados y caldo de verduras al resto de setas en la olla.","Llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que la patata esté tierna.","Añadir tomillo fresco y triturar con la batidora hasta obtener una crema fina.","Volver la crema al fuego suave y añadir nata para cocinar.","Salpimentar con sal y pimienta negra, y remover hasta integrar.","Servir la crema caliente y repartir las setas reservadas por encima."}', 'Crema de setas variadas con aroma a bosque y un fondo de nata.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo","seta"}', NULL, '{}'::main_protein[], true, '[{"text":"Limpiar {{Setas variadas}} con un paño húmedo, sin lavarlas bajo el grifo.","minutes":3,"kind":"prep"},{"text":"Laminar las setas limpias.","minutes":3,"kind":"prep"},{"text":"Pelar y picar {{Cebolla}} fino.","minutes":2,"kind":"prep"},{"text":"Pelar y picar {{Ajo}} fino.","minutes":1,"kind":"prep"},{"text":"Pelar {{Patata}} y cortarla en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el ajo picados hasta que estén transparentes.","minutes":5,"kind":"activo"},{"text":"Añadir las setas laminadas y saltear a fuego fuerte hasta que suelten su agua y se doren ligeramente.","minutes":5,"kind":"activo"},{"text":"Retirar un puñado de setas salteadas y reservar en un plato para emplatar.","minutes":1,"kind":"prep"},{"text":"Añadir la patata en dados y {{Caldo de verduras}} al resto de setas en la olla.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la patata esté tierna.","minutes":15,"kind":"pasivo"},{"text":"Añadir {{Tomillo fresco}} y triturar con la batidora hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Volver la crema al fuego suave y añadir {{Nata para cocinar}}.","minutes":1,"kind":"activo"},{"text":"Salpimentar con {{Sal|gusto}} y {{Pimienta negra|pizca}}, y remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Servir la crema caliente y repartir las setas reservadas por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_054', 'Vichyssoise de puerro y manzana', 'sopas_cremas', 'none', 'patatas', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 45, 'normal', 'verano', 326, 4, 28, 22, 2, true, true, '{"lactosa"}', '[{"name":"Puerro","amount":300,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Manzana Golden","amount":150,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Cebollino","amount":5,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta blanca","amount":1,"unit":"g"}]'::jsonb, '{"Limpiar puerro retirando la parte verde más dura y las raíces.","Cortar el puerro limpio en rodajas de unos 5 mm.","Pelar patata y cortarla en dados de unos 2 cm.","Pelar manzana golden, descorazonarla y cortarla en trozos similares a la patata.","Fundir mantequilla en una olla a fuego suave hasta que esté líquida.","Sofreír el puerro en la mantequilla a fuego suave hasta que esté tierno sin que se dore.","Añadir la patata y la manzana a la olla y remover para integrar con el puerro.","Sofreír la patata y la manzana junto al puerro a fuego medio durante 2 min.","Verter caldo de verduras en la olla y llevar a ebullición a fuego fuerte.","Cocer a fuego medio tapado hasta que la patata esté muy tierna.","Retirar la olla del fuego y triturar el contenido con la batidora hasta obtener una crema muy fina.","Colar la crema por un colador fino presionando con un cazo para lograr una textura sedosa.","Añadir nata para cocinar, sal y pimienta blanca y remover hasta integrar.","Dejar enfriar la crema a temperatura ambiente antes de refrigerar.","Refrigerar la crema en la olla tapada hasta que esté bien fría.","Picar cebollino fino justo antes de servir.","Servir la vichyssoise fría en boles repartiendo el cebollino picado por encima."}', 'Vichyssoise fría de puerro y patata con un toque dulce de manzana.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo","fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Limpiar {{Puerro}} retirando la parte verde más dura y las raíces.","minutes":2,"kind":"prep"},{"text":"Cortar el puerro limpio en rodajas de unos 5 mm.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortarla en dados de unos 2 cm.","minutes":3,"kind":"prep"},{"text":"Pelar {{Manzana Golden}}, descorazonarla y cortarla en trozos similares a la patata.","minutes":2,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en una olla a fuego suave hasta que esté líquida.","minutes":1,"kind":"activo"},{"text":"Sofreír el puerro en la mantequilla a fuego suave hasta que esté tierno sin que se dore.","minutes":8,"kind":"activo"},{"text":"Añadir la patata y la manzana a la olla y remover para integrar con el puerro.","minutes":1,"kind":"activo"},{"text":"Sofreír la patata y la manzana junto al puerro a fuego medio durante 2 min.","minutes":2,"kind":"activo"},{"text":"Verter {{Caldo de verduras}} en la olla y llevar a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego medio tapado hasta que la patata esté muy tierna.","minutes":20,"kind":"pasivo"},{"text":"Retirar la olla del fuego y triturar el contenido con la batidora hasta obtener una crema muy fina.","minutes":3,"kind":"activo"},{"text":"Colar la crema por un colador fino presionando con un cazo para lograr una textura sedosa.","minutes":3,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}}, {{Sal|gusto}} y {{Pimienta blanca|pizca}} y remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Dejar enfriar la crema a temperatura ambiente antes de refrigerar.","minutes":30,"kind":"espera"},{"text":"Refrigerar la crema en la olla tapada hasta que esté bien fría.","minutes":120,"kind":"espera"},{"text":"Picar {{Cebollino}} fino justo antes de servir.","minutes":1,"kind":"prep"},{"text":"Servir la vichyssoise fría en boles repartiendo el cebollino picado por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, true)
