) values
  ('sopas_cremas_055', 'Crema de calabaza con castañas', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 45, 'normal', 'invierno', 334, 5, 38, 18, 2, true, true, '{"lactosa"}', '[{"name":"Calabaza","amount":500,"unit":"g"},{"name":"Castañas cocidas","amount":150,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Caldo de verduras","amount":400,"unit":"ml"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Nuez moscada","amount":1,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar calabaza y cortar en dados de 2-3 cm.","Picar cebolla y puerro fino.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el puerro a fuego suave hasta que estén blandos.","Añadir los dados de calabaza y saltear a fuego medio removiendo.","Reservar un puñado de castañas cocidas para el emplatado.","Añadir el resto de las castañas cocidas a la olla.","Verter caldo de verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio tapado hasta que la calabaza esté muy tierna.","Triturar todo con la batidora hasta obtener una crema fina y homogénea.","Calentar la crema a fuego suave y añadir nata para cocinar.","Añadir nuez moscada y sal; remover hasta integrar.","Cortar las castañas reservadas en trozos gruesos.","Servir la crema caliente con los trozos de castaña por encima."}', 'Crema de calabaza asada con castañas, muy de otoño.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo","frutos_secos"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Calabaza}} y cortar en dados de 2-3 cm.","minutes":5,"kind":"prep"},{"text":"Picar {{Cebolla}} y {{Puerro}} fino.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el puerro a fuego suave hasta que estén blandos.","minutes":8,"kind":"activo"},{"text":"Añadir los dados de calabaza y saltear a fuego medio removiendo.","minutes":5,"kind":"activo"},{"text":"Reservar un puñado de {{Castañas cocidas}} para el emplatado.","minutes":1,"kind":"prep"},{"text":"Añadir el resto de las castañas cocidas a la olla.","minutes":1,"kind":"activo"},{"text":"Verter {{Caldo de verduras}} y llevar a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego medio tapado hasta que la calabaza esté muy tierna.","minutes":20,"kind":"pasivo"},{"text":"Triturar todo con la batidora hasta obtener una crema fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Calentar la crema a fuego suave y añadir {{Nata para cocinar}}.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nuez moscada|pizca}} y {{Sal|gusto}}; remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Cortar las castañas reservadas en trozos gruesos.","minutes":1,"kind":"prep"},{"text":"Servir la crema caliente con los trozos de castaña por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_056', 'Sopa fría de melón y jamón', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 221, 9, 17, 13, 2, true, true, '{"lactosa"}', '[{"name":"Melón","amount":500,"unit":"g"},{"name":"Jamón serrano","amount":40,"unit":"g"},{"name":"Yogur griego","amount":100,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Menta fresca","amount":5,"unit":"g"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Pelar melón, retirar las semillas y cortar la pulpa en trozos grandes.","Triturar los trozos de melón con yogur griego, aceite de oliva y sal hasta obtener una crema fina.","Añadir pimienta negra y triturar de nuevo unos segundos hasta integrar.","Refrigerar la crema tapada hasta que esté bien fría.","Cortar jamón serrano en virutas finas.","Separar unas hojas de menta fresca para decorar.","Repartir la sopa fría en boles individuales.","Decorar cada bol con las virutas de jamón serrano y las hojas de menta fresca. Servir de inmediato."}', 'Sopa fría de melón con virutas de jamón serrano, perfecta para el verano.', NULL, '{}', NULL, true, NULL, '{"lacteo","fruta"}', NULL, ARRAY['cerdo']::main_protein[], false, '[{"text":"Pelar {{Melón}}, retirar las semillas y cortar la pulpa en trozos grandes.","minutes":5,"kind":"prep"},{"text":"Triturar los trozos de melón con {{Yogur griego}}, {{Aceite de oliva|chorrito}} y {{Sal|gusto}} hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Pimienta negra|pizca}} y triturar de nuevo unos segundos hasta integrar.","minutes":1,"kind":"activo"},{"text":"Refrigerar la crema tapada hasta que esté bien fría.","minutes":60,"kind":"espera"},{"text":"Cortar {{Jamón serrano}} en virutas finas.","minutes":2,"kind":"paralelo","during":3},{"text":"Separar unas hojas de {{Menta fresca}} para decorar.","minutes":1,"kind":"paralelo","during":3},{"text":"Repartir la sopa fría en boles individuales.","minutes":1,"kind":"emplatado"},{"text":"Decorar cada bol con las virutas de jamón serrano y las hojas de menta fresca. Servir de inmediato.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, NULL),
  ('sopas_cremas_057', 'Crema de pimientos asados', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 50, 'facil', 'all', 258, 4, 20, 18, 2, true, true, '{"sulfitos"}', '[{"name":"Pimiento rojo","amount":500,"unit":"g"},{"name":"Pimiento amarillo","amount":200,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate maduro","amount":100,"unit":"g"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Vinagre de Jerez","amount":5,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Azúcar","amount":3,"unit":"g"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Cortar cebolla en cuartos.","Disponer pimiento rojo y pimiento amarillo enteros en una bandeja de horno junto con la cebolla y tomate maduro.","Rociar con aceite de oliva y hornear a 200 °C durante 40 min, hasta que la piel de los pimientos esté arrugada y tostada.","Retirar la bandeja del horno y cubrir los pimientos con film o introducirlos en una bolsa cerrada.","Dejar sudar los pimientos tapados 15 min hasta que estén templados.","Pelar los pimientos y retirar las semillas, reservando la pulpa.","Triturar la pulpa de los pimientos junto con la cebolla asada, el tomate asado y caldo de verduras hasta obtener una crema fina.","Colar la crema por un colador fino hasta conseguir una textura sedosa.","Calentar la crema en un cazo a fuego medio hasta que esté bien caliente.","Añadir el resto del aceite de oliva, vinagre de jerez y azúcar, y remover para integrar.","Añadir sal y remover.","Servir la crema caliente o templada."}', 'Crema de pimientos asados, dulce y con un intenso color rojo.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Cebolla}} en cuartos.","minutes":2,"kind":"prep"},{"text":"Disponer {{Pimiento rojo}} y {{Pimiento amarillo}} enteros en una bandeja de horno junto con la cebolla y {{Tomate maduro}}.","minutes":2,"kind":"prep"},{"text":"Rociar con {{Aceite de oliva|chorrito}} y hornear a 200 °C durante 40 min, hasta que la piel de los pimientos esté arrugada y tostada.","minutes":40,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y cubrir los pimientos con film o introducirlos en una bolsa cerrada.","minutes":1,"kind":"activo"},{"text":"Dejar sudar los pimientos tapados 15 min hasta que estén templados.","minutes":15,"kind":"espera"},{"text":"Pelar los pimientos y retirar las semillas, reservando la pulpa.","minutes":5,"kind":"prep"},{"text":"Triturar la pulpa de los pimientos junto con la cebolla asada, el tomate asado y {{Caldo de verduras}} hasta obtener una crema fina.","minutes":3,"kind":"activo"},{"text":"Colar la crema por un colador fino hasta conseguir una textura sedosa.","minutes":3,"kind":"activo"},{"text":"Calentar la crema en un cazo a fuego medio hasta que esté bien caliente.","minutes":4,"kind":"activo"},{"text":"Añadir el resto del {{Aceite de oliva}}, {{Vinagre de Jerez}} y {{Azúcar}}, y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y remover.","minutes":1,"kind":"activo"},{"text":"Servir la crema caliente o templada.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('sopas_cremas_058', 'Consomé con jerez', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 170, 'normal', 'invierno', 55, 6, 3, 2, 6, false, true, '{"huevo","sulfitos","apio"}', '[{"name":"Hueso de ternera","amount":400,"unit":"g"},{"name":"Morcillo de ternera","amount":200,"unit":"g"},{"name":"Hueso de jamón","amount":100,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Puerro","amount":80,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Apio","amount":50,"unit":"g"},{"name":"Agua","amount":2000,"unit":"ml"},{"name":"Jerez seco","amount":40,"unit":"ml"},{"name":"Clara de huevo","amount":1,"unit":"ud"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar zanahoria, puerro, cebolla y apio en trozos grandes.","Colocar hueso de ternera, morcillo de ternera y hueso de jamón en una olla grande.","Añadir agua fría y llevar a ebullición a fuego fuerte.","Retirar la espuma que sube a la superficie con una espumadera hasta que el caldo quede limpio.","Añadir las verduras troceadas a la olla.","Bajar el fuego a suave y cocer sin que hierva con fuerza durante 120 min, espumando de vez en cuando.","Colar el caldo a través de un colador fino, desechando los huesos y las verduras.","Dejar templar el caldo colado hasta que esté tibio pero no caliente.","Batir ligeramente clara de huevo en un bol pequeño.","Incorporar la clara batida al caldo templado y remover suavemente para repartirla.","Llevar a ebullición suave a fuego medio sin remover hasta que la clara forme una costra en la superficie.","Colar de nuevo con cuidado a través de un paño fino, sin presionar, para obtener un caldo cristalino.","Añadir sal y jerez seco al consomé clarificado.","Calentar a fuego suave hasta que esté bien caliente sin que llegue a hervir.","Servir bien caliente en tazas de consomé."}', 'Consomé de ternera clarificado, aromatizado con un toque de jerez seco.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['ternera','cerdo']::main_protein[], true, '[{"text":"Cortar {{Zanahoria}}, {{Puerro}}, {{Cebolla}} y {{Apio}} en trozos grandes.","minutes":5,"kind":"prep"},{"text":"Colocar {{Hueso de ternera}}, {{Morcillo de ternera}} y {{Hueso de jamón}} en una olla grande.","minutes":2,"kind":"prep"},{"text":"Añadir {{Agua}} fría y llevar a ebullición a fuego fuerte.","minutes":10,"kind":"activo"},{"text":"Retirar la espuma que sube a la superficie con una espumadera hasta que el caldo quede limpio.","minutes":5,"kind":"activo"},{"text":"Añadir las verduras troceadas a la olla.","minutes":1,"kind":"activo"},{"text":"Bajar el fuego a suave y cocer sin que hierva con fuerza durante 120 min, espumando de vez en cuando.","minutes":120,"kind":"pasivo"},{"text":"Colar el caldo a través de un colador fino, desechando los huesos y las verduras.","minutes":5,"kind":"activo"},{"text":"Dejar templar el caldo colado hasta que esté tibio pero no caliente.","minutes":15,"kind":"espera"},{"text":"Batir ligeramente {{Clara de huevo}} en un bol pequeño.","minutes":1,"kind":"prep"},{"text":"Incorporar la clara batida al caldo templado y remover suavemente para repartirla.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición suave a fuego medio sin remover hasta que la clara forme una costra en la superficie.","minutes":8,"kind":"pasivo"},{"text":"Colar de nuevo con cuidado a través de un paño fino, sin presionar, para obtener un caldo cristalino.","minutes":5,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y {{Jerez seco}} al consomé clarificado.","minutes":1,"kind":"activo"},{"text":"Calentar a fuego suave hasta que esté bien caliente sin que llegue a hervir.","minutes":4,"kind":"activo"},{"text":"Servir bien caliente en tazas de consomé.","minutes":1,"kind":"emplatado"}]'::jsonb, true, 'especial', NULL, 'olla', NULL, NULL),
  ('sopas_cremas_059', 'Crema de langostinos', 'sopas_cremas', 'marisco', NULL, ARRAY['primero','cena','plato_unico']::meal_role[], 'completo', NULL, 'batidora', 60, 'elaborada', 'all', 420, 30, 12, 28, 2, true, true, '{"marisco","pescado","lactosa","sulfitos"}', '[{"name":"Langostinos","amount":400,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Zanahoria","amount":60,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"g"},{"name":"Brandy","amount":30,"unit":"ml"},{"name":"Fumet de pescado","amount":400,"unit":"ml"},{"name":"Nata para cocinar","amount":100,"unit":"ml"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Pimentón dulce","amount":2,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pelar langostinos, reservando cáscaras y cabezas por separado. Guardar la carne en la nevera.","Picar cebolla, zanahoria y puerro en trozos pequeños.","Calentar aceite de oliva en una olla a fuego fuerte hasta que humee.","Sofreír las cáscaras y cabezas de langostino a fuego fuerte 5 min, presionándolas para que suelten todo su jugo.","Añadir la cebolla, la zanahoria y el puerro picados a la olla.","Sofreír las verduras a fuego medio hasta que estén blandas, unos 8 min.","Añadir tomate triturado y pimentón dulce y cocinar a fuego medio 3 min hasta que el tomate pierda el agua.","Añadir brandy y flambear acercando una llama, o subir el fuego fuerte, hasta que el alcohol se evapore por completo.","Añadir fumet de pescado y llevar a ebullición a fuego fuerte.","Cocer a fuego medio 20 min hasta que las cáscaras hayan cedido todo su sabor.","Triturar todo el conjunto, incluidas las cáscaras, con el túrmix o en batidora hasta obtener una pasta fina.","Colar la crema por un chino fino sobre la olla, presionando bien con una cuchara para extraer todo el sabor.","Calentar la crema colada a fuego suave, añadir nata para cocinar y remover hasta integrar sin que llegue a hervir.","Salpimentar con sal y remover.","Calentar un chorrito de aceite de oliva en sartén a fuego fuerte hasta que humee.","Saltear la carne de los langostinos reservada 2 min hasta que estén rosados y ligeramente dorados.","Servir la crema caliente en boles y colocar los langostinos salteados por encima."}', 'Crema untuosa de langostinos, todo el sabor del marisco en cada cucharada.', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Langostinos}}, reservando cáscaras y cabezas por separado. Guardar la carne en la nevera.","minutes":5,"kind":"prep"},{"text":"Picar {{Cebolla}}, {{Zanahoria}} y {{Puerro}} en trozos pequeños.","minutes":5,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego fuerte hasta que humee.","minutes":1,"kind":"activo"},{"text":"Sofreír las cáscaras y cabezas de langostino a fuego fuerte 5 min, presionándolas para que suelten todo su jugo.","minutes":5,"kind":"activo"},{"text":"Añadir la cebolla, la zanahoria y el puerro picados a la olla.","minutes":1,"kind":"activo"},{"text":"Sofreír las verduras a fuego medio hasta que estén blandas, unos 8 min.","minutes":8,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y {{Pimentón dulce|pizca}} y cocinar a fuego medio 3 min hasta que el tomate pierda el agua.","minutes":3,"kind":"activo"},{"text":"Añadir {{Brandy}} y flambear acercando una llama, o subir el fuego fuerte, hasta que el alcohol se evapore por completo.","minutes":1,"kind":"activo"},{"text":"Añadir {{Fumet de pescado}} y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio 20 min hasta que las cáscaras hayan cedido todo su sabor.","minutes":20,"kind":"pasivo"},{"text":"Triturar todo el conjunto, incluidas las cáscaras, con el túrmix o en batidora hasta obtener una pasta fina.","minutes":2,"kind":"activo"},{"text":"Colar la crema por un chino fino sobre la olla, presionando bien con una cuchara para extraer todo el sabor.","minutes":3,"kind":"activo"},{"text":"Calentar la crema colada a fuego suave, añadir {{Nata para cocinar}} y remover hasta integrar sin que llegue a hervir.","minutes":3,"kind":"activo"},{"text":"Salpimentar con {{Sal|gusto}} y remover.","minutes":1,"kind":"activo"},{"text":"Calentar un chorrito de aceite de oliva en {{@Sartén}} a fuego fuerte hasta que humee.","minutes":1,"kind":"activo"},{"text":"Saltear la carne de los langostinos reservada 2 min hasta que estén rosados y ligeramente dorados.","minutes":2,"kind":"activo"},{"text":"Servir la crema caliente en boles y colocar los langostinos salteados por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_060', 'Sopa de ajo con huevo escalfado', 'sopas_cremas', 'huevo', 'pan', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 25, 'facil', 'invierno', 358, 14, 26, 22, 2, true, false, '{"gluten","huevo"}', '[{"name":"Pan duro","amount":100,"unit":"g"},{"name":"Ajo","amount":20,"unit":"g"},{"name":"Pimentón dulce","amount":5,"unit":"g"},{"name":"Caldo de pollo","amount":600,"unit":"ml"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Aceite de oliva","amount":25,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"}]'::jsonb, '{"Cortar pan duro en rebanadas o taquitos finos.","Pelar y laminar ajo.","Calentar aceite de oliva en una cazuela a fuego medio.","Sofreír el ajo laminado hasta que se dore ligeramente, sin que se queme.","Añadir el pan y saltear hasta que absorba el aceite y se dore ligeramente.","Retirar la cazuela del fuego y añadir pimentón dulce, removiendo rápido para que no se queme.","Verter caldo de pollo y llevar a ebullición a fuego fuerte.","Añadir sal y cocer a fuego medio hasta que el pan se deshaga parcialmente y espese el caldo.","Cascar huevo uno a uno en un hueco hecho en la sopa, separando cada uno.","Cocer a fuego suave hasta que la clara cuaje y la yema quede líquida.","Servir de inmediato en cazuela individual muy caliente."}', 'Sopa castellana de ajo con pimentón y un huevo escalfado en el centro.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['pollo']::main_protein[], false, '[{"text":"Cortar {{Pan duro}} en rebanadas o taquitos finos.","minutes":2,"kind":"prep"},{"text":"Pelar y laminar {{Ajo}}.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una cazuela a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo laminado hasta que se dore ligeramente, sin que se queme.","minutes":3,"kind":"activo"},{"text":"Añadir el pan y saltear hasta que absorba el aceite y se dore ligeramente.","minutes":2,"kind":"activo"},{"text":"Retirar la cazuela del fuego y añadir {{Pimentón dulce}}, removiendo rápido para que no se queme.","minutes":1,"kind":"activo"},{"text":"Verter {{Caldo de pollo}} y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Añadir {{Sal|gusto}} y cocer a fuego medio hasta que el pan se deshaga parcialmente y espese el caldo.","minutes":10,"kind":"pasivo"},{"text":"Cascar {{Huevo}} uno a uno en un hueco hecho en la sopa, separando cada uno.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave hasta que la clara cuaje y la yema quede líquida.","minutes":3,"kind":"activo"},{"text":"Servir de inmediato en cazuela individual muy caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_061', 'Sopa de tomate con grilled cheese', 'sopas_cremas', 'none', 'pan', ARRAY['cena','primero','plato_unico']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 517, 17, 38, 33, 2, true, false, '{"gluten","lactosa"}', '[{"name":"Tomate triturado","amount":500,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Azúcar","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pan de molde","amount":4,"unit":"ud"},{"name":"Queso cheddar en lonchas","amount":80,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Picar cebolla fino.","Picar ajo fino.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada y el ajo picado hasta que estén transparentes.","Añadir tomate triturado y azúcar.","Cocer a fuego medio durante 10 min, removiendo de vez en cuando.","Untar una cara de cada rebanada de pan de molde con mantequilla.","Colocar queso cheddar en lonchas entre 2 rebanadas, con la mantequilla hacia afuera.","Verter caldo de verduras en la olla y llevar a ebullición.","Cocer a fuego medio durante 10 min.","Calentar sartén a fuego medio.","Tostar los sándwiches hasta que estén dorados por un lado.","Dar la vuelta a los sándwiches y tostar hasta que estén dorados y el queso cheddar esté fundido.","Triturar la sopa hasta obtener una crema fina.","Añadir nata para cocinar y calentar a fuego suave sin que hierva.","Añadir sal y remover.","Cortar los sándwiches en tiras.","Servir la crema de tomate caliente con las tiras de sándwich al lado para mojar."}', 'Sopa de tomate casera para mojar tiras de sándwich de queso fundido.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Picar {{Cebolla}} fino.","minutes":2,"kind":"prep","part":"principal"},{"text":"Picar {{Ajo}} fino.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva}} en una olla a fuego medio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Sofreír la cebolla picada y el ajo picado hasta que estén transparentes.","minutes":5,"kind":"activo","part":"principal"},{"text":"Añadir {{Tomate triturado}} y {{Azúcar}}.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cocer a fuego medio durante 10 min, removiendo de vez en cuando.","minutes":10,"kind":"pasivo","part":"principal"},{"text":"Untar una cara de cada rebanada de {{Pan de molde}} con {{Mantequilla}}.","minutes":2,"kind":"paralelo","part":"guarnicion","during":5},{"text":"Colocar {{Queso cheddar en lonchas}} entre 2 rebanadas, con la mantequilla hacia afuera.","minutes":1,"kind":"paralelo","part":"guarnicion","during":5},{"text":"Verter {{Caldo de verduras}} en la olla y llevar a ebullición.","minutes":2,"kind":"activo","part":"principal"},{"text":"Cocer a fuego medio durante 10 min.","minutes":10,"kind":"pasivo","part":"principal"},{"text":"Calentar {{@Sartén}} a fuego medio.","minutes":1,"kind":"paralelo","part":"guarnicion","during":9},{"text":"Tostar los sándwiches hasta que estén dorados por un lado.","minutes":3,"kind":"paralelo","part":"guarnicion","during":9},{"text":"Dar la vuelta a los sándwiches y tostar hasta que estén dorados y el queso cheddar esté fundido.","minutes":3,"kind":"paralelo","part":"guarnicion","during":9},{"text":"Triturar la sopa hasta obtener una crema fina.","minutes":1,"kind":"activo","part":"principal"},{"text":"Añadir {{Nata para cocinar}} y calentar a fuego suave sin que hierva.","minutes":2,"kind":"activo","part":"principal"},{"text":"Añadir {{Sal|gusto}} y remover.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cortar los sándwiches en tiras.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Servir la crema de tomate caliente con las tiras de sándwich al lado para mojar.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL, NULL),
  ('sopas_cremas_062', 'Crema de calabacín y queso azul', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 298, 9, 16, 22, 2, false, true, '{"lactosa"}', '[{"name":"Calabacín","amount":400,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Caldo de verduras","amount":350,"unit":"ml"},{"name":"Queso azul","amount":60,"unit":"g"},{"name":"Nata para cocinar","amount":50,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Sal","amount":2,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Pelar cebolla y picarla fina.","Pelar patata y cortarla en dados pequeños.","Lavar calabacín y cortarlo en rodajas.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir la patata y el calabacín y saltear 3 min a fuego medio.","Añadir caldo de verduras y llevar a ebullición.","Cocer a fuego medio hasta que las verduras estén tiernas.","Retirar del fuego y desmenuzar la mitad de queso azul sobre la olla.","Triturar todo con la batidora hasta obtener una crema fina.","Volver a calentar a fuego suave y añadir nata para cocinar.","Remover hasta integrar la nata por completo.","Salpimentar con sal y pimienta negra al gusto.","Servir la crema con el resto del queso azul desmenuzado por encima."}', 'Crema de calabacín con vetas de queso azul fundiéndose por encima.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Cebolla}} y picarla fina.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortarla en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Lavar {{Calabacín}} y cortarlo en rodajas.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada hasta que esté transparente.","minutes":5,"kind":"activo"},{"text":"Añadir la patata y el calabacín y saltear 3 min a fuego medio.","minutes":3,"kind":"activo"},{"text":"Añadir {{Caldo de verduras}} y llevar a ebullición.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que las verduras estén tiernas.","minutes":15,"kind":"pasivo"},{"text":"Retirar del fuego y desmenuzar la mitad de {{Queso azul}} sobre la olla.","minutes":1,"kind":"activo"},{"text":"Triturar todo con la batidora hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Volver a calentar a fuego suave y añadir {{Nata para cocinar}}.","minutes":1,"kind":"activo"},{"text":"Remover hasta integrar la nata por completo.","minutes":1,"kind":"activo"},{"text":"Salpimentar con {{Sal|gusto}} y {{Pimienta negra|pizca}} al gusto.","minutes":1,"kind":"activo"},{"text":"Servir la crema con el resto del queso azul desmenuzado por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_063', 'Vichyssoise de coliflor', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'normal', 'verano', 150, 5, 14, 9, 2, true, true, '{"lactosa"}', '[{"name":"Coliflor","amount":350,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Puerro","amount":150,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Nata para cocinar","amount":40,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar puerro y laminar en rodajas finas, desechando la parte verde oscura.","Pelar cebolla y picar en trozos pequeños.","Separar coliflor en ramilletes pequeños y lavar bien bajo el grifo.","Pelar patata y cortar en dados de 2 cm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír el puerro y la cebolla a fuego medio hasta que estén blandos.","Añadir la coliflor y la patata a la olla.","Cubrir con agua fría hasta superar los ingredientes 2 cm y llevar a ebullición.","Cocer a fuego medio hasta que la coliflor y la patata estén muy tiernas.","Retirar del fuego y triturar con la batidora hasta obtener una crema completamente fina.","Añadir nata para cocinar y remover hasta integrar por completo.","Dejar enfriar a temperatura ambiente antes de refrigerar.","Refrigerar la crema hasta que esté bien fría.","Servir la vichyssoise bien fría en cuencos."}', 'Vichyssoise blanca y sedosa de coliflor y puerro, más ligera que la clásica de patata', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Puerro}} y laminar en rodajas finas, desechando la parte verde oscura.","minutes":3,"kind":"prep"},{"text":"Pelar {{Cebolla}} y picar en trozos pequeños.","minutes":2,"kind":"prep"},{"text":"Separar {{Coliflor}} en ramilletes pequeños y lavar bien bajo el grifo.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados de 2 cm.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el puerro y la cebolla a fuego medio hasta que estén blandos.","minutes":5,"kind":"activo"},{"text":"Añadir la coliflor y la patata a la olla.","minutes":1,"kind":"activo"},{"text":"Cubrir con agua fría hasta superar los ingredientes 2 cm y llevar a ebullición.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la coliflor y la patata estén muy tiernas.","minutes":18,"kind":"pasivo"},{"text":"Retirar del fuego y triturar con la batidora hasta obtener una crema completamente fina.","minutes":2,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} y remover hasta integrar por completo.","minutes":1,"kind":"activo"},{"text":"Dejar enfriar a temperatura ambiente antes de refrigerar.","minutes":20,"kind":"espera"},{"text":"Refrigerar la crema hasta que esté bien fría.","minutes":120,"kind":"espera"},{"text":"Servir la vichyssoise bien fría en cuencos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_064', 'Crema de boniato y coco', 'sopas_cremas', 'none', 'patatas', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 230, 4, 30, 11, 2, true, true, '{}', '[{"name":"Boniato","amount":400,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Leche de coco","amount":200,"unit":"ml"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Jengibre fresco","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar boniato y cortar en dados de 2 cm.","Pelar cebolla y picar fino.","Pelar ajo y picar fino.","Pelar jengibre fresco y rallar.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada, el ajo picado y el jengibre rallado hasta que estén fragantes.","Añadir los dados de boniato y remover para integrar con el sofrito.","Verter caldo de verduras y llevar a ebullición.","Cocer a fuego medio hasta que el boniato esté muy tierno.","Añadir leche de coco y cocer 2 min más a fuego suave.","Triturar todo con la batidora hasta obtener una crema fina y untuosa.","Servir bien caliente."}', 'Crema naranja suave de boniato asado con leche de coco, cremosa sin necesitar nata', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Boniato}} y cortar en dados de 2 cm.","minutes":3,"kind":"prep"},{"text":"Pelar {{Cebolla}} y picar fino.","minutes":2,"kind":"prep"},{"text":"Pelar {{Ajo}} y picar fino.","minutes":1,"kind":"prep"},{"text":"Pelar {{Jengibre fresco}} y rallar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada, el ajo picado y el jengibre rallado hasta que estén fragantes.","minutes":4,"kind":"activo"},{"text":"Añadir los dados de boniato y remover para integrar con el sofrito.","minutes":1,"kind":"activo"},{"text":"Verter {{Caldo de verduras}} y llevar a ebullición.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que el boniato esté muy tierno.","minutes":15,"kind":"pasivo"},{"text":"Añadir {{Leche de coco}} y cocer 2 min más a fuego suave.","minutes":2,"kind":"activo"},{"text":"Triturar todo con la batidora hasta obtener una crema fina y untuosa.","minutes":2,"kind":"activo"},{"text":"Servir bien caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'olla', NULL, NULL)
