) values
  ('sopas_cremas_065', 'Gazpacho de pepino y aguacate', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 190, 5, 9, 15, 2, true, false, '{"lactosa","sulfitos"}', '[{"name":"Pepino","amount":300,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Pimiento verde","amount":40,"unit":"g"},{"name":"Cebolleta","amount":30,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Yogur natural","amount":100,"unit":"g"},{"name":"Zumo de lima","amount":10,"unit":"ml"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Agua fría","amount":100,"unit":"ml"}]'::jsonb, '{"Pelar pepino y cortar en trozos grandes.","Cortar aguacate por la mitad y deshuesar.","Extraer la pulpa del aguacate con una cuchara y reservar.","Retirar las semillas de pimiento verde y cortar en trozos.","Picar cebolleta en trozos gruesos.","Pelar ajo.","Introducir el pepino, el aguacate, el pimiento verde, la cebolleta y el ajo en el vaso de la batidora.","Añadir yogur natural, zumo de lima, vinagre de jerez y agua fría.","Triturar a máxima potencia hasta obtener una crema fina y homogénea.","Añadir aceite de oliva en hilo fino mientras se tritura hasta que emulsione.","Refrigerar el gazpacho hasta que esté bien frío.","Servir inmediatamente en cuencos fríos."}', 'Gazpacho verde intenso de pepino y aguacate, muy refrescante en días de calor', NULL, '{}', NULL, true, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Pepino}} y cortar en trozos grandes.","minutes":2,"kind":"prep"},{"text":"Cortar {{Aguacate}} por la mitad y deshuesar.","minutes":1,"kind":"prep"},{"text":"Extraer la pulpa del aguacate con una cuchara y reservar.","minutes":1,"kind":"prep"},{"text":"Retirar las semillas de {{Pimiento verde}} y cortar en trozos.","minutes":1,"kind":"prep"},{"text":"Picar {{Cebolleta}} en trozos gruesos.","minutes":1,"kind":"prep"},{"text":"Pelar {{Ajo}}.","minutes":1,"kind":"prep"},{"text":"Introducir el pepino, el aguacate, el pimiento verde, la cebolleta y el ajo en el vaso de la batidora.","minutes":1,"kind":"activo"},{"text":"Añadir {{Yogur natural}}, {{Zumo de lima}}, {{Vinagre de Jerez}} y {{Agua fría}}.","minutes":1,"kind":"activo"},{"text":"Triturar a máxima potencia hasta obtener una crema fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} en hilo fino mientras se tritura hasta que emulsione.","minutes":1,"kind":"activo"},{"text":"Refrigerar el gazpacho hasta que esté bien frío.","minutes":30,"kind":"espera"},{"text":"Servir inmediatamente en cuencos fríos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, NULL),
  ('sopas_cremas_066', 'Crema de guisantes y jamón crujiente', 'sopas_cremas', 'cerdo', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 210, 12, 18, 9, 2, true, true, '{}', '[{"name":"Guisantes congelados","amount":300,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Puerro","amount":100,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Caldo de pollo","amount":300,"unit":"ml"},{"name":"Jamón serrano en lonchas finas","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Menta fresca","amount":5,"unit":"g"}]'::jsonb, '{"Pelar cebolla y puerro, y picarlos en trozos pequeños.","Pelar patata y cortarla en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el puerro picados hasta que estén transparentes.","Añadir la patata en dados y caldo de pollo, y llevar a ebullición.","Cocer a fuego medio durante 10 min, hasta que la patata esté tierna.","Calentar el aceite de oliva restante en sartén a fuego fuerte.","Dorar jamón serrano en lonchas finas hasta que quede crujiente.","Retirar el jamón sobre papel absorbente y trocearlo en pedazos pequeños.","Añadir guisantes congelados a la olla y cocer 5 min hasta que estén tiernos y mantengan el color verde.","Añadir menta fresca a la olla y triturar la crema con la batidora hasta que quede fina y homogénea.","Servir la crema caliente en boles y repartir el jamón crujiente troceado por encima."}', 'Crema de guisantes verde vivo, coronada con virutas doradas de jamón crujiente', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['pollo']::main_protein[], true, '[{"text":"Pelar {{Cebolla}} y {{Puerro}}, y picarlos en trozos pequeños.","minutes":3,"kind":"prep"},{"text":"Pelar {{Patata}} y cortarla en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el puerro picados hasta que estén transparentes.","minutes":4,"kind":"activo"},{"text":"Añadir la patata en dados y {{Caldo de pollo}}, y llevar a ebullición.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio durante 10 min, hasta que la patata esté tierna.","minutes":10,"kind":"pasivo"},{"text":"Calentar el aceite de oliva restante en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Dorar {{Jamón serrano en lonchas finas}} hasta que quede crujiente.","minutes":2,"kind":"activo","part":"guarnicion"},{"text":"Retirar el jamón sobre papel absorbente y trocearlo en pedazos pequeños.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Añadir {{Guisantes congelados}} a la olla y cocer 5 min hasta que estén tiernos y mantengan el color verde.","minutes":5,"kind":"pasivo","part":"principal"},{"text":"Añadir {{Menta fresca}} a la olla y triturar la crema con la batidora hasta que quede fina y homogénea.","minutes":2,"kind":"activo","part":"principal"},{"text":"Servir la crema caliente en boles y repartir el jamón crujiente troceado por encima.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, true, 'olla', NULL, NULL),
  ('sopas_cremas_067', 'Sopa de tomate y pan (pappa al pomodoro)', 'sopas_cremas', 'none', 'pan', ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'verano', 260, 6, 32, 12, 2, true, true, '{"gluten"}', '[{"name":"Pan payés del día anterior","amount":150,"unit":"g"},{"name":"Tomate triturado","amount":400,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Aceite de oliva","amount":30,"unit":"ml"}]'::jsonb, '{"Cortar pan payés del día anterior en trozos irregulares de unos 3 cm.","Pelar y laminar ajo.","Calentar aceite de oliva en una olla a fuego suave.","Sofreír el ajo laminado hasta que esté fragante, sin que tome color.","Añadir tomate triturado y cocer a fuego medio, removiendo de vez en cuando.","Verter caldo de verduras y llevar a ebullición a fuego fuerte.","Añadir el pan troceado y remover para que se empape bien del caldo de tomate.","Cocer a fuego suave aplastando el pan con una cuchara hasta obtener textura espesa y rústica.","Retirar del fuego y añadir albahaca fresca troceada con las manos.","Añadir el resto del aceite de oliva y remover suavemente para integrarlo.","Reposar la sopa 5 min antes de servir, tibia o a temperatura ambiente.","Servir en boles con un hilo de aceite de oliva por encima."}', 'Sopa rústica y espesa de tomate y pan al estilo italiano, con aceite de oliva por encima', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Pan payés del día anterior}} en trozos irregulares de unos 3 cm.","minutes":3,"kind":"prep"},{"text":"Pelar y laminar {{Ajo}}.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego suave.","minutes":1,"kind":"activo"},{"text":"Sofreír el ajo laminado hasta que esté fragante, sin que tome color.","minutes":3,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y cocer a fuego medio, removiendo de vez en cuando.","minutes":10,"kind":"pasivo"},{"text":"Verter {{Caldo de verduras}} y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Añadir el pan troceado y remover para que se empape bien del caldo de tomate.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego suave aplastando el pan con una cuchara hasta obtener textura espesa y rústica.","minutes":9,"kind":"activo"},{"text":"Retirar del fuego y añadir {{Albahaca fresca}} troceada con las manos.","minutes":1,"kind":"activo"},{"text":"Añadir el resto del aceite de oliva y remover suavemente para integrarlo.","minutes":1,"kind":"activo"},{"text":"Reposar la sopa 5 min antes de servir, tibia o a temperatura ambiente.","minutes":5,"kind":"espera"},{"text":"Servir en boles con un hilo de aceite de oliva por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_068', 'Crema de puerros con almendra', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 210, 5, 18, 13, 2, true, true, '{"lactosa","frutos_secos"}', '[{"name":"Puerro","amount":350,"unit":"g"},{"name":"Patata","amount":120,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Nata para cocinar","amount":40,"unit":"ml"},{"name":"Almendras tostadas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar puerro y cortar en rodajas finas, desechando la parte verde más dura.","Pelar cebolla y picar en trozos finos.","Pelar patata y cortar en dados de 2 cm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír el puerro y la cebolla a fuego medio hasta que estén blandos.","Añadir la patata y cubrir con agua fría hasta superar los ingredientes 2 cm.","Llevar a ebullición y cocer a fuego medio hasta que la patata esté tierna.","Cortar almendras tostadas en trozos gruesos.","Retirar la olla del fuego y añadir nata para cocinar.","Triturar con la batidora hasta obtener una crema fina y homogénea.","Servir la crema caliente con las almendras troceadas por encima."}', 'Crema blanca aterciopelada de puerro, con almendra tostada troceada por encima', NULL, '{}', NULL, NULL, NULL, '{"lacteo","frutos_secos"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Puerro}} y cortar en rodajas finas, desechando la parte verde más dura.","minutes":3,"kind":"prep"},{"text":"Pelar {{Cebolla}} y picar en trozos finos.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados de 2 cm.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír el puerro y la cebolla a fuego medio hasta que estén blandos.","minutes":6,"kind":"activo"},{"text":"Añadir la patata y cubrir con agua fría hasta superar los ingredientes 2 cm.","minutes":1,"kind":"activo"},{"text":"Llevar a ebullición y cocer a fuego medio hasta que la patata esté tierna.","minutes":15,"kind":"pasivo"},{"text":"Cortar {{Almendras tostadas}} en trozos gruesos.","minutes":2,"kind":"paralelo","during":6},{"text":"Retirar la olla del fuego y añadir {{Nata para cocinar}}.","minutes":1,"kind":"activo"},{"text":"Triturar con la batidora hasta obtener una crema fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Servir la crema caliente con las almendras troceadas por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_069', 'Velouté de marisco con brandy', 'sopas_cremas', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 45, 'normal', 'all', 270, 16, 10, 18, 2, false, true, '{"marisco","lactosa","gluten","pescado"}', '[{"name":"Gambas","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Zanahoria","amount":50,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Harina","amount":15,"unit":"g"},{"name":"Nata para cocinar","amount":60,"unit":"ml"},{"name":"Brandy","amount":30,"unit":"ml"},{"name":"Fumet de pescado","amount":400,"unit":"ml"},{"name":"Tomate concentrado","amount":15,"unit":"g"},{"name":"Aceite de oliva","amount":10,"unit":"ml"}]'::jsonb, '{"Pelar gambas, separando las colas de las cáscaras y cabezas.","Picar cebolla, puerro y zanahoria en trozos finos.","Calentar aceite de oliva en una olla a fuego fuerte.","Saltear las cáscaras y cabezas de gamba hasta que tomen color.","Retirar las cáscaras y cabezas y reservar.","Sofreír la cebolla picada, el puerro picado y la zanahoria picada a fuego medio hasta que estén blandos.","Añadir tomate concentrado y remover a fuego medio durante 1 min.","Verter brandy y llevar a ebullición hasta que se evapore el alcohol.","Añadir fumet de pescado y las cáscaras y cabezas reservadas.","Cocer a fuego medio durante 15 min.","Colar el caldo con un colador, descartando cáscaras y verduras.","Fundir mantequilla en un cazo limpio a fuego medio.","Añadir harina y remover sin parar durante 1 min hasta obtener un roux liso.","Incorporar el caldo colado poco a poco, removiendo sin parar, hasta que la velouté espese.","Añadir las colas de gamba peladas y cocer a fuego medio hasta que estén rosadas.","Añadir nata para cocinar y remover hasta integrar.","Triturar la velouté con una batidora hasta obtener una textura sedosa.","Servir la velouté caliente en cuencos."}', 'Velouté naranja pálido de marisco, con el aroma que sube al flambear el brandy', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Gambas}}, separando las colas de las cáscaras y cabezas.","minutes":4,"kind":"prep"},{"text":"Picar {{Cebolla}}, {{Puerro}} y {{Zanahoria}} en trozos finos.","minutes":4,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Saltear las cáscaras y cabezas de gamba hasta que tomen color.","minutes":4,"kind":"activo"},{"text":"Retirar las cáscaras y cabezas y reservar.","minutes":1,"kind":"prep"},{"text":"Sofreír la cebolla picada, el puerro picado y la zanahoria picada a fuego medio hasta que estén blandos.","minutes":8,"kind":"pasivo"},{"text":"Añadir {{Tomate concentrado}} y remover a fuego medio durante 1 min.","minutes":1,"kind":"activo"},{"text":"Verter {{Brandy}} y llevar a ebullición hasta que se evapore el alcohol.","minutes":2,"kind":"activo"},{"text":"Añadir {{Fumet de pescado}} y las cáscaras y cabezas reservadas.","minutes":1,"kind":"activo"},{"text":"Cocer a fuego medio durante 15 min.","minutes":15,"kind":"pasivo"},{"text":"Colar el caldo con un colador, descartando cáscaras y verduras.","minutes":2,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en un cazo limpio a fuego medio.","minutes":1,"kind":"activo"},{"text":"Añadir {{Harina}} y remover sin parar durante 1 min hasta obtener un roux liso.","minutes":1,"kind":"activo"},{"text":"Incorporar el caldo colado poco a poco, removiendo sin parar, hasta que la velouté espese.","minutes":4,"kind":"activo"},{"text":"Añadir las colas de gamba peladas y cocer a fuego medio hasta que estén rosadas.","minutes":3,"kind":"activo"},{"text":"Añadir {{Nata para cocinar}} y remover hasta integrar.","minutes":1,"kind":"activo"},{"text":"Triturar la velouté con una batidora hasta obtener una textura sedosa.","minutes":2,"kind":"activo"},{"text":"Servir la velouté caliente en cuencos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, true),
  ('sopas_cremas_070', 'Crema fría de guisantes, menta y langostinos', 'sopas_cremas', 'marisco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'normal', 'verano', 220, 17, 14, 11, 2, true, true, '{"marisco","lactosa"}', '[{"name":"Guisantes congelados","amount":300,"unit":"g"},{"name":"Langostinos pelados","amount":150,"unit":"g"},{"name":"Menta fresca","amount":10,"unit":"g"},{"name":"Caldo de verduras","amount":250,"unit":"ml"},{"name":"Yogur natural","amount":80,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar ajo y reservar.","Llevar a ebullición caldo de verduras en un cazo a fuego fuerte.","Añadir guisantes congelados y el ajo pelado al caldo cuando rompa a hervir.","Cocer los guisantes y el ajo a fuego medio hasta que estén tiernos.","Calentar sartén a fuego fuerte con aceite de oliva.","Saltear langostinos pelados en la sartén caliente hasta que estén rosados.","Retirar los langostinos de la sartén y reservar en la nevera.","Escurrir los guisantes y el ajo cocidos, reservando el caldo de cocción.","Dejar enfriar los guisantes escurridos y el caldo reservado a temperatura ambiente.","Triturar los guisantes con el caldo reservado, menta fresca, yogur natural y el aceite de oliva hasta obtener una crema fina.","Colar la crema por un colador fino para lograr una textura más sedosa.","Refrigerar la crema en la nevera hasta que esté bien fría.","Servir la crema fría en boles con los langostinos reservados repartidos por encima."}', 'Crema fría de guisantes y menta, verde vivo con el rosa de los langostinos encima', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Ajo}} y reservar.","minutes":1,"kind":"prep"},{"text":"Llevar a ebullición {{Caldo de verduras}} en un cazo a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Añadir {{Guisantes congelados}} y el ajo pelado al caldo cuando rompa a hervir.","minutes":1,"kind":"activo"},{"text":"Cocer los guisantes y el ajo a fuego medio hasta que estén tiernos.","minutes":6,"kind":"pasivo"},{"text":"Calentar {{@Sartén}} a fuego fuerte con {{Aceite de oliva|chorrito}}.","minutes":1,"kind":"paralelo","during":3},{"text":"Saltear {{Langostinos pelados}} en la sartén caliente hasta que estén rosados.","minutes":3,"kind":"activo"},{"text":"Retirar los langostinos de la sartén y reservar en la nevera.","minutes":1,"kind":"activo"},{"text":"Escurrir los guisantes y el ajo cocidos, reservando el caldo de cocción.","minutes":1,"kind":"activo"},{"text":"Dejar enfriar los guisantes escurridos y el caldo reservado a temperatura ambiente.","minutes":5,"kind":"espera"},{"text":"Triturar los guisantes con el caldo reservado, {{Menta fresca}}, {{Yogur natural}} y el aceite de oliva hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Colar la crema por un colador fino para lograr una textura más sedosa.","minutes":2,"kind":"activo"},{"text":"Refrigerar la crema en la nevera hasta que esté bien fría.","minutes":60,"kind":"espera"},{"text":"Servir la crema fría en boles con los langostinos reservados repartidos por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, NULL),
  ('sopas_cremas_071', 'Sopa de cebolla con queso gratinado y jamón', 'sopas_cremas', 'cerdo', 'pan', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 50, 'normal', 'invierno', 340, 18, 26, 18, 2, true, false, '{"lactosa","gluten","sulfitos"}', '[{"name":"Cebolla","amount":400,"unit":"g"},{"name":"Mantequilla","amount":20,"unit":"g"},{"name":"Caldo de carne","amount":500,"unit":"ml"},{"name":"Vino blanco","amount":50,"unit":"ml"},{"name":"Pan de baguette en rebanadas","amount":60,"unit":"g"},{"name":"Queso gruyère rallado","amount":80,"unit":"g"},{"name":"Jamón cocido en tiras","amount":60,"unit":"g"},{"name":"Tomillo","amount":2,"unit":"g"}]'::jsonb, '{"Pelar cebolla y cortarla en juliana fina.","Fundir mantequilla en una olla a fuego medio-bajo.","Añadir la cebolla y sofreír a fuego suave, removiendo de vez en cuando, hasta que esté dorada y caramelizada.","Verter vino blanco y subir a fuego fuerte hasta que evapore el alcohol.","Añadir caldo de carne y tomillo y llevar a ebullición.","Cocer a fuego suave durante 10 min.","Precalentar el horno en función gratinador a 220 °C.","Repartir la sopa en 2 boles aptos para horno.","Colocar pan de baguette en rebanadas sobre cada bol.","Repartir jamón cocido en tiras sobre el pan de cada bol.","Cubrir con queso gruyère rallado repartido a partes iguales entre los 2 boles.","Gratinar en el horno 4 min hasta que el queso esté fundido y dorado.","Servir de inmediato con cuidado, pues los boles estarán muy calientes."}', 'Sopa de cebolla caramelizada con queso fundido y dorado sobre el caldo oscuro, y jamón', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Cebolla}} y cortarla en juliana fina.","minutes":5,"kind":"prep"},{"text":"Fundir {{Mantequilla}} en una olla a fuego medio-bajo.","minutes":2,"kind":"activo"},{"text":"Añadir la cebolla y sofreír a fuego suave, removiendo de vez en cuando, hasta que esté dorada y caramelizada.","minutes":25,"kind":"pasivo"},{"text":"Verter {{Vino blanco}} y subir a fuego fuerte hasta que evapore el alcohol.","minutes":3,"kind":"activo"},{"text":"Añadir {{Caldo de carne}} y {{Tomillo}} y llevar a ebullición.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego suave durante 10 min.","minutes":10,"kind":"pasivo"},{"text":"Precalentar el horno en función gratinador a 220 °C.","minutes":5,"kind":"paralelo","during":5},{"text":"Repartir la sopa en 2 boles aptos para horno.","minutes":1,"kind":"emplatado"},{"text":"Colocar {{Pan de baguette en rebanadas}} sobre cada bol.","minutes":1,"kind":"emplatado"},{"text":"Repartir {{Jamón cocido en tiras}} sobre el pan de cada bol.","minutes":1,"kind":"emplatado"},{"text":"Cubrir con {{Queso gruyère rallado}} repartido a partes iguales entre los 2 boles.","minutes":1,"kind":"emplatado"},{"text":"Gratinar en el horno 4 min hasta que el queso esté fundido y dorado.","minutes":4,"kind":"pasivo"},{"text":"Servir de inmediato con cuidado, pues los boles estarán muy calientes.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('sopas_cremas_072', 'Crema de calabaza asada con salvia frita', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 55, 'normal', 'invierno', 230, 4, 22, 14, 2, true, true, '{"lactosa"}', '[{"name":"Calabaza","amount":500,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Caldo de verduras","amount":300,"unit":"ml"},{"name":"Nata para cocinar","amount":40,"unit":"ml"},{"name":"Hojas de salvia fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Pelar calabaza y retirar las semillas.","Cortar la calabaza en dados de 3 cm.","Cortar cebolla en cuartos.","Colocar la calabaza y la cebolla en una bandeja de horno junto con ajo sin pelar.","Rociar con aceite de oliva y repartir bien por la bandeja.","Hornear a 200 °C durante 35 min hasta que la calabaza esté tierna y ligeramente dorada.","Retirar la bandeja del horno y dejar templar 5 min.","Pelar los dientes de ajo asados.","Poner la calabaza, la cebolla y el ajo en una olla.","Añadir caldo de verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio durante 5 min.","Añadir nata para cocinar y triturar con la batidora hasta obtener una crema fina.","Calentar el aceite de oliva restante en sartén a fuego fuerte.","Freír hojas de salvia fresca durante 1 min hasta que estén crujientes.","Retirar las hojas de salvia frita sobre papel absorbente.","Servir la crema caliente con las hojas de salvia frita por encima."}', 'Crema naranja profundo de calabaza asada, con hojas de salvia crujientes encima', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Pelar {{Calabaza}} y retirar las semillas.","minutes":3,"kind":"prep"},{"text":"Cortar la calabaza en dados de 3 cm.","minutes":2,"kind":"prep"},{"text":"Cortar {{Cebolla}} en cuartos.","minutes":1,"kind":"prep"},{"text":"Colocar la calabaza y la cebolla en una bandeja de horno junto con {{Ajo}} sin pelar.","minutes":1,"kind":"prep"},{"text":"Rociar con {{Aceite de oliva|chorrito}} y repartir bien por la bandeja.","minutes":1,"kind":"prep"},{"text":"Hornear a 200 °C durante 35 min hasta que la calabaza esté tierna y ligeramente dorada.","minutes":35,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y dejar templar 5 min.","minutes":5,"kind":"espera"},{"text":"Pelar los dientes de ajo asados.","minutes":1,"kind":"prep"},{"text":"Poner la calabaza, la cebolla y el ajo en una olla.","minutes":1,"kind":"activo"},{"text":"Añadir {{Caldo de verduras}} y llevar a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego medio durante 5 min.","minutes":5,"kind":"pasivo"},{"text":"Añadir {{Nata para cocinar}} y triturar con la batidora hasta obtener una crema fina.","minutes":3,"kind":"activo"},{"text":"Calentar el aceite de oliva restante en {{@Sartén}} a fuego fuerte.","minutes":1,"kind":"activo"},{"text":"Freír {{Hojas de salvia fresca}} durante 1 min hasta que estén crujientes.","minutes":1,"kind":"activo"},{"text":"Retirar las hojas de salvia frita sobre papel absorbente.","minutes":1,"kind":"activo"},{"text":"Servir la crema caliente con las hojas de salvia frita por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('sopas_cremas_073', 'Gazpacho verde de pepino y manzana', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 140, 2, 14, 9, 2, true, true, '{"apio"}', '[{"name":"Pepino","amount":250,"unit":"g"},{"name":"Manzana verde","amount":150,"unit":"g"},{"name":"Pimiento verde","amount":40,"unit":"g"},{"name":"Apio","amount":30,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Vinagre de manzana","amount":15,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Agua fría","amount":100,"unit":"ml"}]'::jsonb, '{"Pelar pepino y cortar en trozos grandes.","Descorazonar manzana verde y cortar en trozos, dejando la piel.","Retirar las semillas de pimiento verde y cortar en trozos.","Cortar apio en trozos y pelar ajo.","Introducir el pepino, la manzana verde, el pimiento verde y el apio en el vaso de la batidora.","Añadir el ajo, vinagre de manzana y agua fría al vaso.","Triturar a máxima potencia hasta obtener una crema fina y homogénea.","Añadir aceite de oliva en hilo fino mientras se tritura hasta que emulsione.","Refrigerar el gazpacho hasta que esté muy frío.","Servir el gazpacho muy frío en cuencos o vasos."}', 'Gazpacho verde brillante de pepino y manzana, dulce y ácido a la vez', NULL, '{}', NULL, true, NULL, '{"verdura","fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Pepino}} y cortar en trozos grandes.","minutes":2,"kind":"prep"},{"text":"Descorazonar {{Manzana verde}} y cortar en trozos, dejando la piel.","minutes":1,"kind":"prep"},{"text":"Retirar las semillas de {{Pimiento verde}} y cortar en trozos.","minutes":1,"kind":"prep"},{"text":"Cortar {{Apio}} en trozos y pelar {{Ajo}}.","minutes":1,"kind":"prep"},{"text":"Introducir el pepino, la manzana verde, el pimiento verde y el apio en el vaso de la batidora.","minutes":1,"kind":"activo"},{"text":"Añadir el ajo, {{Vinagre de manzana}} y {{Agua fría}} al vaso.","minutes":1,"kind":"activo"},{"text":"Triturar a máxima potencia hasta obtener una crema fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} en hilo fino mientras se tritura hasta que emulsione.","minutes":1,"kind":"activo"},{"text":"Refrigerar el gazpacho hasta que esté muy frío.","minutes":30,"kind":"espera"},{"text":"Servir el gazpacho muy frío en cuencos o vasos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, NULL),
  ('sopas_cremas_074', 'Crema de apionabo con avellanas tostadas', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'normal', 'all', 220, 5, 17, 14, 2, true, true, '{"apio","lactosa","frutos_secos"}', '[{"name":"Apionabo","amount":350,"unit":"g"},{"name":"Patata","amount":100,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Nata para cocinar","amount":40,"unit":"ml"},{"name":"Avellanas tostadas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar apionabo, retirando bien la piel gruesa, y cortar en dados de 2 cm.","Pelar patata y cortar en dados de 2 cm.","Pelar cebolla y picar fino.","Calentar aceite de oliva en una olla a fuego medio y sofreír la cebolla picada hasta que esté transparente.","Añadir el apionabo y la patata en dados a la olla.","Cubrir con agua fría hasta superar los ingredientes 2 cm y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que las verduras estén muy tiernas.","Picar groseramente avellanas tostadas con un cuchillo.","Retirar la olla del fuego y añadir nata para cocinar.","Triturar con la batidora hasta obtener una crema fina y homogénea.","Servir la crema caliente con las avellanas picadas por encima."}', 'Crema blanca suave de apionabo, con avellanas troceadas por encima', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo","frutos_secos"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Apionabo}}, retirando bien la piel gruesa, y cortar en dados de 2 cm.","minutes":4,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados de 2 cm.","minutes":2,"kind":"prep"},{"text":"Pelar {{Cebolla}} y picar fino.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio y sofreír la cebolla picada hasta que esté transparente.","minutes":4,"kind":"activo"},{"text":"Añadir el apionabo y la patata en dados a la olla.","minutes":1,"kind":"activo"},{"text":"Cubrir con agua fría hasta superar los ingredientes 2 cm y llevar a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Cocer a fuego medio hasta que las verduras estén muy tiernas.","minutes":20,"kind":"pasivo"},{"text":"Picar groseramente {{Avellanas tostadas}} con un cuchillo.","minutes":2,"kind":"paralelo","during":6},{"text":"Retirar la olla del fuego y añadir {{Nata para cocinar}}.","minutes":1,"kind":"activo"},{"text":"Triturar con la batidora hasta obtener una crema fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Servir la crema caliente con las avellanas picadas por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL)
