) values
  ('sopas_cremas_075', 'Sopa de tomate asado con burrata', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'horno', 45, 'facil', 'all', 260, 9, 14, 19, 2, true, false, '{"lactosa"}', '[{"name":"Tomate maduro","amount":600,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Ajo","amount":15,"unit":"g"},{"name":"Burrata","amount":125,"unit":"g"},{"name":"Albahaca fresca","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":40,"unit":"ml"}]'::jsonb, '{"Precalentar el horno a 200 °C.","Cortar tomate maduro por la mitad.","Cortar cebolla en cuartos.","Disponer el tomate y la cebolla en una bandeja de horno junto con ajo entero y con piel.","Rociar con aceite de oliva y añadir sal por encima.","Hornear a 200 °C durante 30 min hasta que el tomate esté blando y ligeramente tostado.","Retirar la bandeja del horno y dejar templar hasta que se pueda manipular sin quemarse.","Pelar el ajo asado apretando cada diente para extraer la pulpa.","Triturar el tomate, la cebolla y el ajo asados con una batidora hasta obtener una crema fina.","Colar la crema por un colador fino presionando con una cuchara hasta que la textura sea sedosa.","Calentar la crema en una olla a fuego suave durante 5 min hasta que esté bien caliente.","Rectificar de sal al gusto y remover.","Verter la sopa caliente en boles.","Colocar burrata partida en trozos en el centro de cada bol.","Terminar con un chorrito de aceite de oliva y hojas de albahaca fresca por encima."}', 'Sopa de tomate asado rojo intenso, con el corte cremoso de la burrata en el centro', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], true, '[{"text":"Precalentar el horno a 200 °C.","minutes":10,"kind":"pasivo"},{"text":"Cortar {{Tomate maduro}} por la mitad.","minutes":2,"kind":"prep"},{"text":"Cortar {{Cebolla}} en cuartos.","minutes":1,"kind":"paralelo","during":0},{"text":"Disponer el tomate y la cebolla en una bandeja de horno junto con {{Ajo}} entero y con piel.","minutes":1,"kind":"paralelo","during":0},{"text":"Rociar con {{Aceite de oliva|chorrito}} y añadir {{Sal|gusto}} por encima.","minutes":1,"kind":"paralelo","during":0},{"text":"Hornear a 200 °C durante 30 min hasta que el tomate esté blando y ligeramente tostado.","minutes":30,"kind":"pasivo"},{"text":"Retirar la bandeja del horno y dejar templar hasta que se pueda manipular sin quemarse.","minutes":5,"kind":"espera"},{"text":"Pelar el ajo asado apretando cada diente para extraer la pulpa.","minutes":1,"kind":"prep"},{"text":"Triturar el tomate, la cebolla y el ajo asados con una batidora hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Colar la crema por un colador fino presionando con una cuchara hasta que la textura sea sedosa.","minutes":3,"kind":"activo"},{"text":"Calentar la crema en una olla a fuego suave durante 5 min hasta que esté bien caliente.","minutes":5,"kind":"pasivo"},{"text":"Rectificar de sal al gusto y remover.","minutes":1,"kind":"activo"},{"text":"Verter la sopa caliente en boles.","minutes":1,"kind":"emplatado"},{"text":"Colocar {{Burrata}} partida en trozos en el centro de cada bol.","minutes":1,"kind":"emplatado"},{"text":"Terminar con un chorrito de aceite de oliva y hojas de {{Albahaca fresca}} por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'horno', NULL, NULL),
  ('sopas_cremas_076', 'Crema de espárragos verdes con parmesano', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 25, 'facil', 'all', 180, 8, 12, 11, 2, true, true, '{"lactosa"}', '[{"name":"Espárragos verdes","amount":350,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Caldo de verduras","amount":300,"unit":"ml"},{"name":"Queso parmesano en virutas","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Lavar espárragos verdes y retirar la parte final dura del tallo.","Cortar los espárragos en trozos, reservando las puntas para emplatar.","Pelar y picar cebolla.","Pelar patata y cortarla en dados pequeños.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada hasta que esté transparente.","Añadir los dados de patata y los trozos de espárrago y saltear 2 min a fuego medio.","Verter caldo de verduras y llevar a ebullición a fuego fuerte.","Cocer a fuego medio hasta que la patata y los espárragos estén tiernos.","Calentar sartén a fuego medio con un chorrito de aceite de oliva.","Saltear las puntas de espárrago reservadas hasta que estén tiernas y ligeramente doradas.","Retirar la olla del fuego y triturar la crema con la batidora hasta que quede fina y homogénea.","Servir la crema caliente con las puntas salteadas y queso parmesano en virutas por encima."}', 'Crema verde vivo de espárragos, con virutas de parmesano flotando en la superficie', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Lavar {{Espárragos verdes}} y retirar la parte final dura del tallo.","minutes":2,"kind":"prep"},{"text":"Cortar los espárragos en trozos, reservando las puntas para emplatar.","minutes":2,"kind":"prep"},{"text":"Pelar y picar {{Cebolla}}.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortarla en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada hasta que esté transparente.","minutes":4,"kind":"activo"},{"text":"Añadir los dados de patata y los trozos de espárrago y saltear 2 min a fuego medio.","minutes":2,"kind":"activo"},{"text":"Verter {{Caldo de verduras}} y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que la patata y los espárragos estén tiernos.","minutes":13,"kind":"pasivo"},{"text":"Calentar {{@Sartén}} a fuego medio con un chorrito de aceite de oliva.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Saltear las puntas de espárrago reservadas hasta que estén tiernas y ligeramente doradas.","minutes":4,"kind":"activo","part":"guarnicion"},{"text":"Retirar la olla del fuego y triturar la crema con la batidora hasta que quede fina y homogénea.","minutes":2,"kind":"activo","part":"principal"},{"text":"Servir la crema caliente con las puntas salteadas y {{Queso parmesano en virutas}} por encima.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_077', 'Vichyssoise con crujiente de jamón', 'sopas_cremas', 'cerdo', 'patatas', ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'normal', 'verano', 240, 9, 22, 13, 2, true, true, '{"lactosa"}', '[{"name":"Puerro","amount":250,"unit":"g"},{"name":"Patata","amount":200,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Nata para cocinar","amount":40,"unit":"ml"},{"name":"Jamón serrano en lonchas finas","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar puerro y laminar en rodajas finas, desechando la parte verde oscura.","Pelar cebolla y picar fino.","Pelar patata y cortar en dados de 2 cm.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír el puerro y la cebolla hasta que estén blandos y transparentes.","Añadir la patata y cubrir con agua fría hasta superar los ingredientes 2 cm.","Llevar a ebullición y cocer hasta que la patata esté tierna.","Calentar un chorrito de aceite de oliva en sartén a fuego medio.","Dorar jamón serrano en lonchas finas hasta que queden crujientes.","Retirar el jamón y dejar enfriar sobre papel absorbente.","Trocear el jamón en fragmentos pequeños y reservar.","Retirar la olla del fuego y añadir nata para cocinar.","Triturar con la batidora hasta obtener una crema completamente fina.","Dejar enfriar la crema y refrigerar hasta que esté bien fría.","Servir la vichyssoise bien fría con el crujiente de jamón repartido por encima."}', 'Vichyssoise blanca y fría, con virutas doradas de jamón crujiente por encima', NULL, '{}', NULL, NULL, NULL, '{"lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Puerro}} y laminar en rodajas finas, desechando la parte verde oscura.","minutes":3,"kind":"prep","part":"principal"},{"text":"Pelar {{Cebolla}} y picar fino.","minutes":2,"kind":"prep","part":"principal"},{"text":"Pelar {{Patata}} y cortar en dados de 2 cm.","minutes":3,"kind":"prep","part":"principal"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo","part":"principal"},{"text":"Sofreír el puerro y la cebolla hasta que estén blandos y transparentes.","minutes":7,"kind":"activo","part":"principal"},{"text":"Añadir la patata y cubrir con agua fría hasta superar los ingredientes 2 cm.","minutes":1,"kind":"activo","part":"principal"},{"text":"Llevar a ebullición y cocer hasta que la patata esté tierna.","minutes":15,"kind":"pasivo","part":"principal"},{"text":"Calentar un chorrito de aceite de oliva en {{@Sartén}} a fuego medio.","minutes":1,"kind":"activo","part":"guarnicion"},{"text":"Dorar {{Jamón serrano en lonchas finas}} hasta que queden crujientes.","minutes":3,"kind":"activo","part":"guarnicion"},{"text":"Retirar el jamón y dejar enfriar sobre papel absorbente.","minutes":3,"kind":"espera","part":"guarnicion"},{"text":"Trocear el jamón en fragmentos pequeños y reservar.","minutes":1,"kind":"prep","part":"guarnicion"},{"text":"Retirar la olla del fuego y añadir {{Nata para cocinar}}.","minutes":1,"kind":"activo","part":"principal"},{"text":"Triturar con la batidora hasta obtener una crema completamente fina.","minutes":2,"kind":"activo","part":"principal"},{"text":"Dejar enfriar la crema y refrigerar hasta que esté bien fría.","minutes":120,"kind":"espera","part":"principal"},{"text":"Servir la vichyssoise bien fría con el crujiente de jamón repartido por encima.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_078', 'Crema de setas con castañas', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 35, 'normal', 'invierno', 200, 6, 22, 9, 2, true, true, '{"lactosa"}', '[{"name":"Setas variadas","amount":300,"unit":"g"},{"name":"Castañas cocidas","amount":100,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Caldo de verduras","amount":300,"unit":"ml"},{"name":"Nata para cocinar","amount":30,"unit":"ml"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Tomillo","amount":2,"unit":"g"}]'::jsonb, '{"Limpiar setas variadas con un paño húmedo para retirar la tierra.","Cortar las setas en trozos regulares.","Pelar cebolla y puerro y picar ambos en trozos finos.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla y el puerro picados hasta que estén blandos y translúcidos.","Añadir las setas troceadas y saltear a fuego fuerte hasta que suelten su agua y esta se evapore.","Añadir castañas cocidas y tomillo y remover para integrar.","Verter caldo de verduras y llevar a ebullición a fuego medio.","Cocer a fuego suave hasta que todos los ingredientes estén tiernos.","Retirar la olla del fuego y añadir nata para cocinar.","Triturar el conjunto con la batidora hasta obtener una crema fina y homogénea.","Servir la crema bien caliente en cuencos."}', 'Crema marrón profunda de setas y castañas, con dulzor de otoño de fondo', NULL, '{}', NULL, NULL, NULL, '{"verdura","seta","frutos_secos"}', NULL, '{}'::main_protein[], true, '[{"text":"Limpiar {{Setas variadas}} con un paño húmedo para retirar la tierra.","minutes":3,"kind":"prep"},{"text":"Cortar las setas en trozos regulares.","minutes":2,"kind":"prep"},{"text":"Pelar {{Cebolla}} y {{Puerro}} y picar ambos en trozos finos.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el puerro picados hasta que estén blandos y translúcidos.","minutes":5,"kind":"activo"},{"text":"Añadir las setas troceadas y saltear a fuego fuerte hasta que suelten su agua y esta se evapore.","minutes":8,"kind":"activo"},{"text":"Añadir {{Castañas cocidas}} y {{Tomillo|pizca}} y remover para integrar.","minutes":1,"kind":"activo"},{"text":"Verter {{Caldo de verduras}} y llevar a ebullición a fuego medio.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego suave hasta que todos los ingredientes estén tiernos.","minutes":12,"kind":"pasivo"},{"text":"Retirar la olla del fuego y añadir {{Nata para cocinar}}.","minutes":1,"kind":"activo"},{"text":"Triturar el conjunto con la batidora hasta obtener una crema fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Servir la crema bien caliente en cuencos.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_079', 'Sopa fría de tomate y sandía', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 15, 'facil', 'verano', 140, 2, 15, 8, 2, true, true, '{"sulfitos"}', '[{"name":"Tomate maduro","amount":300,"unit":"g"},{"name":"Sandía","amount":300,"unit":"g"},{"name":"Pepino","amount":50,"unit":"g"},{"name":"Ajo","amount":5,"unit":"g"},{"name":"Vinagre de Jerez","amount":10,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Albahaca fresca","amount":5,"unit":"g"}]'::jsonb, '{"Cortar tomate maduro en trozos, retirando el pedúnculo.","Cortar sandía en trozos, retirando las pepitas si las hubiera.","Pelar pepino y cortar en trozos.","Pelar ajo.","Introducir el tomate, la sandía, el pepino y el ajo en el vaso de la batidora.","Añadir vinagre de jerez al vaso de la batidora.","Triturar a máxima potencia hasta obtener una crema fina y homogénea.","Añadir aceite de oliva en hilo fino mientras se tritura hasta que emulsione.","Refrigerar la sopa hasta que esté muy fría.","Picar albahaca fresca fina justo antes de servir.","Servir la sopa muy fría con la albahaca picada por encima."}', 'Sopa fría de tomate y sandía, rojo vivo y sorprendentemente refrescante', NULL, '{}', NULL, true, NULL, '{"verdura","fruta"}', NULL, '{}'::main_protein[], false, '[{"text":"Cortar {{Tomate maduro}} en trozos, retirando el pedúnculo.","minutes":2,"kind":"prep"},{"text":"Cortar {{Sandía}} en trozos, retirando las pepitas si las hubiera.","minutes":2,"kind":"prep"},{"text":"Pelar {{Pepino}} y cortar en trozos.","minutes":1,"kind":"prep"},{"text":"Pelar {{Ajo}}.","minutes":1,"kind":"prep"},{"text":"Introducir el tomate, la sandía, el pepino y el ajo en el vaso de la batidora.","minutes":1,"kind":"activo"},{"text":"Añadir {{Vinagre de Jerez}} al vaso de la batidora.","minutes":1,"kind":"activo"},{"text":"Triturar a máxima potencia hasta obtener una crema fina y homogénea.","minutes":2,"kind":"activo"},{"text":"Añadir {{Aceite de oliva|chorrito}} en hilo fino mientras se tritura hasta que emulsione.","minutes":1,"kind":"activo"},{"text":"Refrigerar la sopa hasta que esté muy fría.","minutes":60,"kind":"espera"},{"text":"Picar {{Albahaca fresca}} fina justo antes de servir.","minutes":1,"kind":"prep"},{"text":"Servir la sopa muy fría con la albahaca picada por encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'crudo', NULL, NULL),
  ('sopas_cremas_080', 'Crema de zanahoria y naranja', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, 'batidora', 30, 'facil', 'all', 170, 3, 24, 7, 2, true, true, '{}', '[{"name":"Zanahoria","amount":400,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Patata","amount":80,"unit":"g"},{"name":"Zumo de naranja","amount":150,"unit":"ml"},{"name":"Caldo de verduras","amount":200,"unit":"ml"},{"name":"Jengibre fresco","amount":5,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar zanahoria y cortar en rodajas.","Pelar cebolla y picar fino.","Pelar patata y cortar en dados pequeños.","Pelar jengibre fresco y rallar.","Calentar aceite de oliva en una olla a fuego medio.","Sofreír la cebolla picada y el jengibre rallado hasta que estén fragantes.","Añadir la zanahoria y la patata y remover.","Verter caldo de verduras y llevar a ebullición.","Cocer a fuego medio hasta que las verduras estén muy tiernas.","Añadir zumo de naranja y cocer 2 min más.","Retirar del fuego y triturar con la batidora hasta obtener una crema fina.","Añadir un poco de agua si la crema ha quedado demasiado espesa y remover.","Servir caliente."}', 'Crema de zanahoria y naranja, naranja intenso por partida doble y muy suave', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Pelar {{Zanahoria}} y cortar en rodajas.","minutes":3,"kind":"prep"},{"text":"Pelar {{Cebolla}} y picar fino.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en dados pequeños.","minutes":2,"kind":"prep"},{"text":"Pelar {{Jengibre fresco}} y rallar.","minutes":1,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla picada y el jengibre rallado hasta que estén fragantes.","minutes":3,"kind":"activo"},{"text":"Añadir la zanahoria y la patata y remover.","minutes":1,"kind":"activo"},{"text":"Verter {{Caldo de verduras}} y llevar a ebullición.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio hasta que las verduras estén muy tiernas.","minutes":18,"kind":"pasivo"},{"text":"Añadir {{Zumo de naranja}} y cocer 2 min más.","minutes":2,"kind":"activo"},{"text":"Retirar del fuego y triturar con la batidora hasta obtener una crema fina.","minutes":2,"kind":"activo"},{"text":"Añadir un poco de agua si la crema ha quedado demasiado espesa y remover.","minutes":1,"kind":"opcional"},{"text":"Servir caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, true, 'olla', NULL, NULL),
  ('sopas_cremas_081', 'Bullabesa ligera de pescado', 'sopas_cremas', 'pescado_blanco', NULL, ARRAY['primero','cena','plato_unico']::meal_role[], 'completo', NULL, NULL, 45, 'elaborada', 'all', 320, 30, 16, 14, 2, true, true, '{"pescado","marisco","moluscos","gluten","sulfitos"}', '[{"name":"Rape","amount":150,"unit":"g"},{"name":"Mejillones","amount":150,"unit":"g"},{"name":"Gambas","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":150,"unit":"g"},{"name":"Cebolla","amount":60,"unit":"g"},{"name":"Puerro","amount":60,"unit":"g"},{"name":"Hinojo","amount":60,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Azafrán en hebras","amount":1,"unit":"g"},{"name":"Vino blanco","amount":80,"unit":"ml"},{"name":"Fumet de pescado","amount":400,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Pan tostado","amount":40,"unit":"g"},{"name":"Perejil fresco","amount":5,"unit":"g"}]'::jsonb, '{"Limpiar mejillones raspando las conchas y retirando las barbas.","Pelar gambas y reservar.","Cortar rape en trozos grandes y salpimentar ligeramente.","Picar cebolla, puerro, hinojo y ajo fino.","Calentar aceite de oliva en una olla amplia a fuego medio.","Sofreír la cebolla, el puerro, el hinojo y el ajo hasta que estén blandos.","Añadir tomate triturado y azafrán en hebras y sofreír.","Verter vino blanco y hervir hasta que reduzca.","Añadir fumet de pescado, llevar a ebullición y cocer a fuego medio.","Incorporar el rape y cocer hasta que empiece a estar hecho.","Añadir los mejillones y las gambas y cocer hasta que los mejillones se abran.","Retirar y descartar los mejillones que no se hayan abierto.","Picar perejil fresco fino y reservar.","Servir la bullabesa en boles hondos con pan tostado y el perejil picado por encima."}', 'Bullabesa de caldo dorado con azafrán y piezas enteras de pescado y marisco', NULL, '{}', true, NULL, NULL, '{}', NULL, ARRAY['marisco']::main_protein[], true, '[{"text":"Limpiar {{Mejillones}} raspando las conchas y retirando las barbas.","minutes":3,"kind":"prep"},{"text":"Pelar {{Gambas}} y reservar.","minutes":2,"kind":"prep"},{"text":"Cortar {{Rape}} en trozos grandes y salpimentar ligeramente.","minutes":2,"kind":"prep"},{"text":"Picar {{Cebolla}}, {{Puerro}}, {{Hinojo}} y {{Ajo}} fino.","minutes":4,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una olla amplia a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla, el puerro, el hinojo y el ajo hasta que estén blandos.","minutes":8,"kind":"pasivo"},{"text":"Añadir {{Tomate triturado}} y {{Azafrán en hebras}} y sofreír.","minutes":4,"kind":"activo"},{"text":"Verter {{Vino blanco}} y hervir hasta que reduzca.","minutes":2,"kind":"activo"},{"text":"Añadir {{Fumet de pescado}}, llevar a ebullición y cocer a fuego medio.","minutes":10,"kind":"pasivo"},{"text":"Incorporar el rape y cocer hasta que empiece a estar hecho.","minutes":4,"kind":"pasivo"},{"text":"Añadir los mejillones y las gambas y cocer hasta que los mejillones se abran.","minutes":4,"kind":"activo"},{"text":"Retirar y descartar los mejillones que no se hayan abierto.","minutes":1,"kind":"activo"},{"text":"Picar {{Perejil fresco}} fino y reservar.","minutes":1,"kind":"prep"},{"text":"Servir la bullabesa en boles hondos con {{Pan tostado}} y el perejil picado por encima.","minutes":2,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_082', 'Puré de verduras con picatostes', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 220, 6, 30, 8, 2, true, true, '{"gluten"}', '[{"name":"Patata","amount":150,"unit":"g"},{"name":"Puerro","amount":100,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Calabacín","amount":100,"unit":"g"},{"name":"Pan de molde","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar y trocear las verduras, cocer en agua o caldo con sal 20 min hasta que estén tiernas.","Triturar hasta obtener una crema fina, rectificar de sal.","Cortar el pan en dados y tostar en una sartén con un poco de aceite hasta dorar.","Servir el puré con los picatostes por encima."}', 'Puré casero de verduras de siempre, con picatostes crujientes.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, true, 'olla', NULL, NULL),
  ('sopas_cremas_083', 'Sopa de picadillo con jamón y huevo duro', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 20, 'facil', 'all', 240, 14, 26, 8, 2, true, true, '{"gluten","huevo"}', '[{"name":"Caldo de pollo","amount":600,"unit":"ml"},{"name":"Fideos finos","amount":60,"unit":"g"},{"name":"Jamón serrano en tacos","amount":40,"unit":"g"},{"name":"Huevo","amount":2,"unit":"ud"},{"name":"Perejil","amount":5,"unit":"g"}]'::jsonb, '{"Cocer los huevos 10 min, enfriar, pelar y picar.","Llevar el caldo a ebullición, añadir los fideos y cocer 4-5 min.","Incorporar el jamón en tacos y el huevo picado.","Servir espolvoreado con perejil."}', 'Sopa de fideos con jamón y huevo duro picado, la sopa de toda la vida.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, ARRAY['cerdo']::main_protein[], NULL, NULL, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_084', 'Caldo con fideos, pollo y verduras', 'sopas_cremas', 'pollo', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 40, 'facil', 'all', 200, 16, 22, 5, 2, true, true, '{"gluten","apio"}', '[{"name":"Pechuga de pollo","amount":150,"unit":"g"},{"name":"Fideos finos","amount":60,"unit":"g"},{"name":"Zanahoria","amount":1,"unit":"ud"},{"name":"Puerro","amount":0.5,"unit":"ud"},{"name":"Apio","amount":0.5,"unit":"ud"},{"name":"Agua","amount":700,"unit":"ml"}]'::jsonb, '{"Cocer la pechuga de pollo con las verduras troceadas en agua con sal 25-30 min hasta que el pollo esté hecho.","Retirar el pollo, desmenuzarlo y volver a incorporarlo al caldo.","Añadir los fideos y cocer 4-5 min más.","Servir caliente."}', 'Caldo casero de pollo con verduras y fideos.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, NULL, 'olla', NULL, NULL)
