insert into recipes (
  id, name, category, main_protein, main_base, meal_roles, type, base_dish_id, required_appliance, time_minutes, difficulty, season, kcal, protein_g, carbs_g, fat_g, base_servings, kid_friendly, tupper_friendly, allergens, ingredients, steps, description, methods, product_aliases, apetecible, montaje, can_be_garnish, main_ingredients, sauce_id, extra_proteins, freezable, steps_rich, estrella, occasion, kid_favourite, tecnica, cocina, lleva_salsa
) values
  ('sopas_cremas_085', 'Sopa de pescado sencilla con picatostes', 'sopas_cremas', 'pescado_blanco', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 260, 20, 22, 10, 2, true, true, '{"pescado","gluten"}', '[{"name":"Merluza o pescado blanco","amount":200,"unit":"g"},{"name":"Fideos finos","amount":50,"unit":"g"},{"name":"Tomate triturado","amount":60,"unit":"ml"},{"name":"Cebolla","amount":0.5,"unit":"ud"},{"name":"Pan de molde","amount":30,"unit":"g"},{"name":"Aceite de oliva","amount":15,"unit":"ml"},{"name":"Caldo de pescado","amount":500,"unit":"ml"}]'::jsonb, '{"Sofreír la cebolla picada con aceite hasta transparentar, añadir el tomate y cocinar 5 min.","Incorporar el caldo de pescado y llevar a ebullición.","Añadir los fideos y cocer 4 min, incorporar el pescado troceado y cocinar 3-4 min más hasta que esté hecho.","Tostar el pan en dados y servir la sopa con los picatostes por encima."}', 'Sopa de pescado sencilla con fideos y picatostes, sin mariscos caros.', NULL, '{}', NULL, NULL, NULL, '{}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, NULL, 'olla', NULL, NULL),
  ('sopas_cremas_086', 'Sopa de verduras con pasta y jamón', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 220, 10, 30, 6, 2, true, true, '{"gluten"}', '[{"name":"Caldo de verduras","amount":600,"unit":"ml"},{"name":"Pasta pequeña","amount":60,"unit":"g"},{"name":"Zanahoria","amount":1,"unit":"ud"},{"name":"Judía verde","amount":100,"unit":"g"},{"name":"Jamón serrano en tacos","amount":40,"unit":"g"}]'::jsonb, '{"Llevar el caldo a ebullición, añadir la zanahoria y la judía verde troceadas, cocer 10 min.","Incorporar la pasta y cocer 8-10 min más hasta que esté al dente.","Añadir el jamón en tacos al final.","Servir caliente."}', 'Sopa ligera de verduras con pasta pequeña y jamón serrano.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, ARRAY['cerdo']::main_protein[], NULL, NULL, true, NULL, NULL, 'olla', 'italiana', NULL),
  ('sopas_cremas_087', 'Sopa de tortilla con aguacate y crema', 'sopas_cremas', 'none', 'pan', ARRAY['primero']::meal_role[], 'completo', NULL, NULL, 30, 'facil', 'all', 310, 8, 32, 17, 2, true, true, '{"lactosa"}', '[{"name":"Tortillas de maíz","amount":4,"unit":"ud"},{"name":"Tomate maduro","amount":400,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Caldo de pollo","amount":600,"unit":"ml"},{"name":"Aguacate","amount":1,"unit":"ud"},{"name":"Queso crema","amount":60,"unit":"g"},{"name":"Cilantro fresco","amount":10,"unit":"g"},{"name":"Aceite de oliva","amount":30,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Cortar las tortillas en tiras finas y freírlas en el aceite hasta que estén doradas y crujientes. Reservar sobre papel absorbente.","En la misma cazuela, pochar la cebolla y el ajo picados hasta que estén transparentes.","Añadir el tomate troceado y cocinar 10 minutos, aplastándolo con la cuchara.","Triturar el sofrito y devolverlo a la cazuela con el caldo. Cocer 10 minutos a fuego suave y salar.","Servir la sopa bien caliente con las tiras de tortilla por encima.","Coronar con el aguacate en dados, una cucharada de queso crema y el cilantro picado."}', 'La sopa mexicana de siempre: caldo de tomate suave, tiras de tortilla crujientes por encima y el contraste fresco del aguacate y la crema.', NULL, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, ARRAY['pollo']::main_protein[], NULL, NULL, true, NULL, true, 'olla', 'mexicana', NULL),
  ('sopas_cremas_088', 'Crema de calabaza con chile y cacahuetes tostados', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 35, 'facil', 'all', 280, 8, 26, 16, 2, false, true, '{"cacahuetes"}', '[{"name":"Calabaza","amount":600,"unit":"g"},{"name":"Cebolla","amount":100,"unit":"g"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Chile fresco","amount":5,"unit":"g"},{"name":"Caldo de verduras","amount":500,"unit":"ml"},{"name":"Cacahuetes tostados","amount":40,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"}]'::jsonb, '{"Pochar la cebolla y el ajo picados en el aceite, a fuego suave, hasta que estén transparentes.","Añadir la calabaza en dados y el chile sin semillas, muy picado. Rehogar 5 minutos.","Cubrir con el caldo y cocer 20 minutos, hasta que la calabaza esté muy tierna.","Triturar hasta que quede fina y rectificar de sal.","Servir con los cacahuetes picados por encima, que es lo que le da el crujiente."}', 'Dulce por la calabaza, con un punto justo de picante y el crujido de los cacahuetes. Una crema que no aburre.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, NULL, 'olla', 'mexicana', NULL),
  ('sopas_cremas_089', 'Sopa miso con tofu y cebolleta', 'sopas_cremas', 'none', NULL, ARRAY['primero','cena']::meal_role[], 'completo', NULL, NULL, 15, 'facil', 'all', 180, 12, 10, 9, 2, false, true, '{"gluten","sesamo","soja"}', '[{"name":"Miso","amount":40,"unit":"g"},{"name":"Tofu firme","amount":200,"unit":"g"},{"name":"Cebolleta","amount":60,"unit":"g"},{"name":"Caldo de verduras","amount":700,"unit":"ml"},{"name":"Salsa de soja","amount":10,"unit":"ml"},{"name":"Aceite de sésamo","amount":5,"unit":"ml"}]'::jsonb, '{"Calentar el caldo sin que llegue a hervir: el miso no debe cocer o pierde el aroma.","Disolver el miso en un cazo con un poco de ese caldo caliente, hasta que no queden grumos.","Devolverlo a la olla y añadir la salsa de soja.","Cortar el tofu en dados y añadirlo. Dejar 3 minutos para que se caliente.","Servir con la cebolleta en aros finos y unas gotas de aceite de sésamo."}', 'Ligera, salada y reconfortante. Quince minutos y una cena que sienta bien.', NULL, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], NULL, NULL, true, NULL, NULL, 'olla', 'asiatica', NULL),
  ('carnes_008', 'Guiso de ternera con patatas', 'carnes', 'ternera', 'patatas', ARRAY['plato_unico']::meal_role[], 'completo', 'carnes_005', NULL, 80, 'normal', 'invierno', 492, 34, 30, 24, 2, true, true, '{}', '[{"name":"Carne de ternera para guisar","amount":300,"unit":"g"},{"name":"Patata","amount":250,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Zanahoria","amount":80,"unit":"g"},{"name":"Guisantes","amount":60,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vino blanco","amount":60,"unit":"ml"}]'::jsonb, '{"Cortar carne de ternera para guisar en dados de unos 3 cm.","Pelar y picar cebolla en brunoise fina.","Pelar zanahoria y cortar en rodajas de 1 cm.","Pelar patata y cortar en trozos medianos.","Calentar aceite de oliva en una olla a fuego fuerte hasta que humee ligeramente.","Dorar los dados de carne de ternera en la olla por todos los lados hasta que estén sellados y dorados; retirar y reservar.","Reducir el fuego a medio y sofreír la cebolla picada y la zanahoria en la misma olla hasta que la cebolla esté transparente.","Añadir tomate triturado y remover; sofreír hasta que el tomate pierda el agua y se concentre.","Incorporar vino blanco y remover para desglasar el fondo de la olla hasta que el alcohol se evapore.","Volver a introducir la carne de ternera reservada, cubrir con agua (aprox. 400 ml) y llevar a ebullición a fuego fuerte.","Tapar la olla, bajar a fuego suave y cocer hasta que la carne esté tierna.","Incorporar la patata troceada y guisantes; remover y cocer a fuego medio hasta que la patata esté tierna.","Retirar del fuego, rectificar de sal si fuera necesario y servir el guiso bien caliente."}', 'Ternera guisada con patatas, guisantes y zanahoria', '[{"appliance":"horno","time":110,"difficulty":"normal","prepSummary":"Se sella la carne y se sofríen las verduras en una olla apta para horno. Se añade el resto de ingredientes y se cocina tapado en el horno a 160°C durante 100-120 minutos, hasta que la carne esté muy tierna. El truco es el cocinado lento y uniforme para una ternera melosa."},{"appliance":"thermomix","time":80,"difficulty":"normal","prepSummary":"Pica las verduras y sofríelas. Incorpora la carne para sellarla ligeramente, luego añade el resto de ingredientes y programa a 90-100°C, giro inverso, velocidad cuchara, durante 70-90 minutos. El truco es usar el giro inverso para no deshacer la carne y que quede jugosa."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Sella la carne y sofríe las verduras en la olla. Añade el resto de ingredientes (excepto guisantes) y cocina a presión durante 35-45 minutos. Despresuriza, añade los guisantes y cocina unos minutos más. El secreto es el tiempo reducido y la carne excepcionalmente tierna."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Carne de ternera para guisar}} en dados de unos 3 cm.","minutes":5,"kind":"prep"},{"text":"Pelar y picar {{Cebolla}} en brunoise fina.","minutes":3,"kind":"prep"},{"text":"Pelar {{Zanahoria}} y cortar en rodajas de 1 cm.","minutes":2,"kind":"prep"},{"text":"Pelar {{Patata}} y cortar en trozos medianos.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una olla a fuego fuerte hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Dorar los dados de carne de ternera en la olla por todos los lados hasta que estén sellados y dorados; retirar y reservar.","minutes":6,"kind":"activo"},{"text":"Reducir el fuego a medio y sofreír la cebolla picada y la zanahoria en la misma olla hasta que la cebolla esté transparente.","minutes":6,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y remover; sofreír hasta que el tomate pierda el agua y se concentre.","minutes":4,"kind":"activo"},{"text":"Incorporar {{Vino blanco}} y remover para desglasar el fondo de la olla hasta que el alcohol se evapore.","minutes":3,"kind":"activo"},{"text":"Volver a introducir la carne de ternera reservada, cubrir con agua (aprox. 400 ml) y llevar a ebullición a fuego fuerte.","minutes":4,"kind":"activo"},{"text":"Tapar la olla, bajar a fuego suave y cocer hasta que la carne esté tierna.","minutes":50,"kind":"pasivo"},{"text":"Incorporar la patata troceada y {{Guisantes}}; remover y cocer a fuego medio hasta que la patata esté tierna.","minutes":20,"kind":"pasivo"},{"text":"Retirar del fuego, rectificar de sal si fuera necesario y servir el guiso bien caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('carnes_015', 'Ternera guisada con zanahorias', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', 'carnes_005', NULL, 80, 'normal', 'invierno', 442, 36, 16, 24, 2, true, true, '{}', '[{"name":"Carne de ternera para guisar","amount":350,"unit":"g"},{"name":"Zanahoria","amount":200,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Vino tinto","amount":80,"unit":"ml"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":8,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Laurel","amount":1,"unit":"ud"}]'::jsonb, '{"Cortar carne de ternera para guisar en trozos de unos 4 cm y salpimentar.","Pelar y picar cebolla en brunoise fina.","Pelar y picar ajo fino.","Pelar zanahoria y cortar en rodajas de 1 cm.","Calentar aceite de oliva en una olla a fuego fuerte hasta que humee ligeramente.","Dorar la carne en tandas en la olla hasta que esté sellada por todos los lados; retirar y reservar.","Bajar a fuego medio y sofreír la cebolla picada en la misma olla hasta que esté transparente.","Añadir el ajo picado y sofreír hasta que desprenda aroma, sin que se dore.","Añadir tomate triturado y remover; cocer hasta que el tomate pierda el exceso de agua.","Incorporar vino tinto y llevar a ebullición hasta que el alcohol se evapore.","Devolver la carne reservada a la olla y añadir laurel; cubrir con agua hasta la mitad del guiso.","Tapar y cocer a fuego suave hasta que la carne esté tierna.","Añadir la zanahoria cortada y cocer tapado a fuego suave hasta que esté tierna.","Retirar el laurel y servir el guiso bien caliente."}', 'Ternera guisada a fuego lento con abundante zanahoria', '[{"appliance":"horno","time":100,"difficulty":"normal","prepSummary":"Dora la ternera y sofríe las verduras en una cazuela apta para horno. Añade el resto de ingredientes, cubre y cocina a 160°C durante 80-90 minutos hasta que la carne esté tierna y la salsa reducida."},{"appliance":"thermomix","time":80,"difficulty":"normal","prepSummary":"Sofríe la cebolla y el ajo, luego dora la ternera en el vaso. Incorpora el resto de ingredientes y cocina a 100°C, velocidad cuchara, giro inverso, durante 70-80 minutos, o hasta que la carne esté muy tierna."},{"appliance":"olla_express","time":50,"difficulty":"normal","prepSummary":"Dora la ternera y sofríe las verduras en la olla. Añade el vino, tomate y laurel. Cierra la olla y cocina a presión media-alta durante unos 35-40 minutos, dejando que se despresurice sola para una ternera muy tierna."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Carne de ternera para guisar}} en trozos de unos 4 cm y salpimentar.","minutes":3,"kind":"prep"},{"text":"Pelar y picar {{Cebolla}} en brunoise fina.","minutes":3,"kind":"prep"},{"text":"Pelar y picar {{Ajo}} fino.","minutes":2,"kind":"prep"},{"text":"Pelar {{Zanahoria}} y cortar en rodajas de 1 cm.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una olla a fuego fuerte hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Dorar la carne en tandas en la olla hasta que esté sellada por todos los lados; retirar y reservar.","minutes":6,"kind":"activo"},{"text":"Bajar a fuego medio y sofreír la cebolla picada en la misma olla hasta que esté transparente.","minutes":5,"kind":"activo"},{"text":"Añadir el ajo picado y sofreír hasta que desprenda aroma, sin que se dore.","minutes":2,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y remover; cocer hasta que el tomate pierda el exceso de agua.","minutes":4,"kind":"activo"},{"text":"Incorporar {{Vino tinto}} y llevar a ebullición hasta que el alcohol se evapore.","minutes":3,"kind":"activo"},{"text":"Devolver la carne reservada a la olla y añadir {{Laurel}}; cubrir con agua hasta la mitad del guiso.","minutes":2,"kind":"activo"},{"text":"Tapar y cocer a fuego suave hasta que la carne esté tierna.","minutes":50,"kind":"pasivo"},{"text":"Añadir la zanahoria cortada y cocer tapado a fuego suave hasta que esté tierna.","minutes":20,"kind":"pasivo"},{"text":"Retirar el laurel y servir el guiso bien caliente.","minutes":1,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('carnes_021', 'Carne guisada con verduras', 'carnes', 'ternera', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'principal', 'carnes_005', NULL, 80, 'normal', 'invierno', 428, 34, 18, 24, 2, true, true, '{}', '[{"name":"Carne de ternera para guisar","amount":300,"unit":"g"},{"name":"Zanahoria","amount":100,"unit":"g"},{"name":"Judías verdes","amount":100,"unit":"g"},{"name":"Guisantes","amount":80,"unit":"g"},{"name":"Cebolla","amount":80,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Vino blanco","amount":60,"unit":"ml"}]'::jsonb, '{"Cortar carne de ternera para guisar en dados de unos 3 cm.","Pelar y picar cebolla en brunoise fina.","Pelar zanahoria y cortar en rodajas de medio centímetro.","Cortar judías verdes en trozos de 3 cm, retirar los extremos.","Calentar aceite de oliva en una olla a fuego fuerte hasta que humee ligeramente.","Dorar los dados de carne de ternera en la olla por todos los lados hasta que estén bien sellados; retirar y reservar.","Bajar el fuego a medio y sofreír la cebolla picada en la misma olla hasta que esté transparente.","Añadir tomate triturado y sofreír hasta que reduzca y oscurezca ligeramente, removiendo con frecuencia.","Añadir vino blanco y remover hasta que evapore el alcohol, unos 2 min.","Devolver la carne sellada a la olla y cubrir con 400 ml de agua; llevar a ebullición a fuego fuerte.","Tapar la olla, bajar a fuego suave y cocer hasta que la carne esté tierna.","Añadir las rodajas de zanahoria, las judías verdes en trozos y guisantes; remover para integrar.","Tapar de nuevo y cocer a fuego suave hasta que las verduras estén tiernas.","Servir la carne guisada con las verduras bien distribuidas en cada plato, regando con el jugo del guiso."}', 'Ternera guisada con zanahoria, judías verdes y guisantes', '[{"appliance":"horno","time":100,"difficulty":"normal","prepSummary":"Sofríe la carne y las verduras en una cazuela apta para horno. Añade el resto de ingredientes, tapa y cocina a 160-170°C durante unos 90-100 minutos hasta que la carne esté muy tierna."},{"appliance":"thermomix","time":85,"difficulty":"normal","prepSummary":"Trocea las verduras y sofríelas. Incorpora la carne para sellarla y luego añade el resto de ingredientes. Cocina a 100°C, giro inverso y velocidad cuchara durante unos 80-85 minutos hasta que la carne esté tierna."},{"appliance":"olla_express","time":35,"difficulty":"normal","prepSummary":"Sella la carne y sofríe las verduras en la olla. Añade el resto de ingredientes, cierra la olla y cocina a presión durante 25-30 minutos. Deja despresurizar de forma natural para una carne muy tierna."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], true, '[{"text":"Cortar {{Carne de ternera para guisar}} en dados de unos 3 cm.","minutes":5,"kind":"prep"},{"text":"Pelar y picar {{Cebolla}} en brunoise fina.","minutes":3,"kind":"prep"},{"text":"Pelar {{Zanahoria}} y cortar en rodajas de medio centímetro.","minutes":3,"kind":"prep"},{"text":"Cortar {{Judías verdes}} en trozos de 3 cm, retirar los extremos.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva}} en una olla a fuego fuerte hasta que humee ligeramente.","minutes":2,"kind":"activo"},{"text":"Dorar los dados de carne de ternera en la olla por todos los lados hasta que estén bien sellados; retirar y reservar.","minutes":6,"kind":"activo"},{"text":"Bajar el fuego a medio y sofreír la cebolla picada en la misma olla hasta que esté transparente.","minutes":5,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y sofreír hasta que reduzca y oscurezca ligeramente, removiendo con frecuencia.","minutes":4,"kind":"activo"},{"text":"Añadir {{Vino blanco}} y remover hasta que evapore el alcohol, unos 2 min.","minutes":2,"kind":"activo"},{"text":"Devolver la carne sellada a la olla y cubrir con 400 ml de agua; llevar a ebullición a fuego fuerte.","minutes":3,"kind":"activo"},{"text":"Tapar la olla, bajar a fuego suave y cocer hasta que la carne esté tierna.","minutes":50,"kind":"pasivo"},{"text":"Añadir las rodajas de zanahoria, las judías verdes en trozos y {{Guisantes}}; remover para integrar.","minutes":1,"kind":"activo"},{"text":"Tapar de nuevo y cocer a fuego suave hasta que las verduras estén tiernas.","minutes":15,"kind":"pasivo"},{"text":"Servir la carne guisada con las verduras bien distribuidas en cada plato, regando con el jugo del guiso.","minutes":2,"kind":"emplatado"}]'::jsonb, NULL, NULL, NULL, 'olla', NULL, NULL),
  ('pasta_arroces_076', 'Arroz caldoso de marisco', 'pasta_arroces', 'marisco', 'arroz', ARRAY['plato_unico']::meal_role[], 'completo', 'pasta_arroces_019', NULL, 40, 'normal', 'all', 438, 28, 50, 14, 2, false, false, '{"marisco","moluscos","pescado"}', '[{"name":"Arroz","amount":160,"unit":"g"},{"name":"Gambas","amount":150,"unit":"g"},{"name":"Mejillones","amount":150,"unit":"g"},{"name":"Rape","amount":100,"unit":"g"},{"name":"Tomate triturado","amount":80,"unit":"ml"},{"name":"Ajo","amount":10,"unit":"g"},{"name":"Cebolla","amount":50,"unit":"g"},{"name":"Aceite de oliva","amount":20,"unit":"ml"},{"name":"Caldo de pescado","amount":550,"unit":"ml"},{"name":"Pimentón dulce","amount":3,"unit":"g"}]'::jsonb, '{"Limpiar mejillones raspando las conchas y retirando las barbas.","Cortar rape en trozos de bocado.","Pelar gambas, reservando 2 enteras para el emplatado.","Picar ajo y cebolla fino.","Calentar aceite de oliva en una cazuela ancha a fuego medio.","Sofreír la cebolla y el ajo hasta que estén transparentes.","Añadir tomate triturado y pimentón dulce y sofreír 2 min removiendo.","Añadir arroz y remover 1 min hasta que se impregne del sofrito.","Verter caldo de pescado y llevar a ebullición a fuego fuerte.","Cocer a fuego medio 10 min removiendo de vez en cuando.","Añadir el rape y las gambas y cocer 3 min a fuego medio.","Añadir los mejillones y cocer 2-3 min hasta que se abran y el arroz esté en su punto.","Retirar del fuego y dejar reposar 2 min.","Servir en platos hondos colocando las gambas enteras reservadas encima."}', 'Arroz caldoso con gambas, mejillones y rape en un caldo intenso de pescado, con piezas de marisco enteras.', NULL, '{}', true, NULL, NULL, '{}', NULL, ARRAY['pescado_blanco']::main_protein[], false, '[{"text":"Limpiar {{Mejillones}} raspando las conchas y retirando las barbas.","minutes":3,"kind":"prep"},{"text":"Cortar {{Rape}} en trozos de bocado.","minutes":2,"kind":"prep"},{"text":"Pelar {{Gambas}}, reservando 2 enteras para el emplatado.","minutes":3,"kind":"prep"},{"text":"Picar {{Ajo}} y {{Cebolla}} fino.","minutes":3,"kind":"prep"},{"text":"Calentar {{Aceite de oliva|chorrito}} en una cazuela ancha a fuego medio.","minutes":1,"kind":"activo"},{"text":"Sofreír la cebolla y el ajo hasta que estén transparentes.","minutes":5,"kind":"activo"},{"text":"Añadir {{Tomate triturado}} y {{Pimentón dulce|pizca}} y sofreír 2 min removiendo.","minutes":2,"kind":"activo"},{"text":"Añadir {{Arroz}} y remover 1 min hasta que se impregne del sofrito.","minutes":1,"kind":"activo"},{"text":"Verter {{Caldo de pescado}} y llevar a ebullición a fuego fuerte.","minutes":2,"kind":"activo"},{"text":"Cocer a fuego medio 10 min removiendo de vez en cuando.","minutes":10,"kind":"pasivo"},{"text":"Añadir el rape y las gambas y cocer 3 min a fuego medio.","minutes":3,"kind":"activo"},{"text":"Añadir los mejillones y cocer 2-3 min hasta que se abran y el arroz esté en su punto.","minutes":3,"kind":"activo"},{"text":"Retirar del fuego y dejar reposar 2 min.","minutes":2,"kind":"espera"},{"text":"Servir en platos hondos colocando las gambas enteras reservadas encima.","minutes":1,"kind":"emplatado"}]'::jsonb, true, NULL, NULL, 'olla', NULL, NULL),
  ('pescados_032', 'Salmón a la plancha con ensalada de aguacate, pepino y eneldo', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', 'pescados_009', NULL, 20, 'normal', 'all', 510, 34, 8, 38, 2, true, false, '{"pescado"}', '[{"name":"Lomos de salmón","amount":300,"unit":"g"},{"name":"Aguacate","amount":150,"unit":"g"},{"name":"Pepino","amount":150,"unit":"g"},{"name":"Eneldo fresco","amount":10,"unit":"g"},{"name":"Zumo de limón","amount":20,"unit":"ml"},{"name":"Aceite de oliva virgen extra","amount":20,"unit":"ml"},{"name":"Sal","amount":3,"unit":"g"},{"name":"Pimienta negra","amount":1,"unit":"g"}]'::jsonb, '{"Retirar lomos de salmón de la nevera y dejar atemperar 10 min antes de cocinar.","Cortar aguacate en dados pequeños.","Cortar pepino en dados pequeños.","Picar eneldo fresco fino.","Mezclar el aguacate y el pepino con la mitad del eneldo picado, zumo de limón, sal y aceite de oliva virgen extra.","Salpimentar pimienta negra los lomos de salmón por ambas caras.","Calentar plancha a fuego fuerte hasta que esté bien caliente.","Añadir aceite de oliva virgen extra sobre la plancha y colocar los lomos de salmón con la piel hacia abajo.","Cocinar los lomos por el lado de la piel 4 min hasta que la piel esté crujiente y dorada.","Dar la vuelta a los lomos y cocinar 2 min más hasta que estén al punto deseado.","Repartir la ensalada de aguacate y pepino en los platos.","Colocar los lomos de salmón sobre la ensalada, añadir el resto del eneldo picado y un hilo de aceite de oliva virgen extra."}', 'Salmón a la plancha con la piel crujiente, acompañado de una ensalada fresca de aguacate, pepino y eneldo.', '[{"appliance":"airfryer","time":18,"difficulty":"facil","prepSummary":"Precalienta la airfryer a 190°C. Cocina el salmón sazonado durante 12-15 minutos, dándole la vuelta a mitad, para un exterior crujiente y un interior jugoso."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 190°C. Hornea el salmón sazonado sobre papel de horno durante 15-18 minutos hasta que esté tierno y cocido, manteniendo su jugosidad."},{"appliance":"thermomix","time":20,"difficulty":"facil","prepSummary":"Cocina el salmón sazonado en el recipiente Varoma durante 15-18 minutos a temperatura Varoma, para un resultado muy jugoso y saludable."},{"appliance":"vaporera","time":18,"difficulty":"facil","prepSummary":"Coloca el salmón sazonado en la cesta de la vaporera y cocina al vapor durante 12-15 minutos para obtener una textura tierna y jugosa, ideal para una comida ligera."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura"}', NULL, '{}'::main_protein[], false, '[{"text":"Retirar {{Lomos de salmón}} de la nevera y dejar atemperar 10 min antes de cocinar.","minutes":10,"kind":"espera"},{"text":"Cortar {{Aguacate}} en dados pequeños.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Cortar {{Pepino}} en dados pequeños.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Picar {{Eneldo fresco}} fino.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Mezclar el aguacate y el pepino con la mitad del eneldo picado, {{Zumo de limón}}, {{Sal|gusto}} y {{Aceite de oliva virgen extra|chorrito}}.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Salpimentar {{Pimienta negra|gusto}} los lomos de salmón por ambas caras.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} a fuego fuerte hasta que esté bien caliente.","minutes":1,"kind":"activo","part":"principal"},{"text":"Añadir {{Aceite de oliva virgen extra|chorrito}} sobre la plancha y colocar los lomos de salmón con la piel hacia abajo.","minutes":1,"kind":"activo","part":"principal"},{"text":"Cocinar los lomos por el lado de la piel 4 min hasta que la piel esté crujiente y dorada.","minutes":4,"kind":"pasivo","part":"principal"},{"text":"Dar la vuelta a los lomos y cocinar 2 min más hasta que estén al punto deseado.","minutes":2,"kind":"activo","part":"principal"},{"text":"Repartir la ensalada de aguacate y pepino en los platos.","minutes":1,"kind":"emplatado","part":"combinado"},{"text":"Colocar los lomos de salmón sobre la ensalada, añadir el resto del eneldo picado y un hilo de aceite de oliva virgen extra.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL, NULL)
