  ('pescados_055', 'Salmón a la plancha con ensalada de pepino y eneldo', 'pescados', 'pescado_azul', NULL, ARRAY['segundo','plato_unico']::meal_role[], 'completo', 'pescados_009', NULL, 20, 'facil', 'all', 445, 34, 7, 30, 2, true, true, '{"pescado","lactosa"}', '[{"name":"Lomos de salmón","amount":320,"unit":"g"},{"name":"Pepino","amount":250,"unit":"g"},{"name":"Yogur natural","amount":80,"unit":"g"},{"name":"Eneldo fresco","amount":8,"unit":"g"},{"name":"Cebolla morada","amount":30,"unit":"g"},{"name":"Limón","amount":1,"unit":"ud"},{"name":"Aceite de oliva","amount":15,"unit":"ml"}]'::jsonb, '{"Pelar pepino, cortar por la mitad a lo largo y retirar las semillas con una cuchara.","Cortar el pepino pelado en medias lunas finas.","Laminar cebolla morada en juliana muy fina.","Picar eneldo fresco fino.","Exprimir limón y reservar el zumo.","Mezclar yogur natural con el eneldo picado, el zumo de limón y lomos de salmón en un bol hasta obtener un aliño homogéneo.","Añadir el pepino y la cebolla morada al aliño y mezclar bien.","Reservar la ensalada en la nevera hasta el momento de servir.","Salpimentar lomos de salmón por ambos lados.","Calentar plancha con aceite de oliva a fuego fuerte hasta que humee.","Colocar los lomos de salmón con la piel hacia abajo y cocinar 4 min hasta que la piel esté crujiente.","Dar la vuelta a los lomos de salmón y cocinar 2 min más hasta que el interior esté jugoso.","Servir los lomos de salmón con la ensalada de pepino y eneldo al lado."}', 'Salmón a la plancha con piel crujiente y una ensalada fresca de pepino y eneldo.', '[{"appliance":"airfryer","time":20,"difficulty":"facil","prepSummary":"Para el salmón, precalienta la airfryer a 190-200°C. Cocina los lomos durante 12-15 minutos, girándolos a mitad, hasta que estén dorados y jugosos. La ensalada se prepara aparte mientras el salmón se cocina."},{"appliance":"horno","time":25,"difficulty":"facil","prepSummary":"Precalienta el horno a 200°C con función de aire si es posible. Hornea los lomos de salmón en una bandeja con papel de horno durante 15-18 minutos hasta que estén cocidos y ligeramente dorados. La ensalada se prepara aparte."}]'::jsonb, '{}', NULL, NULL, NULL, '{"verdura","lacteo"}', NULL, '{}'::main_protein[], false, '[{"text":"Pelar {{Pepino}}, cortar por la mitad a lo largo y retirar las semillas con una cuchara.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Cortar el pepino pelado en medias lunas finas.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Laminar {{Cebolla morada}} en juliana muy fina.","minutes":2,"kind":"prep","part":"salsa"},{"text":"Picar {{Eneldo fresco}} fino.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Exprimir {{Limón}} y reservar el zumo.","minutes":1,"kind":"prep","part":"salsa"},{"text":"Mezclar {{Yogur natural}} con el eneldo picado, el zumo de limón y {{Lomos de salmón|gusto}} en un bol hasta obtener un aliño homogéneo.","minutes":2,"kind":"activo","part":"salsa"},{"text":"Añadir el pepino y la cebolla morada al aliño y mezclar bien.","minutes":1,"kind":"activo","part":"salsa"},{"text":"Reservar la ensalada en la nevera hasta el momento de servir.","minutes":5,"kind":"espera","part":"salsa"},{"text":"Salpimentar {{Lomos de salmón}} por ambos lados.","minutes":1,"kind":"prep","part":"principal"},{"text":"Calentar {{@Plancha}} con {{Aceite de oliva|chorrito}} a fuego fuerte hasta que humee.","minutes":1,"kind":"activo","part":"principal"},{"text":"Colocar los lomos de salmón con la piel hacia abajo y cocinar 4 min hasta que la piel esté crujiente.","minutes":4,"kind":"pasivo","part":"principal"},{"text":"Dar la vuelta a los lomos de salmón y cocinar 2 min más hasta que el interior esté jugoso.","minutes":2,"kind":"activo","part":"principal"},{"text":"Servir los lomos de salmón con la ensalada de pepino y eneldo al lado.","minutes":1,"kind":"emplatado","part":"combinado"}]'::jsonb, true, NULL, NULL, 'plancha', NULL, NULL)
